/// Simulation failure.
#[derive(Debug, thiserror::Error)]
pub enum RuntimeError {
    /// Donor `Error` with its message preserved.
    #[error("{0}")]
    Failure(String),
    /// Donor `RangeError`.
    #[error("{0}")]
    Range(String),
    /// Donor `AggregateError` during load/cleanup.
    #[error("{0}: {1:?}")]
    Aggregate(String, Vec<String>),
    /// World partition failure.
    #[error(transparent)]
    World(#[from] qa_world::WorldError),
    /// Identity failure.
    #[error(transparent)]
    Identity(#[from] qa_core::identity::IdentityError),
    /// Physics failure.
    #[error(transparent)]
    Physics(#[from] super::physics::PhysicsError),
}

fn fail<T>(message: impl Into<String>) -> Result<T, RuntimeError> {
    Err(RuntimeError::Failure(message.into()))
}

fn range<T>(message: impl Into<String>) -> Result<T, RuntimeError> {
    Err(RuntimeError::Range(message.into()))
}

/// Donor module-level `zero`.
fn zero() -> Vec3 {
    Vec3 { x: 0.0, y: 0.0, z: 0.0 }
}

/// Contract three-vector to render vector (donor precision narrows to f32).
fn q2_vec3(value: &qa_net::q2_adapters::Q2Vec3) -> Vec3 {
    Vec3 {
        x: value.x as f32,
        y: value.y as f32,
        z: value.z as f32,
    }
}

/// Donor module-level `add` (f32-rounded sums).
fn add(a: Vec3, b: Vec3) -> Vec3 {
    Vec3 {
        x: (a.x + b.x),
        y: (a.y + b.y),
        z: (a.z + b.z),
    }
}

/// Donor module-level `subtract`.
fn subtract(a: Vec3, b: Vec3) -> Vec3 {
    Vec3 {
        x: a.x - b.x,
        y: a.y - b.y,
        z: a.z - b.z,
    }
}

/// Donor module-level `seconds`.
fn seconds(time: SourceTime) -> f64 {
    time.as_seconds_f64()
}

/// Donor `sourceModel`: parse `*N` inline model paths.
#[allow(dead_code)]
fn source_model(path: &str) -> Option<i32> {
    let rest = path.strip_prefix('*')?;
    if rest.is_empty() || !rest.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    rest.parse::<i32>().ok()
}

