/// Source provider family from a provider string.
///
/// Port of `providerFamily` from donor
/// `src/app/bootstrap/simulation/players.ts`.
/// Provider identity in `namespace:name` donor spelling.
pub fn provider_text(provider: &ProviderId) -> String {
    qa_world::registry::provider_key(provider)
}

pub fn provider_family(provider: &str) -> Result<GameFamily, RuntimeError> {
    if provider.starts_with("q1:") {
        Ok(GameFamily::Q1)
    } else if provider.starts_with("q2:") {
        Ok(GameFamily::Q2)
    } else if provider.starts_with("q3:") {
        Ok(GameFamily::Q3)
    } else {
        range(format!("Unknown source provider family: {provider}"))
    }
}

/// Recipe timing entry for a provider.
///
/// Port of `providerTiming` from donor
/// `src/app/bootstrap/simulation/players.ts`.
pub fn provider_timing<'r>(
    recipe: &'r ExecutableRecipe,
    provider: &str,
) -> Result<&'r qa_content::contract::ProviderTiming, RuntimeError> {
    recipe
        .timing
        .iter()
        .find(|value| provider_text(&value.provider) == provider)
        .ok_or_else(|| RuntimeError::Failure(format!("Recipe has no timing for {provider}")))
}

/// Selected movement profile for a recipe.
///
/// Port of `movementProfile` from donor
/// `src/app/bootstrap/simulation/players.ts`.
pub fn movement_profile(recipe: &ExecutableRecipe) -> Result<MovementProfile, RuntimeError> {
    use qa_core::time::ClockProfile;
    use qa_world::movement::q1::types::{Q1MovementProfile, QwMovementProfile};
    use qa_world::movement::q2::types::{Q2MovementProfile, Q2RereleaseMovementProfile};
    use qa_world::movement::q3::types::{Q3MovementProfile, Q3Product as Q3MoveProduct};
    use qa_world::movement::Q1MovementParameters;
    let movement_provider = provider_text(&recipe.movement.provider);
    let timing = provider_timing(recipe, &movement_provider)?;
    let rererelease = recipe.movement.content.as_str().contains(":rerelease:");
    match &timing.clock {
        ClockProfile::Q1Netquake { .. } => Ok(MovementProfile::Q1Netquake(Q1MovementProfile {
            id: timing.provider.clone(),
            clock: timing.clock,
            numeric: timing.numeric,
            edition: if rererelease {
                qa_world::movement::q1::types::Q1Edition::Rerelease
            } else {
                qa_world::movement::q1::types::Q1Edition::Classic
            },
            parameters: Q1MovementParameters {
                gravity: 800.0,
                stop_speed: 100.0,
                max_speed: 320.0,
                spectator_max_speed: 500.0,
                accelerate: 10.0,
                air_accelerate: 10.0,
                water_accelerate: 10.0,
                friction: 4.0,
                water_friction: 4.0,
                entity_gravity: 1.0,
            },
            edge_friction: 2.0,
            no_clip_angle_hack: false,
        })),
        ClockProfile::Q1Quakeworld { .. } => Ok(MovementProfile::Q1Quakeworld(QwMovementProfile {
            id: timing.provider.clone(),
            clock: timing.clock,
            numeric: timing.numeric,
            parameters: Q1MovementParameters {
                gravity: 800.0,
                stop_speed: 100.0,
                max_speed: 320.0,
                spectator_max_speed: 500.0,
                accelerate: 10.0,
                air_accelerate: 0.7,
                water_accelerate: 10.0,
                friction: 4.0,
                water_friction: 4.0,
                entity_gravity: 1.0,
            },
        })),
        ClockProfile::Q2Classic => Ok(MovementProfile::Q2Classic(Q2MovementProfile {
            id: timing.provider.clone(),
            clock: timing.clock,
            numeric: timing.numeric,
            strafejump_hack: false,
            air_accelerate: 0.0,
            snap_initial: true,
        })),
        ClockProfile::Q2Rerelease { .. } => Ok(MovementProfile::Q2Rerelease(Q2RereleaseMovementProfile {
            id: timing.provider.clone(),
            clock: timing.clock,
            numeric: timing.numeric,
            air_accelerate: 0.0,
            n64_physics: false,
        })),
        ClockProfile::Q3 {
            fixed_movement_milliseconds,
            ..
        } => Ok(MovementProfile::Q3(Q3MovementProfile {
            id: timing.provider.clone(),
            clock: timing.clock,
            numeric: timing.numeric,
            product: Q3MoveProduct::BaseQ3,
            fixed_milliseconds: fixed_movement_milliseconds.map(|value| value as i32),
            no_footsteps: false,
        })),
    }
}

/// Origin carried by a movement state.
///
/// Port of `movementOrigin` from donor
/// `src/app/bootstrap/simulation/players.ts`.
pub fn movement_origin(state: &MovementState) -> Vec3 {
    match state {
        MovementState::Q2Classic(state) => Vec3 {
            x: state.origin_eighths[0] as f32 / 8.0,
            y: state.origin_eighths[1] as f32 / 8.0,
            z: state.origin_eighths[2] as f32 / 8.0,
        },
        MovementState::Q1Netquake(state) => state.origin,
        MovementState::Q1Quakeworld(state) => state.origin,
        MovementState::Q2Rerelease(state) => state.origin,
        MovementState::Q3(state) => state.origin,
    }
}

/// Velocity carried by a movement state.
///
/// Port of `movementVelocity` from donor
/// `src/app/bootstrap/simulation/players.ts`.
pub fn movement_velocity(state: &MovementState) -> Vec3 {
    match state {
        MovementState::Q2Classic(state) => Vec3 {
            x: state.velocity_eighths[0] as f32 / 8.0,
            y: state.velocity_eighths[1] as f32 / 8.0,
            z: state.velocity_eighths[2] as f32 / 8.0,
        },
        MovementState::Q1Netquake(state) => state.velocity,
        MovementState::Q1Quakeworld(state) => state.velocity,
        MovementState::Q2Rerelease(state) => state.velocity,
        MovementState::Q3(state) => state.velocity,
    }
}

