/// Ordered source input-application table.
///
/// Mirror of `ModClientApplications` from donor
/// `src/world/session/mod-client-applications.ts` (canonical home:
/// `qa_world` session mods); unify post-merge.
#[allow(clippy::type_complexity)]
pub struct ModClientApplications {
    live: Rc<dyn Fn(&ModClientIdentity) -> bool>,
    listeners: Vec<(u64, Rc<dyn Fn(&ModClientApplicationEvent)>)>,
    next_invocation: u64,
    next_listener: u64,
    pending: Vec<ModClientApplication>,
    /// Whether any mod observes input.
    pub active: bool,
}

impl ModClientApplications {
    /// Create a table with a liveness predicate.
    pub fn new(live: impl Fn(&ModClientIdentity) -> bool + 'static) -> Self {
        Self {
            live: Rc::new(live),
            listeners: Vec::new(),
            next_invocation: 1,
            next_listener: 1,
            pending: Vec::new(),
            active: false,
        }
    }

    /// Subscribe a listener; returns an unsubscribe token.
    pub fn subscribe(&mut self, listener: impl Fn(&ModClientApplicationEvent) + 'static) -> u64 {
        let token = self.next_listener;
        self.next_listener += 1;
        self.listeners.push((token, Rc::new(listener)));
        self.active = true;
        token
    }

    /// Drop a subscription.
    pub fn unsubscribe(&mut self, token: u64) {
        self.listeners.retain(|(id, _)| *id != token);
        self.active = !self.listeners.is_empty();
    }

    /// Begin an application; returns `None` when no mod observes input.
    pub fn begin(&mut self, mut application: ModClientApplication) -> Option<ModClientApplication> {
        if !self.active || !(self.live)(&application.identity) {
            return None;
        }
        application.invocation = self.next_invocation;
        self.next_invocation += 1;
        let event = ModClientApplicationEvent::Before {
            application: application.clone(),
        };
        for (_, listener) in &self.listeners {
            listener(&event);
        }
        self.pending.push(application.clone());
        Some(application)
    }

    /// Finish an application.
    pub fn finish(&mut self, application: Option<&ModClientApplication>, failed: bool) {
        let Some(application) = application else { return };
        self.pending
            .retain(|pending| pending.invocation != application.invocation);
        let event = ModClientApplicationEvent::After {
            application: application.clone(),
            outcome: if failed {
                ModClientApplicationOutcome::Failed
            } else {
                ModClientApplicationOutcome::Completed
            },
        };
        for (_, listener) in &self.listeners {
            listener(&event);
        }
    }

    /// Release an actor's pending applications.
    pub fn release(&mut self, actor: &ActorId) {
        self.pending.retain(|pending| &pending.identity.actor != actor);
    }

    /// Checkpoint ordinal (donor `checkpoint`).
    pub fn checkpoint(&self) -> u64 {
        self.next_invocation
    }

    /// Restore an ordinal (donor `restore`).
    pub fn restore(&mut self, ordinal: u64) {
        self.next_invocation = ordinal;
    }

    /// Close the table (donor `close`).
    pub fn close(&mut self) {
        self.listeners.clear();
        self.pending.clear();
        self.active = false;
    }
}

