/// Bot goal status code (donor `RereleaseGoalStatus`).
pub type RereleaseGoalStatus = i32;

/// Bot navigation answer (donor `SimulationBotServices["navigation"]`).
#[derive(Debug, Clone)]
pub enum BotNavigationAnswer {
    /// Admitted path.
    Path {
        /// Squared path distance.
        distance_squared: f64,
        /// Path points.
        points: Vec<Vec3>,
    },
    /// No navigation backend.
    NoNavigation,
    /// Goal unreachable.
    Unreachable,
}

/// Transport seam behind [`SimulationBotServices`].
///
/// The donor `bots.ts` transport (`ApplicationBotService`) lands with the
/// bots lane; until then the simulation drives attached transports through
/// this seam.
pub trait BotTransportSeam {
    /// Donor `moveToPoint`.
    fn move_to_point(&self, actor: &ActorId, point: Vec3, tolerance: f64) -> RereleaseGoalStatus;
    /// Donor `followActor`.
    fn follow_actor(&self, actor: &ActorId, target: &ActorId) -> RereleaseGoalStatus;
    /// Donor `isBot`.
    fn is_bot(&self, actor: &ActorId) -> bool;
    /// Donor `configuration`.
    fn configuration(&self) -> Option<qa_core::cvar::CvarRegistry>;
    /// Donor `checkpoint`.
    fn checkpoint(&self) -> Option<ApplicationBotsCheckpoint>;
    /// Donor `frame`.
    fn frame(&self, time: f64, elapsed: f64, automatic: bool) -> Vec<ActorCommand>;
}

/// Bot population checkpoint.
///
/// Mirror of `ApplicationBotsCheckpoint` from donor
/// `src/app/bootstrap/simulation/bots.ts` (canonical home: the bots-lane
/// port); unify post-merge. Only the version tag and opaque transport
/// payload cross this seam; the bots lane owns the schema.
#[derive(Debug, Clone)]
pub struct ApplicationBotsCheckpoint {
    /// Checkpoint version (donor `version: 1`).
    pub version: u32,
    /// Opaque transport payload.
    pub transport: qa_world::save::value::SaveJson,
}

/// Simulation bot services.
///
/// Mirror of `SimulationBotServices` from donor
/// `src/app/bootstrap/simulation/bots.ts` (canonical home: the bots-lane
/// port of that module); unify post-merge.
#[derive(Default)]
pub struct SimulationBotServices {
    transport: Option<Rc<dyn BotTransportSeam>>,
}

impl SimulationBotServices {
    /// Create unattached services.
    pub fn new() -> Self {
        Self::default()
    }

    /// Attach a transport (donor `attachTransport`).
    pub fn attach_transport(&mut self, transport: Rc<dyn BotTransportSeam>) -> Result<(), RuntimeError> {
        if self.transport.is_some() {
            return fail("Bot transport is already attached");
        }
        self.transport = Some(transport);
        Ok(())
    }

    /// Donor `moveToPoint`.
    pub fn move_to_point(&self, actor: &ActorId, point: Vec3, tolerance: f64) -> RereleaseGoalStatus {
        self.transport
            .as_ref()
            .map(|transport| transport.move_to_point(actor, point, tolerance))
            .unwrap_or(0)
    }

    /// Donor `followActor`.
    pub fn follow_actor(&self, actor: &ActorId, target: &ActorId) -> RereleaseGoalStatus {
        self.transport
            .as_ref()
            .map(|transport| transport.follow_actor(actor, target))
            .unwrap_or(0)
    }

    /// Donor `isBot`.
    pub fn is_bot(&self, actor: &ActorId) -> bool {
        self.transport.as_ref().is_some_and(|transport| transport.is_bot(actor))
    }

    /// Donor `configuration`.
    pub fn configuration(&self) -> Option<qa_core::cvar::CvarRegistry> {
        self.transport.as_ref().and_then(|transport| transport.configuration())
    }

    /// Donor `checkpoint`.
    pub fn checkpoint(&self) -> Option<ApplicationBotsCheckpoint> {
        self.transport.as_ref().and_then(|transport| transport.checkpoint())
    }

    /// Donor `frame`.
    pub fn frame(&self, time: f64, elapsed: f64) -> Vec<ActorCommand> {
        self.transport
            .as_ref()
            .map(|transport| transport.frame(time, elapsed, true))
            .unwrap_or_default()
    }
}

