/// Session actor registry with release listeners.
///
/// Wrapper over [`qa_world::registry::ActorRegistry`] adding the donor
/// `SessionActorRegistry` release-listener list and saved-actor references.
/// (Canonical home: `qa_world::registry`; unify post-merge.)
#[allow(clippy::type_complexity)]
pub struct SessionActorRegistry {
    inner: qa_world::registry::ActorRegistry,
    release_listeners: Vec<(u64, Rc<dyn Fn(&OwnedActor, &qa_world::registry::ActorRegistry)>)>,
    next_listener: u64,
}

impl SessionActorRegistry {
    /// Create a registry for an identity owner.
    pub fn new(owner: qa_core::identity::IdentityOwner, capacity: usize) -> Result<Self, RuntimeError> {
        Ok(Self {
            inner: qa_world::registry::ActorRegistry::new(owner, capacity)?,
            release_listeners: Vec::new(),
            next_listener: 1,
        })
    }

    /// Restore a registry from checkpoints.
    pub fn restore(
        owner: qa_core::identity::IdentityOwner,
        checkpoints: &[qa_world::registry::ActorSlotCheckpoint],
        sources: &[qa_world::registry::SourceActorCheckpoint],
        capacity: usize,
    ) -> Result<Self, RuntimeError> {
        Ok(Self {
            inner: qa_world::registry::ActorRegistry::restore(owner, checkpoints, sources, capacity)?,
            release_listeners: Vec::new(),
            next_listener: 1,
        })
    }

    /// Borrow the inner registry.
    pub fn inner(&self) -> &qa_world::registry::ActorRegistry {
        &self.inner
    }

    /// Mutably borrow the inner registry.
    pub fn inner_mut(&mut self) -> &mut qa_world::registry::ActorRegistry {
        &mut self.inner
    }

    /// Donor `isLive`.
    pub fn is_live(&self, actor: &ActorId) -> bool {
        self.inner.is_live(actor)
    }

    /// Donor `resolveOwned`.
    pub fn resolve_owned(&self, actor: &ActorId) -> Option<OwnedActor> {
        self.inner.resolve_owned(actor)
    }

    /// Donor `atSource`.
    pub fn at_source(&self, owner: &ProviderId, slot: u32) -> Option<OwnedActor> {
        self.inner.at_source(owner, slot)
    }

    /// Donor `allocateAtSource`.
    pub fn allocate_at_source(
        &mut self,
        owner: ProviderId,
        slot: u32,
        definition: &str,
    ) -> Result<OwnedActor, RuntimeError> {
        Ok(self.inner.allocate_at_source(owner, slot, definition)?)
    }

    /// Donor `allocate`.
    pub fn allocate(&mut self, owner: ProviderId, definition: &str) -> Result<OwnedActor, RuntimeError> {
        Ok(self.inner.allocate(owner, definition)?)
    }

    /// Donor `sourceOf`.
    pub fn source_of(&self, actor: &ActorId) -> Option<(ProviderId, u32)> {
        self.inner.source_of(actor)
    }

    /// Donor `assertOwned`.
    pub fn assert_owned(&self, actor: &OwnedActor) -> Result<(), RuntimeError> {
        Ok(self.inner.assert_owned(actor)?)
    }

    /// Donor `observations`.
    pub fn observations(&self) -> Vec<qa_world::registry::ActorObservation> {
        self.inner.observations()
    }

    /// Subscribe a release listener; returns an unsubscribe token.
    pub fn on_release(&mut self, listener: impl Fn(&OwnedActor, &qa_world::registry::ActorRegistry) + 'static) -> u64 {
        let token = self.next_listener;
        self.next_listener += 1;
        self.release_listeners.push((token, Rc::new(listener)));
        token
    }

    /// Drop a release subscription (donor `onRelease` unsubscribe).
    pub fn unsubscribe(&mut self, token: u64) {
        self.release_listeners.retain(|(id, _)| *id != token);
    }

    /// Release an actor, notifying listeners.
    pub fn release(&mut self, actor: &OwnedActor) -> Result<(), RuntimeError> {
        let owned = actor.clone();
        self.inner.release(actor)?;
        for (_, listener) in &self.release_listeners {
            listener(&owned, &self.inner);
        }
        Ok(())
    }

    /// Donor `referenceSaved`.
    pub fn reference_saved(
        &self,
        actor: &ActorId,
        _space: SavedReferenceSpace,
    ) -> Result<qa_core::identity::SavedActorId, RuntimeError> {
        if self.resolve_owned(actor).is_none() {
            return fail("Actor has no owned handle");
        }
        Ok(qa_core::identity::SavedActorId::from(actor))
    }

    /// Donor `close` (via inner).
    pub fn close(&mut self) {
        self.inner.close();
        self.release_listeners.clear();
    }
}

/// Donor `referenceSaved` spaces (`"current"` / `"checkpoint"`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SavedReferenceSpace {
    /// Current world.
    Current,
    /// Checkpoint world.
    Checkpoint,
}

/// Actor think-callback table.
///
/// Mirror of `ActorCallbackTable` from donor `src/world/actors/*`
/// (canonical home: `qa_world`); unify post-merge.
#[derive(Default)]
pub struct ActorCallbackTable {
    thinks: HashMap<ActorId, Vec<ThinkRegistration>>,
    callback_bindings: RefCell<HashMap<ActorId, ActorCallbacks>>,
}

/// One registered think callback.
#[derive(Debug, Clone)]
pub struct ThinkRegistration {
    /// Callback id.
    pub callback: String,
    /// Due time.
    pub due: SourceTime,
    /// Provider.
    pub provider: ProviderId,
    /// Sequence.
    pub sequence: u64,
}

impl ActorCallbackTable {
    /// Create an empty table.
    pub fn new() -> Self {
        Self::default()
    }

    /// Run an actor's think callbacks (donor `think`).
    pub fn think(&mut self, actor: &OwnedActor, frame: FrameContext) {
        let _ = (actor, frame);
        self.thinks.remove(actor.id());
    }

    /// Schedule a think (donor `schedule` helper surface).
    pub fn schedule(&mut self, actor: &OwnedActor, registration: ThinkRegistration) {
        self.thinks.entry(actor.id().clone()).or_default().push(registration);
    }

    /// Cancel an actor's thinks.
    pub fn cancel(&mut self, actor: &OwnedActor) {
        self.thinks.remove(actor.id());
    }
}

