/// Gameplay combat authority.
///
/// Mirror of `GameplayAuthority` from donor
/// `src/world/gameplay/authority.ts` (canonical home: `qa_world::combat`);
/// unify post-merge. Damage vocabulary comes from the events lane
/// (`super::events`); [`GameplayAuthority::apply`] runs the canonical donor
/// `apply`/`applyCanonical` pipeline over the registered combat policies.
pub struct GameplayAuthority {
    /// Combat bindings by actor (C4: interior mutability so policy
    /// dispatch re-enters the simulation through weak handles while no
    /// state guard is held).
    combat_states: RefCell<HashMap<ActorId, qa_world::combat::CombatState>>,
    hooks: Option<GameplayAuthorityHooks>,
    /// Live-actor registry for target resolution (C5: wired by construction).
    actors: Option<Rc<RefCell<SessionActorRegistry>>>,
    /// Actor callback table for die/pain dispatch (C4: wired by
    /// construction via `set_callbacks`).
    callbacks: Option<Rc<RefCell<ActorCallbackTable>>>,
    /// Registered combat policies by id (C10: donor `policies`; C4 decide
    /// dispatch in `CombatPolicy.kind`).
    policies: HashMap<ProviderId, CombatPolicy>,
}

/// Donor `GameplayAuthority` hooks (constructor options).
#[derive(Clone)]
#[allow(clippy::type_complexity)]
pub struct GameplayAuthorityHooks {
    /// Donor `team`.
    pub team: Rc<dyn Fn(&ActorId, Option<String>) -> Option<String>>,
    /// Donor `damageAllowed`.
    pub damage_allowed: Rc<dyn Fn(&super::events::DamageRequest) -> bool>,
    /// Donor `impulse`.
    pub impulse: Rc<dyn Fn(&OwnedActor, Vec3, &str)>,
    /// Donor `beforeReaction`.
    pub before_reaction: Rc<dyn Fn(&OwnedActor, &super::events::DamageDecision)>,
    /// Donor `confirmed`.
    pub confirmed: Rc<dyn Fn(&super::events::DamageOutcome)>,
}

impl GameplayAuthority {
    /// Create an empty authority.
    pub fn new() -> Self {
        Self {
            combat_states: RefCell::new(HashMap::new()),
            hooks: None,
            actors: None,
            callbacks: None,
            policies: HashMap::new(),
        }
    }

    /// Install donor hooks.
    pub fn set_hooks(&mut self, hooks: GameplayAuthorityHooks) {
        self.hooks = Some(hooks);
    }

    /// Read combat state (donor `read`).
    pub fn read(&self, actor: &ActorId) -> Option<qa_world::combat::CombatState> {
        self.combat_states.borrow().get(actor).cloned()
    }

    /// Write combat state.
    pub fn write(&mut self, actor: &ActorId, state: qa_world::combat::CombatState) {
        self.combat_states.borrow_mut().insert(actor.clone(), state);
    }

    /// Release an actor.
    pub fn release(&mut self, actor: &ActorId) {
        self.combat_states.borrow_mut().remove(actor);
    }
}

impl Default for GameplayAuthority {
    fn default() -> Self {
        Self::new()
    }
}

