/// Actor execution entry.
///
/// The donor `ActorExecution` union carries live service references per
/// entry; Rust cannot borrow the sources from inside the same state, so
/// entries carry identity only and resolve live services through the state
/// (`with_q1_services` / `with_q2_game`). Transient
/// [`actor_execution::ActorExecution`] views are built at motion/flag call
/// sites under the services `Rc` guards.
#[derive(Debug, Clone, PartialEq)]
pub enum RuntimeExecutionEntry {
    /// QuakeC-driven actor.
    QuakeC {
        /// Owning actor handle.
        actor: OwnedActor,
        /// Content identity.
        content: ContentId,
    },
    /// Native Q1 entity.
    Q1 {
        /// Owning actor handle.
        actor: OwnedActor,
        /// Content identity.
        content: ContentId,
    },
    /// Native Q2 entity.
    Q2 {
        /// Owning actor handle.
        actor: OwnedActor,
        /// Content identity.
        content: ContentId,
    },
    /// Q3 actor stepped by the Q3 arm.
    Q3 {
        /// Owning actor handle.
        actor: OwnedActor,
        /// Owning actor.
        owner: ActorId,
        /// Owning provider.
        provider: ProviderId,
        /// Content identity.
        content: ContentId,
    },
    /// Q3-source actor with native motion and collision.
    Q3Source {
        /// Owning actor handle.
        actor: OwnedActor,
        /// Owning provider.
        provider: ProviderId,
        /// Content identity.
        content: ContentId,
    },
}

impl RuntimeExecutionEntry {
    /// Owning actor handle.
    pub fn actor(&self) -> &OwnedActor {
        match self {
            RuntimeExecutionEntry::QuakeC { actor, .. }
            | RuntimeExecutionEntry::Q1 { actor, .. }
            | RuntimeExecutionEntry::Q2 { actor, .. }
            | RuntimeExecutionEntry::Q3 { actor, .. }
            | RuntimeExecutionEntry::Q3Source { actor, .. } => actor,
        }
    }

    /// Donor `kind` discriminator.
    pub fn kind(&self) -> &'static str {
        match self {
            RuntimeExecutionEntry::QuakeC { .. } => "quakec",
            RuntimeExecutionEntry::Q1 { .. } => "q1",
            RuntimeExecutionEntry::Q2 { .. } => "q2",
            RuntimeExecutionEntry::Q3 { .. } => "q3",
            RuntimeExecutionEntry::Q3Source { .. } => "q3-source",
        }
    }

    /// Content identity.
    pub fn content(&self) -> &ContentId {
        match self {
            RuntimeExecutionEntry::QuakeC { content, .. }
            | RuntimeExecutionEntry::Q1 { content, .. }
            | RuntimeExecutionEntry::Q2 { content, .. }
            | RuntimeExecutionEntry::Q3 { content, .. }
            | RuntimeExecutionEntry::Q3Source { content, .. } => content,
        }
    }
}

impl SourceRuntime {
    /// Donor `kind` discriminator.
    pub fn kind(&self) -> &'static str {
        match self {
            SourceRuntime::Loading => "loading",
            SourceRuntime::QuakeC { .. } => "quakec",
            SourceRuntime::Q1 { .. } => "q1",
            SourceRuntime::Q3 { .. } => "q3",
            SourceRuntime::Q3Qvm { .. } => "q3-qvm",
            SourceRuntime::Q2Native(_) => "q2-native",
            SourceRuntime::Q2 { .. } => "q2",
        }
    }
}

