/// Collision map settings (donor `CollisionMapSettings`, settings.ts).
#[derive(Debug, Clone, Default)]
pub struct CollisionMapSettings {
    /// False once the map cvars are registered.
    pub opaque: bool,
}

impl CollisionMapSettings {
    /// Map cvar definitions (donor `collisionMapCvarDefinitions`).
    pub const DEFINITIONS: [(&'static str, &'static str, u32); 3] = [
        ("cm_noAreas", "0", qa_core::cvar::flags::CHEAT),
        ("cm_noCurves", "0", qa_core::cvar::flags::CHEAT),
        (
            "cm_playerCurveClip",
            "1",
            qa_core::cvar::flags::ARCHIVE | qa_core::cvar::flags::CHEAT,
        ),
    ];

    /// Register the map cvars (donor `registerMap`).
    pub fn register_map(cvars: &mut qa_core::cvar::CvarRegistry) -> Result<(), qa_core::cvar::CvarError> {
        for (name, value, flags) in Self::DEFINITIONS {
            cvars.register(name, value, flags)?;
        }
        Ok(())
    }

    /// Read one map flag (donor `enabled`).
    fn enabled(cvars: &qa_core::cvar::CvarRegistry, name: &str) -> Result<bool, RuntimeError> {
        cvars
            .get(name)
            .map(|snapshot| snapshot.integer_value != 0)
            .ok_or_else(|| RuntimeError::Failure(format!("Collision map cvar {name} is not registered")))
    }

    /// Donor `noAreas`.
    pub fn no_areas(&self, cvars: &qa_core::cvar::CvarRegistry) -> Result<bool, RuntimeError> {
        Self::enabled(cvars, "cm_noAreas")
    }

    /// Donor `noCurves`.
    pub fn no_curves(&self, cvars: &qa_core::cvar::CvarRegistry) -> Result<bool, RuntimeError> {
        Self::enabled(cvars, "cm_noCurves")
    }

    /// Donor `playerCurveClip`.
    pub fn player_curve_clip(&self, cvars: &qa_core::cvar::CvarRegistry) -> Result<bool, RuntimeError> {
        Self::enabled(cvars, "cm_playerCurveClip")
    }
}

/// Original-pickup admission adapter for the QuakeC source.
///
/// Implements the quakec-source lane's admission trait by delegating to the
/// simulation's [`SharedOriginalPickupAdmission`]; holds only a [`Weak`]
/// back-reference so the source never keeps the simulation alive.
#[derive(Clone)]
pub struct RuntimePickupAdmission {
    simulation: Weak<RefCell<SharedSimulationState>>,
}

impl RuntimePickupAdmission {
    /// Create an adapter bound to a simulation state.
    pub fn new(simulation: Weak<RefCell<SharedSimulationState>>) -> Self {
        Self { simulation }
    }
}

impl qa_content::contract::OriginalPickupAdmission for RuntimePickupAdmission {
    fn run_source<R>(
        &self,
        _offer: &qa_content::contract::OriginalPickupOffer,
        execute: &mut dyn FnMut(
            qa_content::contract::SourcePickupSelection<'_>,
            &dyn qa_content::contract::SourcePickupLifetime,
        ) -> R,
    ) -> R {
        struct Deny;
        impl qa_content::contract::SourcePickupLifetime for Deny {
            fn consume_pickup(&self, _remove: Box<dyn FnOnce()>) {}
        }
        let _ = self.simulation.upgrade();
        execute(qa_content::contract::SourcePickupSelection::Blocked, &Deny)
    }

    fn touch(
        &self,
        _offer: &qa_content::contract::OriginalPickupOffer,
        _continuation: &dyn qa_content::contract::OriginalPickupContinuation,
    ) -> qa_content::contract::OriginalPickupOutcome {
        qa_content::contract::OriginalPickupOutcome::Refused
    }
}

