impl super::weapon_behavior_runtime::WeaponBehaviorAttachmentDriver for RuntimeWeaponAttachments {
    fn register(
        &mut self,
        id: &str,
        source: Rc<RefCell<dyn super::weapon_behavior_runtime::WeaponBehaviorSource>>,
    ) -> Result<(), super::weapon_behavior_runtime::WeaponBehaviorRuntimeError> {
        use super::weapon_behavior_runtime::WeaponBehaviorRuntimeError;
        if self.sources.contains_key(id) {
            return Err(WeaponBehaviorRuntimeError::Seam(format!(
                "Weapon behavior already registered: {id}"
            )));
        }
        self.sources.insert(id.to_string(), source);
        Ok(())
    }

    fn launch(
        &mut self,
        selection: &str,
        input: &super::weapon_behavior_runtime::WeaponBehaviorLaunch,
    ) -> Result<
        Option<super::weapon_behavior_runtime::WeaponTrajectoryUpdate>,
        super::weapon_behavior_runtime::WeaponBehaviorRuntimeError,
    > {
        use super::physics::PhysicsActors;
        use super::weapon_behavior_runtime::WeaponBehaviorRuntimeError;
        let fail = |message: String| WeaponBehaviorRuntimeError::Seam(message);
        if self.actors.resolve_owned(input.projectile.id()).is_none() {
            return Err(fail("Weapon behavior projectile is retired".to_string()));
        }
        if !self.actors.is_live(&input.shooter) {
            return Err(fail("Weapon behavior shooter is retired".to_string()));
        }
        let Some(source) = self.sources.get(selection) else {
            return Err(fail(format!("Weapon behavior is unavailable: {selection}")));
        };
        if source.borrow().definition().role != input.role {
            return Err(fail(
                "Weapon behavior does not match the fired projectile role".to_string(),
            ));
        }
        if self.instances.borrow().contains_key(input.projectile.id()) {
            return Err(fail(
                "Projectile already has a selected trajectory behavior".to_string(),
            ));
        }
        let Some(instance) = source.borrow_mut().attach(input) else {
            return Ok(None);
        };
        let initial = *instance.initial();
        self.instances.borrow_mut().insert(
            input.projectile.id().clone(),
            WeaponAttachmentInstance {
                owner: input.projectile.clone(),
                instance,
            },
        );
        Ok(Some(initial))
    }

    fn controls_trajectory(&self, projectile: &ActorId) -> bool {
        self.instances.borrow().contains_key(projectile)
    }

    fn step(
        &mut self,
        projectile: &OwnedActor,
        body: &qa_world::body::BodyState,
        time_seconds: f64,
    ) -> Result<
        Option<super::weapon_behavior_runtime::WeaponTrajectoryUpdate>,
        super::weapon_behavior_runtime::WeaponBehaviorRuntimeError,
    > {
        use super::physics::PhysicsActors;
        use super::weapon_behavior_runtime::WeaponBehaviorRuntimeError;
        if self.actors.resolve_owned(projectile.id()).is_none() {
            return Err(WeaponBehaviorRuntimeError::Seam(
                "Weapon behavior projectile is retired".to_string(),
            ));
        }
        let mut instances = self.instances.borrow_mut();
        let Some(entry) = instances.get_mut(projectile.id()) else {
            return Ok(None);
        };
        if entry.owner != *projectile {
            return Err(WeaponBehaviorRuntimeError::Seam(
                "Weapon behavior actor ownership changed".to_string(),
            ));
        }
        Ok(entry.instance.step(body, time_seconds))
    }

    fn checkpoint(&self) -> super::weapon_behavior_runtime::WeaponBehaviorAttachmentCheckpoint {
        use super::weapon_behavior_runtime::{WeaponBehaviorAttachmentCheckpoint, WeaponBehaviorAttachmentEntry};
        WeaponBehaviorAttachmentCheckpoint {
            version: 1,
            attachments: self
                .instances
                .borrow()
                .values()
                .map(|entry| WeaponBehaviorAttachmentEntry {
                    projectile: qa_core::identity::SavedActorId::from(entry.owner.id()),
                    owner: entry.owner.owner().clone(),
                    definition: entry.instance.definition().clone(),
                })
                .collect(),
        }
    }

    fn restore(
        &mut self,
        checkpoint: &super::weapon_behavior_runtime::WeaponBehaviorAttachmentCheckpoint,
    ) -> Result<(), super::weapon_behavior_runtime::WeaponBehaviorRuntimeError> {
        use super::physics::PhysicsActors;
        use super::weapon_behavior_runtime::WeaponBehaviorRuntimeError;
        let fail = |message: &str| WeaponBehaviorRuntimeError::Seam(message.to_string());
        if checkpoint.version != 1 || !self.instances.borrow().is_empty() {
            return Err(fail(
                "Weapon behavior attachments require an empty matching checkpoint owner",
            ));
        }
        let mut seen = HashSet::new();
        let mut pending = Vec::new();
        for entry in &checkpoint.attachments {
            let owner = self.actors.resolve_saved(entry.projectile);
            let source = self.sources.get(&entry.definition.id);
            let same = source.is_some_and(|source| {
                let definition = source.borrow();
                let definition = definition.definition();
                definition.id == entry.definition.id
                    && definition.role == entry.definition.role
                    && definition.module == entry.definition.module
                    && definition.fire == entry.definition.fire
                    && definition.activate == entry.definition.activate
            });
            let Some(owner) = owner else {
                return Err(fail("Saved weapon behavior owner or source differs"));
            };
            if owner.owner() != &entry.owner || source.is_none() || !same || !seen.insert(owner.id().clone()) {
                return Err(fail("Saved weapon behavior owner or source differs"));
            }
            pending.push((owner, entry.definition.id.clone()));
        }
        for (owner, id) in pending {
            let resumed = self
                .sources
                .get(&id)
                .map(|source| source.borrow_mut().resume(owner.id()));
            match resumed {
                Some(instance) => {
                    self.instances
                        .borrow_mut()
                        .insert(owner.id().clone(), WeaponAttachmentInstance { owner, instance });
                }
                None => {
                    let owned: Vec<ActorId> = self.instances.borrow().keys().cloned().collect();
                    for actor in owned {
                        self.detach(&actor);
                    }
                    return Err(fail("Saved weapon behavior owner or source differs"));
                }
            }
        }
        Ok(())
    }

    fn close(&mut self) -> Result<(), super::weapon_behavior_runtime::WeaponBehaviorRuntimeError> {
        let owned: Vec<ActorId> = self.instances.borrow().keys().cloned().collect();
        for actor in owned {
            self.detach(&actor);
        }
        self.sources.clear();
        Ok(())
    }
}

