/// Cross-representation native execution match (donor `isDeepStrictEqual`).
///
/// The recipe carries contract execution modules while prepared guests carry
/// persistence modules; the discriminating owner, role, API, ABI, and
/// artifact fields are compared instead of the representations.
pub fn native_execution_matches(
    recipe: &qa_content::contract::ResolvedExecutionModule,
    guest: Option<&super::types::NativeQ2GuestOptions>,
) -> bool {
    use qa_content::contract::{ExecutionModule, ModuleRole, NativeAbi, NativeModuleApi};
    use qa_guest::checkpoint::{GameApi, NativeCallAbi};
    let ExecutionModule::Native {
        owner,
        artifact,
        profile,
        role,
        api,
    } = recipe
    else {
        return false;
    };
    if *role != ModuleRole::ServerGame {
        return false;
    }
    let (execution, expected_api, expected_profile) = match guest {
        Some(super::types::NativeQ2GuestOptions::Classic { prepared, .. }) => (
            &prepared.execution,
            NativeModuleApi::Q2ClassicGame,
            NativeAbi::WindowsI386,
        ),
        Some(super::types::NativeQ2GuestOptions::Rerelease { prepared, .. }) => (
            &prepared.execution,
            NativeModuleApi::Q2RereleaseGame,
            NativeAbi::WindowsX86_64,
        ),
        None => return false,
    };
    if *api != expected_api || *profile != expected_profile {
        return false;
    }
    if execution.role != "server-game" {
        return false;
    }
    let api_ok = matches!(
        (&execution.api, api),
        (GameApi::Q2ClassicGame, NativeModuleApi::Q2ClassicGame)
            | (GameApi::Q2RereleaseGame, NativeModuleApi::Q2RereleaseGame)
    );
    let profile_ok = matches!(
        (&execution.implementation, profile),
        (
            crate::persistence::recipe::ExecutionImplementation::Native {
                profile: NativeCallAbi::WindowsI386 { .. },
                ..
            },
            NativeAbi::WindowsI386,
        ) | (
            crate::persistence::recipe::ExecutionImplementation::Native {
                profile: NativeCallAbi::WindowsX8664,
                ..
            },
            NativeAbi::WindowsX86_64,
        )
    );
    let artifact_ok = match &execution.implementation {
        crate::persistence::recipe::ExecutionImplementation::Native {
            artifact: prepared_artifact,
            ..
        } => prepared_artifact.requested_path == artifact.requested_path,
        _ => false,
    };
    api_ok
        && profile_ok
        && artifact_ok
        && execution.owner.provider == provider_text(&owner.provider)
        && execution.owner.content == owner.content.as_str()
}

/// Cross-representation QVM execution match (donor `isDeepStrictEqual`).
pub fn qvm_execution_matches(
    recipe: &qa_content::contract::ResolvedExecutionModule,
    prepared: &crate::persistence::recipe::ResolvedExecutionModule,
) -> bool {
    use qa_content::contract::{ExecutionModule, ModuleRole, Q3ApiIdentity};
    use qa_guest::checkpoint::GameApi;
    let ExecutionModule::Qvm {
        owner,
        artifact,
        role,
        api,
    } = recipe
    else {
        return false;
    };
    if *role != ModuleRole::ServerGame {
        return false;
    }
    if prepared.role != "server-game" {
        return false;
    }
    let api_ok = match (&prepared.api, api) {
        (GameApi::Q3Qagame { version }, Q3ApiIdentity::Qagame(recipe_version)) => {
            *version == i64::from(*recipe_version)
        }
        _ => false,
    };
    let artifact_ok = match &prepared.implementation {
        crate::persistence::recipe::ExecutionImplementation::Qvm {
            artifact: prepared_artifact,
        } => prepared_artifact.requested_path == artifact.requested_path,
        _ => false,
    };
    api_ok
        && artifact_ok
        && prepared.owner.provider == provider_text(&owner.provider)
        && prepared.owner.content == owner.content.as_str()
}

/// Cross-representation QuakeC execution match (donor `isDeepStrictEqual`).
pub fn quakec_execution_matches(
    recipe: &qa_content::contract::ResolvedExecutionModule,
    prepared: &super::quakec_source::QuakeCExecution,
) -> bool {
    use qa_content::contract::ExecutionModule;
    let ExecutionModule::Quakec { owner, artifact, api } = recipe else {
        return false;
    };
    *api == prepared.api
        && prepared.owner.provider == owner.provider
        && prepared.owner.content == owner.content.as_str()
        && prepared.artifact.requested_path == artifact.requested_path
}

