impl SharedInventoryTable {
    /// Create an actor store with initial entries (donor `create`).
    pub fn create(
        &mut self,
        registry: &qa_world::registry::ActorRegistry,
        actor: &OwnedActor,
        entries: &[InventoryEntry],
    ) -> Result<(), RuntimeError> {
        let converted: Vec<qa_world::inventory::InventoryEntry> = entries.iter().map(contract_entry_to_world).collect();
        Ok(self.inner_mut().create(registry, actor, &converted)?)
    }

    /// Entries of a live actor (donor `entries`).
    pub fn entries(&self, registry: &qa_world::registry::ActorRegistry, actor: &ActorId) -> Vec<InventoryEntry> {
        self.inner()
            .entries(registry, actor)
            .iter()
            .map(world_entry_to_contract)
            .collect()
    }

    /// Configure one entry directly (donor `configure`).
    pub fn configure(
        &mut self,
        registry: &qa_world::registry::ActorRegistry,
        actor: &OwnedActor,
        entry: InventoryEntry,
    ) -> Result<(), RuntimeError> {
        Ok(self
            .inner_mut()
            .configure(registry, actor, contract_entry_to_world(&entry))?)
    }
}

impl FrameScheduler {
    /// Schedule a think (donor `schedule`).
    pub fn schedule(
        &self,
        registry: &qa_world::registry::ActorRegistry,
        actor: &OwnedActor,
        callback: &str,
        timing: qa_world::scheduler::ThinkTiming,
    ) -> Result<(), RuntimeError> {
        Ok(self.inner().schedule(
            registry,
            actor,
            callback,
            timing,
            qa_world::scheduler::ScheduleOptions {
                registered_execution: None,
                source_slot: None,
            },
        )?)
    }
}

