/// Completed policy decision before commit.
struct RuntimeCompleteDecision {
    mutations: Vec<super::events::DamageMutation>,
    applied_damage: f64,
    reaction: super::events::DamageReaction,
    feedback: Option<super::events::DamageFeedback>,
}

fn complete_decision(
    mutations: Vec<super::events::DamageMutation>,
    applied_damage: f64,
    reaction: super::events::DamageReaction,
    feedback: Option<super::events::DamageFeedback>,
) -> RuntimeCompleteDecision {
    RuntimeCompleteDecision {
        mutations,
        applied_damage,
        reaction,
        feedback,
    }
}

/// Donor `numberFor`: per-operation arithmetic rounding.
fn policy_round(arithmetic: qa_world::combat::ArmorArithmetic, value: f64) -> f64 {
    if arithmetic == qa_world::combat::ArmorArithmetic::Binary32 {
        f64::from(value as f32)
    } else {
        value
    }
}

/// Donor `scale`: directed impulse with per-operation rounding.
fn policy_scale(direction: Vec3, amount: f64, arithmetic: qa_world::combat::ArmorArithmetic) -> Vec3 {
    let round = |value: f64| policy_round(arithmetic, value);
    let x = round(f64::from(direction.x));
    let y = round(f64::from(direction.y));
    let z = round(f64::from(direction.z));
    let length = round(round(round(x * x) + round(y * y)) + round(z * z)).sqrt();
    if length == 0.0 {
        return zero();
    }
    let inverse = round(1.0 / length);
    Vec3 {
        x: round(round(x * inverse) * amount) as f32,
        y: round(round(y * inverse) * amount) as f32,
        z: round(round(z * inverse) * amount) as f32,
    }
}

/// Donor `selfDamage`.
fn policy_self_damage(request: &super::events::DamageRequest) -> bool {
    request
        .attack
        .attacker
        .as_ref()
        .is_some_and(|attacker| qa_core::identity::same_actor(&request.target, attacker))
}

/// Donor `sameTeam`.
fn policy_same_team(target: &qa_world::combat::CombatState, attacker: Option<&qa_world::combat::CombatState>) -> bool {
    target.team.as_ref().is_some_and(|team| !team.is_empty())
        && attacker.is_some_and(|attacker| target.team == attacker.team)
}

/// Donor `addImpulse`.
fn policy_add_impulse(
    request: &super::events::DamageRequest,
    mutations: &mut Vec<super::events::DamageMutation>,
    direction: Vec3,
    amount: f64,
    arithmetic: qa_world::combat::ArmorArithmetic,
) {
    if amount != 0.0 {
        mutations.push(super::events::DamageMutation::Impulse {
            impulse: policy_scale(direction, amount, arithmetic),
            movement_provider: request.attack.movement_provider.clone(),
        });
    }
}

/// Convert an events attack cause to world damage flags input.
///
/// Environment causes carry no native flags, matching the donor's
/// `attackDamageFlags` fallthrough.
fn policy_damage_cause(cause: &super::events::AttackCause) -> qa_world::combat::DamageCause {
    use qa_world::combat::{DamageCause, Q1ArmorEffect};
    match cause {
        super::events::AttackCause::Q1 { armor_effect, .. } => DamageCause::Q1 {
            armor_effect: match armor_effect {
                Some(super::events::AttackArmorEffect::Bypass) => Q1ArmorEffect::Bypass,
                Some(super::events::AttackArmorEffect::HalfEffectiveness) => Q1ArmorEffect::Half,
                None => Q1ArmorEffect::Full,
            },
        },
        super::events::AttackCause::Q2 { damage_flags, .. } => DamageCause::Q2 {
            damage_flags: *damage_flags,
        },
        super::events::AttackCause::Q3 { damage_flags, .. } => DamageCause::Q3 {
            damage_flags: *damage_flags,
        },
        super::events::AttackCause::Environment { .. } => DamageCause::Q1 {
            armor_effect: Q1ArmorEffect::Full,
        },
    }
}

impl GameplayAuthority {
    /// Create a copied combat binding (donor `create`).
    pub fn create(&self, actor: &OwnedActor, initial: qa_world::combat::CombatState) -> Result<(), RuntimeError> {
        if matches!(initial.armor.regular, qa_world::combat::RegularArmor::Source { .. }) {
            return fail("Copied primary armor cannot own a source formula");
        }
        let mut states = self.combat_states.borrow_mut();
        if states.contains_key(actor.id()) {
            return fail("Actor already has a combat binding");
        }
        states.insert(actor.id().clone(), initial);
        Ok(())
    }

    /// Write health (donor `setHealth`).
    pub fn set_health(&self, actor: &OwnedActor, health: f64) -> Result<(), RuntimeError> {
        if !health.is_finite() {
            return range("Health must be finite");
        }
        let mut states = self.combat_states.borrow_mut();
        let Some(state) = states.get_mut(actor.id()) else {
            return fail("Actor has no combat binding");
        };
        state.health = health;
        Ok(())
    }

    /// Write traits (donor `setTraits`).
    pub fn set_traits(
        &self,
        actor: &OwnedActor,
        changes: qa_content::q2::support::contracts::CombatTraitChanges,
    ) -> Result<(), RuntimeError> {
        let mut states = self.combat_states.borrow_mut();
        let Some(state) = states.get_mut(actor.id()) else {
            return fail("Actor has no combat binding");
        };
        if let Some(can_take_damage) = changes.can_take_damage {
            state.can_take_damage = can_take_damage;
        }
        if let Some(mass) = changes.mass {
            if !mass.is_finite() {
                return range("Actor mass must be finite");
            }
            state.mass = mass;
        }
        if let Some(invulnerable) = changes.invulnerable {
            state.invulnerable = invulnerable;
        }
        if let Some(team) = changes.team {
            state.team = team;
        }
        if let Some(no_knockback) = changes.no_knockback {
            state.no_knockback = no_knockback;
        }
        Ok(())
    }

    /// Read a state with the team hook applied (donor `readState` team step).
    fn combat_state_for(
        &self,
        actor: &ActorId,
        states: &HashMap<ActorId, qa_world::combat::CombatState>,
    ) -> Option<qa_world::combat::CombatState> {
        let mut state = states.get(actor)?.clone();
        if let Some(hooks) = self.hooks.as_ref() {
            state.team = (hooks.team)(actor, state.team.clone());
        }
        Some(state)
    }

    /// Apply damage through the canonical policy pipeline (donor
    /// `apply`/`applyCanonical`).
    ///
    /// The donor runs policy continuations through cursor-observed mutation
    /// commits; with source-owned bindings living in their own combat
    /// tables, every armor stage here takes the synchronous fallback and
    /// every continuation resumes immediately, so the pipeline runs
    /// straight-line with the same read order, mutation order, and hook
    /// calls. The registry borrow stays narrow: it covers decide/commit
    /// only, never the die/pain outcalls. Missing callbacks (construction
    /// has not wired them yet) skip firing rather than failing.
    pub fn apply(&self, request: super::events::DamageRequest) -> Result<super::events::DamageOutcome, RuntimeError> {
        use super::events::{DamageOutcome, DamageReaction};
        let actors = match self.actors.as_ref() {
            Some(actors) => Rc::clone(actors),
            None => {
                return Ok(DamageOutcome::StaleTarget {
                    request: request.clone(),
                });
            }
        };
        let Some(target) = actors.borrow().resolve_owned(&request.target) else {
            return Ok(DamageOutcome::StaleTarget {
                request: request.clone(),
            });
        };
        let policy = self.policies.get(&request.attack.combat_provider).cloned();
        let Some(policy) = policy else {
            return fail(format!(
                "Missing combat policy: {}",
                provider_text(&request.attack.combat_provider)
            ));
        };
        let mut decision = {
            let registry = actors.borrow();
            if !registry.is_live(target.id()) {
                return Ok(DamageOutcome::StaleTarget {
                    request: request.clone(),
                });
            }
            let allowed = self.hooks.as_ref().is_none_or(|hooks| (hooks.damage_allowed)(&request));
            let read_target = || {
                let states = self.combat_states.borrow();
                self.combat_state_for(target.id(), &states)
            };
            let read_attacker = || {
                let attacker = request.attack.attacker.clone()?;
                let states = self.combat_states.borrow();
                self.combat_state_for(&attacker, &states)
            };
            let Some(initial) = read_target() else {
                return fail("Actor has no combat binding");
            };
            let decision = if !allowed {
                complete_decision(Vec::new(), 0.0, DamageReaction::None, None)
            } else {
                match &policy.kind {
                    RuntimeCombatPolicyKind::Q1 {
                        context,
                        armor,
                        source_effects,
                    } => {
                        let attacker = read_attacker();
                        let prepared = self.prepare_q1(&request, &initial, attacker.as_ref(), context, source_effects);
                        match prepared {
                            RuntimeDamagePreparation::Cancel => {
                                complete_decision(Vec::new(), 0.0, DamageReaction::None, None)
                            }
                            RuntimeDamagePreparation::Continue { amount } => self.decide_q1(
                                &request,
                                &target,
                                &initial,
                                &registry,
                                context,
                                armor,
                                source_effects,
                                Some(amount),
                            )?,
                        }
                    }
                    RuntimeCombatPolicyKind::Q2 {
                        context,
                        armor,
                        source_effects,
                    } => self.decide_q2(&request, &initial, &registry, context, armor, source_effects.as_ref())?,
                }
            };
            if !decision.applied_damage.is_finite() {
                return fail("Combat applied damage must be finite");
            }
            self.commit_decision(&target, &registry, &decision)?;
            super::events::DamageDecision {
                request: request.clone(),
                mutations: decision.mutations,
                applied_damage: decision.applied_damage,
                reaction: decision.reaction,
                feedback: decision.feedback,
            }
        };
        if let RuntimeCombatPolicyKind::Q2 {
            context,
            source_effects,
            ..
        } = &policy.kind
        {
            let has_health = decision
                .mutations
                .iter()
                .any(|mutation| matches!(mutation, super::events::DamageMutation::Health { .. }));
            if source_effects.is_some() && has_health && actors.borrow().is_live(target.id()) {
                decision.reaction = self.after_health_q2(&decision, context, source_effects.as_ref());
            }
        }
        if actors.borrow().is_live(target.id()) {
            if let Some(hooks) = self.hooks.as_ref() {
                (hooks.before_reaction)(&target, &decision);
            }
        }
        if actors.borrow().is_live(target.id()) {
            let kick = match &decision.feedback {
                Some(super::events::DamageFeedback::Q2 { knockback, .. }) => *knockback,
                _ => request.knockback,
            };
            if let Some(callbacks) = self.callbacks.as_ref() {
                let registry = actors.borrow();
                let table = callbacks.borrow();
                if decision.reaction == DamageReaction::Death {
                    let _ = table.fire_die(
                        &registry,
                        &RuntimeDeathReaction {
                            attack: Some(request.attack.clone()),
                            target: target.clone(),
                            attacker: request.attack.attacker.clone(),
                            kick,
                            damage: decision.applied_damage,
                            inflictor: request.attack.inflictor.clone(),
                            point: request.point,
                        },
                    )?;
                } else if decision.reaction == DamageReaction::Pain {
                    let _ = table.fire_pain(
                        &registry,
                        &RuntimePainReaction {
                            attack: Some(request.attack.clone()),
                            target: target.clone(),
                            attacker: request.attack.attacker.clone(),
                            kick,
                            damage: decision.applied_damage,
                        },
                    )?;
                }
            }
        }
        let survived = self
            .combat_states
            .borrow()
            .get(target.id())
            .is_some_and(|state| state.health > 0.0);
        let outcome = DamageOutcome::Committed { decision, survived };
        if let Some(hooks) = self.hooks.as_ref() {
            (hooks.confirmed)(&outcome);
        }
        Ok(outcome)
    }

    /// Q1 preparation stage (donor `createQ1CombatPolicy` `prepare`).
    #[allow(clippy::type_complexity)]
    fn prepare_q1(
        &self,
        request: &super::events::DamageRequest,
        target: &qa_world::combat::CombatState,
        attacker: Option<&qa_world::combat::CombatState>,
        context: &Rc<
            dyn Fn(
                &super::events::DamageRequest,
                &qa_world::combat::CombatState,
                Option<&qa_world::combat::CombatState>,
            ) -> qa_content::q1::foundation::gameplay::Q1CombatContext,
        >,
        source_effects: &Q1PolicySourceEffects,
    ) -> RuntimeDamagePreparation {
        use qa_content::q1::foundation::gameplay::Q1CombatArithmetic;
        if !target.can_take_damage {
            return RuntimeDamagePreparation::Cancel;
        }
        let first = context(request, target, attacker);
        let to_arithmetic = |context: &qa_content::q1::foundation::gameplay::Q1CombatContext| {
            if context.arithmetic == Q1CombatArithmetic::Binary32 {
                qa_world::combat::ArmorArithmetic::Binary32
            } else {
                qa_world::combat::ArmorArithmetic::Binary64
            }
        };
        let round = |value: f64| policy_round(to_arithmetic(&first), value);
        let before = source_effects
            .before_quad
            .as_ref()
            .map(|stage| stage(request, round(request.amount), target, attacker));
        if matches!(before, Some(RuntimeDamagePreparation::Cancel)) {
            return RuntimeDamagePreparation::Cancel;
        }
        let quad = request.attack.damage_powerup_owner.is_none()
            && if source_effects.before_quad.is_none() {
                first.quad
            } else {
                context(request, target, attacker).quad
            };
        let damage = round(
            round(match before {
                Some(RuntimeDamagePreparation::Continue { amount }) => amount,
                _ => request.amount,
            }) * if quad { 4.0 } else { 1.0 },
        );
        let after = source_effects
            .after_quad
            .as_ref()
            .map(|stage| stage(request, damage, target, attacker));
        if matches!(after, Some(RuntimeDamagePreparation::Cancel)) {
            return RuntimeDamagePreparation::Cancel;
        }
        RuntimeDamagePreparation::Continue {
            amount: round(match after {
                Some(RuntimeDamagePreparation::Continue { amount }) => amount,
                _ => damage,
            }),
        }
    }

    /// Run one armor stage through the synchronous fallback (donor
    /// `applyCanonical` armor-stage fallback path).
    ///
    /// Returns `None` when the target retired mid-pipeline.
    #[allow(clippy::too_many_arguments)]
    fn armor_stage(
        &self,
        target: &OwnedActor,
        actors: &SessionActorRegistry,
        request: &super::events::DamageRequest,
        channel: qa_content::contract::ProtectionChannel,
        amount: f64,
        flags: &ArmorDamageFlags,
        armor: &RuntimeVictimArmor,
        mutations: &mut Vec<super::events::DamageMutation>,
    ) -> Result<Option<f64>, RuntimeError> {
        use qa_content::contract::ProtectionChannel;
        use qa_world::combat::ArmorStage;
        if !actors.is_live(target.id()) {
            return Ok(None);
        }
        let states = self.combat_states.borrow();
        let Some(current) = self.combat_state_for(target.id(), &states) else {
            return Ok(None);
        };
        drop(states);
        let staged = ArmorDamageFlags {
            stage: Some(if channel == ProtectionChannel::Powered {
                ArmorStage::Power
            } else {
                ArmorStage::Regular
            }),
            ..*flags
        };
        let absorbed = armor(request, &current.armor, amount, &staged)?;
        let saved = if channel == ProtectionChannel::Regular {
            absorbed.regular_saved
        } else {
            absorbed.power_saved
        };
        let other_unchanged = if channel == ProtectionChannel::Regular {
            absorbed.power_saved == 0.0
                && qa_world::combat::ArmorState {
                    regular: current.armor.regular.clone(),
                    ..absorbed.armor.clone()
                } == current.armor
        } else {
            absorbed.regular_saved == 0.0 && absorbed.armor.regular == current.armor.regular
        };
        if !other_unchanged || !saved.is_finite() {
            return fail("Armor fallback changed another channel or returned invalid savings");
        }
        if absorbed.armor != current.armor {
            let mut states = self.combat_states.borrow_mut();
            let Some(live) = states.get_mut(target.id()) else {
                return Ok(None);
            };
            if live.armor != current.armor {
                return fail("Combat armor changed before its decision committed");
            }
            live.armor = absorbed.armor.clone();
            mutations.push(super::events::DamageMutation::Armor {
                before: world_armor_to_contract(&current.armor),
                after: world_armor_to_contract(&absorbed.armor),
            });
        }
        Ok(Some(saved))
    }

    /// Q1 decision stage (donor `createQ1CombatPolicy` `decide`).
    #[allow(clippy::too_many_arguments)]
    #[allow(clippy::type_complexity)]
    fn decide_q1(
        &self,
        request: &super::events::DamageRequest,
        target: &OwnedActor,
        initial: &qa_world::combat::CombatState,
        actors: &SessionActorRegistry,
        context: &Rc<
            dyn Fn(
                &super::events::DamageRequest,
                &qa_world::combat::CombatState,
                Option<&qa_world::combat::CombatState>,
            ) -> qa_content::q1::foundation::gameplay::Q1CombatContext,
        >,
        armor: &RuntimeVictimArmor,
        source_effects: &Q1PolicySourceEffects,
        prepared: Option<f64>,
    ) -> Result<RuntimeCompleteDecision, RuntimeError> {
        use super::events::DamageReaction;
        use qa_content::contract::ProtectionChannel;
        use qa_content::q1::foundation::gameplay::Q1CombatArithmetic;
        if !initial.can_take_damage {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        }
        let first = context(request, initial, self.live_attacker(request).as_ref());
        let arithmetic = if first.arithmetic == Q1CombatArithmetic::Binary32 {
            qa_world::combat::ArmorArithmetic::Binary32
        } else {
            qa_world::combat::ArmorArithmetic::Binary64
        };
        let round = |value: f64| policy_round(arithmetic, value);
        let damage = prepared.unwrap_or_else(|| {
            round(
                round(request.amount)
                    * if first.quad && request.attack.damage_powerup_owner.is_none() {
                        4.0
                    } else {
                        1.0
                    },
            )
        });
        let live_target = || {
            let states = self.combat_states.borrow();
            self.combat_state_for(&request.target, &states)
        };
        let live_attacker = || self.live_attacker(request);
        let victim = live_target();
        if victim.is_none() {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        }
        let allowed = source_effects
            .armor_allowed
            .as_ref()
            .is_none_or(|stage| stage(request, damage, &victim.clone().unwrap(), live_attacker().as_ref()));
        let latest = live_target();
        if latest.is_none() {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        }
        let take = if !allowed {
            (round(damage)).ceil()
        } else {
            let mut staged = Vec::new();
            let flags = attack_damage_flags(&policy_damage_cause(&request.attack.cause));
            let power = self.armor_stage(
                target,
                actors,
                request,
                ProtectionChannel::Powered,
                damage,
                &flags.armor,
                armor,
                &mut staged,
            )?;
            let Some(power) = power else {
                return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
            };
            let saved = self.armor_stage(
                target,
                actors,
                request,
                ProtectionChannel::Regular,
                damage - power,
                &flags.armor,
                armor,
                &mut staged,
            )?;
            let Some(saved) = saved else {
                return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
            };
            let latest = live_target();
            if latest.is_none() {
                return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
            }
            let take = round(damage - (power + saved)).ceil();
            let mut tail = self.after_armor_q1(
                request,
                actors,
                context,
                source_effects,
                damage,
                take,
                !latest.unwrap().no_knockback,
            )?;
            let mut mutations = staged;
            mutations.append(&mut tail.mutations);
            return Ok(RuntimeCompleteDecision {
                mutations,
                applied_damage: tail.applied_damage,
                reaction: tail.reaction,
                feedback: tail.feedback,
            });
        };
        self.after_armor_q1(
            request,
            actors,
            context,
            source_effects,
            damage,
            take,
            !latest.unwrap().no_knockback,
        )
    }

    /// Q1 post-armor stage (donor `afterArmor` inside `decide`).
    #[allow(clippy::too_many_arguments)]
    #[allow(clippy::type_complexity)]
    fn after_armor_q1(
        &self,
        request: &super::events::DamageRequest,
        _actors: &SessionActorRegistry,
        context: &Rc<
            dyn Fn(
                &super::events::DamageRequest,
                &qa_world::combat::CombatState,
                Option<&qa_world::combat::CombatState>,
            ) -> qa_content::q1::foundation::gameplay::Q1CombatContext,
        >,
        source_effects: &Q1PolicySourceEffects,
        damage: f64,
        take: f64,
        victim_knockable: bool,
    ) -> Result<RuntimeCompleteDecision, RuntimeError> {
        use super::events::{DamageMutation, DamageReaction};
        use qa_content::q1::foundation::gameplay::Q1CombatArithmetic;
        let live_target = || {
            let states = self.combat_states.borrow();
            self.combat_state_for(&request.target, &states)
        };
        let live_attacker = || self.live_attacker(request);
        let Some(probe) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let policy_context = context(request, &probe, live_attacker().as_ref());
        let arithmetic = if policy_context.arithmetic == Q1CombatArithmetic::Binary32 {
            qa_world::combat::ArmorArithmetic::Binary32
        } else {
            qa_world::combat::ArmorArithmetic::Binary64
        };
        let round = |value: f64| policy_round(arithmetic, value);
        let mut mutations = Vec::new();
        if let Some(momentum_direction) = policy_context.momentum_direction {
            if policy_context.walk && victim_knockable {
                policy_add_impulse(
                    request,
                    &mut mutations,
                    momentum_direction,
                    round(damage * 8.0),
                    arithmetic,
                );
            }
        }
        let Some(latest) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let protected = latest.invulnerable
            && source_effects
                .protection_applies
                .as_ref()
                .is_none_or(|stage| stage(request, &latest, live_attacker().as_ref()));
        let Some(latest) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        if protected
            || policy_context.base_team_health
                && policy_context.teamplay == 1
                && policy_same_team(&latest, live_attacker().as_ref())
        {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        }
        if source_effects
            .before_health
            .as_ref()
            .is_some_and(|stage| !stage(request, damage, &latest, live_attacker().as_ref()))
        {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        }
        let Some(latest) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let health_take = round(
            source_effects
                .after_armor
                .as_ref()
                .map_or(take, |stage| stage(request, take, &latest, live_attacker().as_ref())),
        );
        let Some(latest) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let health = (-99.0f64).max(round(latest.health - health_take));
        let lethal = if health <= 0.0 {
            source_effects
                .lethal_health
                .as_ref()
                .map(|stage| stage(request, health, &latest, live_attacker().as_ref()))
        } else {
            None
        };
        let Some(latest) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let mut all = mutations;
        all.push(DamageMutation::Health {
            before: latest.health,
            after: lethal.as_ref().map_or(health, |lethal| lethal.health),
        });
        Ok(complete_decision(
            all,
            health_take,
            match lethal {
                Some(lethal) => match lethal.reaction {
                    RuntimeLethalReaction::None => DamageReaction::None,
                    RuntimeLethalReaction::Death => DamageReaction::Death,
                },
                None => {
                    if health <= 0.0 {
                        DamageReaction::Death
                    } else {
                        DamageReaction::Pain
                    }
                }
            },
            None,
        ))
    }

    /// Read the live attacker state for a request, if any.
    fn live_attacker(&self, request: &super::events::DamageRequest) -> Option<qa_world::combat::CombatState> {
        let attacker = request.attack.attacker.clone()?;
        let states = self.combat_states.borrow();
        self.combat_state_for(&attacker, &states)
    }

    /// Q2 decision stage (donor `createQ2CombatPolicy` `decide`).
    #[allow(clippy::type_complexity)]
    fn decide_q2(
        &self,
        request: &super::events::DamageRequest,
        initial: &qa_world::combat::CombatState,
        actors: &SessionActorRegistry,
        context: &Rc<
            dyn Fn(
                &super::events::DamageRequest,
                &qa_world::combat::CombatState,
                Option<&qa_world::combat::CombatState>,
            ) -> Q2PolicyContext,
        >,
        armor: &RuntimeVictimArmor,
        source_effects: Option<&Q2PolicySourceEffects>,
    ) -> Result<RuntimeCompleteDecision, RuntimeError> {
        use super::events::{DamageFeedback, DamageMutation, DamageReaction};
        use qa_content::contract::ProtectionChannel;
        if !initial.can_take_damage {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        }
        let policy_context = context(request, initial, self.live_attacker(request).as_ref());
        let flags = attack_damage_flags(&policy_damage_cause(&request.attack.cause));
        let round = |value: f64| policy_round(policy_context.arithmetic, value);
        let mut damage = request.amount.trunc();
        if !policy_self_damage(request)
            && policy_context.team_damage_enabled
            && policy_same_team(initial, self.live_attacker(request).as_ref())
            && !policy_context.friendly_fire
            && !policy_context.nuke
        {
            damage = 0.0;
        }
        if policy_context.easy_skill && !policy_context.deathmatch && policy_context.player {
            damage = 1.0f64.max((damage * 0.5).trunc());
        }
        if policy_context.defender_sphere && policy_context.player {
            damage = 1.0f64.max((damage * 0.5).trunc());
        }
        if request.delivery != super::events::DamageDelivery::Radius
            && policy_context.monster
            && policy_context.attacker_player
            && !policy_context.has_enemy
            && initial.health > 0.0
        {
            damage = (damage * 2.0).trunc();
        }
        let base_damage = damage;
        let live_target = || {
            let states = self.combat_states.borrow();
            self.combat_state_for(&request.target, &states)
        };
        let live_attacker = || self.live_attacker(request);
        let Some(victim) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let damage = source_effects
            .and_then(|effects| effects.before_momentum.as_ref())
            .map_or(base_damage, |stage| {
                stage(request, base_damage, &victim, live_attacker().as_ref())
            })
            .trunc();
        let Some(victim) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let mut mutations = Vec::new();
        let knockback = if policy_context.no_knockback || victim.no_knockback {
            0.0
        } else {
            request.knockback.trunc()
        };
        if !flags.no_knockback && policy_context.movable {
            let coefficient = if policy_context.player && policy_self_damage(request) {
                1600.0
            } else {
                500.0
            };
            policy_add_impulse(
                request,
                &mut mutations,
                request.direction,
                round(round(coefficient * knockback) / 50.0f64.max(victim.mass)),
                policy_context.arithmetic,
            );
        }
        let Some(victim) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let protection_saved = if victim.invulnerable && !flags.no_protection {
            damage
        } else {
            0.0
        };
        let amount = damage - protection_saved;
        let allowed = source_effects
            .and_then(|effects| effects.power_armor_allowed.as_ref())
            .is_none_or(|stage| stage(request, &victim, live_attacker().as_ref()));
        let Some(target) = actors.resolve_owned(&request.target) else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let power_saved = if !allowed {
            0.0
        } else {
            let saved = self.armor_stage(
                &target,
                actors,
                request,
                ProtectionChannel::Powered,
                amount,
                &flags.armor,
                armor,
                &mut mutations,
            )?;
            let Some(saved) = saved else {
                return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
            };
            saved
        };
        let Some(victim) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let after_power_take = source_effects
            .and_then(|effects| effects.after_power_armor.as_ref())
            .map_or(amount - power_saved, |stage| {
                stage(request, amount - power_saved, &victim, live_attacker().as_ref())
            })
            .trunc();
        let Some(victim) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let regular_allowed = source_effects
            .and_then(|effects| effects.armor_allowed.as_ref())
            .is_none_or(|stage| stage(request, &victim, live_attacker().as_ref()));
        let regular_saved = if !regular_allowed {
            0.0
        } else {
            let saved = self.armor_stage(
                &target,
                actors,
                request,
                ProtectionChannel::Regular,
                after_power_take,
                &flags.armor,
                armor,
                &mut mutations,
            )?;
            let Some(saved) = saved else {
                return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
            };
            saved
        };
        let after_regular_take = after_power_take - regular_saved;
        let Some(victim) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        let mut take = source_effects
            .and_then(|effects| effects.after_armor.as_ref())
            .map_or(after_regular_take, |stage| {
                stage(request, after_regular_take, &victim, live_attacker().as_ref())
            })
            .trunc();
        let Some(victim) = live_target() else {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        };
        if !flags.no_protection && policy_context.reject_team_damage {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, None));
        }
        if flags.destroy_armor && !victim.invulnerable && !flags.no_protection {
            take = damage;
        }
        let feedback = DamageFeedback::Q2 {
            power_armor: power_saved,
            armor: regular_saved + protection_saved,
            blood: take,
            knockback,
        };
        if take == 0.0 {
            return Ok(complete_decision(Vec::new(), 0.0, DamageReaction::None, Some(feedback)));
        }
        let health = (-999.0f64).max((victim.health - take).trunc());
        mutations.push(DamageMutation::Health {
            before: victim.health,
            after: health,
        });
        Ok(complete_decision(
            mutations,
            take,
            if health <= 0.0 {
                DamageReaction::Death
            } else if policy_context.suppress_pain {
                DamageReaction::None
            } else {
                DamageReaction::Pain
            },
            Some(feedback),
        ))
    }

    /// Q2 post-health stage (donor `createQ2CombatPolicy` `afterHealth`).
    #[allow(clippy::type_complexity)]
    fn after_health_q2(
        &self,
        decision: &super::events::DamageDecision,
        context: &Rc<
            dyn Fn(
                &super::events::DamageRequest,
                &qa_world::combat::CombatState,
                Option<&qa_world::combat::CombatState>,
            ) -> Q2PolicyContext,
        >,
        source_effects: Option<&Q2PolicySourceEffects>,
    ) -> super::events::DamageReaction {
        use super::events::DamageReaction;
        let Some(effects) = source_effects.and_then(|effects| effects.after_health.as_ref()) else {
            return decision.reaction;
        };
        effects(
            decision.request.target.clone(),
            decision.request.attack.attacker.clone(),
            decision.applied_damage,
        );
        let states = self.combat_states.borrow();
        let Some(target) = self.combat_state_for(&decision.request.target, &states) else {
            return DamageReaction::None;
        };
        drop(states);
        if target.health <= 0.0 {
            return DamageReaction::Death;
        }
        if context(
            &decision.request,
            &target,
            self.live_attacker(&decision.request).as_ref(),
        )
        .suppress_pain
        {
            DamageReaction::None
        } else {
            DamageReaction::Pain
        }
    }

    /// Validate and commit a decision's health/armor/impulse mutations
    /// (donor `validateMutations` + `commitMutations`).
    fn commit_decision(
        &self,
        target: &OwnedActor,
        actors: &SessionActorRegistry,
        decision: &RuntimeCompleteDecision,
    ) -> Result<(), RuntimeError> {
        use super::events::DamageMutation;
        if decision
            .mutations
            .iter()
            .any(|mutation| matches!(mutation, DamageMutation::SourceVelocity { .. }))
        {
            return fail("Observed source velocity cannot be replayed by a combat policy");
        }
        let states = self.combat_states.borrow();
        let Some(initial) = states.get(target.id()).cloned() else {
            return fail("Actor has no combat binding");
        };
        drop(states);
        let mut health = initial.health;
        let mut armor = initial.armor.clone();
        for mutation in &decision.mutations {
            match mutation {
                DamageMutation::Health { before, after } => {
                    if *before != health || !after.is_finite() {
                        return fail("Invalid ordered health mutation");
                    }
                    health = *after;
                }
                DamageMutation::Armor { before, after } => {
                    if contract_armor_to_world(before) != armor {
                        return fail("Invalid ordered armor mutation");
                    }
                    armor = contract_armor_to_world(after);
                }
                DamageMutation::Impulse { .. } => {}
                DamageMutation::SourceVelocity { .. } => {
                    return fail("Observed source velocity cannot be replayed by a combat policy");
                }
            }
        }
        for mutation in &decision.mutations {
            actors.assert_owned(target)?;
            match mutation {
                DamageMutation::SourceVelocity { .. } => {
                    return fail("Observed source velocity cannot be replayed by a combat policy");
                }
                DamageMutation::Health { before, after } => {
                    let mut states = self.combat_states.borrow_mut();
                    let Some(live) = states.get_mut(target.id()) else {
                        return fail("Actor has no combat binding");
                    };
                    if live.health != *before {
                        return fail("Combat health changed before its decision committed");
                    }
                    live.health = *after;
                }
                DamageMutation::Armor { before, after } => {
                    let mut states = self.combat_states.borrow_mut();
                    let Some(live) = states.get_mut(target.id()) else {
                        return fail("Actor has no combat binding");
                    };
                    if live.armor != contract_armor_to_world(before) {
                        return fail("Combat armor changed before its decision committed");
                    }
                    live.armor = contract_armor_to_world(after);
                }
                DamageMutation::Impulse {
                    impulse,
                    movement_provider,
                } => {
                    if let Some(hooks) = self.hooks.as_ref() {
                        let provider = provider_text(movement_provider);
                        (hooks.impulse)(target, *impulse, &provider);
                    }
                }
            }
        }
        Ok(())
    }
}

// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// C4: combat registration (donor registerCombat + q1CombatSource).
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Register combat policies for the recipe combat provider (donor
    /// `registerCombat`, donor runtime.ts 3125, C4 canonical).
    ///
    /// Q1 source-effect hooks have no readable surface yet (the q1 lane
    /// owns damage-effect retrieval), so the Q1 policy runs the donor
    /// hook-absent fallbacks. Q2 match damage effects need the q2 product
    /// runtime (opaque seam); CTF/LMCTF matches fail loudly until it lands.
    pub fn register_combat(&self) -> Result<(), RuntimeError> {
        let id = self.peek().recipe.combat.provider.clone();
        let family = provider_text(&id);
        if family.starts_with("q1:") {
            let kind = self.q1_combat_policy_kind();
            self.lock().combat.register(CombatPolicy { id, kind })?;
        } else if family.starts_with("q2:") {
            let kind = self.q2_combat_policy_kind()?;
            self.lock().combat.register(CombatPolicy { id, kind })?;
        }
        Ok(())
    }

    /// Build the Q1 combat policy kind (donor `createQ1CombatPolicy` arm).
    fn q1_combat_policy_kind(&self) -> RuntimeCombatPolicyKind {
        let weak = Rc::downgrade(&self.state);
        let actors = Rc::clone(&self.actors);
        let bodies = Rc::clone(&self.bodies_table);
        let context = Rc::new(
            move |request: &super::events::DamageRequest,
                  _target: &qa_world::combat::CombatState,
                  _attacker: Option<&qa_world::combat::CombatState>| {
                let q1_request = q1_damage_request(request);
                weak.upgrade()
                    .and_then(|state| {
                        let sim = join_handle(state, &actors, &bodies);
                        sim.q1_combat_source()
                            .ok()
                            .map(|game| game.borrow_mut().combat_context(&q1_request))
                    })
                    .unwrap_or_else(neutral_q1_combat_context)
            },
        );
        RuntimeCombatPolicyKind::Q1 {
            context,
            armor: self.native_victim_armor(),
            source_effects: Q1PolicySourceEffects {
                before_quad: Some(Rc::new(|_, amount, _, _| RuntimeDamagePreparation::Continue { amount })),
                after_quad: Some(Rc::new(|_, amount, _, _| RuntimeDamagePreparation::Continue { amount })),
                armor_allowed: Some(Rc::new(|_, _, _, _| true)),
                protection_applies: Some(Rc::new(|_, _, _| true)),
                before_health: Some(Rc::new(|_, _, _, _| true)),
                after_armor: Some(Rc::new(|_, amount, _, _| amount)),
                lethal_health: None,
            },
        }
    }

    /// Build the Q2 combat policy kind (donor `createQ2CombatPolicy` arm).
    fn q2_combat_policy_kind(&self) -> Result<RuntimeCombatPolicyKind, RuntimeError> {
        let provider = provider_text(&self.peek().recipe.r#match.provider);
        if provider == "q2:ctf" || provider == "q2:lmctf" {
            self.q2_match_damage_effects()?;
        }
        let weak = Rc::downgrade(&self.state);
        let actors = Rc::clone(&self.actors);
        let bodies = Rc::clone(&self.bodies_table);
        let context = Rc::new(
            move |request: &super::events::DamageRequest,
                  _target: &qa_world::combat::CombatState,
                  _attacker: Option<&qa_world::combat::CombatState>| {
                weak.upgrade()
                    .map(|state| join_handle(state, &actors, &bodies).q2_policy_context(request))
                    .unwrap_or_else(Q2PolicyContext::neutral)
            },
        );
        Ok(RuntimeCombatPolicyKind::Q2 {
            context,
            armor: self.native_victim_armor(),
            source_effects: None,
        })
    }

    /// Build the Q2 combat policy context for a request (donor Q2
    /// `context`, runtime.ts 3149-3163).
    fn q2_policy_context(&self, request: &super::events::DamageRequest) -> Q2PolicyContext {
        use qa_world::combat::ArmorArithmetic;
        let state = self.peek();
        let is_q2 = state.source.kind() == "q2";
        let has_enemy = is_q2
            && match &state.source {
                SourceRuntime::Q2 { game, .. } => game
                    .borrow()
                    .entity(&request.target)
                    .and_then(|entity| entity.enemy.clone())
                    .is_some(),
                _ => false,
            };
        let team_damage_enabled = is_q2 && {
            let provider = provider_text(&state.recipe.r#match.provider);
            provider == "q2:ctf"
                || provider == "q2:lmctf"
                || match &state.source {
                    SourceRuntime::Q2 { game, .. } => game.borrow().options.deathmatch_flags & (64 | 128) != 0,
                    _ => false,
                }
        };
        let friendly_fire = match state.q2_server_registry.as_ref() {
            None => true,
            Some(registry) => registry.borrow().variable_value("dmflags") as i32 & 256 == 0,
        };
        Q2PolicyContext {
            arithmetic: ArmorArithmetic::Binary32,
            player: self.player(&request.target).is_some(),
            monster: self.classname(&request.target).starts_with("monster_"),
            attacker_player: request
                .attack
                .attacker
                .as_ref()
                .is_some_and(|attacker| self.player(attacker).is_some()),
            has_enemy,
            easy_skill: state.options_skill == 0,
            deathmatch: state.options_mode == super::types::SimulationMode::Deathmatch,
            defender_sphere: false,
            team_damage_enabled,
            friendly_fire,
            nuke: false,
            no_knockback: false,
            movable: !state.physics.is_brush(&request.target),
            reject_team_damage: false,
            suppress_pain: false,
        }
    }

    /// Build the native armor-absorption callback (donor
    /// `nativeVictimArmor`).
    fn native_victim_armor(&self) -> RuntimeVictimArmor {
        let weak = Rc::downgrade(&self.state);
        let actors = Rc::clone(&self.actors);
        let bodies = Rc::clone(&self.bodies_table);
        Rc::new(move |request, armor, damage, flags| {
            let Some(state) = weak.upgrade() else {
                return Err(qa_world::WorldError::SimulationClosed);
            };
            let sim = join_handle(state, &actors, &bodies);
            let context = sim.victim_armor_context(request);
            qa_world::combat::absorb_native_armor(armor, damage, flags, &context)
        })
    }
}

impl Q2PolicyContext {
    /// Neutral context for a closed simulation (policy closures keep
    /// running during teardown; the donor never observes this state).
    fn neutral() -> Self {
        Self {
            arithmetic: qa_world::combat::ArmorArithmetic::Binary32,
            player: false,
            monster: false,
            attacker_player: false,
            has_enemy: false,
            easy_skill: false,
            deathmatch: false,
            defender_sphere: false,
            team_damage_enabled: false,
            friendly_fire: false,
            nuke: false,
            no_knockback: false,
            movable: false,
            reject_team_damage: false,
            suppress_pain: false,
        }
    }
}

/// Neutral Q1 combat context for a closed simulation (policy closures
/// keep running during teardown; the donor never observes this state).
fn neutral_q1_combat_context() -> qa_content::q1::foundation::gameplay::Q1CombatContext {
    use qa_content::q1::foundation::gameplay::{Q1CombatArithmetic, Q1CombatContext};
    Q1CombatContext {
        arithmetic: Q1CombatArithmetic::Binary32,
        quad: false,
        teamplay: 0,
        base_team_health: false,
        walk: false,
        momentum_direction: None,
    }
}

// ---------------------------------------------------------------------------
// C4: adopted orphan combat source.
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Q1 combat source services (donor `q1CombatSource`, donor
    /// runtime.ts 1361, unowned pre-2168 range).
    ///
    /// C4: orphan adopted; no wave lane owns the pre-2168 range. Returns the
    /// live Q1 entity services behind the Q1 source arm or the Q1-family
    /// selected arsenal.
    pub fn q1_combat_source(
        &self,
    ) -> Result<Rc<RefCell<qa_content::q1::foundation::entity_services::Q1EntityServices>>, RuntimeError> {
        let state = self.peek();
        if let SourceRuntime::Q1 { services, .. } = &state.source {
            return Ok(Rc::clone(services));
        }
        if let Some(SelectedArsenal::Q1(arsenal)) = state.selected_arsenal.as_ref() {
            return Ok(arsenal.game());
        }
        fail("Q1 combat needs a Q1 source")
    }
}

/// Convert an events damage request to a Q1 foundation request.
/// Convert an events attack to Q1 foundation provenance.
fn q1_attack_provenance(
    attack: &super::events::AttackProvenance,
) -> qa_content::q1::foundation::gameplay::AttackProvenance {
    use qa_content::q1::foundation::gameplay as q1;
    q1::AttackProvenance {
        sequence: attack.sequence,
        time: attack.time,
        attacker: attack.attacker.clone(),
        inflictor: attack.inflictor.clone(),
        originating_projectile: attack.originating_projectile.clone(),
        weapon: attack.weapon.clone(),
        weapon_provider: attack.weapon_provider.clone(),
        damage_powerup_owner: attack.damage_powerup_owner.clone(),
        combat_provider: attack.combat_provider.clone(),
        inventory_provider: attack.inventory_provider.clone(),
        movement_provider: attack.movement_provider.clone(),
        cause: q1_attack_cause(&attack.cause),
    }
}

fn q1_damage_request(request: &super::events::DamageRequest) -> qa_content::q1::foundation::gameplay::DamageRequest {
    use qa_content::q1::foundation::gameplay as q1;
    q1::DamageRequest {
        attack: q1_attack_provenance(&request.attack),
        target: request.target.clone(),
        amount: request.amount,
        knockback: request.knockback,
        direction: request.direction,
        point: request.point,
        normal: request.normal,
        delivery: match request.delivery {
            super::events::DamageDelivery::Direct => q1::DamageDelivery::Direct,
            super::events::DamageDelivery::Radius => q1::DamageDelivery::Radius,
        },
    }
}

/// Convert an events attack cause to a Q2 support cause.
fn q2_attack_cause(cause: &super::events::AttackCause) -> qa_content::q2::support::contracts::AttackCause {
    use qa_content::q2::support::contracts as q2;
    match cause {
        super::events::AttackCause::Q1 {
            death_type,
            armor_effect,
        } => q2::AttackCause::Q1 {
            death_type: death_type.clone(),
            armor_effect: armor_effect.map(|effect| match effect {
                super::events::AttackArmorEffect::Bypass => q2::Q1ArmorEffect::Bypass,
                super::events::AttackArmorEffect::HalfEffectiveness => q2::Q1ArmorEffect::HalfEffectiveness,
            }),
        },
        super::events::AttackCause::Q2 {
            means_of_death,
            damage_flags,
            native,
        } => q2::AttackCause::Q2 {
            means_of_death: *means_of_death,
            damage_flags: *damage_flags,
            native: native.as_ref().map(|native| match native {
                super::events::Q2NativeCause::Classic { game, value } => q2::Q2NativeCause::Classic {
                    game: match game {
                        super::events::Q2NativeGame::Base => q2::Q2NativeGame::Base,
                        super::events::Q2NativeGame::Xatrix => q2::Q2NativeGame::Xatrix,
                        super::events::Q2NativeGame::Rogue => q2::Q2NativeGame::Rogue,
                        super::events::Q2NativeGame::Ctf => q2::Q2NativeGame::Ctf,
                    },
                    value: *value,
                },
                super::events::Q2NativeCause::Rerelease {
                    id,
                    friendly_fire,
                    no_point_loss,
                } => q2::Q2NativeCause::Rerelease {
                    id: *id,
                    friendly_fire: *friendly_fire,
                    no_point_loss: *no_point_loss,
                },
            }),
        },
        super::events::AttackCause::Q3 {
            means_of_death,
            damage_flags,
        } => q2::AttackCause::Q3 {
            means_of_death: *means_of_death,
            damage_flags: *damage_flags,
        },
        super::events::AttackCause::Environment { hazard } => q2::AttackCause::Environment {
            hazard: match hazard {
                super::events::EnvironmentHazard::Fall => q2::EnvironmentHazard::Fall,
                super::events::EnvironmentHazard::Drown => q2::EnvironmentHazard::Drown,
                super::events::EnvironmentHazard::Lava => q2::EnvironmentHazard::Lava,
                super::events::EnvironmentHazard::Slime => q2::EnvironmentHazard::Slime,
                super::events::EnvironmentHazard::Crush => q2::EnvironmentHazard::Crush,
                super::events::EnvironmentHazard::Trigger => q2::EnvironmentHazard::Trigger,
            },
        },
    }
}

/// Convert an events attack to Q2 support provenance.
fn q2_attack_provenance(
    attack: &super::events::AttackProvenance,
) -> qa_content::q2::support::contracts::AttackProvenance {
    use qa_content::q2::support::contracts as q2;
    q2::AttackProvenance {
        sequence: attack.sequence,
        time: attack.time,
        attacker: attack.attacker.clone(),
        inflictor: attack.inflictor.clone(),
        originating_projectile: attack.originating_projectile.clone(),
        weapon: attack.weapon.clone(),
        weapon_provider: attack.weapon_provider.clone(),
        damage_powerup_owner: attack.damage_powerup_owner.clone(),
        combat_provider: attack.combat_provider.clone(),
        inventory_provider: attack.inventory_provider.clone(),
        movement_provider: attack.movement_provider.clone(),
        cause: q2_attack_cause(&attack.cause),
    }
}

/// Convert an events decision to a Q1 foundation decision.
fn q1_damage_decision(
    decision: &super::events::DamageDecision,
) -> qa_content::q1::foundation::gameplay::DamageDecision {
    use qa_content::q1::foundation::gameplay as q1;
    q1::DamageDecision {
        request: q1_damage_request(&decision.request),
        mutations: decision
            .mutations
            .iter()
            .map(|mutation| match mutation {
                super::events::DamageMutation::Health { before, after } => q1::DamageMutation::Health {
                    before: *before,
                    after: *after,
                },
                super::events::DamageMutation::Armor { before, after } => q1::DamageMutation::Armor {
                    before: before.clone(),
                    after: after.clone(),
                },
                super::events::DamageMutation::SourceVelocity {
                    before,
                    after,
                    movement_provider,
                } => q1::DamageMutation::SourceVelocity {
                    before: *before,
                    after: *after,
                    movement_provider: movement_provider.clone(),
                },
                super::events::DamageMutation::Impulse {
                    impulse,
                    movement_provider,
                } => q1::DamageMutation::Impulse {
                    impulse: *impulse,
                    movement_provider: movement_provider.clone(),
                },
            })
            .collect(),
        applied_damage: decision.applied_damage,
        reaction: match decision.reaction {
            super::events::DamageReaction::None => q1::DamageReaction::None,
            super::events::DamageReaction::Pain => q1::DamageReaction::Pain,
            super::events::DamageReaction::Death => q1::DamageReaction::Death,
        },
        feedback: decision.feedback.as_ref().map(|feedback| match feedback {
            super::events::DamageFeedback::Q2 {
                power_armor,
                armor,
                blood,
                knockback,
            } => q1::DamageFeedback::Q2 {
                power_armor: *power_armor,
                armor: *armor,
                blood: *blood,
                knockback: *knockback,
            },
            super::events::DamageFeedback::Q3 { knockback, battlesuit } => q1::DamageFeedback::Q3 {
                knockback: *knockback,
                battlesuit: *battlesuit,
            },
        }),
    }
}

/// Convert an events decision to a Q2 support decision.
fn q2_damage_decision(decision: &super::events::DamageDecision) -> qa_content::q2::support::contracts::DamageDecision {
    use qa_content::q2::support::contracts as q2;
    q2::DamageDecision {
        request: q2::DamageRequest {
            attack: q2_attack_provenance(&decision.request.attack),
            target: decision.request.target.clone(),
            amount: decision.request.amount,
            knockback: decision.request.knockback,
            direction: decision.request.direction,
            point: decision.request.point,
            normal: decision.request.normal,
            delivery: match decision.request.delivery {
                super::events::DamageDelivery::Direct => q2::DamageDelivery::Direct,
                super::events::DamageDelivery::Radius => q2::DamageDelivery::Radius,
            },
        },
        mutations: decision
            .mutations
            .iter()
            .map(|mutation| match mutation {
                super::events::DamageMutation::Health { before, after } => q2::DamageMutation::Health {
                    before: *before,
                    after: *after,
                },
                super::events::DamageMutation::Armor { before, after } => q2::DamageMutation::Armor {
                    before: before.clone(),
                    after: after.clone(),
                },
                super::events::DamageMutation::SourceVelocity {
                    before,
                    after,
                    movement_provider,
                } => q2::DamageMutation::SourceVelocity {
                    before: *before,
                    after: *after,
                    movement_provider: movement_provider.clone(),
                },
                super::events::DamageMutation::Impulse {
                    impulse,
                    movement_provider,
                } => q2::DamageMutation::Impulse {
                    impulse: *impulse,
                    movement_provider: movement_provider.clone(),
                },
            })
            .collect(),
        applied_damage: decision.applied_damage,
        reaction: match decision.reaction {
            super::events::DamageReaction::None => q2::DamageReactionKind::None,
            super::events::DamageReaction::Pain => q2::DamageReactionKind::Pain,
            super::events::DamageReaction::Death => q2::DamageReactionKind::Death,
        },
        feedback: decision.feedback.as_ref().map(|feedback| match feedback {
            super::events::DamageFeedback::Q2 {
                power_armor,
                armor,
                blood,
                knockback,
            } => q2::DamageFeedback::Q2 {
                power_armor: *power_armor,
                armor: *armor,
                blood: *blood,
                knockback: *knockback,
            },
            super::events::DamageFeedback::Q3 { knockback, battlesuit } => q2::DamageFeedback::Q3 {
                knockback: *knockback,
                battlesuit: *battlesuit,
            },
        }),
    }
}

/// Convert an events attack cause to a Q3 records cause.
fn q3_attack_cause(cause: &super::events::AttackCause) -> qa_content::q3::base::records::AttackCause {
    use qa_content::q3::base::records as q3;
    match cause {
        super::events::AttackCause::Q1 {
            death_type,
            armor_effect,
        } => q3::AttackCause::Q1 {
            death_type: death_type.clone(),
            armor_effect: armor_effect.map(|effect| match effect {
                super::events::AttackArmorEffect::Bypass => q3::Q1ArmorEffect::Bypass,
                super::events::AttackArmorEffect::HalfEffectiveness => q3::Q1ArmorEffect::HalfEffectiveness,
            }),
        },
        super::events::AttackCause::Q2 {
            means_of_death,
            damage_flags,
            native,
        } => q3::AttackCause::Q2 {
            means_of_death: *means_of_death,
            damage_flags: *damage_flags,
            native: native.as_ref().map(|native| match native {
                super::events::Q2NativeCause::Classic { game, value } => q3::Q2NativeCause::Classic {
                    game: match game {
                        super::events::Q2NativeGame::Base => q3::Q2ClassicGame::Base,
                        super::events::Q2NativeGame::Xatrix => q3::Q2ClassicGame::Xatrix,
                        super::events::Q2NativeGame::Rogue => q3::Q2ClassicGame::Rogue,
                        super::events::Q2NativeGame::Ctf => q3::Q2ClassicGame::Ctf,
                    },
                    value: *value,
                },
                super::events::Q2NativeCause::Rerelease {
                    id,
                    friendly_fire,
                    no_point_loss,
                } => q3::Q2NativeCause::Rerelease {
                    id: *id,
                    friendly_fire: *friendly_fire,
                    no_point_loss: *no_point_loss,
                },
            }),
        },
        super::events::AttackCause::Q3 {
            means_of_death,
            damage_flags,
        } => q3::AttackCause::Q3 {
            means_of_death: *means_of_death,
            damage_flags: *damage_flags,
        },
        super::events::AttackCause::Environment { hazard } => q3::AttackCause::Environment {
            hazard: match hazard {
                super::events::EnvironmentHazard::Fall => q3::EnvironmentHazard::Fall,
                super::events::EnvironmentHazard::Drown => q3::EnvironmentHazard::Drown,
                super::events::EnvironmentHazard::Lava => q3::EnvironmentHazard::Lava,
                super::events::EnvironmentHazard::Slime => q3::EnvironmentHazard::Slime,
                super::events::EnvironmentHazard::Crush => q3::EnvironmentHazard::Crush,
                super::events::EnvironmentHazard::Trigger => q3::EnvironmentHazard::Trigger,
            },
        },
    }
}

/// Convert an events damage request to a Q3 records request.
fn q3_damage_request(request: &super::events::DamageRequest) -> qa_content::q3::base::records::DamageRequest {
    use qa_content::q3::base::records as q3;
    q3::DamageRequest {
        attack: q3::AttackProvenance {
            sequence: request.attack.sequence as i32,
            time: request.attack.time,
            attacker: request.attack.attacker.clone(),
            inflictor: request.attack.inflictor.clone(),
            originating_projectile: request.attack.originating_projectile.clone(),
            weapon: request.attack.weapon.clone(),
            weapon_provider: request.attack.weapon_provider.clone(),
            damage_powerup_owner: request.attack.damage_powerup_owner.clone(),
            combat_provider: request.attack.combat_provider.clone(),
            inventory_provider: request.attack.inventory_provider.clone(),
            movement_provider: request.attack.movement_provider.clone(),
            cause: q3_attack_cause(&request.attack.cause),
        },
        target: request.target.clone(),
        amount: request.amount as f32,
        knockback: request.knockback as f32,
        direction: request.direction,
        point: request.point,
        normal: request.normal,
        delivery: match request.delivery {
            super::events::DamageDelivery::Direct => qa_world::combat::Delivery::Direct,
            super::events::DamageDelivery::Radius => qa_world::combat::Delivery::Radius,
        },
    }
}

