impl SharedSimulation {
    /// Apply server settings to a fresh source registry (donor
    /// `initializeServerSettings`, donor runtime.ts 5344, C7's range).
    ///
    /// The construction-time `profile`/`restored` pieces stay parameters
    /// because the state drops them; the body is the donor algorithm.
    pub fn initialize_server_settings(
        &self,
        cvars: &mut qa_core::cvar::CvarRegistry,
        profile: Option<&crate::settings::server::ServerProfile>,
        restored: bool,
    ) -> Result<(), RuntimeError> {
        use crate::settings::server::{
            apply_server_profile, server_definitions_for_selection, ProviderRef, ServerBinding,
        };
        let (world_kind, scene) = {
            let state = self.peek();
            (state.world_kind.clone(), state.scene.clone())
        };
        if world_kind == "q3-bsp" {
            CollisionMapSettings::register_map(cvars).map_err(source_failure)?;
            let settings = CollisionMapSettings { opaque: false };
            self.lock().source_collision_settings = Some(CollisionMapSettings { opaque: false });
            if !restored {
                scene.bind_collision_settings(settings);
            }
        }
        let Some(profile) = profile else {
            return Ok(());
        };
        let recipe = self.peek().recipe.clone();
        let reference = |value: &ProviderReference| ProviderRef {
            provider: provider_text(&value.provider),
            content: value.content.as_str().to_string(),
        };
        let definitions = server_definitions_for_selection(
            &reference(&recipe.map.entities),
            &reference(&recipe.r#match),
            &reference(&recipe.combat),
        )
        .map_err(source_failure)?;
        let bindings: Vec<ServerBinding> = definitions
            .into_iter()
            .map(|definition| ServerBinding {
                definition,
                initializing: true,
            })
            .collect();
        apply_server_profile(profile, &bindings, cvars).map_err(source_failure)?;
        Ok(())
    }
}

