/// Standing collision bounds for a character family (donor
/// `playerStandingBounds`).
pub fn player_standing_bounds(character: GameFamily) -> Bounds {
    use qa_world::movement::q3::postures::Q3_SOURCE_STANDING_BOUNDS;
    if character == GameFamily::Q3 {
        Q3_SOURCE_STANDING_BOUNDS
    } else {
        Bounds {
            min: Vec3 {
                x: -16.0,
                y: -16.0,
                z: -24.0,
            },
            max: Vec3 {
                x: 16.0,
                y: 16.0,
                z: 32.0,
            },
        }
    }
}

/// Posture table for a player (donor `playerPostures`).
pub fn player_postures(player: &MovementPlayer) -> qa_world::movement::q3::types::Q3Postures {
    use qa_world::movement::q3::postures::Q3_SOURCE_POSTURES;
    use qa_world::movement::q3::types::Q3Posture;
    if player.character == GameFamily::Q3 {
        Q3_SOURCE_POSTURES
    } else {
        qa_world::movement::q3::types::Q3Postures {
            standing_view_height: player.view_height,
            crouched: Q3Posture {
                bounds: Bounds {
                    min: player.standing_bounds.min,
                    max: Vec3 {
                        z: 4.0,
                        ..player.standing_bounds.max
                    },
                },
                view_height: -2.0,
            },
            dead: Q3Posture {
                bounds: Bounds {
                    min: player.standing_bounds.min,
                    max: Vec3 {
                        z: -8.0,
                        ..player.standing_bounds.max
                    },
                },
                view_height: -16.0,
            },
            invulnerability_expanded: Q3_SOURCE_POSTURES.invulnerability_expanded,
        }
    }
}

/// Crouched collision bounds (donor `playerCrouchedBounds`).
pub fn player_crouched_bounds(player: &MovementPlayer) -> Bounds {
    player_postures(player).crouched.bounds
}

/// Profile with per-player gravity and source overrides applied (donor
/// `selectedMovementProfile`). The Q2 movement config comes from the
/// simulation host (donor `host.q2MovementConfig`).
pub fn selected_movement_profile(player: &MovementPlayer, q2_config: Option<Q2MovementConfig>) -> MovementProfile {
    selected_movement_profile_with(&player.profile, player, q2_config)
}

/// Profile override over an explicit base profile.
pub fn selected_movement_profile_with(
    profile: &MovementProfile,
    player: &MovementPlayer,
    q2_config: Option<Q2MovementConfig>,
) -> MovementProfile {
    match profile {
        MovementProfile::Q1Netquake(inner) => {
            let mut next = inner.clone();
            next.parameters.gravity = player.world_gravity;
            MovementProfile::Q1Netquake(next)
        }
        MovementProfile::Q1Quakeworld(inner) => {
            let mut next = inner.clone();
            next.parameters.gravity = player.world_gravity;
            MovementProfile::Q1Quakeworld(next)
        }
        MovementProfile::Q3(inner) => {
            let Some(source) = player.source_movement.as_ref() else {
                return MovementProfile::Q3(inner.clone());
            };
            let mut next = inner.clone();
            next.fixed_milliseconds = source.fixed_msec;
            if let Some(no_footsteps) = source.no_footsteps {
                next.no_footsteps = no_footsteps;
            }
            MovementProfile::Q3(next)
        }
        MovementProfile::Q2Classic(inner) => {
            let Some(config) = q2_config else {
                return MovementProfile::Q2Classic(inner.clone());
            };
            let mut next = inner.clone();
            next.air_accelerate = config.air_accelerate;
            MovementProfile::Q2Classic(next)
        }
        MovementProfile::Q2Rerelease(inner) => {
            let Some(config) = q2_config else {
                return MovementProfile::Q2Rerelease(inner.clone());
            };
            let mut next = inner.clone();
            next.air_accelerate = config.air_accelerate;
            next.n64_physics = config.n64_physics;
            MovementProfile::Q2Rerelease(next)
        }
    }
}

/// Per-frame movement environment for a player (donor
/// `playerMovementEnvironment`).
pub fn player_movement_environment(
    player: &MovementPlayer,
    combat: &qa_world::combat::CombatState,
    speed_multiplier: f64,
) -> qa_world::movement::types::MovementEnvironment {
    use qa_world::movement::types::MovementEnvironment;
    let gravity_multiplier = if matches!(player.state, MovementState::Q3(_)) {
        1.0
    } else {
        player.gravity_multiplier
    };
    if let Some(source) = player.source_environment.as_ref() {
        MovementEnvironment {
            flight: (source.flight || player.flight) && combat.health > 0.0,
            health: combat.health,
            invulnerable: source.invulnerable || combat.invulnerable,
            gravity_multiplier,
            speed_multiplier: if speed_multiplier == 1.0 {
                None
            } else {
                Some(speed_multiplier)
            },
            ..*source
        }
    } else {
        MovementEnvironment {
            health: combat.health,
            flight: player.flight && combat.health > 0.0,
            haste: false,
            invulnerable: combat.invulnerable,
            gravity_multiplier,
            speed_multiplier: if speed_multiplier == 1.0 {
                None
            } else {
                Some(speed_multiplier)
            },
            ..MovementEnvironment::default()
        }
    }
}
// C11: grapple/offhand equipment + weapon-behavior source construction
// (donor `runtime.ts` lines 2168-2574).
//
// Re-entrancy rule for this section: equipment arenas (`GrappleRuntime`,
// the hand-grenade game, `WeaponSlot`) call back into the state through
// stored `Weak` handles, so no method below holds a state borrow while
// invoking arena code. `GrappleRuntime` is not `Clone` (its checkpoint
// bridge is boxed), so arena access goes through the take-restore helpers
// (`with_grapple`, `with_hand_grenades`, `with_weapon_slot`): the subsystem
// is removed from the state, the guard is dropped, the arena runs, and the
// subsystem is restored. Nested takes observe `None`, which is exactly the
// donor's `?.`/`??` path. A `RestoreGuard` reinstalls the subsystem even
// when arena code panics, so a panic keeps its original cause instead of
// also losing the subsystem.
// ---------------------------------------------------------------------------

/// Reinstall a taken subsystem on drop (C11 take-restore helpers).
struct RestoreGuard<T, F: FnOnce(Option<T>)> {
    value: Option<T>,
    restore: Option<F>,
}

impl<T, F: FnOnce(Option<T>)> RestoreGuard<T, F> {
    fn hold(value: T, restore: F) -> Self {
        Self {
            value: Some(value),
            restore: Some(restore),
        }
    }

    fn get(&mut self) -> &mut T {
        self.value.as_mut().expect("C11 restore guard used after release")
    }

    fn release(mut self) -> T {
        self.restore.take();
        self.value.take().expect("C11 restore guard used after release")
    }
}

impl<T, F: FnOnce(Option<T>)> Drop for RestoreGuard<T, F> {
    fn drop(&mut self) {
        if let Some(restore) = self.restore.take() {
            restore(self.value.take());
        }
    }
}

/// Session grapple control for source compositions (donor `sharedGrapple`).
///
/// Implements [`qa_content::contract::SharedGrappleControl`] over a weak
/// simulation handle. The selection is snapshotted: the trait borrows it,
/// and composition callbacks must not hold the state lock.
#[allow(dead_code)]
pub(crate) struct SessionGrappleControl {
    selection: qa_content::contract::GrappleSelection,
    weak: std::rc::Weak<std::cell::RefCell<SharedSimulationState>>,
    actors: std::rc::Rc<std::cell::RefCell<SessionActorRegistry>>,
    bodies: std::rc::Rc<std::cell::RefCell<qa_world::body::BodyTable>>,
}

impl qa_content::contract::SharedGrappleControl for SessionGrappleControl {
    fn selection(&self) -> &qa_content::contract::GrappleSelection {
        &self.selection
    }

    fn native_slot(&self, _mechanic: qa_content::contract::GrappleMechanic) -> bool {
        // Donor `nativeSlot: () => false`.
        false
    }

    fn input(&self, actor: &ActorId, held: bool) {
        // The trait is infallible; donor `setGrappleInput` throws when the
        // simulation is closed, the actor is not an equipment player, or no
        // offhand grapple is selected. Composition input has no error
        // channel, so failures are ignored here.
        if let Some(sim) = self
            .weak
            .upgrade()
            .map(|state| join_handle(state, &self.actors, &self.bodies))
        {
            let _ = sim.set_grapple_input(actor, held);
        }
    }

    fn release(&self, actor: &ActorId) {
        if let Some(sim) = self
            .weak
            .upgrade()
            .map(|state| join_handle(state, &self.actors, &self.bodies))
        {
            sim.with_grapple(|grapple| {
                let _ = grapple.release(actor);
            });
        }
    }

    fn pulling(&self, actor: &ActorId) -> bool {
        self.weak
            .upgrade()
            .map(|state| join_handle(state, &self.actors, &self.bodies))
            .and_then(|sim| sim.with_grapple(|grapple| grapple.pulling(actor)))
            .unwrap_or(false)
    }

    fn gravity_scale(&self, actor: &ActorId) -> u8 {
        let scaled = self
            .weak
            .upgrade()
            .map(|state| join_handle(state, &self.actors, &self.bodies))
            .and_then(|sim| sim.with_grapple(|grapple| grapple.gravity_scale(actor)));
        match scaled {
            Some(value) if value <= 0 => 0,
            Some(_) => 1,
            None => 1,
        }
    }
}

/// Grapple presentation snapshot (donor `grappleState` result object).
