type Q1DamageDecision = qa_content::q1::foundation::gameplay::DamageDecision;
type Q1DamageMutation = qa_content::q1::foundation::gameplay::DamageMutation;
type Q1DamageReaction = qa_content::q1::foundation::gameplay::DamageReaction;
