/// Shared handles for C11 table adapters.
#[derive(Clone)]
struct C11Tables {
    actors: std::rc::Rc<std::cell::RefCell<SessionActorRegistry>>,
    bodies: std::rc::Rc<std::cell::RefCell<qa_world::body::BodyTable>>,
    weak: std::rc::Weak<std::cell::RefCell<SharedSimulationState>>,
}

impl C11Tables {
    fn sim(&self) -> SharedSimulation {
        let state = self
            .weak
            .upgrade()
            .expect("equipment arena used after the simulation dropped");
        join_handle(state, &self.actors, &self.bodies)
    }
}

impl SessionActorRegistry {
    /// Resolve a saved actor reference to a live handle (C11).
    ///
    /// Donor `resolveSaved`: matches by slot/generation against the live
    /// set, via [`qa_world::registry::ActorRegistry::resolve_saved`].
    pub fn resolve_saved(&self, saved: qa_core::identity::SavedActorId) -> Option<OwnedActor> {
        self.inner.resolve_saved(&saved)
    }
}

impl SharedInventoryTable {
    /// Whether the actor has an inventory binding (C11).
    pub fn has(&self, registry: &qa_world::registry::ActorRegistry, actor: &ActorId) -> bool {
        self.inner().contains(registry, actor)
    }

    /// Consume items (C11).
    pub fn consume(
        &mut self,
        registry: &qa_world::registry::ActorRegistry,
        actor: &OwnedActor,
        item: &str,
        count: f64,
    ) -> Result<bool, RuntimeError> {
        Ok(self.inner_mut().consume(registry, actor, item, count)?)
    }

    /// Give items (C11).
    pub fn give(
        &mut self,
        registry: &qa_world::registry::ActorRegistry,
        actor: &OwnedActor,
        item: &str,
        count: f64,
    ) -> Result<f64, RuntimeError> {
        Ok(self.inner_mut().give(registry, actor, item, count)?)
    }

    /// Adjust a signed source counter (C11).
    pub fn adjust_source_counter(
        &mut self,
        registry: &qa_world::registry::ActorRegistry,
        actor: &OwnedActor,
        item: &str,
        delta: f64,
    ) -> Result<f64, RuntimeError> {
        Ok(self.inner_mut().adjust_source_counter(registry, actor, item, delta)?)
    }
}

/// Q1 actor registry over the shared session registry (C11).
struct C11Q1Actors {
    tables: C11Tables,
}

impl qa_content::q1::foundation::host::Q1SessionActorRegistry for C11Q1Actors {
    fn allocate_at_source(
        &mut self,
        owner: &ProviderId,
        source_slot: u32,
        definition: &str,
    ) -> Result<OwnedActor, qa_content::q1::Q1Error> {
        self.tables
            .actors
            .borrow_mut()
            .allocate_at_source(owner.clone(), source_slot, definition)
            .map_err(q1_error)
    }

    fn assert_owned(&self, actor: &OwnedActor) -> Result<(), qa_content::q1::Q1Error> {
        self.tables.actors.borrow().assert_owned(actor).map_err(q1_error)
    }

    fn resolve_owned(&self, actor: &ActorId) -> Option<OwnedActor> {
        self.tables.actors.borrow().resolve_owned(actor)
    }

    fn is_live(&self, actor: &ActorId) -> bool {
        self.tables.actors.borrow().is_live(actor)
    }

    fn observations(&self) -> Vec<Q1Obs> {
        self.tables
            .actors
            .borrow()
            .observations()
            .iter()
            .map(world_obs_to_q1)
            .collect()
    }

    fn source_of(&self, actor: &ActorId) -> Option<Q1Slot> {
        self.tables
            .actors
            .borrow()
            .source_of(actor)
            .map(|(provider, slot)| Q1Slot { provider, slot })
    }

    fn release(&mut self, actor: &OwnedActor) -> Result<(), qa_content::q1::Q1Error> {
        self.tables.actors.borrow_mut().release(actor).map_err(q1_error)
    }

    fn resolve_saved(&self, saved: &qa_core::identity::SavedActorId) -> Option<OwnedActor> {
        self.tables.actors.borrow().resolve_saved(*saved)
    }

    fn reference_saved(&mut self, saved: &qa_core::identity::SavedActorId) -> ActorId {
        self.tables
            .actors
            .borrow()
            .resolve_saved(*saved)
            .expect("equipment Q1 saved actor has no live handle")
            .id()
            .clone()
    }
}

