/// Q1 callback bindings for one equipment arena (C11).
///
/// The session callback table has no binding set of its own, and each
/// actor executes in exactly one arena, so the arena host tracks its own
/// bindings here.
struct C11Q1Callbacks {
    bound: std::collections::HashSet<ActorId>,
}

impl qa_content::q1::foundation::host::Q1ActorCallbackTable for C11Q1Callbacks {
    fn bind(&mut self, actor: &OwnedActor) {
        self.bound.insert(actor.id().clone());
    }

    fn unbind(&mut self, actor: &OwnedActor) {
        self.bound.remove(actor.id());
    }

    fn is_bound(&self, actor: &ActorId) -> bool {
        self.bound.contains(actor)
    }
}

/// Q1 combat authority over the session gameplay authority (C11).
struct C11Q1Combat {
    tables: C11Tables,
    adjustments: std::collections::HashMap<ActorId, qa_content::q1::foundation::host::Q1DamageAdjustHook>,
}

impl qa_content::q1::foundation::host::Q1GameplayAuthority for C11Q1Combat {
    fn create(&mut self, actor: &OwnedActor, initial: &Q1Combat) -> Result<(), qa_content::q1::Q1Error> {
        let sim = self.tables.sim();
        sim.lock().combat.write(actor.id(), q1_combat_to_world(initial));
        Ok(())
    }

    fn read(&self, actor: &ActorId) -> Option<Q1Combat> {
        self.tables
            .sim()
            .peek()
            .combat
            .read(actor)
            .map(|state| world_combat_to_q1(&state))
    }

    fn set_health(&mut self, actor: &OwnedActor, health: f64) -> Result<(), qa_content::q1::Q1Error> {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            combat.health = health;
            state.combat.write(actor.id(), combat);
        }
        Ok(())
    }

    fn set_armor(
        &mut self,
        actor: &OwnedActor,
        armor: &qa_content::contract::ArmorState,
    ) -> Result<(), qa_content::q1::Q1Error> {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            combat.armor = contract_armor_to_world(armor);
            state.combat.write(actor.id(), combat);
        }
        Ok(())
    }

    fn set_traits(&mut self, actor: &OwnedActor, traits: Q1Traits) -> Result<(), qa_content::q1::Q1Error> {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            combat.can_take_damage = traits.can_take_damage;
            combat.mass = traits.mass;
            combat.invulnerable = traits.invulnerable;
            combat.team = traits.team;
            if let Some(no_knockback) = traits.no_knockback {
                combat.no_knockback = no_knockback;
            }
            state.combat.write(actor.id(), combat);
        }
        Ok(())
    }

    fn set_regular_armor(
        &mut self,
        actor: &OwnedActor,
        regular: &qa_content::contract::RegularArmorState,
    ) -> Result<(), qa_content::q1::Q1Error> {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            let mut armor = world_armor_to_contract(&combat.armor);
            armor.regular = regular.clone();
            combat.armor = contract_armor_to_world(&armor);
            state.combat.write(actor.id(), combat);
        }
        Ok(())
    }

    fn set_regular_points(&mut self, actor: &OwnedActor, points: f64) -> Result<(), qa_content::q1::Q1Error> {
        // Without a seed kind an armor-less actor cannot gain regular
        // armor; the write applies to existing armor only.
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            let mut armor = world_armor_to_contract(&combat.armor);
            match &mut armor.regular {
                ContractRegular::Q1 { points: slot, .. }
                | ContractRegular::Q2 { points: slot, .. }
                | ContractRegular::Q3 { points: slot, .. }
                | ContractRegular::Source { points: slot, .. } => *slot = points,
                ContractRegular::None => {}
            }
            combat.armor = contract_armor_to_world(&armor);
            state.combat.write(actor.id(), combat);
        }
        Ok(())
    }

    fn bind_damage_adjustment(
        &mut self,
        actor: &OwnedActor,
        adjust: qa_content::q1::foundation::host::Q1DamageAdjustHook,
    ) {
        self.adjustments.insert(actor.id().clone(), adjust);
    }

    fn apply(&mut self, request: &Q1DamageRequest) -> Q1DamageOutcome {
        let mut amount = request.amount;
        let mut knockback = request.knockback;
        if let Some(adjust) = self.adjustments.get(&request.target) {
            if let Some(adjusted) = adjust(request) {
                amount = adjusted.amount;
                knockback = adjusted.knockback;
            }
        }
        let sim = self.tables.sim();
        let state = sim.lock();
        let event = super::events::DamageRequest {
            attack: q1_provenance_to_events(&request.attack),
            target: request.target.clone(),
            amount,
            knockback,
            direction: request.direction,
            point: request.point,
            normal: request.normal,
            delivery: q1_delivery_to_events(&request.delivery),
        };
        let outcome = state.combat.apply(event).expect("equipment Q1 damage apply failed");
        match outcome {
            super::events::DamageOutcome::StaleTarget { .. } => Q1DamageOutcome::StaleTarget {
                request: request.clone(),
            },
            super::events::DamageOutcome::Committed { decision, survived } => Q1DamageOutcome::Committed {
                decision: Q1DamageDecision {
                    request: request.clone(),
                    mutations: decision.mutations.iter().map(events_mutation_to_q1).collect(),
                    applied_damage: decision.applied_damage,
                    reaction: events_reaction_to_q1(&decision.reaction),
                    feedback: decision.feedback.as_ref().map(events_feedback_to_q1),
                },
                survived,
            },
        }
    }
}

/// Q1 inventory table over the session inventory table (C11).
struct C11Q1Inventory {
    tables: C11Tables,
}

impl qa_content::q1::foundation::host::Q1SharedInventoryTable for C11Q1Inventory {
    fn create(
        &mut self,
        actor: &OwnedActor,
        entries: &[qa_content::contract::InventoryEntry],
    ) -> Result<(), qa_content::q1::Q1Error> {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        let created: Vec<qa_world::inventory::InventoryEntry> = entries.iter().map(contract_entry_to_world).collect();
        state
            .inventory
            .inner_mut()
            .create(actors_ref.inner(), actor, created.as_slice())
            .map_err(q1_error)
    }

    fn entries(&self, actor: &ActorId) -> Vec<qa_content::contract::InventoryEntry> {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let state = sim.peek();
        state
            .inventory
            .inner()
            .entries(actors_ref.inner(), actor)
            .iter()
            .map(world_entry_to_contract)
            .collect()
    }

    fn has(&self, actor: &ActorId) -> bool {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let state = sim.peek();
        state.inventory.has(actors_ref.inner(), actor)
    }

    fn count(&self, actor: &ActorId, item: &qa_content::contract::ItemId) -> f64 {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let state = sim.peek();
        state.inventory.count(actors_ref.inner(), actor, item.as_str())
    }

    fn consume(&mut self, actor: &OwnedActor, item: &qa_content::contract::ItemId, count: f64) -> bool {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        state
            .inventory
            .consume(actors_ref.inner(), actor, item.as_str(), count)
            .expect("equipment Q1 inventory consume failed")
    }

    fn give(&mut self, actor: &OwnedActor, item: &qa_content::contract::ItemId, count: f64) -> f64 {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        state
            .inventory
            .give(actors_ref.inner(), actor, item.as_str(), count)
            .expect("equipment Q1 inventory give failed")
    }

    fn configure(
        &mut self,
        actor: &OwnedActor,
        entry: &qa_content::contract::InventoryEntry,
    ) -> Result<(), qa_content::q1::Q1Error> {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        state
            .inventory
            .inner_mut()
            .configure(actors_ref.inner(), actor, contract_entry_to_world(entry))
            .map_err(q1_error)
    }

    fn adjust_source_counter(
        &mut self,
        actor: &OwnedActor,
        item: &qa_content::contract::ItemId,
        delta: f64,
    ) -> Result<f64, qa_content::q1::Q1Error> {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        state
            .inventory
            .adjust_source_counter(actors_ref.inner(), actor, item.as_str(), delta)
            .map_err(q1_error)
    }
}

