/// Q2 combat authority over the session gameplay authority (C11).
struct C11Q2Combat {
    tables: C11Tables,
}

impl qa_content::q2::support::tables::Q2CombatAuthority for C11Q2Combat {
    fn create(&mut self, actor: &OwnedActor, initial: &Q2Combat) {
        self.tables
            .sim()
            .lock()
            .combat
            .write(actor.id(), q2_combat_to_world(initial));
    }

    fn read(&self, actor: &ActorId) -> Option<Q2Combat> {
        self.tables
            .sim()
            .peek()
            .combat
            .read(actor)
            .map(|state| world_combat_to_q2(&state))
    }

    fn set_health(&mut self, actor: &OwnedActor, health: f64) {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            combat.health = health;
            state.combat.write(actor.id(), combat);
        }
    }

    fn set_armor(&mut self, actor: &OwnedActor, armor: &qa_content::contract::ArmorState) {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            combat.armor = contract_armor_to_world(armor);
            state.combat.write(actor.id(), combat);
        }
    }

    fn set_regular_points(&mut self, actor: &OwnedActor, points: f64, initial: Option<&ContractRegular>) {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        let Some(mut combat) = state.combat.read(actor.id()) else {
            return;
        };
        let mut armor = world_armor_to_contract(&combat.armor);
        match &mut armor.regular {
            ContractRegular::Q1 { points: slot, .. }
            | ContractRegular::Q2 { points: slot, .. }
            | ContractRegular::Q3 { points: slot, .. }
            | ContractRegular::Source { points: slot, .. } => *slot = points,
            ContractRegular::None => {
                if let Some(seed) = initial {
                    armor.regular = seed.clone();
                }
            }
        }
        combat.armor = contract_armor_to_world(&armor);
        state.combat.write(actor.id(), combat);
    }

    fn set_regular_armor(&mut self, actor: &OwnedActor, regular: &ContractRegular) {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            let mut armor = world_armor_to_contract(&combat.armor);
            armor.regular = regular.clone();
            combat.armor = contract_armor_to_world(&armor);
            state.combat.write(actor.id(), combat);
        }
    }

    fn set_powered_protection(&mut self, actor: &OwnedActor, powered: &ContractPowered) {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            let mut armor = world_armor_to_contract(&combat.armor);
            armor.powered = powered.clone();
            combat.armor = contract_armor_to_world(&armor);
            state.combat.write(actor.id(), combat);
        }
    }

    fn set_traits(&mut self, actor: &OwnedActor, changes: &qa_content::q2::support::contracts::CombatTraitChanges) {
        let sim = self.tables.sim();
        let mut state = sim.lock();
        if let Some(mut combat) = state.combat.read(actor.id()) {
            if let Some(can_take_damage) = changes.can_take_damage {
                combat.can_take_damage = can_take_damage;
            }
            if let Some(mass) = changes.mass {
                combat.mass = mass;
            }
            if let Some(invulnerable) = changes.invulnerable {
                combat.invulnerable = invulnerable;
            }
            if let Some(team) = changes.team.clone() {
                combat.team = team;
            }
            if let Some(no_knockback) = changes.no_knockback {
                combat.no_knockback = no_knockback;
            }
            state.combat.write(actor.id(), combat);
        }
    }

    fn bind_power_armor_cells(
        &mut self,
        _actor: &OwnedActor,
        _cells: Box<dyn qa_content::q2::support::contracts::PowerArmorCells>,
    ) {
        // Power-armor cell bindings are installed by the primary Q2 source
        // arenas; equipment arenas never bind them.
    }

    fn apply(&mut self, input: &Q2DamageRequest) -> Q2DamageOutcome {
        let sim = self.tables.sim();
        let state = sim.lock();
        let event = super::events::DamageRequest {
            attack: q2_provenance_to_events(&input.attack),
            target: input.target.clone(),
            amount: input.amount,
            knockback: input.knockback,
            direction: input.direction,
            point: input.point,
            normal: input.normal,
            delivery: match &input.delivery {
                Q2Delivery::Direct => super::events::DamageDelivery::Direct,
                Q2Delivery::Radius => super::events::DamageDelivery::Radius,
            },
        };
        let outcome = state.combat.apply(event).expect("equipment Q2 damage apply failed");
        match outcome {
            super::events::DamageOutcome::StaleTarget { .. } => Q2DamageOutcome::StaleTarget { request: input.clone() },
            super::events::DamageOutcome::Committed { decision, survived } => Q2DamageOutcome::Committed {
                decision: Q2DamageDecision {
                    request: input.clone(),
                    mutations: decision.mutations.iter().map(events_mutation_to_q2).collect(),
                    applied_damage: decision.applied_damage,
                    reaction: events_reaction_to_q2(&decision.reaction),
                    feedback: decision.feedback.as_ref().map(events_feedback_to_q2),
                },
                survived,
            },
        }
    }
}

/// Q2 inventory table over the session inventory table (C11).
struct C11Q2Inventory {
    tables: C11Tables,
}

impl qa_content::q2::support::tables::Q2InventoryTable for C11Q2Inventory {
    fn create(&mut self, actor: &OwnedActor, entries: &[qa_content::contract::InventoryEntry]) {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        let created: Vec<qa_world::inventory::InventoryEntry> = entries.iter().map(contract_entry_to_world).collect();
        state
            .inventory
            .inner_mut()
            .create(actors_ref.inner(), actor, created.as_slice())
            .expect("equipment Q2 inventory creation failed");
    }

    fn entries(&self, actor: &ActorId) -> Vec<qa_content::contract::InventoryEntry> {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let state = sim.peek();
        state
            .inventory
            .inner()
            .entries(actors_ref.inner(), actor)
            .iter()
            .map(world_entry_to_contract)
            .collect()
    }

    fn has(&self, actor: &ActorId) -> bool {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let state = sim.peek();
        state.inventory.has(actors_ref.inner(), actor)
    }

    fn count(&self, actor: &ActorId, item: &qa_content::contract::ItemId) -> f64 {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let state = sim.peek();
        state.inventory.count(actors_ref.inner(), actor, item.as_str())
    }

    fn consume(&mut self, actor: &OwnedActor, item: &qa_content::contract::ItemId, count: f64) -> bool {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        state
            .inventory
            .consume(actors_ref.inner(), actor, item.as_str(), count)
            .expect("equipment Q2 inventory consume failed")
    }

    fn give(&mut self, actor: &OwnedActor, item: &qa_content::contract::ItemId, count: f64) -> f64 {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        state
            .inventory
            .give(actors_ref.inner(), actor, item.as_str(), count)
            .expect("equipment Q2 inventory give failed")
    }

    fn configure(&mut self, actor: &OwnedActor, entry: &qa_content::contract::InventoryEntry) {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        state
            .inventory
            .inner_mut()
            .configure(actors_ref.inner(), actor, contract_entry_to_world(entry))
            .expect("equipment Q2 inventory configure failed");
    }

    fn adjust_source_counter(&mut self, actor: &OwnedActor, item: &qa_content::contract::ItemId, delta: f64) -> f64 {
        let sim = self.tables.sim();
        let actors = sim.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = sim.lock();
        state
            .inventory
            .adjust_source_counter(actors_ref.inner(), actor, item.as_str(), delta)
            .expect("equipment Q2 inventory counter adjust failed")
    }
}

