impl RuntimePresentation {
    /// Light style pattern (donor `lightStyle`).
    pub fn light_style(&self, style: i32) -> &str {
        self.styles
            .get(&style)
            .map(|value| value.pattern.as_str())
            .unwrap_or("")
    }

    /// Animated light styles (donor `lightStyles`).
    ///
    /// The donor iterates its insertion-ordered map; this port sorts by style
    /// for determinism.
    pub fn light_styles(&self, seconds: f64) -> Vec<super::types::SceneLightStyle> {
        let mut styles: Vec<(&i32, &PresentationStyle)> = self.styles.iter().collect();
        styles.sort_by(|left, right| left.0.cmp(right.0));
        styles
            .into_iter()
            .map(|(style, value)| {
                let letter = if value.pattern.is_empty() {
                    12
                } else {
                    let bytes = value.pattern.as_bytes();
                    i32::from(bytes[((seconds * 10.0).floor() as usize) % bytes.len()]) - 97
                };
                let scale = f64::from(letter) / 12.0;
                if value.family == GameFamily::Q1 {
                    super::types::SceneLightStyle::Q1 {
                        style: *style,
                        value: if value.pattern.is_empty() { 256 } else { letter * 22 },
                    }
                } else {
                    super::types::SceneLightStyle::Q2 {
                        style: *style,
                        rgb: Vec3 {
                            x: scale as f32,
                            y: scale as f32,
                            z: scale as f32,
                        },
                        white: scale * 3.0,
                    }
                }
            })
            .collect()
    }

    /// Register a resolved resource (donor `registerResource`).
    pub fn register_resource(
        &mut self,
        content: &ContentId,
        path: &str,
        resource: qa_content::contract::ResolvedResourceReference,
    ) -> Result<(), RuntimeError> {
        if resource.requested_path != path {
            return fail("Registered resource path does not match its source request");
        }
        let key = format!("{}/{}", content.as_str(), path);
        self.resources_by_id.insert(resource.id.clone(), resource.clone());
        self.resources.insert(key, resource);
        Ok(())
    }
}

impl SessionMods {
    /// Whether a provider belongs to an enabled mod (donor `owns`).
    pub fn owns(&self, provider: &ProviderId) -> bool {
        let key = qa_world::registry::provider_key(provider);
        self.enabled.iter().any(|entry| entry == &key)
    }

    /// Advance enabled mod runtimes (donor `advance`).
    ///
    /// The open/busy protocol is verbatim; no runtimes live behind the sync
    /// seam yet, so the per-entry loop is empty until the mods lane lands.
    pub fn advance(&mut self, frame: &FrameContext) -> Result<(), RuntimeError> {
        let _ = frame;
        if self.closed {
            return fail("Mod session is closed");
        }
        if self.busy {
            return fail("Cannot advance mods during a lifecycle operation");
        }
        self.busy = true;
        self.busy = false;
        Ok(())
    }
}

