/// Begin monster-source frames (donor `beginMonsterFrames`, unowned scaffold).
#[allow(dead_code)]
pub(super) fn begin_monster_frames(
    state: &mut SharedSimulationState,
    milliseconds: f64,
    map: bool,
) -> Result<(), RuntimeError> {
    use qa_content::q2::foundation::host::Q2Edition;
    let map_provider = provider_text(&state.recipe.map.entities.provider);
    let world_clock = provider_timing(&state.recipe, &map_provider)?.clock;
    let source_frame = state.source_frame;
    for source in state.monster_sources.values_mut() {
        if let Some((reference, clock, game, addon)) = source.q1_frame_parts() {
            clock.advanced = false;
            if !map {
                continue;
            }
            let timing_provider = provider_text(&reference.provider);
            let timing = provider_timing(&state.recipe, &timing_provider)?.clock;
            let projected = super::provider_frames::provider_frame(source_frame, &world_clock, &timing);
            clock.frame = projected;
            clock.advanced = true;
            game.begin_frame(seconds(projected.time), seconds(projected.elapsed));
            if let Some(addon) = addon.as_ref() {
                q1_monster_addon_frame(addon, seconds(projected.elapsed));
            }
        } else if let Some((clock, game)) = source.q2_frame_parts() {
            clock.advanced = false;
            let classic = game.options.edition == Q2Edition::Classic;
            let interval = if classic { 100.0 } else { 25.0 };
            let next = (seconds(clock.frame.time) * 1000.0).round() + interval;
            if milliseconds != next {
                continue;
            }
            let (time, elapsed) = if classic {
                (
                    SourceTime::Seconds((next / 1000.0) as f32),
                    SourceTime::Seconds((interval / 1000.0) as f32),
                )
            } else {
                (
                    SourceTime::Milliseconds(next as i32),
                    SourceTime::Milliseconds(interval as i32),
                )
            };
            clock.frame = FrameContext {
                frame: clock.frame.frame + 1,
                phase: qa_core::time::FramePhase::FrameEntry,
                time,
                elapsed,
            };
            clock.advanced = true;
            q2_monster_begin_frame(game);
        }
    }
    Ok(())
}

/// Whether a QuakeC client advances its own punch (donor `clientPunchAdvances`).
///
/// Missing siblings: CQ owns `quakec_source.rs`; the client punch hook has no
/// Rust home yet. Neutral `true` preserves the NetQuake skip shape.
#[allow(dead_code)]
fn quakec_client_punch_advances(source: &SourceRuntime, actor: &ActorId) -> bool {
    let _ = (source, actor);
    true
}

/// Advance Q1 punch angles (donor `advanceQ1Punch`, unowned scaffold).
#[allow(dead_code)]
pub(super) fn advance_q1_punch(
    state: &mut SharedSimulationState,
    actors: &Rc<RefCell<SessionActorRegistry>>,
) -> Result<(), RuntimeError> {
    use qa_core::numeric::{NumericOps, Q1_DONOR_PROFILE};
    let numeric = NumericOps::select(Q1_DONOR_PROFILE).map_err(|error| RuntimeError::Failure(error.to_string()))?;
    for actor in sim_players(state) {
        let owned = actors.borrow().resolve_owned(&actor);
        let Some(owned) = owned else { continue };
        let Some(player) = state.player_states.get(&owned) else {
            continue;
        };
        if player.cutscene.is_some() || player.intermission {
            continue;
        }
        if let MovementState::Q1Netquake(q1) = &player.state {
            if q1.move_type == 0 {
                continue;
            }
        }
        let quakec_netquake = matches!(
            &state.source,
            SourceRuntime::QuakeC { game } if game.kind() == super::types::QuakeCSourceKind::Netquake
        );
        if quakec_netquake {
            let is_netquake = matches!(player.state, MovementState::Q1Netquake(_));
            if is_netquake || !quakec_client_punch_advances(&state.source, &actor) {
                continue;
            }
        }
        let elapsed = seconds(state.source_frame.elapsed);
        let punch = state
            .q1_punch
            .advance(&actor, elapsed, &numeric)
            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        if let Some(player) = state.player_states.get_mut(&owned) {
            if let MovementState::Q1Netquake(q1) = &mut player.state {
                q1.punch_angles = punch;
            }
        }
    }
    Ok(())
}

/// Source-order position (donor `sourcePosition`, C4 range).
#[allow(dead_code)]
pub(super) fn source_position(
    state: &SharedSimulationState,
    actors: &Rc<RefCell<SessionActorRegistry>>,
    actor: &ActorId,
) -> (i64, i64) {
    let registry = actors.borrow();
    let source = registry.source_of(actor);
    let provider = source
        .as_ref()
        .map(|(provider, _)| qa_world::registry::provider_key(provider))
        .or_else(|| {
            registry
                .observe(actor)
                .map(|observed| qa_world::registry::provider_key(&observed.owner))
        })
        .unwrap_or_else(|| "world:unknown".to_string());
    let slot = source
        .map(|(_, slot)| i64::from(slot))
        .unwrap_or_else(|| i64::from(actor.slot()));
    match &state.recipe.ordering {
        qa_content::contract::FrameOrdering::Mixed { providers } => {
            let index = providers
                .iter()
                .position(|candidate| qa_world::registry::provider_key(candidate) == provider)
                .map(|index| index as i64)
                .unwrap_or(-1);
            (index, slot)
        }
        _ => {
            let map_provider = provider_text(&state.recipe.map.entities.provider);
            if provider != map_provider {
                (1, i64::from(actor.slot()))
            } else {
                (0, slot)
            }
        }
    }
}

// ---------------------------------------------------------------------------
// C8 step/frame region (donor `runtime.ts` 5470-6004).
//
// Step/frame advance for native Quake II guests, Q3 round restart, team-game
// policy, presentation commit points, and selected-arsenal grants. Actor turn
// iteration uses [`ordered_actor_turns`]; native guest stepping goes through
// the real guest-world and compat sibling surfaces.
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Current output (donor `currentOutput`, C6 range).
    pub fn current_output(&self) -> Result<SimulationOutput, RuntimeError> {
        self.assert_open()?;
        Ok(SimulationOutput {
            snapshot: self.snapshot()?,
            events: Vec::new(),
        })
    }

    /// World snapshot (donor `snapshot`, C6 range).
    ///
    /// Contract note: donor `snapshot` also carries `session`,
    /// `configurations`, and `scene` (donor 4780-4785), but
    /// `qa_world::session::WorldSnapshot` — the contract the network lanes
    /// build on — models only frame/actors/bodies/inventories. This port
    /// fills the four contracted fields; the extras need a world-lane
    /// decision before they have a Rust home.
    pub fn snapshot(&self) -> Result<WorldSnapshot, RuntimeError> {
        let state = self.peek();
        let actors = self.actors.borrow();
        let observations = actors.observations();
        let snapshot_actors: Vec<qa_world::session::SnapshotActor> = observations
            .iter()
            .map(|observed| qa_world::session::SnapshotActor {
                id: qa_core::identity::SavedActorId::from(&observed.id),
                owner: observed.owner.clone(),
                definition: observed.definition.clone(),
            })
            .collect();
        let tables = self.bodies_table.borrow();
        let bodies: Vec<qa_world::session::SnapshotBody> = observations
            .iter()
            .filter_map(|observed| {
                let id = qa_core::identity::SavedActorId::from(&observed.id);
                tables
                    .read(actors.inner(), &observed.id)
                    .map(|body| qa_world::session::SnapshotBody { id, state: body })
            })
            .collect();
        let inventories: Vec<qa_world::session::SnapshotInventory> = sim_players(&state)
            .into_iter()
            .map(|actor| {
                let entries = state.inventory.inner().entries(actors.inner(), &actor);
                qa_world::session::SnapshotInventory {
                    id: qa_core::identity::SavedActorId::from(&actor),
                    entries,
                }
            })
            .collect();
        Ok(WorldSnapshot {
            frame: state.source_frame,
            actors: snapshot_actors,
            bodies,
            inventories,
        })
    }
}

