///
/// Missing siblings: C5 ports `arsenal` (donor 3872); the merge replaces this
/// player-state passthrough.
fn arsenal_seam(player: &MovementPlayer) -> qa_world::movement::types::ArsenalState {
    player.arsenal.clone()
}

impl SharedSimulation {
    /// Weapon slot projection (donor `slotProjection`, C6 range).
    pub fn slot_projection(
        &self,
        actor: &ActorId,
        model: Option<super::types::SimulationPresentation>,
    ) -> Result<super::weapon_slot_projection::WeaponSlotProjection, RuntimeError> {
        use super::types::{PlayerUiItem, SimulationPresentation};
        use super::weapon_slot::WeaponReference;
        use super::weapon_slot_projection::WeaponSlotProjection;
        use super::weapon_slot_projection::{project_weapon_slot, EquipmentWeaponProjection};
        use qa_content::contract::{GrappleBinding, GrappleMechanicDetail, SourceItemKind};
        use qa_content::q3::foundation::arsenal::q3_weapon_item;
        let native = matches!(
            self.peek().source,
            SourceRuntime::Q2Native(_) | SourceRuntime::Q3Qvm { .. }
        );
        let ui = if native {
            self.native_player_ui(actor)?
        } else {
            self.primary_ui(actor)?
        };
        let state = self.lock();
        let player = if native {
            None
        } else {
            Some(require_sim_player(&state, &self.actors, actor)?)
        };
        let arsenal = player.as_ref().map(arsenal_seam);
        let q3_pending = match player.as_ref() {
            None => state.native_weapon_requests.get(actor).copied(),
            Some(player) => state
                .q3_arsenals
                .get(&player.actor)
                .and_then(|arsenal| arsenal.requested_weapon),
        };
        let pending_item = if state
            .selected_arsenal
            .as_ref()
            .is_some_and(|selected| selected.has(actor))
        {
            state
                .selected_arsenal
                .as_ref()
                .and_then(|selected| selected.pending_weapon(actor))
        } else if let Some(arsenal) = arsenal.as_ref() {
            match &arsenal.state {
                qa_world::movement::types::WeaponState::Q2 { pending_weapon, .. } => pending_weapon.clone(),
                _ => q3_pending.and_then(|weapon| q3_weapon_item(weapon).map(|item| item.item.clone())),
            }
        } else {
            q3_pending.and_then(|weapon| q3_weapon_item(weapon).map(|item| item.item.clone()))
        };
        let primary = WeaponSlotProjection {
            active: ui.active_weapon.clone().map(|item| WeaponReference {
                provider: state.weapon_provider.provider.clone(),
                item,
            }),
            pending: pending_item.map(|item| WeaponReference {
                provider: state.weapon_provider.provider.clone(),
                item,
            }),
            ui,
            model,
        };
        let (presentations, snapshot) = match state.weapon_slots.get(actor) {
            None => return Ok(primary),
            Some(slot) => (
                slot.presentations()
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?,
                slot.snapshot(),
            ),
        };
        drop(state);
        let view = player_view_seam(self, actor)?;
        let mut state = self.lock();
        let registry = self.actors.borrow();
        let inner = registry.inner();
        let mut sources = Vec::with_capacity(presentations.len());
        for present in &presentations {
            let definitions: Vec<&qa_content::contract::SourceItemDefinition> = present
                .items
                .iter()
                .filter(|item| matches!(item.kind, SourceItemKind::Weapon(_)))
                .collect();
            let active = definitions
                .iter()
                .find(|item| Some(&item.item) == present.active.as_ref());
            let ammo_item = active.and_then(|item| match &item.kind {
                SourceItemKind::Weapon(weapon) => weapon.ammo.clone(),
                SourceItemKind::Counter => None,
            });
            let ammo = ammo_item.map(|item| super::types::UiAmmo {
                count: state.inventory.count(inner, actor, &item),
                item,
            });
            let weapon_status = active.map(|item| {
                let ammo = match (&item.kind, ammo.clone()) {
                    (SourceItemKind::Weapon(_), Some(ammo)) => super::arsenal::selected::WeaponAmmoStatus::Finite {
                        item: ammo.item.clone(),
                        count: ammo.count,
                        has_ammo_to_start: ammo.count > 0.0,
                        low: false,
                    },
                    _ => super::arsenal::selected::WeaponAmmoStatus::Unmetered,
                };
                super::arsenal::selected::WeaponHudStatus {
                    source: present.source.clone(),
                    item: item.item.clone(),
                    label: item.label.clone(),
                    ammo,
                }
            });
            let held = active.and_then(|item| match &item.kind {
                SourceItemKind::Weapon(weapon) => weapon.held.clone(),
                SourceItemKind::Counter => None,
            });
            let content = present.source.content.as_str();
            let family = if content.starts_with("q1:") {
                GameFamily::Q1
            } else if content.starts_with("q2:") {
                GameFamily::Q2
            } else {
                GameFamily::Q3
            };
            let (path, frame) = match present.model.as_ref() {
                None => (String::new(), 0),
                Some(qa_content::contract::SourceWeaponModel::Resolved { resource, frame }) => {
                    (resource.requested_path.clone(), *frame as i32)
                }
                Some(qa_content::contract::SourceWeaponModel::SourcePath { path, frame }) => {
                    (path.clone(), *frame as i32)
                }
            };
            let model = if present.model.is_none() && held.is_none() {
                None
            } else {
                Some(SimulationPresentation {
                    actor: actor.clone(),
                    content: present.source.content.clone(),
                    held_weapon: held,
                    family,
                    path,
                    frame,
                    old_frame: frame,
                    origin: add(
                        view.origin,
                        Vec3 {
                            x: 0.0,
                            y: 0.0,
                            z: view.view_height as f32,
                        },
                    ),
                    angles: view.angles,
                    scale: 1.0,
                    visible: present.model.is_some()
                        && primary.ui.health > 0.0
                        && player
                            .as_ref()
                            .is_none_or(|player| !player.intermission && player.cutscene.is_none()),
                    view_weapon: true,
                    native_held_weapon: false,
                    weapon_item: None,
                    replaces_body: false,
                    render_source_client: false,
                    flare: None,
                    back_lerp: None,
                    skin: 0,
                    skin_path: None,
                    indexed_skin: None,
                    player_colors: None,
                    effects: 0,
                    render_flags: 0,
                    previous_origin: None,
                    model_beam: None,
                    shader_beam: None,
                    model_attachments: None,
                    model_anchor: None,
                    q3_grapple_cable: None,
                    alpha: None,
                    q3_weapon: None,
                })
            };
            if let Some(qa_content::contract::SourceWeaponModel::Resolved { resource, .. }) = present.model.as_ref() {
                state
                    .events
                    .register_resource(&present.source.content, &resource.requested_path, resource.clone())
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            }
            sources.push(super::weapon_slot_projection::SourceWeaponProjection {
                provider: present.source.provider.clone(),
                active: present.active.clone().map(|item| WeaponReference {
                    provider: present.source.provider.clone(),
                    item,
                }),
                pending: present.pending.clone().map(|item| WeaponReference {
                    provider: present.source.provider.clone(),
                    item,
                }),
                items: definitions
                    .iter()
                    .enumerate()
                    .map(|(index, definition)| PlayerUiItem {
                        id: definition.item.clone(),
                        label: definition.label.clone(),
                        kind: super::types::PlayerUiItemKind::Weapon,
                        source_ordinal: primary.ui.items.len() as f64 + index as f64,
                        owned: state.inventory.count(inner, actor, &definition.item) > 0.0,
                        has_ammo: match &definition.kind {
                            SourceItemKind::Weapon(weapon) => weapon
                                .ammo
                                .as_ref()
                                .is_none_or(|ammo| state.inventory.count(inner, actor, ammo) > 0.0),
                            SourceItemKind::Counter => true,
                        },
                        count: match &definition.kind {
                            SourceItemKind::Weapon(weapon) => weapon
                                .ammo
                                .as_ref()
                                .map(|ammo| state.inventory.count(inner, actor, ammo)),
                            SourceItemKind::Counter => None,
                        },
                        warning_count: 0.0,
                    })
                    .collect(),
                weapon_status,
                ammo,
                model,
            });
        }
        let (selection, grapple) = match state.grapple.as_ref() {
            Some(grapple) => match grapple.selection() {
                qa_content::contract::GrappleSelection::Enabled {
                    source,
                    binding,
                    mechanic,
                } if *binding == GrappleBinding::Slot => ((source.clone(), mechanic.clone()), grapple),
                _ => return Ok(project_weapon_slot(&snapshot, &primary, None, &sources)),
            },
            None => return Ok(project_weapon_slot(&snapshot, &primary, None, &sources)),
        };
        let gear = grapple.weapon_view(actor);
        let weapon = grapple.weapon();
        let gear_model = gear.as_ref().map(|gear| {
            let (path, frame, kick_origin, kick_pitch, model_attachments, model_anchor, q3_weapon) = match gear {
                super::grapple_runtime::GrappleWeaponView::Standard {
                    path,
                    frame,
                    kick_origin,
                    kick_pitch,
                } => (path.clone(), *frame, *kick_origin, *kick_pitch, None, None, None),
                super::grapple_runtime::GrappleWeaponView::Qvm(view) => (
                    view.path.clone(),
                    view.frame,
                    view.kick_origin,
                    view.kick_pitch,
                    Some(
                        view.model_attachments
                            .iter()
                            .map(|attachment| super::types::ModelAttachment {
                                path: attachment.path.clone(),
                                tag: attachment.tag.clone(),
                            })
                            .collect(),
                    ),
                    Some(view.model_anchor.clone()),
                    Some(super::types::Q3WeaponPresentation {
                        time_milliseconds: view.q3_weapon.time_ms as i32,
                        torso_animation: view.q3_weapon.torso_animation,
                        last_fire_milliseconds: view.q3_weapon.last_fire_ms.map(|value| value as i32),
                        firing: view.q3_weapon.firing,
                        horizontal_speed: view.q3_weapon.horizontal_speed,
                        bob_cycle: f64::from(view.q3_weapon.bob_cycle),
                        weapon: view.q3_weapon.weapon as i32,
                    }),
                ),
            };
            SimulationPresentation {
                actor: actor.clone(),
                content: selection.0.content.clone(),
                family: match selection.1 {
                    GrappleMechanicDetail::Q1Threewave { .. } => GameFamily::Q1,
                    GrappleMechanicDetail::Q3Qvm { .. } => GameFamily::Q3,
                    _ => GameFamily::Q2,
                },
                path,
                frame,
                old_frame: frame,
                origin: add(
                    add(
                        view.origin,
                        Vec3 {
                            x: 0.0,
                            y: 0.0,
                            z: view.view_height as f32,
                        },
                    ),
                    kick_origin,
                ),
                angles: add(
                    view.angles,
                    Vec3 {
                        x: kick_pitch as f32,
                        y: 0.0,
                        z: 0.0,
                    },
                ),
                scale: 1.0,
                visible: primary.ui.health > 0.0
                    && player
                        .as_ref()
                        .is_none_or(|player| !player.intermission && player.cutscene.is_none()),
                view_weapon: true,
                model_attachments,
                model_anchor,
                q3_weapon,
                held_weapon: None,
                native_held_weapon: false,
                weapon_item: None,
                replaces_body: false,
                render_source_client: false,
                flare: None,
                back_lerp: None,
                skin: 0,
                skin_path: None,
                indexed_skin: None,
                player_colors: None,
                effects: 0,
                render_flags: 0,
                previous_origin: None,
                model_beam: None,
                shader_beam: None,
                q3_grapple_cable: None,
                alpha: None,
            }
        });
        let equipment = EquipmentWeaponProjection {
            source: selection.0.clone(),
            item: PlayerUiItem {
                id: weapon.item.clone(),
                label: (if matches!(selection.1, GrappleMechanicDetail::Q2Lmctf) {
                    "Hook"
                } else {
                    "Grapple"
                })
                .to_string(),
                kind: super::types::PlayerUiItemKind::Weapon,
                source_ordinal: primary.ui.items.len() as f64,
                owned: state.inventory.count(inner, actor, &weapon.item) > 0.0,
                has_ammo: true,
                count: None,
                warning_count: 0.0,
            },
            weapon,
            model: gear_model,
        };
        Ok(project_weapon_slot(&snapshot, &primary, Some(&equipment), &sources))
    }
}

// C6 native inventory surface (donor 4831-4921 + owned seams).

/// Native drop debit/consume kind (donor `nativeDropProtection` kind).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NativeDropKind {
    /// Debit the original inventory around the effect.
    Debit,
    /// Consume the original inventory around the effect.
    Consume,
}

/// Native drop projection (donor `nativeDropProjection` result).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NativeDropProjection {
    /// Original drop source item.
    pub source: ItemId,
    /// Projected current weapon, if the selection still shows one.
    pub current: Option<ItemId>,
    /// Projected pending weapon, if the selection still shows one.
    pub pending: Option<ItemId>,
}

/// Rerelease primary protection around a debit/consume effect (donor
/// `withRereleasePrimaryProtection`).
///
/// Missing siblings: the rerelease/compat lane owns the guest-memory armor
/// protection (`source.game.source.host` has no Rust home, and the guest
/// worlds implement no `NativePrimaryWeaponWorld`). The ownership check and
/// the effect run; only the armor-memory shielding is omitted.
fn with_rerelease_primary_protection_seam<R>(
    current_owner: bool,
    kind: NativeDropKind,
    execute: impl FnOnce() -> Result<R, RuntimeError>,
) -> Result<R, RuntimeError> {
    if !current_owner {
        return fail("Original inventory drop owner retired during its effect");
    }
    let _ = kind;
    execute()
}

/// Native configstrings (donor `source.game.configstrings`).
///
/// Missing siblings: the q2-native lane owns configstring exposure on the
/// guest worlds. Labels fall back to `""` per the donor `?? ""`.
fn q2_native_configstrings(source: &Q2NativeSource) -> std::collections::HashMap<i32, String> {
    let _ = source;
    std::collections::HashMap::new()
}

/// Weapon request (donor `requestWeapon`, C11 range).
///
/// The bound-slot path is real; the primary-handoff fallback and equipment
/// admission are C11's (`primaryHandoff`, `requireEquipmentPlayer`).
impl SharedSimulation {
    /// Guard an original-inventory drop (donor `nativeDropProtection`, C6 range).
    pub fn native_drop_protection<R>(
        &self,
        actor: &ActorId,
        kind: NativeDropKind,
        execute: impl FnOnce() -> Result<R, RuntimeError>,
    ) -> Result<R, RuntimeError> {
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q2Native(Q2NativeSource::Classic { .. }) => execute(),
            SourceRuntime::Q2Native(Q2NativeSource::Rerelease { .. }) => {
                let current_owner = self.actors.borrow().is_live(actor);
                with_rerelease_primary_protection_seam(current_owner, kind, execute)
            }
            _ => fail("Original inventory drop lost its native source"),
        }
    }

    /// Original drop owner for ammunition (donor `nativeDropAmmoSource`, C6 range).
    pub fn native_drop_ammo_source(&self, item: &ItemId) -> Result<ItemId, RuntimeError> {
        let state = self.peek();
        let supply = state.selected_original_supply.as_ref().ok_or_else(|| {
            RuntimeError::Failure("Selected dropped ammunition has no original supply policy".to_string())
        })?;
        let commands = state.native_primary_commands.as_ref().ok_or_else(|| {
            RuntimeError::Failure("Selected dropped ammunition has no original supply policy".to_string())
        })?;
        let slots = commands.inventory_slots();
        if slots.iter().any(|slot| &slot.item == item && slot.ammunition)
            && supply
                .ammo
                .iter()
                .any(|row| &row.source == item && row.destinations.contains(item))
        {
            return Ok(item.clone());
        }
        let owner = supply
            .ammo_owners
            .iter()
            .find(|row| &row.item == item)
            .map(|row| row.source.clone());
        let candidates: Vec<&qa_content::contract::PickupRoute> = supply
            .ammo
            .iter()
            .filter(|row| row.destinations.contains(item))
            .collect();
        let mapping = match owner {
            None => {
                if candidates.len() == 1 {
                    Some(candidates[0])
                } else {
                    None
                }
            }
            Some(owner) => candidates.into_iter().find(|row| row.source == owner),
        };
        match mapping {
            Some(mapping) if slots.iter().any(|slot| slot.item == mapping.source && slot.ammunition) => {
                Ok(mapping.source.clone())
            }
            _ => fail(format!(
                "Selected ammunition {item} has no unique available original drop owner"
            )),
        }
    }

    /// Native drop projection (donor `nativeDropProjection`, C6 range).
    pub fn native_drop_projection(&self, actor: &ActorId, item: &ItemId) -> Result<NativeDropProjection, RuntimeError> {
        let state = self.peek();
        let prototypes = native_primary_profile(&state).map(|profile| profile.inventory().prototypes.clone());
        let prototypes = prototypes
            .ok_or_else(|| RuntimeError::Failure("Native drop has no declared original item prototypes".to_string()))?;
        let component = state
            .inventory
            .item_definitions(actor)
            .into_iter()
            .find(|definition| &definition.item == item);
        let owner = self.actors.borrow().resolve_owned(actor);
        let equipment = match (owner, state.selected_q3_source.as_ref()) {
            (Some(owner), Some(selected)) => selected
                .inventory(&owner)
                .map_err(|error| RuntimeError::Failure(error.to_string()))?
                .into_iter()
                .find(|entry| &entry.item == item),
            _ => None,
        };
        if component.is_some() || equipment.is_some() {
            let droppable = component.is_some_and(|component| component.actions.iter().any(|action| action == "drop"));
            return Ok(NativeDropProjection {
                source: if droppable {
                    prototypes.droppable.clone()
                } else {
                    prototypes.undroppable.clone()
                },
                current: None,
                pending: None,
            });
        }
        let selected = state.selected_arsenal.as_ref();
        let supply = state.selected_original_supply.as_ref();
        let sources = state.selected_original_weapons.as_ref();
        let admitted = selected.is_some_and(|selected| selected.has(actor));
        if !admitted || supply.is_none() || sources.is_none() {
            return fail("Selected drop has no admitted supply policy");
        }
        let selected = selected.expect("admitted selected arsenal");
        let sources = sources.expect("admitted supply sources").clone();
        let weapon = selected.catalog().into_iter().find(|weapon| &weapon.item == item);
        let source_weapon = sources.get(item);
        let source = if weapon.is_some() {
            match source_weapon {
                None => return fail("Selected dropped weapon has no original supply owner"),
                Some(source) => source.clone().unwrap_or_else(|| prototypes.undroppable.clone()),
            }
        } else {
            drop(state);
            self.native_drop_ammo_source(item)?
        };
        let slot = self.weapon_slot(actor)?;
        let active = slot.active.as_ref().map(|weapon| weapon.item.clone());
        let pending = slot.pending.as_ref().map(|weapon| weapon.item.clone());
        let project = |current: Option<ItemId>| -> Result<Option<ItemId>, RuntimeError> {
            let Some(current) = current else { return Ok(None) };
            let Some(native) = sources.get(&current) else {
                return fail("Current selected weapon has no original supply owner");
            };
            if weapon.is_some() && current != *item && native.as_ref() == Some(&source) {
                return Ok(None);
            }
            Ok(native.clone())
        };
        Ok(NativeDropProjection {
            source: source.clone(),
            current: project(active)?,
            pending: project(pending)?,
        })
    }

    /// Native inventory rows (donor `nativeInventoryRows`, C6 range).
    pub fn native_inventory_rows(
        &self,
        actor: &ActorId,
    ) -> Result<Option<Vec<qa_compat::q2::native_primary_inventory::NativeInventoryRow>>, RuntimeError> {
        use qa_compat::q2::native_primary_inventory::{InventoryPresentation, NativeInventoryRow};
        let state = self.peek();
        let SourceRuntime::Q2Native(source) = &state.source else {
            return Ok(None);
        };
        let Some(commands) = state.native_primary_commands.as_ref() else {
            return Ok(None);
        };
        let selected = state.selected_arsenal.as_ref().filter(|selected| selected.has(actor));
        let definitions = state.inventory.item_definitions(actor);
        if selected.is_none() && definitions.is_empty() {
            return Ok(None);
        }
        let slots = commands.inventory_slots();
        let labels = q2_native_configstrings(source);
        let label_base = match source {
            Q2NativeSource::Classic { .. } => 1056,
            Q2NativeSource::Rerelease { .. } => 11326,
        };
        let label_for =
            |index: u32| -> String { labels.get(&(label_base + index as i32)).cloned().unwrap_or_default() };
        let actors = self.actors.borrow();
        let inner = actors.inner();
        let native: Vec<NativeInventoryRow> = slots
            .iter()
            .filter(|slot| selected.is_none() || (!slot.weapon && !slot.ammunition))
            .map(|slot| NativeInventoryRow {
                item: slot.item.clone(),
                label: label_for(slot.index),
                count: state.inventory.count(inner, actor, &slot.item) as i32,
                source_index: slot.index,
                selected: false,
                presence_only: false,
                presentation: None,
            })
            .collect();
        let prototypes = native_primary_profile(&state).map(|profile| profile.inventory().prototypes.clone());
        let prototypes = prototypes.ok_or_else(|| {
            RuntimeError::Failure("Native inventory has no declared original item prototypes".to_string())
        })?;
        let weapon_prototype = slots
            .iter()
            .find(|slot| slot.item == prototypes.weapon)
            .ok_or_else(|| {
                RuntimeError::Failure("Original inventory lacks its declared weapon/ammo prototypes".to_string())
            })?;
        let ammo_prototype = slots
            .iter()
            .find(|slot| slot.item == prototypes.ammunition)
            .ok_or_else(|| {
                RuntimeError::Failure("Original inventory lacks its declared weapon/ammo prototypes".to_string())
            })?;
        let provider_key = qa_world::registry::provider_key(&state.weapon_provider.provider);
        let mut weapons = Vec::new();
        if let Some(selected) = selected {
            if let Some(ui) = selected.ui(actor, &state.weapon_provider) {
                weapons = ui
                    .items
                    .iter()
                    .filter(|item| item.kind == super::types::PlayerUiItemKind::Weapon)
                    .map(|item| NativeInventoryRow {
                        item: item.id.clone(),
                        label: item.label.clone(),
                        count: state.inventory.count(inner, actor, &item.id) as i32,
                        source_index: weapon_prototype.index,
                        selected: true,
                        presence_only: false,
                        presentation: Some(InventoryPresentation::Weapon {
                            source: provider_key.clone(),
                            weapon: item.id.clone(),
                        }),
                    })
                    .collect();
            }
        }
        let mut ammunition = Vec::new();
        if let Some(selected) = selected {
            let mut seen = std::collections::HashSet::new();
            for weapon in selected.catalog() {
                let Some(ammo) = weapon.ammo.clone() else { continue };
                if !seen.insert(ammo.clone()) {
                    continue;
                }
                if weapons.iter().any(|row: &NativeInventoryRow| row.item == ammo) {
                    continue;
                }
                let weapon = selected
                    .catalog()
                    .into_iter()
                    .find(|weapon| weapon.ammo.as_ref() == Some(&ammo))
                    .ok_or_else(|| {
                        RuntimeError::Failure("Selected ammo has no authored weapon presentation".to_string())
                    })?;
                let family = match selected {
                    SelectedArsenal::Q1(_) => super::arsenal::selected::ArsenalFamily::Q1,
                    SelectedArsenal::Q2(_) => super::arsenal::selected::ArsenalFamily::Q2,
                    SelectedArsenal::Q3(_) => super::arsenal::selected::ArsenalFamily::Q3,
                };
                let label = super::arsenal::inventory_labels::selected_ammo_label(family, &ammo)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                ammunition.push(NativeInventoryRow {
                    item: ammo.clone(),
                    label,
                    count: state.inventory.count(inner, actor, &ammo) as i32,
                    source_index: ammo_prototype.index,
                    selected: true,
                    presence_only: false,
                    presentation: Some(InventoryPresentation::Ammunition {
                        source: provider_key.clone(),
                        weapon: weapon.item.clone(),
                    }),
                });
            }
        }
        let mut retained = Vec::new();
        if selected.is_some() {
            let entities_key = qa_world::registry::provider_key(&state.recipe.map.entities.provider);
            for slot in slots.iter().filter(|slot| {
                slot.ammunition
                    && !ammunition.iter().any(|row: &NativeInventoryRow| row.item == slot.item)
                    && state.selected_original_supply.as_ref().is_some_and(|supply| {
                        supply
                            .ammo
                            .iter()
                            .any(|mapping| mapping.destinations.contains(&slot.item))
                    })
            }) {
                let icon = if slot.icon.is_empty() {
                    None
                } else if slot.icon.starts_with('/') || slot.icon.starts_with('\\') {
                    Some(slot.icon[1..].to_string())
                } else {
                    Some(format!("pics/{}.pcx", slot.icon))
                };
                retained.push(NativeInventoryRow {
                    item: slot.item.clone(),
                    label: label_for(slot.index),
                    count: state.inventory.count(inner, actor, &slot.item) as i32,
                    source_index: ammo_prototype.index,
                    selected: true,
                    presence_only: false,
                    presentation: Some(InventoryPresentation::Item {
                        source: entities_key.clone(),
                        icon,
                    }),
                });
            }
        }
        let usable_prototype = slots
            .iter()
            .find(|slot| slot.item == prototypes.usable)
            .ok_or_else(|| {
                RuntimeError::Failure("Original inventory lacks usable and passive item prototypes".to_string())
            })?;
        let passive_prototype = slots
            .iter()
            .find(|slot| slot.item == prototypes.passive)
            .ok_or_else(|| {
                RuntimeError::Failure("Original inventory lacks usable and passive item prototypes".to_string())
            })?;
        let owner = actors.resolve_owned(actor);
        let mut equipment = Vec::new();
        if let Some(owner) = owner {
            if let Some(selected_q3) = state.selected_q3_source.as_ref() {
                equipment = selected_q3
                    .inventory(&owner)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?
                    .into_iter()
                    .map(|entry| NativeInventoryRow {
                        item: entry.item.clone(),
                        label: entry.label.clone(),
                        count: entry.count,
                        source_index: if entry.usable {
                            usable_prototype.index
                        } else {
                            passive_prototype.index
                        },
                        selected: true,
                        presence_only: false,
                        presentation: Some(InventoryPresentation::Item {
                            source: provider_key.clone(),
                            icon: entry.icon.clone(),
                        }),
                    })
                    .collect();
            }
        }
        let components: Vec<NativeInventoryRow> = definitions
            .iter()
            .map(|item| {
                let source_index = if item.kind == "weapon" {
                    weapon_prototype.index
                } else if item.actions.iter().any(|action| action == "use") {
                    usable_prototype.index
                } else if definitions
                    .iter()
                    .any(|weapon| weapon.kind == "weapon" && weapon.ammo.as_ref() == Some(&item.item))
                {
                    ammo_prototype.index
                } else {
                    passive_prototype.index
                };
                let item_source = qa_world::registry::provider_key(&item.source.provider);
                NativeInventoryRow {
                    item: item.item.clone(),
                    label: item.label.clone(),
                    count: state.inventory.count(inner, actor, &item.item) as i32,
                    source_index,
                    selected: true,
                    presence_only: true,
                    presentation: Some(InventoryPresentation::Item {
                        source: item_source,
                        icon: item.icon.clone(),
                    }),
                }
            })
            .collect();
        let mut order: Vec<ItemId> = Vec::new();
        let mut merged: std::collections::HashMap<ItemId, NativeInventoryRow> = std::collections::HashMap::new();
        for row in weapons
            .into_iter()
            .chain(ammunition)
            .chain(retained)
            .chain(native)
            .chain(equipment)
            .chain(components)
        {
            if !merged.contains_key(&row.item) {
                order.push(row.item.clone());
            }
            merged.insert(row.item.clone(), row);
        }
        Ok(Some(
            order.into_iter().filter_map(|item| merged.remove(&item)).collect(),
        ))
    }

    /// Use a selected inventory item (donor `useSelectedInventoryItem`, C6 range).
    pub fn use_selected_inventory_item(&self, actor: &ActorId, item: &ItemId) -> Result<(), RuntimeError> {
        let state = self.peek();
        let definition = state
            .inventory
            .item_definitions(actor)
            .into_iter()
            .find(|value| &value.item == item);
        let catalogued = state
            .selected_arsenal
            .as_ref()
            .is_some_and(|selected| selected.catalog().iter().any(|weapon| &weapon.item == item));
        if definition
            .as_ref()
            .is_some_and(|definition| definition.kind == "weapon")
            || catalogued
        {
            let provider = definition
                .map(|definition| definition.source.provider.clone())
                .unwrap_or_else(|| state.weapon_provider.provider.clone());
            drop(state);
            self.request_weapon(
                actor,
                &super::weapon_slot::WeaponReference {
                    provider,
                    item: item.clone(),
                },
            )?;
            return Ok(());
        }
        if let Some(action) = state.inventory.item_action(actor, item, "use") {
            drop(state);
            action();
            return Ok(());
        }
        let q3_selected = state
            .selected_arsenal
            .as_ref()
            .is_some_and(|selected| selected.family() == "q3");
        if q3_selected {
            drop(state);
            let mut state = self.lock();
            let selected = state.selected_arsenal.as_mut().expect("q3 selected arsenal");
            if selected.use_item(actor, item)? {
                return Ok(());
            }
        }
        fail("Admitted selected inventory item has no use owner")
    }
}
