// C3 §2a: victim armor context (donor `victimArmorContext`, runtime.ts
// 3105-3117) + world-actor lookup (donor `worldActor`, runtime.ts:3276).
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// World actor id (donor `worldActor`, donor runtime.ts 3276, C4
    /// canonical).
    ///
    /// Donor `actors.atSource(provider, provider.startsWith("q3:") ? 1022 :
    /// 0)?.id ?? null`, exact.
    pub fn world_actor(&self) -> Option<ActorId> {
        let state = self.peek();
        let provider = &state.recipe.map.entities.provider;
        let slot = if provider_text(provider).starts_with("q3:") {
            1022
        } else {
            0
        };
        self.actors().at_source(provider, slot).map(|owned| owned.id().clone())
    }

    /// Victim context for native armor absorption (donor
    /// `victimArmorContext`, runtime.ts 3105-3117).
    ///
    /// The donor reads the Q2 edition from the victim execution entry's
    /// live services; entries carry identity only here, so the Q2 branch
    /// reads the live game-services edition through the state instead and
    /// falls back to the inventory-content probe when the source is not Q2.
    pub fn victim_armor_context(&self, request: &super::events::DamageRequest) -> qa_world::combat::VictimArmorContext {
        use qa_world::combat::{ArmorArithmetic, Q2ArmorContext, Q2ArmorProduct};
        let state = self.peek();
        let rerelease_content = state.recipe.inventory.content.as_str().contains(":rerelease:");
        let ctf = provider_text(&state.recipe.r#match.provider) == "q2:ctf";
        let q2_product = match &state.source {
            SourceRuntime::Q2 { game, .. } => match game.borrow().options.edition {
                qa_content::q2::foundation::host::Q2Edition::Classic => Q2ArmorProduct::Classic,
                qa_content::q2::foundation::host::Q2Edition::Rerelease => Q2ArmorProduct::Rerelease,
            },
            _ => {
                if rerelease_content {
                    Q2ArmorProduct::Rerelease
                } else {
                    Q2ArmorProduct::Classic
                }
            }
        };
        let product = match state.actor_executions.get(&request.target) {
            Some(entry) if entry.kind() == "q2" => q2_product,
            _ => {
                if rerelease_content {
                    Q2ArmorProduct::Rerelease
                } else {
                    Q2ArmorProduct::Classic
                }
            }
        };
        let bodies = self.bodies();
        let body = bodies.read(&request.target);
        let contact = body
            .as_ref()
            .map(|body| subtract(request.point, body.origin))
            .unwrap_or_else(zero);
        let q1_zero_contact = matches!(request.attack.cause, super::events::AttackCause::Q1 { .. })
            && body.is_some()
            && contact.x == 0.0
            && contact.y == 0.0
            && contact.z == 0.0;
        let direction = match (&request.attack.inflictor, q1_zero_contact) {
            (Some(inflictor), true) if self.world_actor().as_ref() != Some(inflictor) => Vec3 {
                x: -request.direction.x,
                y: -request.direction.y,
                z: -request.direction.z,
            },
            _ => contact,
        };
        let dx = direction.x as f64;
        let dy = direction.y as f64;
        let dz = direction.z as f64;
        let length = (dx * dx + dy * dy + dz * dz).sqrt();
        let yaw = body.as_ref().map(|body| body.angles.y as f64).unwrap_or(0.0) * std::f64::consts::PI / 180.0;
        let screen_facing_dot = if length == 0.0 {
            0.0
        } else {
            (dx * yaw.cos() + dy * yaw.sin()) / length
        };
        let alive = state
            .combat
            .read(&request.target)
            .map(|combat| combat.health)
            .unwrap_or(0.0)
            > 0.0;
        qa_world::combat::VictimArmorContext {
            screen_facing_dot,
            arithmetic: ArmorArithmetic::Binary32,
            q2: Some(Q2ArmorContext { product, ctf, alive }),
        }
    }
}

