/// Donor `registerQ2NativeClient` mode (C10 seam; C7 owns the canonical port).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Q2NativeClientMode {
    /// Live admission.
    Live,
    /// Save-restore admission.
    Restore,
}

impl SharedSimulation {
    /// Donor `requirePlayer` (donor runtime.ts 5772).
    pub fn require_player(&self, actor: &ActorId) -> Result<MovementPlayer, RuntimeError> {
        self.player(actor)
            .ok_or_else(|| RuntimeError::Failure("Actor is not an admitted player".to_string()))
    }

    /// Drive a player from a cinematic control (donor `controlPlayer`,
    /// donor 5729, C8's range).
    pub fn control_player(
        &self,
        actor: &ActorId,
        control: &qa_content::q1::foundation::host::Q1CutsceneControl,
    ) -> Result<(), RuntimeError> {
        let player = self.require_player(actor)?;
        let body = self
            .bodies()
            .read(actor)
            .ok_or_else(|| RuntimeError::Failure("Controlled player has no body".to_string()))?;
        self.update_player(actor, |entry| {
            entry.cutscene = Some(PlayerCutscene {
                origin: control.origin,
                angles: control.angles,
                view_offset: control.view_offset,
            });
            entry.view_angles = control.angles;
            entry.view_height = f64::from(control.view_offset.z);
            entry.ground = TraceHit::None;
            match &mut entry.state {
                MovementState::Q1Netquake(state) => {
                    state.origin = control.origin;
                    state.velocity = zero();
                    state.angles = control.angles;
                    state.view_angles = control.angles;
                    state.move_type = 0;
                    state.ground = TraceHit::None;
                }
                MovementState::Q2Classic(state) => {
                    state.move_type = 4;
                    state.origin_eighths = [
                        (f64::from(control.origin.x) * 8.0).trunc() as i32,
                        (f64::from(control.origin.y) * 8.0).trunc() as i32,
                        (f64::from(control.origin.z) * 8.0).trunc() as i32,
                    ];
                    state.velocity_eighths = [0, 0, 0];
                }
                MovementState::Q2Rerelease(state) => {
                    state.move_type = 5;
                    state.origin = control.origin;
                    state.velocity = zero();
                }
                MovementState::Q3(state) => {
                    state.movement_type = 4;
                    state.origin = control.origin;
                    state.velocity = zero();
                    state.view_angles = control.angles;
                    state.ground = TraceHit::None;
                }
                MovementState::Q1Quakeworld(state) => {
                    state.origin = control.origin;
                    state.velocity = zero();
                    state.angles = control.angles;
                }
            }
        })?;
        self.bodies().write(
            &player.actor,
            qa_world::body::BodyState {
                origin: control.origin,
                angles: control.angles,
                velocity: zero(),
                ground: None,
                ..body
            },
        )?;
        self.peek().combat.set_traits(
            &player.actor,
            qa_content::q2::support::contracts::CombatTraitChanges {
                can_take_damage: Some(false),
                ..Default::default()
            },
        )?;
        self.bodies().link(&player.actor)?;
        let services = match &self.peek().source {
            SourceRuntime::Q1 { services, .. } => Some(Rc::clone(services)),
            _ => None,
        };
        if let Some(services) = services {
            services.borrow_mut().player_input(
                &player.actor,
                &qa_content::q1::foundation::entity_services::Q1PlayerInput {
                    attack: false,
                    jump: false,
                    teleport_until: None,
                },
            );
            services
                .borrow_mut()
                .weapon_input(
                    &player.actor,
                    None,
                    control.angles,
                    self.time_seconds(),
                    player.water_level as i32,
                )
                .map_err(source_failure)?;
        }
        Ok(())
    }

    /// Client owning an actor (donor `playerClient`; C7 canonical).
    pub fn player_client(&self, actor: &ActorId) -> Option<ClientId> {
        let state = self.peek();
        if let SourceRuntime::Q2Native(native) = &state.source {
            let clients = match native {
                Q2NativeSource::Classic { clients, .. } => clients,
                Q2NativeSource::Rerelease { clients, .. } => clients,
            };
            return clients
                .iter()
                .find(|(_, owner)| owner.id() == actor)
                .map(|(client, _)| client.clone());
        }
        if let SourceRuntime::Q3Qvm { game, .. } = &state.source {
            return game
                .players()
                .into_iter()
                .find(|player| player.actor == *actor)
                .map(|player| player.client);
        }
        drop(state);
        self.player(actor).map(|player| player.client)
    }

    /// Admitted player actor ids (donor `players`, donor runtime.ts 3283,
    /// C4 canonical).
    ///
    /// The default arm sorts by client slot, matching the donor.
    pub fn players(&self) -> Vec<ActorId> {
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q2Native(native) => {
                let clients = match native {
                    Q2NativeSource::Classic { clients, .. } => clients,
                    Q2NativeSource::Rerelease { clients, .. } => clients,
                };
                clients.values().map(|owner| owner.id().clone()).collect()
            }
            SourceRuntime::Q3Qvm { game, .. } => game.players().into_iter().map(|player| player.actor).collect(),
            _ => {
                let mut players: Vec<&MovementPlayer> = state.player_states.values().collect();
                players.sort_by_key(|player| player.client.slot());
                players.into_iter().map(|player| player.actor.id().clone()).collect()
            }
        }
    }

    /// Native client owning an actor (donor `nativeQ2Client`; C7 canonical).
    pub fn native_q2_client(&self, actor: &ActorId) -> Result<ClientId, RuntimeError> {
        let state = self.peek();
        let native = match &state.source {
            SourceRuntime::Q2Native(native) => native,
            _ => return fail("No native Quake II source"),
        };
        let clients = match native {
            Q2NativeSource::Classic { clients, .. } => clients,
            Q2NativeSource::Rerelease { clients, .. } => clients,
        };
        clients
            .iter()
            .find(|(_, owner)| owner.id() == actor)
            .map(|(client, _)| client.clone())
            .ok_or_else(|| RuntimeError::Failure("Actor has no native Quake II client".to_string()))
    }

    /// Register a native client (donor `registerQ2NativeClient`; C7 canonical).
    pub fn register_q2_native_client(
        &self,
        client: &ClientId,
        mode: Q2NativeClientMode,
    ) -> Result<OwnedActor, RuntimeError> {
        let (is_native, max_clients, already) = {
            let state = self.peek();
            let has = match &state.source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { clients, .. })
                | SourceRuntime::Q2Native(Q2NativeSource::Rerelease { clients, .. }) => clients.contains_key(client),
                _ => false,
            };
            (
                matches!(state.source, SourceRuntime::Q2Native(_)),
                state.options_max_clients,
                has,
            )
        };
        let owns = self.actors.borrow().inner().owner().owns_client(client);
        if !is_native || !owns || client.slot() as usize >= max_clients || already {
            return fail("Invalid native client registration");
        }
        let id = {
            let mut state = self.state.borrow_mut();
            let native = match &mut state.source {
                SourceRuntime::Q2Native(native) => native,
                _ => return fail("No native Quake II source"),
            };
            match native {
                Q2NativeSource::Classic { game, .. } => game
                    .actor(client.slot() + 1)
                    .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                Q2NativeSource::Rerelease { game, .. } => game
                    .actor(client.slot() + 1)
                    .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
            }
        };
        let actor = match id {
            Some(id) => self.actors.borrow().resolve_owned(&id),
            None => None,
        };
        let actor = match actor {
            Some(actor) => actor,
            None => return fail("Native ClientConnect did not reserve its source actor"),
        };
        {
            let mut state = self.state.borrow_mut();
            let native = match &mut state.source {
                SourceRuntime::Q2Native(native) => native,
                _ => return fail("No native Quake II source"),
            };
            match native {
                Q2NativeSource::Classic { clients, .. } | Q2NativeSource::Rerelease { clients, .. } => {
                    clients.insert(client.clone(), actor.clone());
                }
            }
            if mode == Q2NativeClientMode::Live {
                if let Some(travel) = state.options_native_q2_travel.as_ref() {
                    if let Some(selection) = travel
                        .clients()
                        .iter()
                        .find(|entry| entry.client == *client)
                        .and_then(|entry| entry.native_inventory_selection.clone())
                    {
                        state
                            .restored_native_inventory_selections
                            .insert(actor.id().clone(), Some(selection));
                    }
                }
            }
        }
        if mode == Q2NativeClientMode::Live {
            let has_inventory = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game.has_source_inventory(),
                    SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game.has_source_inventory(),
                    _ => false,
                }
            };
            if has_inventory {
                self.c10_bind_equipment_inventory(&actor, &[])?;
            }
        }
        Ok(actor)
    }
}
