/// Require an admitted player, panicking with the donor message.
///
/// Donor `requirePlayer` throws `Error("Actor is not an admitted
/// player")`; [`SharedSimulation::require_player`] returns the same
/// message as `Err`, so this rethrows it for call sites that cannot
/// propagate (donor closures that return values, not promises).
fn req_player(sim: &SharedSimulation, actor: &ActorId) -> MovementPlayer {
    sim.require_player(actor).unwrap_or_else(|error| panic!("{error}"))
}

impl SharedSimulation {
    /// Mutate an admitted player's movement state.
    ///
    /// Donor `MovementPlayer` objects are shared references that call
    /// sites mutate in place; [`SharedSimulation::player`] snapshots
    /// clone, so writes go through this helper under a narrow lock.
    pub fn update_player(&self, actor: &ActorId, update: impl FnOnce(&mut MovementPlayer)) -> Result<(), RuntimeError> {
        let owned = self
            .actors()
            .resolve_owned(actor)
            .ok_or_else(|| RuntimeError::Failure("Actor is not an admitted player".to_string()))?;
        let mut state = self.lock();
        let player = state
            .player_states
            .get_mut(&owned)
            .ok_or_else(|| RuntimeError::Failure("Actor is not an admitted player".to_string()))?;
        update(player);
        Ok(())
    }

    /// Set world gravity (donor `setWorldGravity`, runtime.ts:5745).
    pub fn set_world_gravity(&self, gravity: f64) -> Result<(), RuntimeError> {
        Ok(self.lock().physics.set_world_gravity(gravity)?)
    }

    /// Player UI snapshot (donor `playerUi`, runtime.ts:4948).
    ///
    /// Donor `slotProjection(actor, null).ui`.
    pub fn player_ui(&self, actor: &ActorId) -> Result<super::types::PlayerUi, RuntimeError> {
        Ok(self.slot_projection(actor, None)?.ui)
    }
}

/// Whether a movement state matches a movement profile dialect (C10).
#[allow(dead_code)]
fn movement_kind_matches(state: &MovementState, profile: &MovementProfile) -> bool {
    matches!(
        (state, profile),
        (MovementState::Q1Netquake(_), MovementProfile::Q1Netquake(_))
            | (MovementState::Q1Quakeworld(_), MovementProfile::Q1Quakeworld(_))
            | (MovementState::Q2Classic(_), MovementProfile::Q2Classic(_))
            | (MovementState::Q2Rerelease(_), MovementProfile::Q2Rerelease(_))
            | (MovementState::Q3(_), MovementProfile::Q3(_))
    )
}

impl SharedSimulation {
    /// Build the live player record (donor `createPlayer`, donor runtime.ts
    /// 3311, C4 canonical).
    ///
    /// The restore tail overwrites the saved fields from the checkpoint.
    /// Standing bounds and view height come from the character profile
    /// (`playerStandingBounds`; q3 26 else 22). NetQuake move type, flags,
    /// water type, and health match the donor constructor constants.
    pub fn create_player(
        &self,
        actor: &OwnedActor,
        client: &ClientId,
        origin: Vec3,
        angles: Vec3,
        arsenal: ArsenalState,
    ) -> Result<MovementPlayer, RuntimeError> {
        use qa_world::movement::q1::types::{Q1MovementState, QwMovementState};
        use qa_world::movement::q2::types::{Q2MovementState, Q2RereleaseMovementState};
        use qa_world::movement::q3::types::Q3MovementState;
        let recipe = self.peek().recipe.clone();
        let profile = movement_profile(&recipe)?;
        let character = match provider_text(&recipe.character.definition.provider) {
            text if text.starts_with("q1:") => GameFamily::Q1,
            text if text.starts_with("q2:") => GameFamily::Q2,
            text if text.starts_with("q3:") => GameFamily::Q3,
            text => return fail(format!("Unknown character family: {text}")),
        };
        let gravity = self.peek().physics.gravity();
        let view_height = if character == GameFamily::Q3 { 26.0 } else { 22.0 };
        let standing = player_standing_bounds(character);
        let mut state = match &profile {
            MovementProfile::Q1Netquake(_) => MovementState::Q1Netquake(Q1MovementState {
                origin,
                velocity: zero(),
                angles,
                old_origin: origin,
                angular_velocity: zero(),
                view_angles: angles,
                punch_angles: zero(),
                move_type: 3,
                flags: 4096,
                ground: TraceHit::None,
                water_level: 0,
                water_type: -1,
                teleport_time_seconds: 0.0,
                water_jump_direction: zero(),
                ideal_pitch: 0.0,
                fix_angle: false,
                health: 100.0,
            }),
            MovementProfile::Q1Quakeworld(_) => MovementState::Q1Quakeworld(QwMovementState {
                origin,
                velocity: zero(),
                angles,
                old_buttons: 0,
                water_jump_time_seconds: 0.0,
                dead: false,
                spectator: 0,
                ground: TraceHit::None,
            }),
            MovementProfile::Q2Classic(_) => MovementState::Q2Classic(Q2MovementState {
                move_type: 0,
                origin_eighths: [
                    (origin.x * 8.0) as i32,
                    (origin.y * 8.0) as i32,
                    (origin.z * 8.0) as i32,
                ],
                velocity_eighths: [0, 0, 0],
                flags: 0,
                time_eight_milliseconds: 0,
                gravity,
                delta_angle_shorts: [0, 0, 0],
            }),
            MovementProfile::Q2Rerelease(_) => MovementState::Q2Rerelease(Q2RereleaseMovementState {
                move_type: 0,
                origin,
                velocity: zero(),
                flags: 0,
                time_milliseconds: 0,
                gravity,
                delta_angles: zero(),
                view_height,
            }),
            MovementProfile::Q3(_) => MovementState::Q3(Q3MovementState {
                command_time_milliseconds: 0,
                movement_type: 0,
                bob_cycle: 0,
                movement_flags: 0,
                movement_time_milliseconds: 0,
                origin,
                velocity: zero(),
                gravity,
                speed: 320.0,
                delta_angle_words: [0, 0, 0],
                movement_direction: 0,
                grapple_point: zero(),
                flags: 0,
                view_angles: angles,
                view_height,
                ground: TraceHit::None,
                predictable_event_sequence: 0,
                jump_pad: None,
                movement_frame: 0,
                jump_pad_frame: 0,
            }),
        };
        if matches!(
            state,
            MovementState::Q2Classic(_) | MovementState::Q2Rerelease(_) | MovementState::Q3(_)
        ) {
            match &mut state {
                MovementState::Q2Classic(classic) => classic.gravity = gravity,
                MovementState::Q2Rerelease(rerelease) => rerelease.gravity = gravity,
                MovementState::Q3(q3) => q3.gravity = gravity,
                _ => {}
            }
        }
        let animation = ActorAnimationState {
            provider: recipe.movement.provider.clone(),
            state: match &profile {
                MovementProfile::Q1Netquake(_) | MovementProfile::Q1Quakeworld(_) => {
                    qa_world::movement::types::AnimationState::Q1 {
                        frame: 12,
                        next_frame_seconds: 0.0,
                    }
                }
                MovementProfile::Q2Classic(_) | MovementProfile::Q2Rerelease(_) => {
                    qa_world::movement::types::AnimationState::Q2 {
                        frame: 0,
                        end_frame: 0,
                        priority: 0,
                        duck: false,
                        run: false,
                    }
                }
                MovementProfile::Q3(_) => qa_world::movement::types::AnimationState::Q3 {
                    legs: 0,
                    torso: 0,
                    legs_timer_milliseconds: 0,
                    torso_timer_milliseconds: 0,
                },
            },
        };
        Ok(MovementPlayer {
            actor: actor.clone(),
            client: client.clone(),
            recipe,
            character,
            standing_bounds: standing,
            profile,
            state,
            arsenal,
            animation,
            view_angles: angles,
            command_angles: angles,
            view_height,
            bounds: standing,
            ground: TraceHit::None,
            water_level: 0.0,
            water_type: 0.0,
            intermission: false,
            cutscene: None,
            fixed_pose_active: false,
            body_shape_base: None,
            gravity_multiplier: 1.0,
            flight: false,
            world_gravity: gravity,
            buttons: 0.0,
            previous_buttons: 0.0,
            last_sequence: -1,
            net_quake_command: None,
            last_weapon_seconds: f64::NEG_INFINITY,
            arsenal_intent: None,
            source_movement: None,
            source_environment: None,
            q2_movement_config: None,
            movement_speed_multiplier: 1.0,
        })
    }

    /// Construct and store the Q1 character foundation game (donor
    /// `q1CharacterSource` foundation arm, donor runtime.ts 3751).
    fn build_q1_character_foundation(&self) -> Result<(), RuntimeError> {
        use qa_content::q1::foundation::types::{Q1Edition, Q1FoundationOptions};
        let reference = self.peek().recipe.character.definition.clone();
        let numeric = {
            let state = self.peek();
            provider_timing(&state.recipe, &provider_text(&reference.provider))?.numeric
        };
        let skill = self.peek().options_skill;
        let mode = self.peek().options_mode;
        let max_clients = self.peek().options_max_clients;
        let campaign = self.peek().recipe.map.entities.provider.clone();
        let combat_provider = self.peek().recipe.combat.provider.clone();
        let inventory_provider = self.peek().recipe.inventory.provider.clone();
        let movement_provider = self.peek().recipe.movement.provider.clone();
        let gravity = self.peek().physics.gravity();
        let random = self.peek().random.clone();
        let tables = C11Tables {
            actors: self.actors_handle(),
            bodies: self.bodies_handle(),
            weak: self.weak(),
        };
        let now_tables = tables.clone();
        let now = Box::new(move || now_tables.sim().time_seconds());
        let frame_tables = tables.clone();
        let frame_seconds = Box::new(move || seconds(frame_tables.sim().peek().source_frame.elapsed));
        let schedule_tables = tables.clone();
        let schedule = Box::new(move |actor: &OwnedActor, due: Option<f64>| {
            let sim = schedule_tables.sim();
            match due {
                None => {
                    let actors = sim.actors.borrow();
                    sim.lock()
                        .scheduler
                        .cancel(actors.inner(), actor)
                        .expect("character think cancel failed");
                }
                Some(due) => {
                    sim.schedule(actor, due).expect("character think schedule failed");
                }
            }
        });
        let host = self.q1_actor_host(
            &reference,
            super::source_hosts::ActorHostRuntime {
                numeric,
                random,
                now,
                frame_seconds,
                schedule,
            },
            super::source_transition::SourceLevelAuthority::ActorSource,
        );
        let mut game = qa_content::q1::foundation::entity_services::Q1EntityServices::new(
            host,
            Q1FoundationOptions {
                provider: Some(reference.provider.clone()),
                precache_program: None,
                edition: if reference.content.as_str().contains(":rerelease:") {
                    Q1Edition::Rerelease
                } else {
                    Q1Edition::Classic
                },
                physics_edition: Some(self.q1_physics_edition()),
                skill: i32::from(skill),
                deathmatch: i32::from(mode == super::types::SimulationMode::Deathmatch),
                coop: mode == super::types::SimulationMode::Coop,
                campaign,
                combat_provider,
                movement_provider,
                inventory_provider,
                gravity,
                max_clients: Some(max_clients as i32),
                no_exit: None,
                teamplay: None,
                aim_threshold: None,
            },
        )
        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        qa_content::q1::base::map_entities::register_map_callbacks(&mut game)
            .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?;
        qa_content::q1::base::player::register_character_callbacks(&mut game)
            .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?;
        self.state.borrow_mut().q1_character_foundation = Some(game);
        Ok(())
    }

    /// Donor `attachQ1Character` (C10 seam; C4 owns the canonical port).
    ///
    /// Q1-kind sources attach through the live source entity services;
    /// the detached-foundation arm still needs the q1 lane's foundation
    /// construction (C4's canonical port replaces this seam).
    pub fn attach_q1_character(&self, player: &MovementPlayer) -> Result<(), RuntimeError> {
        use qa_content::q1::base::player::{Q1CharacterActor, Q1CharacterOptions};
        let actor = player.actor.clone();
        let needs_foundation = {
            let state = self.peek();
            !matches!(state.source, SourceRuntime::Q1 { .. })
                && !matches!(state.selected_weapon_source, Some(SelectedWeaponSource::Q1 { .. }))
                && state.q1_character_foundation.is_none()
        };
        if needs_foundation {
            self.build_q1_character_foundation()?;
        }
        let character = {
            let state = self.peek();
            let mut services_guard = None;
            let game = match &state.source {
                SourceRuntime::Q1 { services, .. } => &*services_guard.insert(services.borrow()),
                _ if matches!(state.selected_weapon_source, Some(SelectedWeaponSource::Q1 { .. })) => {
                    match &state.selected_weapon_source {
                        Some(SelectedWeaponSource::Q1 { game, .. }) => game,
                        _ => return fail("Selected Q1 source has no entity services"),
                    }
                }
                _ => match state.q1_character_foundation.as_ref() {
                    Some(game) => game,
                    None => return fail("Q1 character foundation was not constructed"),
                },
            };
            Q1CharacterActor::new(
                game,
                actor.clone(),
                Q1CharacterOptions {
                    drop_inventory: None,
                    request_respawn: None,
                    source_pose: None,
                    fall_damage_allowed: None,
                },
            )
            .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?
        };
        let simulation = Rc::downgrade(&self.state);
        let pain_simulation = simulation.clone();
        let die_simulation = simulation;
        let actors = Rc::clone(&self.actors);
        let pain_actor = actor.clone();
        let die_actor = actor.clone();
        let time = self.time_seconds();
        {
            let mut state = self.state.borrow_mut();
            state.q1_characters.insert(actor.clone(), character);
            let registry = actors.borrow();
            state.callbacks.borrow().bind(
                &registry,
                &actor,
                ActorCallbacks {
                    think: None,
                    touch: None,
                    use_action: None,
                    pain: Some(Rc::new(move |reaction: &RuntimePainReaction| {
                        let Some(simulation) = pain_simulation.upgrade() else {
                            return;
                        };
                        let mut state = simulation.borrow_mut();
                        let actor = pain_actor.clone();
                        let attacker = reaction.attacker.clone();
                        let damage = reaction.damage;
                        let Some(mut character) = state.q1_characters.remove(&actor) else {
                            return;
                        };
                        if let SourceRuntime::Q1 { services, .. } = &state.source {
                            let _ = character.pain(&mut services.borrow_mut(), attacker.as_ref(), damage, false);
                        } else if let Some(SelectedWeaponSource::Q1 { game, .. }) =
                            state.selected_weapon_source.as_mut()
                        {
                            let _ = character.pain(game, attacker.as_ref(), damage, false);
                        } else if let Some(game) = state.q1_character_foundation.as_mut() {
                            let _ = character.pain(game, attacker.as_ref(), damage, false);
                        }
                        state.q1_characters.insert(actor.clone(), character);
                    })),
                    die: Some(Rc::new(move |reaction: &RuntimeDeathReaction| {
                        let Some(simulation) = die_simulation.upgrade() else {
                            return;
                        };
                        let mut state = simulation.borrow_mut();
                        let actor = die_actor.clone();
                        let attacker = reaction.attacker.clone();
                        let has_game = matches!(state.source, SourceRuntime::Q1 { .. })
                            || matches!(state.selected_weapon_source, Some(SelectedWeaponSource::Q1 { .. }))
                            || state.q1_character_foundation.is_some();
                        if !has_game {
                            return;
                        }
                        let Some(mut character) = state.q1_characters.remove(&actor) else {
                            return;
                        };
                        let bounced = if let SourceRuntime::Q1 { services, .. } = &state.source {
                            let mut borrowed = services.borrow_mut();
                            borrowed.time = time;
                            let _ = character.die(&mut borrowed, attacker.as_ref());
                            character.presentation().movement == qa_content::q1::foundation::types::Q1MoveType::Bounce
                        } else if let Some(SelectedWeaponSource::Q1 { game, .. }) =
                            state.selected_weapon_source.as_mut()
                        {
                            game.time = time;
                            let _ = character.die(game, attacker.as_ref());
                            character.presentation().movement == qa_content::q1::foundation::types::Q1MoveType::Bounce
                        } else if let Some(game) = state.q1_character_foundation.as_mut() {
                            game.time = time;
                            let _ = character.die(game, attacker.as_ref());
                            character.presentation().movement == qa_content::q1::foundation::types::Q1MoveType::Bounce
                        } else {
                            state.q1_characters.insert(actor.clone(), character);
                            return;
                        };
                        state.q1_characters.insert(actor.clone(), character);
                        if let Some(owned) = state
                            .player_states
                            .keys()
                            .find(|owned| owned.id() == actor.id())
                            .cloned()
                        {
                            if let Some(player) = state.player_states.get_mut(&owned) {
                                if let MovementState::Q1Netquake(netquake) = &mut player.state {
                                    netquake.move_type = if bounced { 10 } else { 6 };
                                }
                            }
                        }
                    })),
                },
            )?;
        }
        Ok(())
    }

    /// Donor `attachQ2Character` (C10 seam; C4 owns the canonical port).
    ///
    /// Missing siblings: C4's character attach (q2-lane service/host wiring
    /// for pain reactions and death); delete this seam when it lands.
    pub fn attach_q2_character(&self, player: &MovementPlayer) -> Result<(), RuntimeError> {
        use qa_content::q2::base::player::character::{Q2CharacterActor, Q2CharacterOptions};
        let actor = player.actor.clone();
        let (appearance, content, mode) = {
            let state = self.peek();
            (
                state.recipe.character.appearance.provider.clone(),
                state.recipe.character.definition.content.clone(),
                state.options_mode,
            )
        };
        let model = format!(
            "players/{}/tris.md2",
            provider_text(&appearance).split('/').next_back().unwrap_or("male")
        );
        let mode = match mode {
            super::types::SimulationMode::Singleplayer => qa_content::q2::foundation::host::Q2Mode::Singleplayer,
            super::types::SimulationMode::Coop => qa_content::q2::foundation::host::Q2Mode::Coop,
            super::types::SimulationMode::Deathmatch => qa_content::q2::foundation::host::Q2Mode::Deathmatch,
        };
        let character = Q2CharacterActor::new(
            actor.clone(),
            Q2CharacterOptions {
                edition: Some(if content.as_str().contains(":rerelease:") {
                    qa_content::q2::foundation::host::Q2Edition::Rerelease
                } else {
                    qa_content::q2::foundation::host::Q2Edition::Classic
                }),
                model,
                skin: 0,
                slot: player.client.slot() as i32,
                mode,
                deathmatch_flags: 0,
                environment: false,
                view_rules: None,
            },
            self.time_seconds(),
        );
        {
            let mut state = self.state.borrow_mut();
            let actors = self.actors.borrow();
            state.q2_characters.insert(actor.clone(), character);
            let simulation = Rc::downgrade(&self.state);
            let pain_actor = actor.clone();
            state.callbacks.borrow().bind(
                &actors,
                &actor,
                ActorCallbacks {
                    think: None,
                    touch: None,
                    use_action: None,
                    pain: Some(Rc::new(move |_| {
                        let Some(simulation) = simulation.upgrade() else {
                            return;
                        };
                        let mut state = simulation.borrow_mut();
                        if let Some(character) = state.q2_characters.get_mut(&pain_actor) {
                            character.pain();
                        }
                    })),
                    die: None,
                },
            )?;
        }
        Ok(())
    }

    /// Donor `resumeQ2Presentation` (C10 seam; C4 owns the canonical port).
    ///
    /// The q2 product runtime is still opaque, so there is no rerelease sky,
    /// story, fog, or flashlight state to re-emit yet.
    /// Missing siblings: q2-product lane rerelease state; delete this seam when it lands.
    pub fn resume_q2_presentation(&self) -> Result<(), RuntimeError> {
        Ok(())
    }

    /// Bind a weapon slot (donor `bindWeaponSlot`, runtime.ts 2259).
    pub fn bind_weapon_slot(
        &self,
        actor: &ActorId,
        restored: Option<super::weapon_slot::WeaponSlotRestoreState>,
    ) -> Result<(), RuntimeError> {
        let owner = self
            .actors
            .borrow()
            .resolve_owned(actor)
            .ok_or_else(|| RuntimeError::Failure("Weapon slot actor retired".to_string()))?;
        let primary = self.primary_handoff(actor)?;
        let equipment = {
            let state = self.peek();
            let slot_bound = state.grapple.as_ref().is_some_and(|grapple| {
                matches!(
                    grapple.selection(),
                    qa_content::contract::GrappleSelection::Enabled {
                        binding: qa_content::contract::GrappleBinding::Slot,
                        ..
                    }
                )
            });
            if slot_bound {
                let handoff = state
                    .grapple
                    .as_ref()
                    .expect("grapple checked above")
                    .handoff(actor)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                Some(Box::new(handoff) as Box<dyn super::weapon_slot::EquipmentWeaponHandoff>)
            } else {
                None
            }
        };
        let actors = self.actors_handle();
        let check_actor = actor.clone();
        let current = move || actors.borrow().resolve_owned(&check_actor).as_ref() == Some(&owner);
        let slot = super::weapon_slot::WeaponSlot::new(primary, equipment, restored, Box::new(current))
            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        self.lock().weapon_slots.insert(actor.clone(), slot);
        Ok(())
    }
}

impl SharedSimulation {
    /// Donor `selectedAmmoActors` (C10; pre-zone donor 1829, no owning child).
    pub fn selected_ammo_actors(&self) -> Vec<OwnedActor> {
        let state = self.peek();
        state
            .player_states
            .values()
            .filter(|player| {
                state
                    .selected_arsenal
                    .as_ref()
                    .is_some_and(|arsenal| arsenal.has(player.actor.id()))
            })
            .map(|player| player.actor.clone())
            .collect()
    }

    /// Donor `bindSelectedOriginalPickups` (C10; pre-zone donor 1727, no owning child).
    ///
    /// Previous bindings are disposed; the replacement live pickup routing
    /// waits for the world lane's `bindPickup`.
    /// Missing siblings: world-lane inventory `bindPickup`; original-pickup
    /// routing stays unbound until it lands.
    pub fn bind_selected_original_pickups(&self, actor: &OwnedActor) -> Result<(), RuntimeError> {
        let mut state = self.state.borrow_mut();
        if let Some(dispose) = state.selected_pickup_bindings.remove(actor.id()) {
            dispose();
        }
        Ok(())
    }

    /// Donor `restoreSelectedMonsters` (C10; pre-zone donor 1203, no owning child).
    ///
    /// Missing siblings: monster-lane `MonsterMap` restore wiring
    /// (`SelectedMonsters::restore` needs the running map program, mission
    /// behaviors, and q1 monster missions); monster sessions fail closed
    /// until it lands.
    pub fn restore_selected_monsters(
        &self,
        _saved: &super::monster_checkpoint::SelectedMonstersCheckpoint,
    ) -> Result<(), RuntimeError> {
        if self.peek().selected_monsters.is_none() {
            return fail("Saved monsters have no selected admission");
        }
        fail("Missing siblings: monster-lane MonsterMap restore wiring (donor 1203)")
    }

    /// Donor `bindEquipmentInventory` (C10; pre-zone donor 2114, no owning child).
    ///
    /// The q2-native live source view (`sourceInventory` + inventory `bind`
    /// with capacity/supplemental closures) has no substrate yet, so both
    /// arms snapshot `initial` into a copied store. Restore data stays
    /// correct per the save; later native-side changes diverge until the
    /// guest-services and world lanes land the live binding.
    /// Missing siblings: guest-services `sourceInventory`, world-lane
    /// inventory `bind`; delete the snapshot fallback when they land.
    /// Duplicate: C11 landed a same-named panicking version; the parent
    /// unifies (this one reports donor errors instead of panicking).
    pub fn c10_bind_equipment_inventory(
        &self,
        actor: &OwnedActor,
        initial: &[qa_world::inventory::InventoryEntry],
    ) -> Result<(), RuntimeError> {
        let actors = self.actors.borrow();
        let mut state = self.state.borrow_mut();
        state.inventory.inner_mut().create(actors.inner(), actor, initial)?;
        Ok(())
    }

    /// Donor `equipmentPlayerAvailable` (C10; pre-zone donor 2140, no owning child).
    ///
    /// Duplicate: C11 landed a same-named boolean version; the parent
    /// unifies (this one reports donor errors instead of panicking or
    /// defaulting health to 100).
    pub fn c10_equipment_player_available(&self, actor: &ActorId) -> Result<bool, RuntimeError> {
        use qa_content::q3::base::shared::definitions::MoveType;
        let native_ui = match &self.peek().source {
            SourceRuntime::Q2Native(_) => Some(self.native_player_ui(actor)?),
            _ => None,
        };
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q3Qvm { game, weapons, .. } => {
                let Some(entry) = game.players().into_iter().find(|player| player.actor == *actor) else {
                    return Ok(false);
                };
                if let Some(weapons) = weapons {
                    return weapons
                        .available(actor, false)
                        .map_err(|error| RuntimeError::Failure(format!("{error:?}")));
                }
                let record = game.records.player(entry.source_entity);
                Ok(record.stats[0] > 0
                    && record.movement_type != MoveType::PmSpectator as i32
                    && record.movement_type != MoveType::PmIntermission as i32
                    && record.movement_type != MoveType::PmSpintermission as i32)
            }
            SourceRuntime::Q2Native(_) => {
                let client = self.player_client(actor);
                let ui = native_ui.expect("native UI precomputed for native sources");
                Ok(client.is_some() && ui.health > 0.0)
            }
            _ => {
                let player = self.player(actor);
                let Some(player) = player else { return Ok(false) };
                let health = state.combat.read(actor).map(|combat| combat.health).unwrap_or(0.0);
                Ok(!player.intermission && player.cutscene.is_none() && health > 0.0)
            }
        }
    }
}
