use qa_bots::scene::{
    PointContentsQuery as BotsPointContentsQuery, PointContentsResult as BotsPointContentsResult,
    TraceQuery as BotsTraceQuery, TraceResult as BotsTraceResult, VisibilityKind as BotsVisibilityKind,
};

/// Shared scene queries as a guest scene (donor `scene`).
///
/// Adapts the state scene plus the session body tables to
/// [`SceneQueries`](qa_bots::scene::SceneQueries) /
/// [`ActorHostScene`](super::source_hosts::ActorHostScene). Model bounds
/// and actor queries read live session data; geometry sweeps and BSP
/// queries have no Rust home (the state holds no collision world), so
/// they report open space like the port's vacant-geometry fakes.
///
/// Missing siblings: collision-lane BSP/sweep queries over the decoded
/// map; rewire `trace`, `point_contents`, `box_leaves`,
/// `areas_connected`, `cluster_visible`, `trace_excluding`,
/// `geometry_trace`, `point_leaf`, `leaf_cluster`, `leaf_area`,
/// `model_count`, and `q2_texture_info` when it lands.
pub struct SharedSceneAdapter {
    /// Shared scene queries.
    pub scene: Rc<SharedSceneQueries>,
    /// Session body tables for actor queries.
    pub bodies: Rc<RefCell<qa_world::body::BodyTable>>,
    /// Session actor registry for body reads.
    pub actors: Rc<RefCell<SessionActorRegistry>>,
    /// Weak simulation for physics collision records.
    pub simulation: Weak<RefCell<SharedSimulationState>>,
}

impl SharedSceneAdapter {
    /// Clear-sweep result (donor trace that hits nothing).
    fn miss(query: &BotsTraceQuery) -> BotsTraceResult {
        BotsTraceResult {
            fraction: 1.0,
            end: query.end,
            start_solid: false,
            all_solid: false,
            contact: qa_bots::scene::TraceContact::None,
            hit: qa_bots::scene::TraceHit::None,
            detail: qa_bots::scene::TraceDetail::Q1 {
                in_open: true,
                in_water: false,
                source_plane: qa_core::math::Plane {
                    normal: Vec3 { x: 0.0, y: 0.0, z: 0.0 },
                    distance: 0.0,
                },
                surface_flags: None,
                contents: None,
            },
        }
    }
}

impl qa_bots::scene::SceneQueries for SharedSceneAdapter {
    fn trace(&self, query: &BotsTraceQuery) -> BotsTraceResult {
        let _ = query;
        Self::miss(query)
    }

    fn point_contents(&self, _query: &BotsPointContentsQuery) -> BotsPointContentsResult {
        BotsPointContentsResult::Q1 { contents: 0 }
    }

    fn box_leaves(&self, _bounds: &Bounds, _limit: usize) -> qa_bots::scene::LeafQueryResult {
        qa_bots::scene::LeafQueryResult {
            leaves: vec![1],
            topnode: Some(2),
            overflow: false,
        }
    }

    fn areas_connected(&self, _first: i32, _second: i32) -> bool {
        true
    }

    fn cluster_visible(&self, _from: i32, _to: i32, _kind: BotsVisibilityKind) -> bool {
        true
    }
}

impl super::source_hosts::ActorHostScene for SharedSceneAdapter {
    fn trace_excluding(&self, query: &BotsTraceQuery, _excluded: &[ActorId]) -> BotsTraceResult {
        Self::miss(query)
    }

    fn geometry_trace(&self, query: &BotsTraceQuery) -> BotsTraceResult {
        Self::miss(query)
    }

    fn point_leaf(&self, _point: Vec3) -> i32 {
        1
    }

    fn leaf_cluster(&self, _leaf: i32) -> i32 {
        2
    }

    fn leaf_area(&self, _leaf: i32) -> i32 {
        1
    }

    fn model_bounds(&self, model: i32) -> Bounds {
        self.scene.model_bounds(model)
    }

    fn query_actors(
        &self,
        bounds: &Bounds,
        _role: qa_world::spatial::QueryRole,
    ) -> Vec<qa_world::spatial::SpatialActor> {
        let simulation = self
            .simulation
            .upgrade()
            .expect("scene adapter used after the simulation dropped");
        let state = simulation.borrow();
        let actors = self.actors.borrow();
        let bodies = self.bodies.borrow();
        actors
            .observations()
            .into_iter()
            .filter_map(|observation| {
                let linked = bodies.linked(actors.inner(), &observation.id)?;
                if !qa_world::spatial::bounds_intersect(&linked.absolute_bounds, bounds) {
                    return None;
                }
                let collision = state.physics.collision_of(&observation.id)?;
                Some(qa_world::spatial::SpatialActor {
                    body: linked,
                    collision,
                })
            })
            .collect()
    }

    fn model_count(&self) -> usize {
        0
    }

    fn q2_texture_info(&self) -> Option<Vec<super::source_hosts::SceneTextureInfo>> {
        None
    }
}

