/// Q2 actor-host bindings over the shared session (donor `q2ActorHost`
/// bindings).
///
/// Table views reuse the C11 adapters; session behavior upgrades the
/// [`Weak`] handle in narrow scopes. Used for the native Q2 guest engine
/// and the classic/rerelease Q2 composition host.
///
/// Callback binding tracks the bound set locally (C11's adapter); the
/// session channel table is bound by the spawn lane, not the host.
pub struct Q2SeamBindings {
    /// Shared table handles.
    tables: C11Tables,
    /// Session actor registry view.
    actors: C11Q2Actors,
    /// Session body table view.
    bodies: C11Q2Bodies,
    /// Session callback table view.
    callbacks: C11Q2Callbacks,
    /// Session combat authority view.
    combat: C11Q2Combat,
    /// Session inventory table view.
    inventory: C11Q2Inventory,
    /// Original-pickup admission.
    pickups: Q2SeamPickups,
    /// Entity content for execution registration.
    content: ContentId,
    /// Frame time in seconds (donor `runtime.frameSeconds`).
    frame_seconds: f64,
    /// Level authority for transitions.
    authority: super::source_transition::SourceLevelAuthority,
    /// Session seat identity lookup (donor `options.playerIdentity`).
    player_identity: Option<super::types::PlayerIdentityLookup>,
}

impl Q2SeamBindings {
    /// Create bindings over shared handles.
    pub fn new(
        simulation: Weak<RefCell<SharedSimulationState>>,
        actors: Rc<RefCell<SessionActorRegistry>>,
        bodies: Rc<RefCell<qa_world::body::BodyTable>>,
        content: ContentId,
        frame_seconds: f64,
        authority: super::source_transition::SourceLevelAuthority,
        player_identity: Option<super::types::PlayerIdentityLookup>,
    ) -> Self {
        let tables = C11Tables {
            actors,
            bodies,
            weak: simulation.clone(),
        };
        Self {
            tables: tables.clone(),
            actors: C11Q2Actors { tables: tables.clone() },
            bodies: C11Q2Bodies { tables: tables.clone() },
            callbacks: C11Q2Callbacks {
                bound: std::collections::HashSet::new(),
            },
            combat: C11Q2Combat { tables: tables.clone() },
            inventory: C11Q2Inventory { tables: tables.clone() },
            pickups: Q2SeamPickups::new(simulation),
            content,
            frame_seconds,
            authority,
            player_identity,
        }
    }

    /// Rebuild the simulation handle (donor `this`).
    fn session(&self) -> SharedSimulation {
        self.tables.sim()
    }

    /// Session seat identity for an admitted player (donor
    /// `rereleaseHooks.playerIdentity`).
    pub fn session_player_identity(
        &self,
        actor: &ActorId,
    ) -> qa_content::q2::rerelease::types::Q2RereleasePlayerIdentity {
        let sim = self.session();
        let lookup = self
            .player_identity
            .clone()
            .expect("Q2 rerelease admission requires session seat identity");
        let player = req_player(&sim, actor);
        let found = lookup(&player.client);
        qa_content::q2::rerelease::types::Q2RereleasePlayerIdentity {
            seat: found.seat as i32,
            social_id: found.social_id,
        }
    }
}

impl super::source_hosts::Q2ActorHostBindings for Q2SeamBindings {
    fn actors(&mut self) -> &mut dyn qa_content::q2::support::tables::Q2ActorRegistry {
        &mut self.actors
    }

    fn bodies(&mut self) -> &mut dyn qa_content::q2::support::tables::Q2BodyTable {
        &mut self.bodies
    }

    fn callbacks(&mut self) -> &mut dyn qa_content::q2::support::tables::Q2CallbackTable {
        &mut self.callbacks
    }

    fn combat(&mut self) -> &mut dyn qa_content::q2::support::tables::Q2CombatAuthority {
        &mut self.combat
    }

    fn inventory(&mut self) -> &mut dyn qa_content::q2::support::tables::Q2InventoryTable {
        &mut self.inventory
    }

    fn original_pickups(&mut self) -> Option<&mut dyn qa_content::q2::foundation::host::Q2OriginalPickups> {
        Some(&mut self.pickups)
    }

    fn weapon_behavior(&mut self) -> Option<&mut dyn qa_content::q2::support::contracts::WeaponBehaviorProjectilePort> {
        None
    }

    fn weapon_target_override(
        &mut self,
        actor: &ActorId,
    ) -> Option<Option<qa_content::q2::foundation::host::Q2WeaponTarget>> {
        // Canonical port lives on SharedSimulation; the donor never throws
        // here, so fall back to no override on error.
        self.session().q2_weapon_target(actor).ok()
    }

    fn monster_target_override(
        &mut self,
        actor: &ActorId,
    ) -> Option<Option<qa_content::monsters::MonsterTargetObservation>> {
        // Canonical port lives on SharedSimulation; the donor never throws
        // here, so fall back to no override on error.
        self.session().monster_target(actor).ok()
    }

    fn register_entity(&mut self, actor: &OwnedActor) {
        self.session()
            .register_actor_execution(RuntimeExecutionEntry::Q2 {
                actor: actor.clone(),
                content: self.content.clone(),
            })
            .expect("Q2 entity registration failed");
    }

    fn now(&self) -> f64 {
        self.session().time_seconds()
    }

    fn frame_seconds(&self) -> f64 {
        self.frame_seconds
    }

    fn gravity(&self) -> f64 {
        self.session().peek().physics.gravity()
    }

    fn random(&mut self) -> f64 {
        f64::from(self.session().lock().random.next_unit())
    }

    fn schedule(&mut self, actor: &OwnedActor, due_seconds: Option<f64>) {
        let sim = self.session();
        match due_seconds {
            None => {
                let actors = sim.actors_handle();
                let registry = actors.borrow();
                sim.lock()
                    .scheduler
                    .cancel(registry.inner(), actor)
                    .expect("think cancel failed");
            }
            Some(due) => sim.schedule(actor, due).expect("think schedule failed"),
        }
    }

    fn touch_triggers(&mut self, actor: &OwnedActor) {
        self.session().lock().physics.touch_triggers(actor);
    }

    fn players(&mut self) -> Vec<ActorId> {
        self.session().players()
    }

    fn world_actor(&mut self) -> ActorId {
        self.session().world_actor().expect("Map has no source world actor")
    }

    fn is_player(&mut self, actor: &ActorId) -> bool {
        self.session().player_client(actor).is_some()
    }

    fn is_monster(&mut self, actor: &ActorId) -> bool {
        let sim = self.session();
        let state = sim.peek();
        match state.actor_executions.get(actor) {
            Some(RuntimeExecutionEntry::QuakeC { .. }) => sim
                .with_quakec_source(|game| game.weapon_target(actor))
                .and_then(|result| result.ok())
                .flatten()
                .is_some_and(|target| target.monster),
            Some(RuntimeExecutionEntry::Q2 { .. }) => sim
                .q2_game_services()
                .and_then(|game| game.borrow().entity(actor).map(|entity| entity.server_flags & 4 != 0))
                .unwrap_or(false),
            Some(RuntimeExecutionEntry::Q1 { .. }) => sim
                .q1_services()
                .and_then(|services| services.borrow().entity(actor).map(|entity| entity.monster.is_some()))
                .unwrap_or(false),
            _ => false,
        }
    }

    fn set_solid(&mut self, actor: &OwnedActor, solid: qa_content::q2::foundation::host::Q2Solid, model: Option<i32>) {
        use super::physics::{PhysicsFamily, SolidKind};
        use qa_content::q2::foundation::host::Q2Solid;
        let solid = match solid {
            Q2Solid::None => SolidKind::None,
            Q2Solid::Trigger => SolidKind::Trigger,
            Q2Solid::Box => SolidKind::Box,
            Q2Solid::Brush => SolidKind::Brush,
        };
        let _ = self.session().lock().physics.set_solid(
            actor,
            solid,
            model.map(|model| model as u32),
            PhysicsFamily::Q2,
            None,
        );
    }

    fn set_motion(&mut self, motion: &qa_content::q2::foundation::host::Q2Motion) {
        self.session().lock().physics.set_motion(motion.clone());
    }

    fn set_area_portal(&mut self, portal: i32, open: bool) {
        let sim = self.session();
        let scene = sim.scene();
        let mut state = sim.lock();
        state.area_portals.insert(portal as u32, open);
        scene.set_area_portal_state(portal as u32, open);
    }

    fn emit(&mut self, event: qa_content::q2::foundation::host::Q2PresentationEvent) {
        use qa_content::q2::foundation::host::Q2PresentationEvent;
        let sim = self.session();
        let now = sim.time_seconds();
        let mut state = sim.lock();
        if let Q2PresentationEvent::Model(model) = &event {
            let index = model
                .path
                .strip_prefix('*')
                .and_then(|n| n.parse::<i32>().ok())
                .unwrap_or(0);
            state.source_models.insert(
                model.actor.clone(),
                RuntimeQ2ModelEvent {
                    path: model.path.clone(),
                    model: index,
                    frame: model.frame,
                    old_frame: model.old_frame,
                    scale: model.scale,
                    alpha: model.alpha,
                    skin: model.skin,
                    effects: model.effects,
                    render_flags: model.render_flags,
                },
            );
        }
        let primary =
            matches!(state.source, SourceRuntime::Q2 { .. }) && self.content == state.recipe.map.entities.content;
        let time = if primary {
            state.source_frame.time
        } else {
            qa_core::time::SourceTime::Seconds(now as f32)
        };
        let content = self.content.clone();
        state.events.emit_owned(
            None,
            &content,
            super::types::SourcePresentationEvent::Q2(event),
            time,
            None,
        );
    }

    fn player_view_state(&mut self, player: &ActorId) -> Option<qa_content::q2::foundation::host::Q2PlayerViewState> {
        use qa_content::q2::foundation::host::Q2PlayerViewState;
        let sim = self.session();
        sim.player_client(player)?; // Missing siblings: Q2 product player states (oldVelocity) and
                                    // per-actor grapple previous velocity (C11 grapple); zero until
                                    // those readers land.
        let view_angles = sim.player(player).map(|player| player.view_angles).unwrap_or(zero());
        Some(Q2PlayerViewState {
            view_angles,
            old_velocity: zero(),
        })
    }

    fn key_consumed(&mut self, player: &ActorId) {
        let sim = self.session();
        let pair = {
            let state = sim.peek();
            match &state.source {
                SourceRuntime::Q2 { game, .. } => Some((game.clone(), state.q2_product.clone())),
                _ => None,
            }
        };
        if let Some((game, Some(product))) = pair {
            if game.borrow().entity(player).is_some() {
                product
                    .borrow()
                    .players
                    .consumed_key(player.clone(), &mut game.borrow_mut());
            }
        }
    }

    fn prepare_level_change(
        &mut self,
        map: &str,
        landmark: Option<&qa_content::q2::foundation::host::Q2LandmarkCarry>,
        server_flags: i32,
    ) {
        self.session().lock().level_change = Some(LevelChange {
            map: map.to_string(),
            landmark: landmark.map(|landmark| Q2LandmarkCarry {
                player: landmark.player.clone(),
                name: landmark.name.clone(),
                relative_origin: landmark.relative_origin,
                relative_velocity: landmark.relative_velocity,
                relative_view_angles: landmark.relative_view_angles,
            }),
            server_flags,
        });
    }

    fn transition(&mut self, intent: qa_content::q2::support::contracts::TransitionIntent) {
        use super::source_transition::{source_level_transition, SourceLevelAuthority};
        use qa_content::q2::support::contracts::TransitionIntent as Q2Intent;
        let sim = self.session();
        let intermission = matches!(intent, Q2Intent::CampaignLevel { .. })
            && self.authority == SourceLevelAuthority::PrimaryWorld
            && {
                let state = sim.peek();
                !state.checking_q2_rules && matches!(state.source, SourceRuntime::Q2 { .. })
            };
        if intermission {
            let (game, product, change) = {
                let state = sim.peek();
                let SourceRuntime::Q2 { game, .. } = &state.source else {
                    unreachable!("Q2 transition checked the source kind")
                };
                (game.clone(), state.q2_product.clone(), state.level_change.clone())
            };
            let product = product.expect("Q2 source has no assembled product");
            if let Q2Intent::CampaignLevel { map, .. } = &intent {
                let destination = match &change {
                    Some(change) => change.map.clone(),
                    None => map.strip_prefix("q2:").unwrap_or(map).to_string(),
                };
                let landmark = change.and_then(|change| change.landmark).map(|landmark| {
                    qa_content::q2::foundation::host::Q2LandmarkCarry {
                        player: landmark.player,
                        name: landmark.name,
                        relative_origin: landmark.relative_origin,
                        relative_velocity: landmark.relative_velocity,
                        relative_view_angles: landmark.relative_view_angles,
                    }
                });
                product
                    .borrow()
                    .players
                    .begin_intermission(&mut game.borrow_mut(), destination, landmark);
                return;
            }
        }
        let cause = match &intent {
            Q2Intent::CampaignLevel { cause, .. } => cause.clone(),
            _ => None,
        };
        let mut state = sim.lock();
        let rewritten = source_level_transition(
            q2_intent_to_world(intent),
            &state.recipe.campaign,
            &state.recipe.r#match.provider,
            self.authority,
        );
        let mut out = world_intent_to_q1(rewritten);
        if let qa_content::q1::foundation::gameplay::TransitionIntent::CampaignLevel { cause: slot, .. } = &mut out {
            *slot = cause;
        }
        state.transitions.push(out);
    }

    fn diagnostic(&mut self, message: &str) {
        self.session().lock().events.message(
            super::events::NetworkEvent::Print {
                level: 2,
                text: message.to_string(),
            },
            None,
            None,
        );
    }
}

/// Convert a Q2 transition intent to the shared world intent.
fn q2_intent_to_world(
    intent: qa_content::q2::support::contracts::TransitionIntent,
) -> qa_world::session::TransitionIntent {
    use qa_content::q2::support::contracts::TransitionIntent as Q2;
    use qa_world::session::{MissionGate as WorldGate, TransitionIntent as World};
    match intent {
        Q2::CampaignLevel {
            campaign,
            map,
            spawn_point,
            gates,
            ..
        } => World::CampaignLevel {
            campaign,
            map,
            spawn: spawn_point,
            gates: gates
                .into_iter()
                .map(|gate| WorldGate {
                    objective: gate.objective,
                    satisfied: gate.satisfied,
                })
                .collect(),
        },
        Q2::CampaignComplete { campaign, gates } => World::CampaignComplete {
            campaign,
            gates: gates
                .into_iter()
                .map(|gate| WorldGate {
                    objective: gate.objective,
                    satisfied: gate.satisfied,
                })
                .collect(),
        },
        Q2::RoundComplete { provider, winner } => World::RoundComplete {
            match_id: provider,
            winner,
        },
        Q2::MatchRotation { provider, map } => World::MatchRotation {
            match_id: provider,
            map,
        },
    }
}

/// Convert a shared world intent to the state transition intent.
fn world_intent_to_q1(
    intent: qa_world::session::TransitionIntent,
) -> qa_content::q1::foundation::gameplay::TransitionIntent {
    use qa_content::q1::foundation::gameplay::{MissionGate as Q1Gate, TransitionIntent as Q1};
    use qa_world::session::TransitionIntent as World;
    match intent {
        World::CampaignLevel {
            campaign,
            map,
            spawn,
            gates,
        } => Q1::CampaignLevel {
            campaign,
            map,
            spawn_point: spawn,
            gates: gates
                .into_iter()
                .map(|gate| Q1Gate {
                    objective: gate.objective,
                    satisfied: gate.satisfied,
                })
                .collect(),
            cause: None,
        },
        World::CampaignComplete { campaign, gates } => Q1::CampaignComplete {
            campaign,
            gates: gates
                .into_iter()
                .map(|gate| Q1Gate {
                    objective: gate.objective,
                    satisfied: gate.satisfied,
                })
                .collect(),
        },
        World::RoundComplete { match_id, winner } => Q1::RoundComplete {
            match_provider: match_id,
            winner,
        },
        World::MatchRotation { match_id, map } => Q1::MatchRotation {
            match_provider: match_id,
            map,
        },
    }
}

// ---------------------------------------------------------------------------
// C6 step tail (donor runtime.ts 4429-4775).
//
// The tail covers one boundary iteration of `SharedSimulation.step`: the
// run-frame preamble, the client-command loop, the actor-turn loop, the
// post-frame reconciliation, and the frame-exit settlement. C5 owns the
// step head (donor 4345-4428: guards, settlement checks, deadline
// expansion, the boundary loop) and calls `step_frame_tail` once per
// boundary with the head's loop locals mirrored in `StepTailContext`.
// ---------------------------------------------------------------------------

/// Step-boundary flags for one boundary iteration (donor `boundary` object,
/// C5's range; mirrored so the tail compiles standalone).
#[derive(Debug, Clone, Copy)]
pub struct StepBoundary {
    /// Map turn runs this boundary (donor `boundary.map`).
    pub map: bool,
    /// Selected-Q2 weapon turn runs (donor `boundary.q2`).
    pub q2: bool,
    /// Selected-Q3 turn runs (donor `boundary.q3`).
    pub q3: bool,
    /// Boundary time in milliseconds (donor `boundary.milliseconds`).
    pub milliseconds: f64,
}

/// Step-loop locals the C6 tail reads (donor step() head bindings, C5's
/// range; mirrored so the tail compiles standalone).
#[derive(Debug, Clone)]
pub struct StepTailContext {
    /// Map turn runs this boundary (donor `run`).
    pub run: bool,
    /// Any map turn runs this step (donor `mapRun`).
    pub map_run: bool,
    /// Match is paused (donor `paused`).
    pub paused: bool,
    /// Commands execute this boundary (donor `commandTurn`).
    pub command_turn: bool,
    /// Boundary flags (donor `boundary`).
    pub boundary: StepBoundary,
    /// Round settlement is active (donor `settlement.kind === "active"`).
    pub settlement_active: bool,
    /// Fixed source frame length in milliseconds (donor `fixed`).
    pub fixed: Option<f64>,
    /// Source elapsed time in seconds (donor `elapsed`).
    pub elapsed: f64,
    /// Selected-arsenal clock at the previous boundary (donor
    /// `previousSelectedMilliseconds`).
    pub previous_selected_milliseconds: f64,
    /// Selected-Q3 clock at the previous boundary (donor `previousQ3Time`).
    pub previous_q3_time: f64,
}

/// Outer-loop flow after the tail (donor `break`/`continue` past the tail
/// blocks, C5's boundary loop).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StepTailFlow {
    /// Fall through to the next tail statement.
    Fallthrough,
    /// Break C5's boundary loop (donor `break`).
    BreakLoop,
    /// Continue C5's boundary loop (donor `continue`).
    ContinueLoop,
}

/// Truncate donor button bits (donor `&` coerces through ToInt32; button
