/// Store a received NetQuake command (donor `player.receiveNetQuake`).
///
/// The world-command twin keeps the checkpoint-visible copy; the movement
/// lane owns the rest of receive (sequence gating lives with the move).
#[allow(dead_code)]
fn receive_net_quake_seam(player: &mut MovementPlayer, command: &ActorCommand) {
    use qa_net::common::commands::UserCommand;
    let twin = match &command.command {
        UserCommand::Q1Netquake { .. } => {
            let (acknowledged, view, forward, side) =
                command.command.q1_netquake_move().unwrap_or((0.0, [0.0; 3], 0.0, 0.0));
            Some(qa_world::movement::types::Q1UserCommand {
                acknowledged_server_time_seconds: acknowledged,
                view_angles: Vec3 {
                    x: view[0] as f32,
                    y: view[1] as f32,
                    z: view[2] as f32,
                },
                forward_move: forward,
                side_move: side,
                up_move: command.command.up_move().unwrap_or(0.0),
                buttons: step_button_bits(command.command.buttons()),
                impulse: command.command.impulse().unwrap_or(0.0) as i32,
            })
        }
        _ => None,
    };
    player.net_quake_command = twin;
}

