impl SharedSimulation {
    /// Run one boundary-iteration tail (donor step() 4429-4775, C6 range).
    ///
    /// C5's step head calls this once per boundary with the head's loop
    /// locals; the return selects the outer-loop flow (donor
    /// `break`/`continue`).
    #[allow(dead_code)]
    pub(super) fn step_frame_tail(
        &self,
        input: &InputBatch,
        ctx: &mut StepTailContext,
    ) -> Result<StepTailFlow, RuntimeError> {
        // Donor 4429-4432.
        let mut bot_commands: Vec<ActorCommand> = Vec::new();
        let applications_active = self.peek().mod_client_applications.active;
        let mut pending_net_quake: Option<HashMap<ActorId, ActorCommand>> = applications_active.then(HashMap::new);
        let mut pending_q1_pre_think: Option<HashMap<OwnedActor, u64>> = applications_active.then(HashMap::new);
        let prepares_q1_clients = {
            let state = self.peek();
            match &state.source {
                SourceRuntime::Q1 { .. } => true,
                SourceRuntime::QuakeC { game } => game.kind() == super::types::QuakeCSourceKind::Netquake,
                _ => false,
            }
        };
        // Donor 4433-4490: `if (run)`.
        if ctx.run {
            let flow = self.step_tail_run_frame(
                input,
                ctx,
                &mut bot_commands,
                &mut pending_net_quake,
                &mut pending_q1_pre_think,
                prepares_q1_clients,
            )?;
            if flow != StepTailFlow::Fallthrough {
                return Ok(flow);
            }
        }
        // Donor 4491-4493.
        if self.peek().source.kind() == "q2" && q2_intermission_fade_pending() {
            return Ok(StepTailFlow::ContinueLoop);
        }
        if ctx.run && !prepares_q1_clients && !ctx.settlement_active {
            let state = self.peek();
            let time_ms = match state.source_frame.time {
                SourceTime::Milliseconds(value) => f64::from(value),
                SourceTime::Seconds(_) => (self.time_seconds() * 1000.0).trunc(),
            };
            let elapsed_ms = ctx.elapsed * 1000.0;
            bot_commands = state.bot_services.frame(time_ms, elapsed_ms);
        }
        // Donor 4494-4590: client-command loop.
        self.step_tail_commands(input, ctx, &bot_commands, &pending_net_quake, &mut pending_q1_pre_think)?;
        // Donor 4592-4689: actor-turn loop.
        self.step_tail_actors(ctx, prepares_q1_clients)?;
        // Donor 4694-4730: post-frame reconciliation.
        self.step_tail_post_frames(ctx)?;
        // Donor 4731-4765: frame-exit finish.
        self.step_tail_finish(ctx)
    }
}

impl SharedSimulation {
    /// Run-frame preamble (donor 4433-4490).
    #[allow(clippy::too_many_arguments)]
    #[allow(dead_code)]
    fn step_tail_run_frame(
        &self,
        input: &InputBatch,
        ctx: &StepTailContext,
        bot_commands: &mut Vec<ActorCommand>,
        pending_net_quake: &mut Option<HashMap<ActorId, ActorCommand>>,
        pending_q1_pre_think: &mut Option<HashMap<OwnedActor, u64>>,
        prepares_q1_clients: bool,
    ) -> Result<StepTailFlow, RuntimeError> {
        use qa_core::time::FramePhase;
        // Donor 4434-4437: advance the source frame.
        {
            let mut state = self.lock();
            let clock_frame = state.clock.frame();
            if ctx.settlement_active {
                state.source_frame = FrameContext {
                    frame: clock_frame.frame + 1,
                    elapsed: SourceTime::Milliseconds(100),
                    phase: FramePhase::FrameEntry,
                    ..clock_frame
                };
            } else if ctx.fixed.is_none() {
                state.source_frame = FrameContext {
                    elapsed: SourceTime::Seconds(ctx.elapsed as f32),
                    phase: FramePhase::FrameEntry,
                    ..clock_frame
                };
            } else if matches!(clock_frame.time, SourceTime::Seconds(_)) {
                let elapsed = SourceTime::Seconds(ctx.elapsed as f32);
                state.source_frame = state
                    .clock
                    .advance(elapsed, FramePhase::FrameEntry)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            } else {
                let elapsed = SourceTime::Milliseconds(ctx.fixed.unwrap_or(0.0) as i32);
                state.source_frame = state
                    .clock
                    .advance(elapsed, FramePhase::FrameEntry)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            }
        }
        // Donor 4438.
        {
            let mut state = self.lock();
            begin_monster_frames(&mut state, ctx.boundary.milliseconds, true)?;
        }
        // Donor 4439-4444: selected Q1 arsenal frame.
        {
            let mut state = self.lock();
            if matches!(state.selected_arsenal, Some(SelectedArsenal::Q1(_))) {
                let frame = selected_q1_frame(&state)?;
                let time_s = seconds(frame.time);
                let elapsed_s = seconds(frame.elapsed);
                if let Some(SelectedArsenal::Q1(q1)) = state.selected_arsenal.as_mut() {
                    q1.game().borrow_mut().begin_frame(time_s, elapsed_s);
                }
                if matches!(state.selected_weapon_source, Some(SelectedWeaponSource::Q1 { .. })) {
                    selected_q1_mission_weapons_frame_seam(elapsed_s);
                }
                if let Some(SelectedArsenal::Q1(q1)) = state.selected_arsenal.as_mut() {
                    q1.frame(time_s)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
        }
        // Donor 4445.
        if !ctx.paused {
            let mut state = self.lock();
            advance_q1_punch(&mut state, &self.actors)?;
        }
        // Donor 4446: hand-grenade equipment frame.
        {
            let mut state = self.lock();
            if state.hand_grenades.is_some() {
                let map_clock = step_map_clock(&state)?;
                let provider_clock = match state.hand_grenades.as_ref().and_then(|hand| match hand.selection() {
                    qa_content::contract::HandGrenadeSelection::Enabled { source, .. } => Some(source.clone()),
                    qa_content::contract::HandGrenadeSelection::Disabled => None,
                }) {
                    Some(source) => {
                        let provider = provider_text(&source.provider);
                        provider_timing(&state.recipe, &provider)?.clock
                    }
                    None => map_clock,
                };
                let source_frame = state.source_frame;
                state.equipment_frame =
                    super::provider_frames::provider_frame(source_frame, &map_clock, &provider_clock);
            }
        }
        // Donor 4447-4453: grapple frame and source begins.
        {
            let mut state = self.lock();
            if state.grapple.is_some() {
                let map_clock = step_map_clock(&state)?;
                let (provider_clock, mechanic) =
                    match state.grapple.as_ref().and_then(|grapple| match grapple.selection() {
                        qa_content::contract::GrappleSelection::Enabled { source, mechanic, .. } => {
                            Some((source.clone(), mechanic.clone()))
                        }
                        qa_content::contract::GrappleSelection::Disabled => None,
                    }) {
                        Some((source, mechanic)) => {
                            let provider = provider_text(&source.provider);
                            (provider_timing(&state.recipe, &provider)?.clock, Some(mechanic))
                        }
                        None => (map_clock, None),
                    };
                let source_frame = state.source_frame;
                state.grapple_frame = super::provider_frames::provider_frame(source_frame, &map_clock, &provider_clock);
                let grapple_frame = state.grapple_frame;
                let player_actors: Vec<ActorId> = state.player_states.keys().map(|owned| owned.id().clone()).collect();
                match mechanic {
                    Some(qa_content::contract::GrappleMechanicDetail::Q1Threewave { .. }) => {
                        let grapple = state.grapple.as_ref().expect("grapple frame needs the grapple");
                        grapple_threewave_begin_frame_seam(
                            grapple,
                            seconds(grapple_frame.time),
                            seconds(grapple_frame.elapsed),
                        );
                    }
                    Some(qa_content::contract::GrappleMechanicDetail::Q3Qvm { .. }) => {
                        let source = state.qvm_grapple_source.clone();
                        let milliseconds = (seconds(grapple_frame.time) * 1000.0).round();
                        let frame = grapple_frame.frame;
                        drop(state);
                        if let Some(source) = source {
                            grapple_qvm_begin_frame_seam(&source, milliseconds, frame, &player_actors)?;
                        }
                    }
                    _ => {}
                }
            }
        }
        // Donor 4454-4460: Q2 rerelease intermission fade short-circuit.
        if self.peek().source.kind() == "q2" && q2_intermission_fade_pending() {
            {
                let mut state = self.lock();
                state.checking_q2_rules = true;
            }
            let result = q2_intermission_fade_frame_seam();
            {
                let mut state = self.lock();
                state.checking_q2_rules = false;
            }
            result?;
            {
                let mut state = self.lock();
                state.source_frame = state.clock.enter(FramePhase::FrameExit);
                if !state.transitions.is_empty() {
                    return Ok(StepTailFlow::BreakLoop);
                }
            }
            return Ok(StepTailFlow::ContinueLoop);
        }
        // Donor 4461: Q1 game begin frame.
        {
            let time_seconds = self.time_seconds();
            let state = self.lock();
            if let SourceRuntime::Q1 { services, .. } = &state.source {
                services.borrow_mut().begin_frame(time_seconds, ctx.elapsed);
            }
        }
        // Donor 4462: bot commands for Q1 clients.
        if prepares_q1_clients {
            let state = self.peek();
            let time_ms = match state.source_frame.time {
                SourceTime::Milliseconds(value) => f64::from(value),
                SourceTime::Seconds(_) => (self.time_seconds() * 1000.0).trunc(),
            };
            *bot_commands = state.bot_services.frame(time_ms, ctx.elapsed * 1000.0);
        }
        // Donor 4463-4484: NetQuake command receive + prepare.
        if prepares_q1_clients {
            self.step_tail_netquake_receive(input, bot_commands, pending_net_quake)?;
            self.step_tail_netquake_prepare(pending_net_quake)?;
        }
        // Donor 4485: QuakeC game begin frame.
        {
            let state = self.peek();
            if let SourceRuntime::QuakeC { game } = &state.source {
                let frame = state.source_frame;
                game.begin_frame(&frame)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            }
        }
        // Donor 4486-4490: Q1 composition pre-frame for non-NetQuake players.
        if self.peek().source.kind() == "q1" {
            self.step_tail_q1_composition(input, ctx, pending_q1_pre_think)?;
        }
        let _ = FramePhase::FrameEntry;
        Ok(StepTailFlow::Fallthrough)
    }
}

impl SharedSimulation {
    /// NetQuake command receive (donor 4464-4474).
    #[allow(dead_code)]
    fn step_tail_netquake_receive(
        &self,
        input: &InputBatch,
        bot_commands: &[ActorCommand],
        pending_net_quake: &mut Option<HashMap<ActorId, ActorCommand>>,
    ) -> Result<(), RuntimeError> {
        let applications_active = self.peek().mod_client_applications.active;
        for command in input.commands.iter().chain(bot_commands.iter()) {
            let player = self.require_player(&command.actor)?;
            if step_profile_kind(&player.profile) != "q1-netquake"
                || step_command_stale(command.sequence, player.last_sequence)
            {
                continue;
            }
            self.observe_client_command(command)?;
            if applications_active {
                {
                    let mut state = self.lock();
                    if let Some(entry) = state.player_states.get_mut(&player.actor) {
                        receive_net_quake_seam(entry, command);
                    }
                }
                if let Some(pending) = pending_net_quake.as_mut() {
                    pending.insert(player.actor.id().clone(), command.clone());
                }
            } else {
                let prepared = prepare_arsenal_command_seam(&player, command, false);
                {
                    let mut state = self.lock();
                    if let Some(entry) = state.player_states.get_mut(&player.actor) {
                        receive_net_quake_seam(entry, &prepared);
                    }
                }
                {
                    let state = self.peek();
                    if let Some(grapple) = state.grapple.as_ref() {
                        grapple.set_jump(player.actor.id(), step_button_bits(command.command.buttons()) & 2 != 0);
                    }
                }
            }
            {
                let state = self.peek();
                if let SourceRuntime::Q1 {
                    services, composition, ..
                } = &state.source
                {
                    if services.borrow().intermission.is_some() {
                        composition
                            .request_intermission_exit(
                                &mut services.borrow_mut(),
                                player.buttons != 0.0,
                                Some((player.actor.id(), step_button_bits(player.buttons) & 1 != 0)),
                            )
                            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                    }
                }
            }
        }
        Ok(())
    }

    /// NetQuake movement prepare (donor 4475-4483).
    fn step_tail_netquake_prepare(
        &self,
        pending_net_quake: &Option<HashMap<ActorId, ActorCommand>>,
    ) -> Result<(), RuntimeError> {
        use qa_core::time::FramePhase;
        let applications_active = self.peek().mod_client_applications.active;
        let actors: Vec<OwnedActor> = {
            let state = self.peek();
            state
                .player_states
                .values()
                .filter(|player| {
                    step_profile_kind(&player.profile) == "q1-netquake"
                        && player.cutscene.is_none()
                        && !player.intermission
                })
                .map(|player| player.actor.clone())
                .collect()
        };
        for owned in actors {
            let scale = {
                let state = self.peek();
                state
                    .grapple
                    .as_ref()
                    .map(|grapple| grapple.gravity_scale(owned.id()))
                    .unwrap_or(1)
            };
            let result = {
                let mut state = self.lock();
                let source_frame = state.source_frame;
                let Some(player) = state.player_states.get_mut(&owned) else {
                    continue;
                };
                let saved = player.gravity_multiplier;
                player.gravity_multiplier *= f64::from(scale);
                let frame = FrameContext {
                    phase: FramePhase::ClientCommand,
                    ..source_frame
                };
                let pending = pending_net_quake.as_ref().and_then(|map| map.get(player.actor.id()));
                let result = prepare_net_quake_seam(player, &frame, applications_active, pending);
                player.gravity_multiplier = saved;
                result
            };
            result?;
        }
        Ok(())
    }
}

impl SharedSimulation {
    /// Q1 composition pre-frame for non-NetQuake players (donor 4486-4504).
    #[allow(dead_code)]
    fn step_tail_q1_composition(
        &self,
        input: &InputBatch,
        ctx: &StepTailContext,
        pending_q1_pre_think: &mut Option<HashMap<OwnedActor, u64>>,
    ) -> Result<(), RuntimeError> {
        use qa_net::common::commands::MovementDialect;
        // Donor 4487: world gravity from the Q1 cvar.
        {
            let gravity = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q1 { cvars, .. } => f64::from(cvars.borrow().variable_value("sv_gravity")),
                    _ => return Ok(()),
                }
            };
            let mut state = self.lock();
            step_set_world_gravity(&mut state, gravity)?;
        }
        let state = self.peek();
        let SourceRuntime::Q1 {
            services, composition, ..
        } = &state.source
        else {
            return Ok(());
        };
        // Donor 4488: the composition pre-frame takes the source elapsed seconds.
        composition
            .pre_frame(&mut services.borrow_mut(), ctx.elapsed)
            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        // Donor 4489-4503.
        let applications_active = state.mod_client_applications.active;
        for player in state.player_states.values() {
            if step_profile_kind(&player.profile) == "q1-netquake" {
                continue;
            }
            let received = input.commands.iter().rev().find(|value| {
                value.actor == *player.actor.id() && (value.sequence as i64) > (player.last_sequence as i64)
            });
            if applications_active && received.is_some() && player.cutscene.is_none() && !player.intermission {
                if let (Some(pending), Some(got)) = (pending_q1_pre_think.as_mut(), received) {
                    pending.insert(player.actor.clone(), got.sequence);
                }
                continue;
            }
            let command = received.map(|got| &got.command);
            let jump = match command {
                None => step_button_bits(player.buttons) & 2 != 0,
                Some(held) if held.dialect() == MovementDialect::Q1Netquake => {
                    step_button_bits(held.buttons()) & 2 != 0
                }
                Some(held) if held.dialect() == MovementDialect::Q2Rerelease => {
                    step_button_bits(held.buttons()) & 8 != 0
                }
                Some(held) => held.up_move().unwrap_or(0.0) > 0.0,
            };
            let buttons = command.map(|held| held.buttons()).unwrap_or(player.buttons);
            composition
                .input(
                    &mut services.borrow_mut(),
                    player.actor.id(),
                    &qa_content::q1::composition::types::Q1SourceInput {
                        attack: player.cutscene.is_none() && step_button_bits(buttons) & 1 != 0,
                        jump: player.cutscene.is_none() && jump,
                        use_action: step_button_bits(buttons) & 4 != 0,
                        impulse: command.and_then(|held| held.impulse()).unwrap_or(0.0) as i32,
                    },
                )
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            composition
                .player_pre_think(&mut services.borrow_mut(), player.actor.id())
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            services
                .borrow_mut()
                .player_frame(&player.actor, self.time_seconds(), Some(player.water_level as i32))
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        }
        Ok(())
    }
}

