/// Donor `actors.referenceSaved(saved)` in the checkpoint domain (C10).
///
/// Resolves through [`qa_world::registry::ActorRegistry::resolve_saved`];
/// unresolvable references fail with the donor's range error.
fn reference_saved_actor(
    actors: &SessionActorRegistry,
    saved: qa_core::identity::SavedActorId,
) -> Result<ActorId, RuntimeError> {
    actors
        .inner()
        .resolve_saved(&saved)
        .map(|owned| owned.id().clone())
        .ok_or_else(|| RuntimeError::Range("Invalid historical actor checkpoint reference".to_string()))
}

impl SharedSimulation {
    /// Donor `restore` tail (C10: donor `runtime.ts` 6455-6846 save/load/close tail).
    ///
    /// C9's restore head runs the `q2-native` original-file blocks, then
    /// calls this for the saved-client loop and everything after (donor
    /// 6456 through the end of `restore`). The loop header at donor 6455 is
    /// re-attributed here so the loop stays whole; C9 ends its head after
    /// the classic-restore `if` block.
    #[allow(dead_code)]
    fn restore_native_clients_and_tail(&self, save: &super::save::SimulationSaveImage) -> Result<(), RuntimeError> {
        use qa_world::save::records::read_saved_actor;
        use qa_world::save::shared::read_vector;
        let is_q2_native = matches!(self.peek().source, SourceRuntime::Q2Native(_));
        if is_q2_native {
            let saved_clients = super::save::native_q2_saved_clients(save).map_err(source_failure)?;
            for saved in &saved_clients {
                let client = self
                    .peek()
                    .options_restored_clients
                    .clone()
                    .unwrap_or_default()
                    .into_iter()
                    .find(|client| client.slot() as i64 == saved.client_slot);
                let Some(client) = client else {
                    return fail("Native saved client has no retained session identity");
                };
                let allowed = {
                    let mut state = self.state.borrow_mut();
                    let native = match &mut state.source {
                        SourceRuntime::Q2Native(native) => native,
                        _ => return fail("No native Quake II source"),
                    };
                    match native {
                        Q2NativeSource::Classic { game, .. } => game
                            .connect(client.slot() + 1, &saved.userinfo)
                            .map(|outcome| outcome.allowed)
                            .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                        Q2NativeSource::Rerelease { game, .. } => game
                            .connect(client.slot() + 1, &saved.userinfo, 0, false)
                            .map(|outcome| outcome.allowed)
                            .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                    }
                };
                if !allowed {
                    return fail("Native source rejected restored client");
                }
                self.register_q2_native_client(&client, Q2NativeClientMode::Restore)?;
                if saved.phase == "active" {
                    let mut state = self.state.borrow_mut();
                    let native = match &mut state.source {
                        SourceRuntime::Q2Native(native) => native,
                        _ => return fail("No native Quake II source"),
                    };
                    match native {
                        Q2NativeSource::Classic { game, .. } => game
                            .begin(client.slot() + 1)
                            .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                        Q2NativeSource::Rerelease { game, .. } => game
                            .begin(client.slot() + 1)
                            .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                    }
                }
            }
            let module = {
                let state = self.peek();
                let native = match &state.source {
                    SourceRuntime::Q2Native(native) => native,
                    _ => return fail("No native Quake II source"),
                };
                match native {
                    Q2NativeSource::Classic { game, .. } => game
                        .module()
                        .map(|module| module.id.clone())
                        .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                    Q2NativeSource::Rerelease { game, .. } => game
                        .module()
                        .map(|module| module.id.clone())
                        .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                }
            };
            self.actors.borrow_mut().rebind_restored_source(&module)?;
            let has_inventory = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game.has_source_inventory(),
                    SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game.has_source_inventory(),
                    _ => false,
                }
            };
            if has_inventory {
                let clients = {
                    let state = self.peek();
                    match &state.source {
                        SourceRuntime::Q2Native(Q2NativeSource::Classic { clients, .. })
                        | SourceRuntime::Q2Native(Q2NativeSource::Rerelease { clients, .. }) => {
                            clients.values().cloned().collect::<Vec<_>>()
                        }
                        _ => Vec::new(),
                    }
                };
                for actor in &clients {
                    let entries = save
                        .inventories
                        .iter()
                        .find(|entry| self.actors.borrow().resolve_saved(entry.actor) == Some(actor.clone()))
                        .map(|entry| entry.entries.clone())
                        .unwrap_or_default();
                    self.c10_bind_equipment_inventory(actor, &entries)?;
                }
            }
        }
        let document = super::save::simulation_save_reader(save).map_err(source_failure)?;
        let reader = document.reader();
        let velocities = reader.field("nativeEquipmentVelocity");
        if velocities.value.is_some() {
            for entry in velocities.list(|value| {
                let actor = reference_saved_actor(&self.actors.borrow(), read_saved_actor(value.field("actor"))?)?;
                let velocity = read_vector(value.field("velocity"))?;
                Ok::<_, RuntimeError>((actor, velocity))
            })? {
                self.state
                    .borrow_mut()
                    .native_equipment_velocity
                    .insert(entry.0, entry.1);
            }
        }
        let requests = reader.field("nativeWeaponRequests");
        if requests.value.is_some() {
            for entry in requests.list(|value| {
                let actor = reference_saved_actor(&self.actors.borrow(), read_saved_actor(value.field("actor"))?)?;
                let weapon = value.field("weapon").integer(0)?;
                Ok::<_, RuntimeError>((actor, weapon))
            })? {
                self.state.borrow_mut().native_weapon_requests.insert(
                    entry.0,
                    i32::try_from(entry.1).map_err(|_| requests.fail("expected an integer in range"))?,
                );
            }
        }
        let map_provider = provider_text(&self.peek().recipe.map.entities.provider);
        let random = save
            .random
            .iter()
            .find(|stream| stream.provider == map_provider)
            .map(|stream| &stream.state);
        let Some(random) = random else {
            return fail("Save has no matching source random stream");
        };
        let checkpoint = match random {
            qa_world::save::shared::SaveRandomState::GlibcRandom { .. }
            | qa_world::save::shared::SaveRandomState::RereleaseMt19937 { .. } => {
                super::random::random_checkpoint_from_save(random).map_err(|error| {
                    RuntimeError::Range(match error {
                        super::random::RandomError::InvalidState => "Invalid source random state".to_string(),
                        _ => error.to_string(),
                    })
                })?
            }
            _ => return fail("Save has no matching source random stream"),
        };
        let is_rerelease = matches!(checkpoint, super::random::RandomCheckpoint::Mt19937(_));
        self.state
            .borrow_mut()
            .random
            .restore(&checkpoint)
            .map_err(|error| match error {
                super::random::RandomError::ProfileMismatch if is_rerelease => {
                    RuntimeError::Failure("Rerelease random state cannot restore a classic source stream".to_string())
                }
                super::random::RandomError::ProfileMismatch => {
                    RuntimeError::Failure("Classic random state cannot restore a rerelease source stream".to_string())
                }
                _ => RuntimeError::Range(error.to_string()),
            })?;
        let host_milliseconds = reader.field("hostMilliseconds").finite()?;
        self.state.borrow_mut().host_milliseconds = host_milliseconds;
        let paused = reader.field("q1Paused");
        self.state.borrow_mut().q1_pause_state = if paused.value.is_none() {
            false
        } else {
            paused.boolean()?
        };
        let scheduling = reader.field("sourceSchedulingMilliseconds");
        self.state.borrow_mut().source_scheduling_milliseconds = if scheduling.value.is_none() {
            host_milliseconds
        } else {
            scheduling.finite()?
        };
        let attack_sequence = reader.field("attackSequence").integer(0)?;
        self.state.borrow_mut().attack_sequence = attack_sequence as u64;
        let visibility = reader.field("q1ClientVisibility").value.cloned();
        self.state
            .borrow_mut()
            .q1_client_visibility
            .restore(visibility.as_ref())?;
        let campaign = reader.field("campaign");
        self.state.borrow_mut().q1_campaign.flags = campaign.field("flags").number()? as i32;
        self.state.borrow_mut().q1_campaign.skill = campaign.field("skill").choice_i64(&[0, 1, 2, 3])? as i32;
        let equipment_enabled = {
            let state = self.peek();
            matches!(
                state.recipe.equipment.grapple,
                qa_content::contract::GrappleSelection::Enabled { .. }
            ) || matches!(
                state.recipe.equipment.hand_grenades,
                qa_content::contract::HandGrenadeSelection::Enabled { .. }
            )
        };
        let is_q3_qvm = matches!(self.peek().source, SourceRuntime::Q3Qvm { .. });
        if (is_q2_native || is_q3_qvm) && equipment_enabled {
            for entry in &save.inventories {
                let actor = self.actors.borrow().resolve_saved(entry.actor);
                if let Some(actor) = actor {
                    let bound = self
                        .state
                        .borrow()
                        .inventory
                        .has(self.actors.borrow().inner(), actor.id());
                    if self.player_client(actor.id()).is_some() && !bound {
                        self.c10_bind_equipment_inventory(&actor, &entry.entries)?;
                    }
                }
            }
        }
        let declaration = reader.field("qvmPrimaryDeclaration");
        let expected_declaration = {
            let state = self.peek();
            match (&state.source, state.options_q3_guest.as_ref()) {
                (SourceRuntime::Q3Qvm { .. }, Some(guest)) => guest
                    .prepared
                    .primary
                    .declaration
                    .as_ref()
                    .map(|declaration| declaration.digest.as_str().to_string()),
                _ => None,
            }
        };
        let declared = if declaration.value.is_none() {
            None
        } else {
            declaration.nullable(|value| value.string())?
        };
        if declared != expected_declaration {
            return Err(declaration
                .fail("saved primary QVM interfaces differ from the mounted compatibility declaration")
                .into());
        }
        let armor_projection = reader.field("qvmArmorProjection");
        if armor_projection.value.is_some() {
            armor_projection.literal_i64(1)?;
        }
        let inventory_projection = reader.field("qvmInventoryProjection");
        if inventory_projection.value.is_some() {
            inventory_projection.literal_i64(1)?;
            let qualified = matches!(self.peek().source, SourceRuntime::Q3Qvm { inventory: Some(_), .. });
            if !qualified {
                return fail("Saved QVM inventory requires qualified source storage");
            }
        }
        let native_projection = reader.field("nativeInventoryProjection");
        if native_projection.value.is_some() {
            native_projection.literal_i64(1)?;
            let qualified = is_q2_native
                && match &self.peek().source {
                    SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game.has_source_inventory(),
                    SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game.has_source_inventory(),
                    _ => false,
                };
            if !qualified {
                return fail("Saved native inventory requires qualified source storage");
            }
        }
        let mut inventories = save.inventories.clone();
        if is_q2_native
            && match &self.peek().source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game.has_source_inventory(),
                SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game.has_source_inventory(),
                _ => false,
            }
        {
            let clients = match &self.peek().source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { clients, .. })
                | SourceRuntime::Q2Native(Q2NativeSource::Rerelease { clients, .. }) => {
                    clients.values().cloned().collect::<Vec<_>>()
                }
                _ => Vec::new(),
            };
            let legacy = native_projection.value.is_none();
            self.restore_inventory_coverage(&mut inventories, &clients, legacy, &save.actors)?;
        }
        if inventory_projection.value.is_none() {
            let covered: Option<Vec<OwnedActor>> = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q3Qvm {
                        game,
                        inventory: Some(_),
                        ..
                    } => {
                        let owned = self
                            .actors
                            .borrow()
                            .inner()
                            .owned_by(&state.recipe.map.entities.provider);
                        let num_clients = game.game.data.num_clients();
                        Some(
                            owned
                                .into_iter()
                                .filter(|actor| {
                                    let slot = game.records.slot(actor.id());
                                    match slot {
                                        Some(slot) => {
                                            slot >= 0
                                                && (slot as usize) < num_clients
                                                && state.inventory.has(self.actors.borrow().inner(), actor.id())
                                        }
                                        None => false,
                                    }
                                })
                                .collect(),
                        )
                    }
                    _ => None,
                }
            };
            if let Some(covered) = covered {
                self.restore_inventory_coverage(&mut inventories, &covered, true, &save.actors)?;
            }
        }
        let map_provider_id = self.peek().recipe.map.entities.provider.clone();
        let hydrate_needed = {
            let state = self.peek();
            matches!(state.source, SourceRuntime::QuakeC { .. } | SourceRuntime::Q3Qvm { .. })
                && matches!(state.selected_weapon_source, Some(SelectedWeaponSource::Q1 { .. }))
        };
        let effective = {
            let state = self.peek();
            match state.source_items_restore.as_ref() {
                Some(restore) => restore.effective(inventories)?,
                None => inventories,
            }
        };
        let combat = {
            let state = self.peek();
            let bindings = match &state.source {
                SourceRuntime::Q3Qvm {
                    combat: Some(combat), ..
                } if armor_projection.value.is_none() => Some(combat),
                _ => None,
            };
            match bindings {
                None => save.combat.clone(),
                Some(bindings) => save
                    .combat
                    .iter()
                    .map(|entry| {
                        let resolved = self.actors.borrow().resolve_saved(entry.actor);
                        let mut entry = entry.clone();
                        if let Some(owner) = resolved {
                            let source_owned = self
                                .actors
                                .borrow()
                                .source_of(owner.id())
                                .is_some_and(|(provider, _)| provider == map_provider_id);
                            if source_owned {
                                entry.state.armor = bindings
                                    .normalize_legacy_armor(owner.id(), &entry.state.armor)
                                    .map_err(source_failure)?;
                            }
                        }
                        Ok::<_, RuntimeError>(entry)
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            }
        };
        let view = qa_world::save::world_state::SharedSaveView {
            actors: save.actors.clone(),
            bodies: save.bodies.clone(),
            combat: combat.iter().map(|entry| (entry.actor, entry.state.clone())).collect(),
            inventories: effective
                .iter()
                .map(|entry| (entry.actor, entry.entries.clone()))
                .collect(),
            providers: save.providers.clone(),
            legacy_armor_layout: save.legacy_armor_layout,
        };
        let module_id = if is_q2_native {
            let state = self.peek();
            let native = match &state.source {
                SourceRuntime::Q2Native(native) => native,
                _ => return fail("No native Quake II source"),
            };
            Some(match native {
                Q2NativeSource::Classic { game, .. } => game
                    .module()
                    .map(|module| module.id.clone())
                    .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                Q2NativeSource::Rerelease { game, .. } => game
                    .module()
                    .map(|module| module.id.clone())
                    .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
            })
        } else {
            None
        };
        {
            let mut host = C10SharedWorldHost {
                actors: Rc::clone(&self.actors),
                bodies: Rc::clone(&self.bodies_table),
                state: Rc::clone(&self.state),
                map_provider: map_provider_id.clone(),
                module_id,
                copied_combat: HashSet::new(),
                combat_error: None,
                body_links_only: false,
            };
            let hydrate_error: Rc<RefCell<Option<RuntimeError>>> = Rc::new(RefCell::new(None));
            let selected_source = reader.field("selectedWeaponSource");
            let character_is_q1 = provider_text(&self.peek().recipe.character.definition.provider).starts_with("q1:");
            let mut hydrate = {
                let hydrate_error = Rc::clone(&hydrate_error);
                move |host: &mut C10SharedWorldHost| {
                    let result = (|| -> Result<(), RuntimeError> {
                        selected_source.field("kind").literal_str("q1")?;
                        // Donor `q1CharacterSource()` ensure: q1-kind sources already hold
                        // their game; selected-q1 adjunct registration and standalone
                        // foundation construction belong to the q1 lane.
                        // The q1 entity restore needs the q1 persistence->content
                        // checkpoint bridge (the two `Q1FoundationCheckpoint` types have
                        // no converter yet); the donor's game restore plus per-player
                        // max-health sync land with it.
                        let _ = (character_is_q1, &host.state);
                        fail("Missing siblings: q1 persistence->content checkpoint bridge (hydrate)")
                    })();
                    if let Err(error) = result {
                        *hydrate_error.borrow_mut() = Some(error);
                    }
                }
            };
            let hydrate_option: Option<&mut dyn FnMut(&mut C10SharedWorldHost)> =
                if hydrate_needed { Some(&mut hydrate) } else { None };
            let completion =
                qa_world::save::world_state::restore_shared_world_state(&view, &mut host, hydrate_option, true)?;
            if hydrate_error.borrow().is_some() {
                let error = hydrate_error
                    .borrow_mut()
                    .take()
                    .unwrap_or_else(|| RuntimeError::Failure("Selected Q1 hydration failed".to_string()));
                return Err(error);
            }
            let completion = completion
                .ok_or_else(|| RuntimeError::Failure("Shared restore did not defer protection".to_string()))?;
            let staged = completion.into_staged();
            if let Some(error) = host.combat_error.take() {
                return Err(error);
            }
            self.state.borrow_mut().pending_shared_restore = Some(PendingSharedRestore::new(staged));
        }
        let restored = reader.field("players").list(|value| {
            let errors = value.clone();
            let saved_actor = read_saved_actor(value.field("actor"))?;
            let owner = self.actors.borrow().resolve_saved(saved_actor);
            let Some(owner) = owner else {
                return Err(errors.fail("Missing restored actor").into());
            };
            let fallback = owner.id().clone();
            let resolve_failed = Rc::new(RefCell::new(false));
            let resolve_cell = Rc::clone(&resolve_failed);
            let reference: &super::player_checkpoint::ActorReference<'_> =
                &|saved| match self.actors.borrow().resolve_saved(saved) {
                    Some(owner) => owner.id().clone(),
                    None => {
                        *resolve_cell.borrow_mut() = true;
                        fallback.clone()
                    }
                };
            let saved_player = super::player_checkpoint::read_movement_player(value, reference)?;
            if *resolve_failed.borrow() {
                return Err(RuntimeError::Range(
                    "Invalid historical actor checkpoint reference".to_string(),
                ));
            }
            let client = self
                .peek()
                .options_restored_clients
                .clone()
                .unwrap_or_default()
                .into_iter()
                .find(|client| client.slot() == saved_player.client_slot);
            let Some(client) = client else {
                return Err(errors.fail("Saved player has no connected session client").into());
            };
            if !self.actors.borrow().inner().owner().owns_client(&client) {
                return Err(errors.fail("Saved player has no connected session client").into());
            }
            let bodies = SharedBodiesView {
                actors: Rc::clone(&self.actors),
                tables: Rc::clone(&self.bodies_table),
            };
            let Some(body) = bodies.read(owner.id()) else {
                return Err(errors.fail("Saved player has no body").into());
            };
            let mut player = self.create_player(
                &owner,
                &client,
                body.origin,
                saved_player.view_angles,
                saved_player.arsenal.clone(),
            )?;
            if !movement_kind_matches(&saved_player.state, &player.profile) {
                return Err(errors
                    .fail("Saved movement state differs from the selected movement provider")
                    .into());
            }
            player.state = saved_player.state;
            player.arsenal = saved_player.arsenal;
            player.animation = saved_player.animation;
            player.view_angles = saved_player.view_angles;
            player.command_angles = saved_player.command_angles;
            player.view_height = saved_player.view_height;
            player.bounds = saved_player.bounds;
            player.ground = saved_player.ground;
            player.water_level = saved_player.water_level;
            player.water_type = saved_player.water_type;
            player.intermission = saved_player.intermission;
            player.cutscene = saved_player.cutscene.map(|cutscene| PlayerCutscene {
                origin: cutscene.origin,
                angles: cutscene.angles,
                view_offset: cutscene.view_offset,
            });
            player.fixed_pose_active = saved_player.fixed_pose_active;
            player.body_shape_base = saved_player.body_shape_base;
            player.gravity_multiplier = saved_player.gravity_multiplier;
            player.flight = saved_player.flight;
            player.world_gravity = saved_player.world_gravity;
            player.buttons = saved_player.buttons;
            player.previous_buttons = saved_player.previous_buttons;
            player.last_sequence = saved_player.last_sequence;
            player.net_quake_command = saved_player.net_quake_command;
            player.last_weapon_seconds = saved_player.last_weapon_seconds;
            player.arsenal_intent = saved_player.arsenal_intent.map(|intent| PlayerArsenalIntent {
                provider: intent.provider,
                weapon: intent.weapon,
                use_holdable: intent.use_holdable,
                impulse: intent.impulse,
            });
            Ok::<_, RuntimeError>((owner, player))
        })?;
        for (owner, player) in restored {
            self.state.borrow_mut().player_states.insert(owner, player);
        }
        // Donor q3-kind continuation (donor 6564-6580).
        if matches!(self.peek().source, SourceRuntime::Q3 { .. }) {
            let native = super::save::native_q3_runtime_reader(save).map_err(source_failure)?;
            let product = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q3 { game } => game
                        .product()
                        .ok_or_else(|| source_failure("Q3 source product is not bound"))?,
                    _ => return fail("Q3 source product is not bound"),
                }
            };
            for entry in &native.arsenals {
                let actor = self.actors.borrow().resolve_saved(entry.actor);
                let Some(actor) = actor else {
                    return fail("Saved Q3 arsenal has no unique matching player and product");
                };
                {
                    let state = self.peek();
                    if !state.player_states.contains_key(&actor)
                        || state.q3_arsenals.contains_key(&actor)
                        || entry.state.product != product
                    {
                        return fail("Saved Q3 arsenal has no unique matching player and product");
                    }
                }
                self.state.borrow_mut().q3_arsenals.insert(actor, entry.state.clone());
            }
            let mut movement = HashSet::new();
            for entry in &native.movement {
                let actor = self.actors.borrow().resolve_saved(entry.actor);
                let Some(actor) = actor else {
                    return fail("Saved Q3 movement has no unique matching player");
                };
                if movement.contains(&actor) {
                    return fail("Saved Q3 movement has no unique matching player");
                }
                let mut state = self.state.borrow_mut();
                let Some(player) = state.player_states.get_mut(&actor) else {
                    return fail("Saved Q3 movement has no unique matching player");
                };
                movement.insert(actor.clone());
                // The runtime mirror drops `debug_level` (no counterpart on
                // the local `ClientMovementOptions`); the q3 lane unifies the
                // shapes post-merge.
                player.source_movement = entry.state.as_ref().map(|state| ClientMovementOptions {
                    trace_mask: Some(state.trace_mask),
                    fixed_msec: state.fixed_msec,
                    no_footsteps: Some(state.no_footsteps),
                    gauntlet_hit: Some(state.gauntlet_hit),
                });
            }
            {
                let state = self.peek();
                if movement.len() != state.player_states.len() || state.q3_arsenals.len() != state.player_states.len() {
                    return fail("Saved Q3 player continuation is incomplete");
                }
            }
            for entry in &native.last_attacks {
                let actor = self.actors.borrow().resolve_saved(entry.actor);
                let Some(actor) = actor else {
                    return fail("Saved Q3 attack has no unique matching actor");
                };
                if self.peek().last_attack.contains_key(&actor) {
                    return fail("Saved Q3 attack has no unique matching actor");
                }
                let attack = restore_q2_attack(&entry.attack, &self.actors.borrow())?;
                self.state.borrow_mut().last_attack.insert(actor, attack);
            }
            if provider_text(&self.peek().recipe.combat.provider).starts_with("q3:") {
                return fail("Missing siblings: q3 lane source combat bridge (restore)");
            }
            {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q3 { game } => game.finish_native_restore()?,
                    _ => return fail("Q3 source is not bound"),
                }
            }
        }
        // Donor selected-weapon-source restore (donor 6581-6620).
        {
            let selected_source = reader.field("selectedWeaponSource");
            let kind = {
                let state = self.peek();
                match &state.selected_weapon_source {
                    Some(SelectedWeaponSource::Q1 { .. }) => Some("q1"),
                    Some(SelectedWeaponSource::Q2 { .. }) => Some("q2"),
                    None => None,
                }
            };
            if kind.is_none() {
                // Donor `selectedSource.value !== null`: the field is
                // required, so a missing field fails like a present one.
                if !matches!(selected_source.value, Some(qa_world::save::value::SaveJson::Null)) {
                    return Err(selected_source
                        .fail("Saved selected weapon source has no matching authority")
                        .into());
                }
            } else if let Some(kind) = kind {
                selected_source.field("kind").literal_str(kind)?;
                let random =
                    super::equipment_checkpoint::read_source_random_checkpoint(selected_source.field("random"))?;
                {
                    let mut state = self.state.borrow_mut();
                    match state.selected_weapon_source.as_mut() {
                        Some(SelectedWeaponSource::Q1 { random: stream, .. })
                        | Some(SelectedWeaponSource::Q2 { random: stream, .. }) => {
                            stream.restore(&random).map_err(source_failure)?;
                        }
                        None => {}
                    }
                }
                if kind == "q1" {
                    if !hydrate_needed {
                        if provider_text(&self.peek().recipe.character.definition.provider).starts_with("q1:") {
                            self.with_q1_character_source(|_| ())?;
                        }
                        return fail(
                            "Missing siblings: q1 persistence->content checkpoint bridge (selectedWeaponSource q1)",
                        );
                    }
                } else {
                    let saved_frame = selected_source.field("frame");
                    let time = saved_frame.field("time");
                    let elapsed = saved_frame.field("elapsed");
                    let (time_kind, elapsed_kind, interval) = {
                        let state = self.peek();
                        match &state.selected_weapon_source {
                            Some(SelectedWeaponSource::Q2 {
                                frame,
                                interval_milliseconds,
                                ..
                            }) => {
                                let kind_of = |time: &qa_core::time::SourceTime| match time {
                                    qa_core::time::SourceTime::Seconds(_) => "seconds",
                                    qa_core::time::SourceTime::Milliseconds(_) => "milliseconds",
                                };
                                (kind_of(&frame.time), kind_of(&frame.elapsed), *interval_milliseconds)
                            }
                            _ => return fail("Selected Q2 source is not bound"),
                        }
                    };
                    time.field("kind").literal_str(time_kind)?;
                    elapsed.field("kind").literal_str(elapsed_kind)?;
                    let frame = qa_core::time::FrameContext {
                        frame: i32::try_from(saved_frame.field("frame").integer(0)?)
                            .map_err(|_| RuntimeError::Range("Selected Q2 source frame is out of range".to_string()))?,
                        time: qa_world::save::shared::read_time(time)?,
                        elapsed: qa_world::save::shared::read_time(elapsed)?,
                        phase: match saved_frame
                            .field("phase")
                            .choice_str(&["frame-entry", "client-command", "entity-think", "frame-exit"])?
                            .as_str()
                        {
                            "frame-entry" => qa_core::time::FramePhase::FrameEntry,
                            "client-command" => qa_core::time::FramePhase::ClientCommand,
                            "entity-think" => qa_core::time::FramePhase::EntityThink,
                            _ => qa_core::time::FramePhase::FrameExit,
                        },
                    };
                    if selected_source.field("intervalMilliseconds").finite()? != interval {
                        return Err(selected_source
                            .field("intervalMilliseconds")
                            .fail("Selected source interval differs from the admitted source")
                            .into());
                    }
                    let map_milliseconds = selected_source.field("mapMilliseconds").finite()?;
                    let next_milliseconds = selected_source.field("nextMilliseconds").finite()?;
                    {
                        let mut state = self.state.borrow_mut();
                        match state.selected_weapon_source.as_mut() {
                            Some(SelectedWeaponSource::Q2 {
                                frame: current,
                                map_milliseconds: map,
                                next_milliseconds: next,
                                ..
                            }) => {
                                *current = frame;
                                *map = map_milliseconds;
                                *next = next_milliseconds;
                            }
                            _ => return fail("Selected Q2 source is not bound"),
                        }
                    }
                    if map_milliseconds < 0.0
                        || next_milliseconds <= map_milliseconds
                        || next_milliseconds - map_milliseconds > interval
                    {
                        return Err(selected_source
                            .fail("Selected Q2 source deadline must follow admitted map progress")
                            .into());
                    }
                    // The selected-q2 entity/weapon restore needs the q2
                    // lane's opaque-service restore; fail closed in donor
                    // order (the turn replays below run once it lands).
                    return fail(
                        "Missing siblings: q2 selected-source entity/weapon restore (opaque Q2EntityServices/Q2Weapons)",
                    );
                    #[allow(unreachable_code)]
                    {
                        selected_source.field("turns").list(|value| {
                            let state = value.field("state");
                            let firing = state.field("firing");
                            let firing = if firing.value.is_none()
                                || matches!(firing.value, Some(qa_world::save::value::SaveJson::Null))
                            {
                                None
                            } else {
                                Some(super::arsenal::q2::Q2SelectedFiring {
                                    weapon: firing.field("weapon").string()?,
                                    credit: firing.field("credit").number()?,
                                })
                            };
                            let actor =
                                reference_saved_actor(&self.actors.borrow(), read_saved_actor(value.field("actor"))?)?;
                            let turn = super::arsenal::q2::Q2SelectedWeaponTurnState {
                                buttons: i32::try_from(state.field("buttons").integer(i64::MIN)?).map_err(|_| {
                                    RuntimeError::Range("Selected Q2 turn buttons are out of range".to_string())
                                })?,
                                latched_buttons: i32::try_from(state.field("latchedButtons").integer(i64::MIN)?)
                                    .map_err(|_| {
                                        RuntimeError::Range("Selected Q2 latched buttons are out of range".to_string())
                                    })?,
                                weapon_thunk: state.field("weaponThunk").boolean()?,
                                firing,
                            };
                            let mut state = self.state.borrow_mut();
                            match state.selected_arsenal.as_mut() {
                                Some(SelectedArsenal::Q2(arsenal)) => {
                                    arsenal.restore_turn(&actor, &turn).map_err(source_failure)?;
                                    Ok::<_, RuntimeError>(())
                                }
                                _ => Err(selected_source.fail("Selected Q2 source has no arsenal").into()),
                            }
                        })?;
                        let mut state = self.state.borrow_mut();
                        for player in state.player_states.values_mut() {
                            let next = arsenal_seam(player);
                            player.arsenal = next;
                        }
                    }
                }
            }
        }
        // Donor q1/q2 source restores (donor 6621-6629).
        {
            let is_q1 = matches!(self.peek().source, SourceRuntime::Q1 { .. });
            let is_q2 = matches!(self.peek().source, SourceRuntime::Q2 { .. });
            if is_q1 && super::save::saved_source_cvars(save).map_err(source_failure)?.is_none() {
                reader.field("sourceCvars").list(|value| {
                    let name = value.field("name").string()?;
                    let text = value.field("value").string()?;
                    let state = self.peek();
                    match &state.source {
                        SourceRuntime::Q1 { cvars, .. } => {
                            cvars.borrow_mut().set(&name, &text, true).map_err(source_failure)?;
                        }
                        _ => return fail("Q1 source console variables are not bound"),
                    }
                    Ok::<_, RuntimeError>(())
                })?;
            }
            if is_q1 {
                let bytes =
                    super::save::simulation_provider_checkpoint(save, "q1:foundation").map_err(source_failure)?;
                let checkpoint = crate::persistence::q1::foundation::decode_q1_foundation_checkpoint(&bytes.bytes)
                    .map_err(source_failure)?;
                let mut state = self.state.borrow_mut();
                match &mut state.source {
                    SourceRuntime::Q1 { game, .. } => game.restore(&checkpoint, false)?,
                    _ => return fail("Q1 source game is not bound"),
                }
            } else if is_q2 {
                return fail(
                    "Missing siblings: q2 lane restoreQ2Product (opaque Q2ProductRuntime plus persistence->content checkpoint bridge)",
                );
                #[allow(unreachable_code)]
                {
                    let saved_cvars = super::save::saved_source_cvars(save).map_err(source_failure)?;
                    if let Some(saved) = saved_cvars.as_ref() {
                        let state = self.peek();
                        if let Some(registry) = state.q2_server_registry.as_ref() {
                            crate::settings::server::restore_q2_server_cvars(&mut registry.borrow_mut(), saved)
                                .map_err(source_failure)?;
                        }
                    }
                }
            }
        }
        // Donor native weapon clocks (donor 6630-6637).
        {
            let native_weapon_times = reader.field("nativeWeaponTimes");
            self.state.borrow_mut().native_weapon_times.clear();
            if native_weapon_times.value.is_some() {
                native_weapon_times.list(|value| {
                    let actor = reference_saved_actor(&self.actors.borrow(), read_saved_actor(value.field("actor"))?)?;
                    let time = value.field("time").finite()?;
                    let bad = {
                        let state = self.peek();
                        !matches!(state.source, SourceRuntime::Q2Native(_))
                            || state.selected_arsenal.is_none()
                            || state.native_weapon_times.contains_key(&actor)
                    };
                    if bad {
                        return Err(value
                            .fail("Saved native weapon clock has no unique selected owner")
                            .into());
                    }
                    self.state.borrow_mut().native_weapon_times.insert(actor, time);
                    Ok::<_, RuntimeError>(())
                })?;
            }
        }
        // Donor selected Q3 source restore (donor 6638-6660).
        let selected_clients = if self
            .peek()
            .selected_arsenal
            .as_ref()
            .is_some_and(|arsenal| arsenal.family() == "q3")
        {
            reader.field("selectedArsenals").list(|value| {
                let saved = read_saved_actor(value.field("actor"))?;
                let actor = self.actors.borrow().resolve_saved(saved);
                let Some(actor) = actor else {
                    return Err(value.fail("Missing restored actor").into());
                };
                let state = super::arsenal::q3::read_q3_selected_arsenal_checkpoint(value.field("state"))?;
                Ok::<_, RuntimeError>((actor, state))
            })?
        } else {
            Vec::new()
        };
        {
            let selected_q3 = reader.field("selectedQ3Source");
            let old_ballistics = reader.field("selectedBallistics");
            let legacy_q3 =
                matches!(old_ballistics.value, Some(value) if !matches!(value, qa_world::save::value::SaveJson::Null));
            if self.peek().selected_q3_source.is_some() {
                if legacy_q3 {
                    if matches!(selected_q3.value, Some(value) if !matches!(value, qa_world::save::value::SaveJson::Null))
                    {
                        return Err(old_ballistics.fail("Saved Q3 source has two projectile owners").into());
                    }
                    {
                        let state = self.peek();
                        if !matches!(state.source, SourceRuntime::Q1 { .. } | SourceRuntime::Q2 { .. }) {
                            return Err(old_ballistics
                                .fail("Legacy Q3 source requires its original foreign map")
                                .into());
                        }
                    }
                    let saved = super::arsenal::q3_source_legacy::read_legacy_q3_source(
                        old_ballistics.clone(),
                        &|field| {
                            let saved = read_saved_actor(field.clone())?;
                            self.actors
                                .borrow()
                                .resolve_saved(saved)
                                .ok_or_else(|| qa_world::WorldError::BadSave("Missing restored actor".to_string()))
                        },
                        &|saved| {
                            self.actors
                                .borrow()
                                .resolve_saved(saved)
                                .map(|owner| owner.id().clone())
                                .ok_or_else(|| {
                                    qa_world::WorldError::BadSave(
                                        "Invalid historical actor checkpoint reference".to_string(),
                                    )
                                })
                        },
                    )?;
                    let timing = {
                        let state = self.peek();
                        let timing = provider_timing(&state.recipe, &provider_text(&state.weapon_provider.provider))?;
                        match &timing.clock {
                            qa_core::time::ClockProfile::Q3 {
                                server_frame_milliseconds,
                                ..
                            } => Some(*server_frame_milliseconds),
                            _ => None,
                        }
                    };
                    let Some(server_frame) = timing else {
                        return Err(old_ballistics.fail("Invalid legacy Q3 source clock").into());
                    };
                    if saved.milliseconds < 0 {
                        return Err(old_ballistics.fail("Invalid legacy Q3 source clock").into());
                    }
                    {
                        let mut state = self.state.borrow_mut();
                        state.selected_milliseconds = f64::from(saved.milliseconds);
                        state.selected_q3_time = f64::from(saved.milliseconds);
                        state.selected_q3_next = f64::from(saved.milliseconds) + server_frame;
                    }
                    {
                        let state = self.peek();
                        let mut actors = HashSet::new();
                        for (actor, _) in &selected_clients {
                            actors.insert(actor.clone());
                        }
                        if actors.len() != state.player_states.len()
                            || selected_clients.len() != state.player_states.len()
                            || selected_clients
                                .iter()
                                .any(|(actor, _)| !state.player_states.contains_key(actor))
                        {
                            return Err(old_ballistics
                                .fail("Legacy Q3 source client coverage differs from its saved players")
                                .into());
                        }
                    }
                    {
                        let state = self.peek();
                        let selected = state
                            .selected_q3_source
                            .as_ref()
                            .ok_or_else(|| source_failure("Selected Q3 source is not bound"))?;
                        let clients: Vec<super::arsenal::q3_source_legacy::LegacyQ3Client> = selected_clients
                            .iter()
                            .map(|(actor, checkpoint)| super::arsenal::q3_source_legacy::LegacyQ3Client {
                                actor: actor.clone(),
                                state: checkpoint.clone(),
                            })
                            .collect();
                        selected.restore_legacy(&saved, &clients).map_err(source_failure)?;
                    }
                } else {
                    let milliseconds = selected_q3.field("milliseconds").finite()?;
                    let time = selected_q3.field("time").finite()?;
                    let next = selected_q3.field("next").finite()?;
                    let strings = selected_q3.field("strings").list(|value| {
                        Ok::<_, RuntimeError>((value.field("index").integer(0)?, value.field("value").string()?))
                    })?;
                    {
                        let mut state = self.state.borrow_mut();
                        state.selected_milliseconds = milliseconds;
                        state.selected_q3_time = time;
                        state.selected_q3_next = next;
                        for (index, text) in strings {
                            let index = i32::try_from(index).map_err(|_| {
                                RuntimeError::Range("Selected Q3 string index is out of range".to_string())
                            })?;
                            state.selected_q3_strings.insert(index, text);
                        }
                    }
                    let source_field = selected_q3.field("source");
                    let Some(source_value) = source_field.value else {
                        return Err(source_field.fail("Saved Q3 source state is missing").into());
                    };
                    let state = self.peek();
                    let selected = state
                        .selected_q3_source
                        .as_ref()
                        .ok_or_else(|| source_failure("Selected Q3 source is not bound"))?;
                    let actors = self.actors.borrow();
                    selected
                        .restore(source_value, &|saved| actors.resolve_saved(saved), &|saved| {
                            actors
                                .resolve_saved(saved)
                                .map(|owner| owner.id().clone())
                                .expect("Invalid historical actor checkpoint reference")
                        })
                        .map_err(source_failure)?;
                }
            } else if legacy_q3
                || matches!(selected_q3.value, Some(value) if !matches!(value, qa_world::save::value::SaveJson::Null))
            {
                return Err(selected_q3.fail("Saved Q3 source has no selected owner").into());
            }
        }
        // Donor selected arsenals (donor 6661-6669).
        {
            let selected = reader.field("selectedArsenals");
            let is_q3_arsenal = self
                .peek()
                .selected_arsenal
                .as_ref()
                .is_some_and(|arsenal| arsenal.family() == "q3");
            if is_q3_arsenal {
                let old_ballistics = reader.field("selectedBallistics");
                let legacy_q3 = matches!(old_ballistics.value, Some(value) if !matches!(value, qa_world::save::value::SaveJson::Null));
                let map = {
                    let state = self.peek();
                    if matches!(state.source, SourceRuntime::Q1 { .. }) {
                        Some(super::arsenal::q3_source_legacy::LegacyMap::Q1)
                    } else if matches!(state.source, SourceRuntime::Q2 { .. }) {
                        Some(super::arsenal::q3_source_legacy::LegacyMap::Q2)
                    } else {
                        None
                    }
                };
                for (actor, checkpoint) in &selected_clients {
                    let state = match (legacy_q3, map) {
                        (true, Some(map)) => {
                            super::arsenal::q3_source_legacy::migrate_legacy_q3_arsenal(checkpoint, map)
                                .map_err(source_failure)?
                        }
                        _ => checkpoint.clone(),
                    };
                    let mut lock = self.state.borrow_mut();
                    match lock.selected_arsenal.as_mut() {
                        Some(SelectedArsenal::Q3(arsenal)) => {
                            arsenal.restore(actor, &state).map_err(source_failure)?;
                        }
                        _ => {
                            return fail("Saved selected arsenal has no matching authority");
                        }
                    }
                }
                {
                    let mut lock = self.state.borrow_mut();
                    for player in lock.player_states.values_mut() {
                        let next = arsenal_seam(player);
                        player.arsenal = next;
                    }
                }
            } else if matches!(selected.value, Some(value) if !matches!(value, qa_world::save::value::SaveJson::Null)) {
                return Err(selected.fail("Saved selected arsenal has no matching authority").into());
            }
        }
        // Donor native inventory selections (donor 6671-6677).
        {
            self.state.borrow_mut().restored_native_inventory_selections.clear();
            let selections = reader.field("nativeInventorySelections");
            if selections.value.is_some() {
                selections.list(|value| {
                    let actor = reference_saved_actor(&self.actors.borrow(), read_saved_actor(value.field("actor"))?)?;
                    let item = value.field("item").nullable(qa_world::save::value::namespaced)?;
                    let bad = {
                        let state = self.peek();
                        let actors = self.actors.borrow();
                        !matches!(state.source, SourceRuntime::Q2Native(_))
                            || !state.inventory.inner().has(actors.inner(), &actor)
                            || state.restored_native_inventory_selections.contains_key(&actor)
                    };
                    if bad {
                        return Err(value
                            .fail("Saved native inventory cursor has no unique selected owner")
                            .into());
                    }
                    self.state
                        .borrow_mut()
                        .restored_native_inventory_selections
                        .insert(actor, item);
                    Ok::<_, RuntimeError>(())
                })?;
            }
        }
        // Donor selected monsters (donor 6678-6680).
        {
            let monsters = reader.field("selectedMonsters");
            if self.peek().selected_monsters.is_some() {
                let checkpoint = super::monster_checkpoint::read_selected_monsters_checkpoint(monsters)?;
                self.restore_selected_monsters(&checkpoint)?;
            } else if !matches!(monsters.value, Some(qa_world::save::value::SaveJson::Null)) {
                // Donor `monsters.value !== null`: the field is required,
                // so a missing field fails like a present one.
                return Err(monsters
                    .fail("Saved selected monsters have no matching admission")
                    .into());
            }
        }
        // Donor grapple restore (donor 6681-6687).
        {
            let grapple_field = reader.field("grapple");
            if self.peek().grapple.is_some() {
                let checkpoint = super::grapple_checkpoint::read_grapple_runtime_checkpoint(
                    grapple_field,
                    &read_qvm_grapple_component_checkpoint,
                )?;
                let state = self.peek();
                let grapple = state
                    .grapple
                    .as_ref()
                    .ok_or_else(|| source_failure("Saved grapple has no selected controller"))?;
                grapple.restore(checkpoint).map_err(source_failure)?;
            } else if matches!(
                self.peek().recipe.equipment.grapple,
                qa_content::contract::GrappleSelection::Enabled {
                    mechanic: qa_content::contract::GrappleMechanicDetail::Q3Qvm { .. },
                    ..
                }
            ) {
                let checkpoint = super::grapple_checkpoint::read_grapple_runtime_checkpoint(
                    grapple_field,
                    &read_qvm_grapple_component_checkpoint,
                )?;
                let slots = super::weapon_slot_checkpoint::read_weapon_slots(reader.field("weaponSlots"))?;
                self.state.borrow_mut().pending_qvm_grapple_restore = Some(PendingQvmGrappleRestore {
                    grapple: checkpoint,
                    slots,
                });
            } else if matches!(grapple_field.value, Some(value) if !matches!(value, qa_world::save::value::SaveJson::Null))
            {
                return Err(grapple_field.fail("Saved grapple has no selected controller").into());
            }
        }
        self.state.borrow_mut().weapon_slots.clear();
        if self.peek().pending_qvm_grapple_restore.is_none() {
            for saved in super::weapon_slot_checkpoint::read_weapon_slots(reader.field("weaponSlots"))? {
                let actor = self.actors.borrow().resolve_saved(saved.actor);
                let Some(actor) = actor else {
                    return fail("Saved slot actor is missing");
                };
                self.bind_weapon_slot(actor.id(), Some(saved.state))?;
            }
        }
        // Donor hand-grenade restore (donor 6688-6691).
        {
            let equipment = reader.field("handGrenades");
            if self.peek().hand_grenades.is_some() {
                let checkpoint = super::equipment_checkpoint::read_hand_grenade_runtime_checkpoint(equipment)?;
                let restored = self.with_hand_grenades(|runtime, game| {
                    let mut state = self.lock();
                    runtime.restore(game, &mut state.random, checkpoint)
                })?;
                if let Some(result) = restored {
                    result.map_err(source_failure)?;
                }
            } else if matches!(equipment.value, Some(value) if !matches!(value, qa_world::save::value::SaveJson::Null))
            {
                return Err(equipment.fail("Saved equipment has no selected controller").into());
            }
        }
        {
            let equipment = {
                let state = self.peek();
                matches!(state.source, SourceRuntime::Q2Native(_) | SourceRuntime::Q3Qvm { .. })
                    && (state.grapple.is_some() || state.hand_grenades.is_some())
            };
            if equipment {
                for actor in self.players() {
                    let available = self.equipment_player_available(&actor);
                    let mut state = self.state.borrow_mut();
                    state.native_equipment_players.insert(actor.clone());
                    state.native_equipment_alive.insert(actor, available);
                }
            }
        }
        // Donor q1 character foundation (donor 6693-6694).
        {
            let foundation = reader.field("q1CharacterFoundation");
            if matches!(foundation.value, Some(value) if !matches!(value, qa_world::save::value::SaveJson::Null)) {
                return fail("Missing siblings: q1 persistence->content checkpoint bridge (q1CharacterFoundation)");
            }
        }
        // Donor q1 characters (donor 6695-6699).
        reader.field("q1Characters").list(|value| {
            let saved = read_saved_actor(value.field("actor"))?;
            let owner = self.actors.borrow().resolve_saved(saved);
            let Some(owner) = owner else {
                return Err(value.fail("Missing restored actor").into());
            };
            let player = self.require_player(owner.id())?;
            self.attach_q1_character(&player)?;
            let bytes = value.field("bytes").bytes()?;
            let mut state = self.state.borrow_mut();
            let Some(mut character) = state.q1_characters.remove(&owner) else {
                return Err(value.fail("Q1 character was not bound").into());
            };
            if let Some(SelectedWeaponSource::Q1 { game, .. }) = state.selected_weapon_source.as_ref() {
                character.restore(game, &bytes).map_err(source_failure)?;
            } else if let Some(game) = state.q1_character_foundation.as_ref() {
                character.restore(game, &bytes).map_err(source_failure)?;
            } else {
                return Err(value.fail("Q1 character has no game").into());
            }
            state.q1_characters.insert(owner, character);
            Ok::<_, RuntimeError>(())
        })?;
        // Donor q2 characters (donor 6700-6704). The content character
        // restore needs the q2 persistence->content checkpoint bridge; fail
        // closed before attaching when the save carries any entries.
        {
            let entries = reader.field("q2Characters").list(|value| {
                let saved = read_saved_actor(value.field("actor"))?;
                let owner = self.actors.borrow().resolve_saved(saved);
                let Some(owner) = owner else {
                    return Err(value.fail("Missing restored actor").into());
                };
                let _ = crate::persistence::q2::players::read_q2_character_checkpoint(value.field("state"))
                    .map_err(source_failure)?;
                Ok::<_, RuntimeError>(owner)
            })?;
            if !entries.is_empty() {
                return fail("Missing siblings: q2 persistence->content character checkpoint bridge (q2Characters)");
            }
        }
        // Donor character starts (donor 6705).
        reader.field("characterStarts").list(|value| {
            let saved = read_saved_actor(value.field("actor"))?;
            let owner = self.actors.borrow().resolve_saved(saved);
            let Some(owner) = owner else {
                return Err(value.fail("Missing restored actor").into());
            };
            let start = value.field("start").nullable(|field| {
                let saved = read_saved_actor(field)?;
                reference_saved_actor(&self.actors.borrow(), saved)
            })?;
            self.state.borrow_mut().character_starts.insert(owner, start);
            Ok::<_, RuntimeError>(())
        })?;
        // Donor q3 characters (donor 6706-6715). Character construction plus
        // restore belongs to the q3 lane; fail closed when the save carries
        // any entries.
        {
            let entries = reader.field("q3Characters").list(|value| {
                let saved = read_saved_actor(value.field("actor"))?;
                let owner = self.actors.borrow().resolve_saved(saved);
                let Some(owner) = owner else {
                    return Err(value.fail("Missing restored actor").into());
                };
                let _ = super::player_checkpoint::read_q3_character(value.field("state"))?;
                Ok::<_, RuntimeError>(owner)
            })?;
            if !entries.is_empty() {
                return fail("Missing siblings: q3 lane Q3CharacterActor construction/restore (q3Characters)");
            }
        }
        // Donor selected-original-pickup binding (donor 6716).
        for actor in self.players() {
            if let Some(owner) = self.actors.borrow().resolve_owned(&actor) {
                self.bind_selected_original_pickups(&owner)?;
            }
        }
        // Donor death animations (donor 6717).
        {
            let death = reader.field("deathAnimations");
            death.field("version").literal_i64(1)?;
            let index = i32::try_from(death.field("index").integer(0)?)
                .map_err(|_| RuntimeError::Range("Death animation index is out of range".to_string()))?;
            self.state
                .borrow_mut()
                .death_animations
                .restore(qa_content::q3::base::game::death::Q3DeathAnimationCheckpoint { version: 1, index });
        }
        // Donor character ticks (donor 6718).
        reader.field("characterTicks").list(|value| {
            let saved = read_saved_actor(value.field("actor"))?;
            let owner = self.actors.borrow().resolve_saved(saved);
            let Some(owner) = owner else {
                return Err(value.fail("Missing restored actor").into());
            };
            let time = value.field("time").number()?;
            self.state.borrow_mut().character_ticks.insert(owner, time);
            Ok::<_, RuntimeError>(())
        })?;
        // Donor entry carry (donor 6719).
        reader.field("entryCarry").list(|value| {
            let saved = read_saved_actor(value.field("actor"))?;
            let owner = self.actors.borrow().resolve_saved(saved);
            let Some(owner) = owner else {
                return Err(value.fail("Missing restored actor").into());
            };
            let state = super::player_checkpoint::read_q1_travel(value.field("state"))?;
            self.state.borrow_mut().entry_carry.insert(owner, state);
            Ok::<_, RuntimeError>(())
        })?;
        // Donor detached models (donor 6720-6724).
        reader.field("detachedModels").list(|value| {
            let saved = read_saved_actor(value.field("actor"))?;
            let owner = self.actors.borrow().resolve_saved(saved);
            let Some(owner) = owner else {
                return Err(value.fail("Missing restored actor").into());
            };
            let model = DetachedModel {
                content: ContentId(qa_world::save::shared::read_content_id(value.field("content"))?),
                path: value.field("path").string()?,
            };
            {
                let mut state = self.state.borrow_mut();
                state.detached_models.insert(owner.clone(), model);
                let registry = self.actors.borrow();
                let actors = Rc::clone(&self.actors);
                state.callbacks.borrow().bind(
                    &registry,
                    &owner,
                    ActorCallbacks {
                        think: Some(Rc::new(move |owned: &OwnedActor, _frame: FrameContext| {
                            let _ = actors.borrow_mut().release(owned);
                        })),
                        touch: None,
                        use_action: None,
                        pain: None,
                        die: None,
                    },
                )?;
            }
            Ok::<_, RuntimeError>(())
        })?;
        // Donor view models (donor 6725-6729).
        reader.field("viewModels").list(|value| {
            let actor = reference_saved_actor(&self.actors.borrow(), read_saved_actor(value.field("actor"))?)?;
            let q2 = value.field("q2").nullable(|view| {
                Ok::<_, RuntimeError>(ViewModelQ2 {
                    skin: i32::try_from(view.field("skin").integer(i64::MIN)?)
                        .map_err(|_| RuntimeError::Range("View-model skin is out of range".to_string()))?,
                    rate: view.field("rate").finite()?,
                    kick_origin: read_vector(view.field("kickOrigin"))?,
                    kick_angles: read_vector(view.field("kickAngles"))?,
                })
            })?;
            #[allow(clippy::cast_possible_truncation)]
            let frame = value.field("frame").number()? as i32;
            let entry = ViewModelEntry {
                path: value.field("path").string()?,
                frame,
                q2,
            };
            self.state.borrow_mut().view_models.insert(actor, entry);
            Ok::<_, RuntimeError>(())
        })?;
        // Donor q2 views (donor 6730).
        reader.field("q2Views").list(|value| {
            let actor = reference_saved_actor(&self.actors.borrow(), read_saved_actor(value.field("actor"))?)?;
            let view = super::player_checkpoint::read_q2_view(value.field("view"))?;
            self.state.borrow_mut().q2_views.insert(actor, view);
            Ok::<_, RuntimeError>(())
        })?;
        // Donor native module plus reconstructed-actor helper (donor 6469).
        let links_module = if is_q2_native {
            let state = self.peek();
            let native = match &state.source {
                SourceRuntime::Q2Native(native) => native,
                _ => return fail("No native Quake II source"),
            };
            Some(match native {
                Q2NativeSource::Classic { game, .. } => game
                    .module()
                    .map(|module| module.id.clone())
                    .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                Q2NativeSource::Rerelease { game, .. } => game
                    .module()
                    .map(|module| module.id.clone())
                    .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
            })
        } else {
            None
        };
        let reconstructed = |actor: &ActorId| -> bool {
            is_q2_native
                && self
                    .actors
                    .borrow()
                    .source_of(actor)
                    .is_some_and(|(provider, _)| Some(&provider) == links_module.as_ref())
        };
        // Donor source models (donor 6731-6739). The runtime
        // `RuntimeQ2ModelEvent` holds path/model only, so non-reconstructed
        // entries fail closed; the q2 lane owns full model-state storage.
        reader.field("sourceModels").list(|value| {
            let attached = value.field("attachedModels").list(|entry| entry.string())?;
            let actor = reference_saved_actor(&self.actors.borrow(), read_saved_actor(value.field("actor"))?)?;
            if attached.len() > 3 {
                return Err(value.fail("Q2 attached models exceed three slots").into());
            }
            if reconstructed(&actor) {
                return Ok::<_, RuntimeError>(());
            }
            if attached.len() != 3 {
                return Err(value.fail("Q2 attached models must retain three slots").into());
            }
            fail("Missing siblings: q2 lane source-model state storage (RuntimeQ2ModelEvent holds path/model only)")
        })?;
        // Donor level change (donor 6740-6742).
        {
            let level = reader.field("levelChange").nullable(|value| {
                let landmark = value.field("landmark").nullable(|value| {
                    Ok::<_, RuntimeError>(Q2LandmarkCarry {
                        player: reference_saved_actor(&self.actors.borrow(), read_saved_actor(value.field("player"))?)?,
                        name: value.field("name").string()?,
                        relative_origin: read_vector(value.field("relativeOrigin"))?,
                        relative_velocity: read_vector(value.field("relativeVelocity"))?,
                        relative_view_angles: read_vector(value.field("relativeViewAngles"))?,
                    })
                })?;
                #[allow(clippy::cast_possible_truncation)]
                let server_flags = value.field("serverFlags").number()? as i32;
                Ok::<_, RuntimeError>(LevelChange {
                    map: value.field("map").string()?,
                    landmark,
                    server_flags,
                })
            })?;
            self.state.borrow_mut().level_change = level;
        }
        // Donor physics checkpoint (donor 6743).
        {
            let physics = reader.field("physics");
            let q3 = matches!(
                self.peek().source,
                SourceRuntime::Q3 { .. } | SourceRuntime::Q3Qvm { .. }
            );
            self.lock().physics.restore_checkpoint(&physics, q3, &reconstructed)?;
        }
        // Donor area portals (donor 6744).
        reader.field("portals").list(|value| {
            let portal = value.field("portal").integer(0)?;
            let open = value.field("open").boolean()?;
            let portal = u32::try_from(portal)
                .map_err(|_| RuntimeError::Range("Area portal index is out of range".to_string()))?;
            {
                let state = self.peek();
                state.scene.set_area_portal_state(portal, open);
            }
            self.state.borrow_mut().area_portals.insert(portal, open);
            Ok::<_, RuntimeError>(())
        })?;
        // Donor shared body links (donor 6745).
        {
            let map_provider = self.peek().recipe.map.entities.provider.clone();
            let mut host = C10SharedWorldHost {
                actors: Rc::clone(&self.actors),
                bodies: Rc::clone(&self.bodies_table),
                state: Rc::clone(&self.state),
                map_provider,
                module_id: links_module.clone(),
                copied_combat: HashSet::new(),
                combat_error: None,
                body_links_only: true,
            };
            qa_world::save::world_state::restore_shared_body_links(&save.bodies, &mut host)?;
        }
        // Donor physics spatial restore (donor 6746).
        {
            let physics = reader.field("physics");
            self.lock().physics.restore_spatial(&physics, &reconstructed)?;
        }
        // Donor q2 server gravity (donor 6747-6750).
        if matches!(self.peek().source, SourceRuntime::Q2 { .. }) && self.peek().q2_server_registry.is_some() {
            let gravity = self.peek().physics.gravity().to_string();
            if super::save::saved_source_cvars(save).map_err(source_failure)?.is_none() {
                let state = self.peek();
                let registry = state.q2_server_registry.as_ref().unwrap();
                registry
                    .borrow_mut()
                    .set("sv_gravity", &gravity, true)
                    .map_err(source_failure)?;
            } else {
                let state = self.peek();
                let registry = state.q2_server_registry.as_ref().unwrap();
                if registry.borrow().get("sv_gravity").is_none() {
                    registry
                        .borrow_mut()
                        .register("sv_gravity", &gravity, 0)
                        .map_err(source_failure)?;
                }
            }
        }
        // Donor think scheduling (donor 6751-6756).
        for think in &save.thinks {
            let actor = self.actors.borrow().resolve_saved(think.actor);
            let Some(actor) = actor else {
                return fail("Saved think has no restored actor");
            };
            let timing = qa_world::scheduler::ThinkTiming {
                execution_provider: think.execution_provider.as_deref().map(parse_provider).transpose()?,
                due: think.due,
                boundary: think.boundary,
                order: qa_world::scheduler::InvocationOrder {
                    actor: actor.id().clone(),
                    provider: parse_provider(&think.provider)?,
                    sequence: think.sequence,
                },
            };
            let actors = self.actors.borrow();
            self.peek()
                .scheduler
                .schedule(actors.inner(), &actor, &think.callback, timing)?;
        }
        // Donor q1 punch (donor 6757-6763).
        {
            let punch_field = reader.field("q1Punch");
            self.lock().q1_punch.restore(&punch_field)?;
            if punch_field.value.is_none()
                && self
                    .peek()
                    .selected_arsenal
                    .as_ref()
                    .is_some_and(|arsenal| arsenal.family() == "q1")
                && matches!(
                    self.peek().selected_weapon_source,
                    Some(SelectedWeaponSource::Q1 { .. })
                )
            {
                let players = self.players();
                let writes: Vec<(ActorId, Vec3)> = {
                    let state = self.peek();
                    let game = match &state.selected_weapon_source {
                        Some(SelectedWeaponSource::Q1 { game, .. }) => game,
                        _ => return fail("Selected Q1 source is not bound"),
                    };
                    players
                        .iter()
                        .filter_map(|actor| {
                            game.players
                                .get(actor)
                                .map(|previous| (actor.clone(), previous.punch_angles))
                        })
                        .collect()
                };
                let mut state = self.lock();
                for (actor, angles) in writes {
                    state.q1_punch.write(&actor, angles).map_err(source_failure)?;
                }
            }
        }
        // Donor dropped pickups (donor 6764).
        self.lock()
            .dropped_pickups
            .restore(reader.field("droppedPickups"))
            .map_err(source_failure)?;
        // Donor weapon behaviors (donor 6765).
        self.lock()
            .weapon_behavior
            .restore(reader.field("weaponBehaviors"))
            .map_err(source_failure)?;
        // Donor mod-client applications (donor 6766).
        {
            let ordinal_field = reader.field("modClientApplicationOrdinal");
            let ordinal = if ordinal_field.value.is_none() {
                0
            } else {
                u64::try_from(ordinal_field.integer(0)?)
                    .map_err(|_| RuntimeError::Range("Mod-client application ordinal is out of range".to_string()))?
            };
            self.lock().mod_client_applications.restore(ordinal);
        }
        // Donor mod-client commands (donor 6767-6768).
        {
            struct RestoreHost<'s> {
                sim: &'s SharedSimulation,
                identity: std::cell::Ref<'s, qa_core::identity::IdentityOwner>,
            }
            impl super::mod_client_checkpoint::ModClientHost for RestoreHost<'_> {
                fn identity(&self) -> &qa_core::identity::IdentityOwner {
                    &self.identity
                }
                fn actor(
                    &self,
                    saved: qa_core::identity::SavedActorId,
                ) -> Result<ActorId, super::mod_client_checkpoint::ModClientCheckpointError> {
                    reference_saved_actor(&self.sim.actors.borrow(), saved).map_err(|error| {
                        super::mod_client_checkpoint::ModClientCheckpointError::World(qa_world::WorldError::BadSave(
                            error.to_string(),
                        ))
                    })
                }
                fn client(&self, actor: &ActorId) -> Option<ClientId> {
                    self.sim.player_client(actor)
                }
            }
            let identity = std::cell::Ref::map(self.actors.borrow(), |registry| registry.inner().owner());
            let host = RestoreHost { sim: self, identity };
            let commands =
                super::mod_client_checkpoint::read_mod_client_commands(reader.field("modClientCommands"), &host)
                    .map_err(source_failure)?;
            for value in &commands {
                let client = self.player_client(&value.input.actor).ok_or_else(|| {
                    RuntimeError::Failure("Saved command requires one live restored client".to_string())
                })?;
                let input = restored_mod_client_command(&value.input, &client)?;
                self.lock().mod_client_commands.insert(
                    value.input.actor.clone(),
                    ModClientCommand {
                        input,
                        time: value.time,
                    },
                );
            }
        }
        // Donor events (donor 6769).
        {
            let events_field = reader.field("events");
            let actors = self.actors.borrow();
            self.lock().events.restore(&events_field, &|saved| {
                actors
                    .resolve_saved(saved)
                    .map(|owner| owner.id().clone())
                    .expect("Invalid historical actor checkpoint reference")
            })?;
        }
        // Donor Q2 presentation resume (donor 6770).
        self.resume_q2_presentation()?;
        // Donor selected ammo timers (donor 6771-6777).
        {
            let ammo_timers = reader.field("selectedAmmoTimers");
            let owned =
                self.peek().selected_ammo_timers.is_some() && matches!(self.peek().source, SourceRuntime::Q3 { .. });
            if owned {
                let actors = self.selected_ammo_actors();
                let mut state = self.lock();
                let timers = state
                    .selected_ammo_timers
                    .as_mut()
                    .ok_or_else(|| source_failure("Saved ammo timers have no selected source owner"))?;
                timers
                    .restore(
                        ammo_timers,
                        &actors,
                        &|saved| {
                            self.actors
                                .borrow()
                                .resolve_saved(saved)
                                .ok_or_else(|| qa_world::WorldError::BadSave("Missing restored actor".to_string()))
                        },
                        &|_, _| {
                            // Legacy lookups need the q3 source records, which
                            // the opaque `Q3SourceRuntime` does not expose;
                            // modern saves never invoke this closure.
                            panic!("Missing siblings: q3 lane ammo-timer legacy records (Q3SourceRuntime.records)")
                        },
                    )
                    .map_err(source_failure)?;
            } else if matches!(ammo_timers.value, Some(value) if !matches!(value, qa_world::save::value::SaveJson::Null))
            {
                return Err(ammo_timers
                    .fail("Saved ammo timers have no selected source owner")
                    .into());
            }
        }
        // Donor event sequence check (donor 6778).
        if self.peek().events.next_sequence() != save.next_event_sequence {
            return fail("Save event sequence disagrees with its source journal");
        }
        Ok(())
    }
}

