/// Relativize a command against movement state (donor
/// `relativeMovementCommand`).
///
/// Missing siblings: angle-space tracking lives with the world-twin port
/// (`q3_commands`); net commands carry no angle space, so absolute-aim
/// relativization cannot fire and the command passes through until the
/// twins merge.
#[allow(dead_code)]
fn relative_movement_command_seam(command: &ActorCommand) -> ActorCommand {
    command.clone()
}

/// Apply an input command through the movement lane (donor
/// `player.withInputCommand`).
///
/// Missing siblings: the movement lane owns input scoping/slicing; the
/// execute callback fires directly until it lands.
#[allow(dead_code)]
fn with_input_command_seam(
    execute: &mut dyn FnMut(qa_net::common::commands::UserCommand, Option<ArsenalIntent>) -> Result<(), RuntimeError>,
    frame: &FrameContext,
    effective: qa_net::common::commands::UserCommand,
    arsenal: Option<ArsenalIntent>,
) -> Result<(), RuntimeError> {
    let _ = frame;
    execute(effective, arsenal)
}

/// Outcome of a movement-lane move (donor `moved`; only the
/// Q2-rerelease-active check survives the seam).
#[allow(dead_code)]
struct StepMoveOutcome {
    /// Moved stayed active on a Q2-rerelease state.
    q2_rerelease_active: bool,
}

/// Move through an applied mod-client command (donor `player.moveCommand`).
///
/// Missing siblings: the movement lane owns the move; no state advances
/// until it lands.
#[allow(dead_code)]
fn move_command_seam(
    player: &mut MovementPlayer,
    relative: &ActorCommand,
    frame: &FrameContext,
) -> Result<StepMoveOutcome, RuntimeError> {
    let _ = (player, relative, frame);
    Ok(StepMoveOutcome {
        q2_rerelease_active: false,
    })
}

/// Move through a raw command (donor `player.move`).
