impl SharedSimulation {
    /// Write a mutated movement player back to the table.
    #[allow(dead_code)]
    fn step_writeback_player(&self, owned: &OwnedActor, pstate: &MovementPlayer) {
        if let Some(entry) = self.lock().player_states.get_mut(owned) {
            *entry = pstate.clone();
        }
    }

    /// Client-command loop (donor 4494-4590).
    fn step_tail_commands(
        &self,
        input: &InputBatch,
        ctx: &StepTailContext,
        bot_commands: &[ActorCommand],
        pending_net_quake: &Option<HashMap<ActorId, ActorCommand>>,
        pending_q1_pre_think: &mut Option<HashMap<OwnedActor, u64>>,
    ) -> Result<(), RuntimeError> {
        use qa_core::time::FramePhase;
        let applications_active = self.peek().mod_client_applications.active;
        let mut commands: Vec<ActorCommand> = Vec::new();
        if ctx.command_turn {
            commands.extend(input.commands.iter().cloned());
        }
        commands.extend(bot_commands.iter().cloned());
        for received in commands {
            // Donor 4510: paused attack mask.
            let mut command = if ctx.paused {
                let masked = (step_button_bits(received.command.buttons()) & !1) as f64;
                let mut masked_command = received.clone();
                masked_command.command = masked_command.command.with_buttons(masked);
                masked_command
            } else {
                received
            };
            // Donor 4511-4516.
            let owned = match self.player(&command.actor) {
                Some(player) => player.actor.clone(),
                None => {
                    if pending_net_quake
                        .as_ref()
                        .is_some_and(|map| map.contains_key(&command.actor))
                    {
                        continue;
                    }
                    return fail("Command targets an unadmitted player");
                }
            };
            {
                let state = self.peek();
                let last = state.player_states.get(&owned).map(|player| player.last_sequence);
                if last.is_none_or(|last| step_command_stale(command.sequence, last)) {
                    continue;
                }
            }
            self.observe_client_command(&command)?;
            // Donor 4586-4590: relativize + dispatch through the input wrapper.
            if applications_active {
                command = relative_movement_command_seam(&command);
            }
            let frame = {
                let state = self.peek();
                FrameContext {
                    phase: FramePhase::ClientCommand,
                    elapsed: SourceTime::Milliseconds(input.elapsed_milliseconds as i32),
                    ..state.source_frame
                }
            };
            let (effective, arsenal) = (command.command.clone(), command.arsenal.clone());
            let mut execute = |effective: qa_net::common::commands::UserCommand,
                               arsenal: Option<ArsenalIntent>|
             -> Result<(), RuntimeError> {
                self.step_tail_execute_command(
                    input.elapsed_milliseconds,
                    ctx.paused,
                    applications_active,
                    &owned,
                    &mut command,
                    effective,
                    arsenal,
                    &mut *pending_q1_pre_think,
                )
            };
            if applications_active {
                with_input_command_seam(&mut execute, &frame, effective, arsenal)?;
            } else {
                execute(effective, arsenal)?;
            }
        }
        Ok(())
    }
}

impl SharedSimulation {
    /// Execute one effective client command (donor `execute`, 4517-4584).
    #[allow(clippy::too_many_arguments)]
    #[allow(dead_code)]
    fn step_tail_execute_command(
        &self,
        input_elapsed_ms: f64,
        paused: bool,
        applications_active: bool,
        owned: &OwnedActor,
        command: &mut ActorCommand,
        effective: qa_net::common::commands::UserCommand,
        arsenal: Option<ArsenalIntent>,
        pending_q1_pre_think: &mut Option<HashMap<OwnedActor, u64>>,
    ) -> Result<(), RuntimeError> {
        use qa_core::time::FramePhase;
        use qa_net::common::commands::MovementDialect;
        // Donor 4517: rebind the effective command (arsenal only when defined).
        command.command = effective;
        if arsenal.is_some() {
            command.arsenal = arsenal;
        }
        // Donor 4518-4527: pending Q1 pre-think.
        let pre_think_due = pending_q1_pre_think
            .as_ref()
            .is_some_and(|map| map.get(owned) == Some(&command.sequence));
        if self.peek().source.kind() == "q1" && pre_think_due {
            if let Some(map) = pending_q1_pre_think.as_mut() {
                map.remove(owned);
            }
            let effective = command.command.clone();
            let jump = match effective.dialect() {
                MovementDialect::Q1Netquake | MovementDialect::Q1Quakeworld => {
                    step_button_bits(effective.buttons()) & 2 != 0
                }
                MovementDialect::Q2Rerelease => step_button_bits(effective.buttons()) & 8 != 0,
                _ => effective.up_move().unwrap_or(0.0) > 0.0,
            };
            // The net arsenal twin carries no impulse, so the arsenal leg of
            // the donor impulse can never fire; the effective command rules.
            let impulse = effective.impulse().unwrap_or(0.0) as i32;
            {
                let state = self.peek();
                let water_level = state.player_states.get(owned).map(|player| player.water_level as i32);
                if let SourceRuntime::Q1 {
                    services, composition, ..
                } = &state.source
                {
                    composition
                        .input(
                            &mut services.borrow_mut(),
                            owned.id(),
                            &qa_content::q1::composition::types::Q1SourceInput {
                                attack: step_button_bits(effective.buttons()) & 1 != 0,
                                jump,
                                use_action: step_button_bits(effective.buttons()) & 4 != 0,
                                impulse,
                            },
                        )
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                    composition
                        .player_pre_think(&mut services.borrow_mut(), owned.id())
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                    services
                        .borrow_mut()
                        .player_frame(owned, self.time_seconds(), water_level)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
            if !self.actors.borrow().is_live(owned.id()) {
                return Ok(());
            }
        }
        // Donor 4528: arsenal intent.
        let prepared = {
            let state = self.peek();
            match state.player_states.get(owned) {
                Some(player) => prepare_arsenal_command_seam(player, command, paused),
                None => return Ok(()),
            }
        };
        *command = prepared;
        let mut pstate = match self.peek().player_states.get(owned).cloned() {
            Some(player) => player,
            None => return Ok(()),
        };
        // Donor 4529-4532: LMCTF pin.
        if paused && q2_lmctf_can_move_seam(owned.id()) == Some(false) {
            pstate.last_sequence = command.sequence as i32;
            self.step_writeback_player(owned, &pstate);
            return Ok(());
        }
        // Donor 4533-4536: cutscene button tracking.
        if pstate.cutscene.is_some() {
            pstate.previous_buttons = pstate.buttons;
            pstate.buttons = command.command.buttons();
            pstate.last_sequence = command.sequence as i32;
            self.step_writeback_player(owned, &pstate);
            return Ok(());
        }
        // Donor 4537-4540: Q1 intermission button tracking.
        let q1_intermission = {
            let state = self.peek();
            match &state.source {
                SourceRuntime::Q1 { services, .. } => services.borrow().intermission.is_some(),
                _ => false,
            }
        };
        if self.peek().source.kind() == "q1" && q1_intermission {
            pstate.previous_buttons = pstate.buttons;
            pstate.buttons = command.command.buttons();
            pstate.last_sequence = command.sequence as i32;
            self.step_writeback_player(owned, &pstate);
            let state = self.peek();
            if let SourceRuntime::Q1 {
                services, composition, ..
            } = &state.source
            {
                composition
                    .request_intermission_exit(
                        &mut services.borrow_mut(),
                        pstate.buttons != 0.0,
                        Some((owned.id(), step_button_bits(pstate.buttons) & 1 != 0)),
                    )
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            }
            return Ok(());
        }
        // Donor 4545-4548: grapple jump latch.
        {
            let state = self.peek();
            if let Some(grapple) = state.grapple.as_ref() {
                let held = match command.command.dialect() {
                    MovementDialect::Q1Netquake | MovementDialect::Q1Quakeworld => {
                        step_button_bits(command.command.buttons()) & 2 != 0
                    }
                    MovementDialect::Q2Rerelease => step_button_bits(command.command.buttons()) & 8 != 0,
                    _ => command.command.up_move().unwrap_or(0.0) > 0.0,
                };
                grapple.set_jump(owned.id(), held);
            }
        }
        // Donor 4549-4563: Q3 think or gravity-scaled move.
        if self.peek().source.kind() == "q3" {
            {
                let mut state = self.lock();
                state.q3_commands.insert(owned.clone(), command.clone());
            }
            q3_player_think_seam(command);
            {
                let mut state = self.lock();
                state.q3_commands.remove(owned);
            }
            sync_q3_player_seam(&pstate);
        } else {
            let source_is_q2 = self.peek().source.kind() == "q2";
            let match_gravity = if source_is_q2 {
                q2_match_gravity_scale_seam(owned.id())
            } else {
                1.0
            };
            let (grapple_scale, grapple_present, physics_gravity) = {
                let state = self.peek();
                (
                    state
                        .grapple
                        .as_ref()
                        .map(|grapple| grapple.gravity_scale(owned.id()))
                        .unwrap_or(1),
                    state.grapple.is_some(),
                    state.physics.gravity(),
                )
            };
            let saved_multiplier = pstate.gravity_multiplier;
            pstate.gravity_multiplier *= match_gravity * f64::from(grapple_scale);
            if (source_is_q2 || grapple_present)
                && matches!(step_state_kind(&pstate.state), "q2-classic" | "q2-rerelease" | "q3")
            {
                let gravity = (physics_gravity * pstate.gravity_multiplier).trunc();
                match &mut pstate.state {
                    MovementState::Q2Classic(inner) => inner.gravity = gravity,
                    MovementState::Q2Rerelease(inner) => inner.gravity = gravity,
                    MovementState::Q3(inner) => inner.gravity = gravity,
                    _ => {}
                }
            }
            let relative = relative_movement_command_seam(command);
            let movement_frame = {
                let state = self.peek();
                let elapsed_ms = if step_profile_kind(&pstate.profile) == "q1-netquake" {
                    input_elapsed_ms.clamp(1.0, 100.0)
                } else {
                    input_elapsed_ms
                };
                FrameContext {
                    phase: FramePhase::ClientCommand,
                    elapsed: SourceTime::Milliseconds(elapsed_ms as i32),
                    ..state.source_frame
                }
            };
            let moved = if applications_active {
                move_command_seam(&mut pstate, &relative, &movement_frame)?
            } else {
                move_seam(&mut pstate, &relative, &movement_frame)?
            };
            if source_is_q2 && moved.q2_rerelease_active {
                q2_movement_impact_seam(owned.id());
            }
            pstate.gravity_multiplier = saved_multiplier;
        }
        // Donor 4564-4565: liveness + NetQuake punch sync.
        if !self.actors.borrow().is_live(owned.id()) {
            self.step_writeback_player(owned, &pstate);
            return Ok(());
        }
        if step_state_kind(&pstate.state) == "q1-netquake" {
            let punch = {
                let mut state = self.lock();
                state
                    .q1_punch
                    .read(owned.id())
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?
            };
            if let MovementState::Q1Netquake(inner) = &mut pstate.state {
                inner.punch_angles = punch;
            }
        }
        // Donor 4566-4574: selected-arsenal weapon step for Q2 profiles.
        let selected_present = self.peek().selected_arsenal.is_some();
        if !paused
            && selected_present
            && matches!(step_profile_kind(&pstate.profile), "q2-classic" | "q2-rerelease")
            && self.actors.borrow().is_live(owned.id())
        {
            let combat = self.peek().combat.read(owned.id());
            let Some(combat) = combat else {
                return fail("Selected arsenal owner has no combat state");
            };
            let milliseconds = command
                .command
                .milliseconds()
                .unwrap_or_else(|| input_elapsed_ms.clamp(1.0, 100.0));
            let frame = {
                let state = self.peek();
                FrameContext {
                    phase: FramePhase::ClientCommand,
                    elapsed: SourceTime::Milliseconds(milliseconds as i32),
                    ..state.source_frame
                }
            };
            let environment = player_movement_environment(&pstate, &combat, pstate.movement_speed_multiplier);
            let input = StepWeaponInput {
                actor: owned,
                command: &command.command,
                frame,
                arsenal: arsenal_seam(&pstate),
                animation: pstate.animation.clone(),
                environment,
                gauntlet_hit: false,
            };
            let (arsenal, animation) = weapon_step_seam(&pstate, &input);
            pstate.arsenal = arsenal;
            pstate.animation = animation;
        }
        // Donor 4575: Q1 post-physics.
        if self.peek().source.kind() == "q1" && self.actors.borrow().is_live(owned.id()) {
            let time_seconds = self.time_seconds();
            let state = self.peek();
            if let SourceRuntime::Q1 {
                services, composition, ..
            } = &state.source
            {
                services
                    .borrow_mut()
                    .player_after_physics(owned, time_seconds)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                composition
                    .player_post_think(&mut services.borrow_mut(), owned.id())
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            }
        }
        // Donor 4576-4580: Q2 post-client-think view height.
        if !paused && self.peek().source.kind() == "q2" && self.actors.borrow().is_live(owned.id()) {
            let gibbed = q2_player_gibbed_seam(owned.id());
            let health = self
                .peek()
                .combat
                .read(owned.id())
                .map(|state| state.health)
                .unwrap_or(0.0);
            let state = self.peek();
            if let SourceRuntime::Q2 { game, .. } = &state.source {
                let mut borrowed = game.borrow_mut();
                if let Some(entity) = borrowed.entity_mut(owned.id()) {
                    if !pstate.intermission {
                        entity.view_height = if pstate.character == GameFamily::Q2 && health <= 0.0 {
                            if gibbed {
                                8
                            } else {
                                -2
                            }
                        } else {
                            pstate.view_height as i32
                        };
                    }
                    q2_after_client_think_seam(owned.id());
                }
            }
        }
        // Donor 4581-4582: character post-move hooks.
        if self.peek().q2_characters.contains_key(owned) {
            q2_character_after_client_think_seam(owned.id());
        }
        self.step_tail_q1_character_post_move(owned)?;
        // Donor 4583.
        if !paused {
            self.lock().physics.commit_attachments();
        }
        self.step_writeback_player(owned, &pstate);
        Ok(())
    }
}

impl SharedSimulation {
    /// Run Q1 character post-move (donor `q1Characters.get(actor)?.postMove()`).
    ///
    /// The character's game is the Q1 source game when the source is Q1,
    /// else the selected Q1 arsenal game; with neither, the lane's game
    /// registry owns the call and it is skipped.
    #[allow(dead_code)]
    fn step_tail_q1_character_post_move(&self, owned: &OwnedActor) -> Result<(), RuntimeError> {
        if !self.peek().q1_characters.contains_key(owned) {
            return Ok(());
        }
        if self.peek().source.kind() == "q1" {
            let services = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q1 { services, .. } => Some(services.clone()),
                    _ => None,
                }
            };
            if let Some(services) = services {
                let mut game = services.borrow_mut();
                let mut locked = self.lock();
                if let Some(character) = locked.q1_characters.get_mut(owned) {
                    character
                        .post_move(&mut game)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
            return Ok(());
        }
        let selected_game = {
            let state = self.peek();
            match &state.selected_arsenal {
                Some(SelectedArsenal::Q1(q1)) => Some(q1.game()),
                _ => None,
            }
        };
        if let Some(game) = selected_game {
            let mut borrowed = game.borrow_mut();
            let mut locked = self.lock();
            if let Some(character) = locked.q1_characters.get_mut(owned) {
                character
                    .post_move(&mut borrowed)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            }
        }
        Ok(())
    }
}
// ---------------------------------------------------------------------------
// C3 §3a-iii: Q2 actor-host factory (donor `q2ActorHost`, runtime.ts
// 2061-2079).
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Build a Q2 actor host over the shared session (donor `q2ActorHost`,
    /// runtime.ts 2061-2079).
    ///
    /// The donor passes a runtime bundle (`numeric`, shared `random`,
    /// `now`/`frameSeconds`/`schedule` closures); the shared pieces
    /// resolve through the weak handle inside the bindings, so only the
    /// per-source pieces (`numeric`, `frame_seconds`) are parameters.
    /// `readMonster` has no Rust home on identity-only execution
    /// entries, so it is dropped (both C3 call sites pass a loader that
    /// resolves to no monster state).
    pub fn q2_actor_host(
        &self,
        source: &ProviderReference,
        numeric: qa_core::numeric::NumericProfile,
        frame_seconds: f64,
        authority: super::source_transition::SourceLevelAuthority,
        player_identity: Option<super::types::PlayerIdentityLookup>,
    ) -> Box<dyn qa_content::q2::foundation::host::Q2FoundationHost> {
        use super::source_hosts::{create_q2_actor_host, ActorHostWorld};
        let tables = C11Tables {
            actors: self.actors_handle(),
            bodies: self.bodies_handle(),
            weak: self.weak(),
        };
        let bindings = Q2SeamBindings::new(
            self.weak(),
            self.actors_handle(),
            self.bodies_handle(),
            source.content.clone(),
            frame_seconds,
            authority,
            player_identity,
        );
        let world_tables = tables.clone();
        let order_tables = tables.clone();
        let world = ActorHostWorld {
            scene: Rc::new(SharedSceneAdapter {
                scene: self.scene(),
                bodies: self.bodies_handle(),
                actors: self.actors_handle(),
                simulation: self.weak(),
            }),
            numeric,
            world_actor: Rc::new(move || world_tables.sim().world_actor()),
            source_order: Rc::new(move |a, b| match order_tables.sim().source_order(a, b) {
                std::cmp::Ordering::Less => -1,
                std::cmp::Ordering::Equal => 0,
                std::cmp::Ordering::Greater => 1,
            }),
        };
        let _ = tables;
        Box::new(create_q2_actor_host(bindings, world))
    }
}

/// [`SharedWorldHost`](qa_world::save::world_state::SharedWorldHost) over the live tables (C10).
#[allow(dead_code)]
struct C10SharedWorldHost {
    actors: Rc<RefCell<SessionActorRegistry>>,
    bodies: Rc<RefCell<qa_world::body::BodyTable>>,
    state: Rc<RefCell<SharedSimulationState>>,
    map_provider: ProviderId,
    module_id: Option<ProviderId>,
    copied_combat: HashSet<(u32, u32)>,
    combat_error: Option<RuntimeError>,
    /// Donor body-links storage selects reconstructed-or-copied only (no
    /// prebound arm); set for the `restoreSharedBodyLinks` host.
    body_links_only: bool,
}

impl C10SharedWorldHost {
    #[allow(dead_code)]
    fn resolve(&self, saved: qa_core::identity::SavedActorId) -> Option<OwnedActor> {
        self.actors.borrow().resolve_saved(saved)
    }

    #[allow(dead_code)]
    fn world_failure(error: impl ToString) -> qa_world::WorldError {
        qa_world::WorldError::BadSave(error.to_string())
    }
}

impl qa_world::save::world_state::SharedWorldHost for C10SharedWorldHost {
    fn is_active(&self, saved: qa_core::identity::SavedActorId) -> bool {
        self.resolve(saved).is_some()
    }

    fn owner(&self, saved: qa_core::identity::SavedActorId) -> Option<String> {
        self.resolve(saved).map(|owned| provider_text(owned.owner()))
    }

    fn storage(&self, saved: qa_core::identity::SavedActorId) -> qa_world::save::world_state::StorageKind {
        use qa_world::save::world_state::StorageKind;
        let provider = self
            .resolve(saved)
            .and_then(|owned| self.actors.borrow().source_of(owned.id()).map(|(provider, _)| provider));
        if self
            .module_id
            .as_ref()
            .is_some_and(|module| Some(module) == provider.as_ref())
        {
            return StorageKind::SourceReconstructed;
        }
        if !self.body_links_only
            && matches!(
                self.state.borrow().source,
                SourceRuntime::QuakeC { .. } | SourceRuntime::Q3Qvm { .. }
            )
            && provider.as_ref() == Some(&self.map_provider)
        {
            return StorageKind::Prebound;
        }
        StorageKind::Copied
    }

    fn body(&self, saved: qa_core::identity::SavedActorId) -> Option<qa_world::session::SavedBodyState> {
        let owned = self.resolve(saved)?;
        let actors = self.actors.borrow();
        let bodies = self.bodies.borrow();
        bodies
            .read(actors.inner(), owned.id())
            .map(|body| qa_world::session::SavedBodyState {
                origin: body.origin,
                angles: body.angles,
                velocity: body.velocity,
                bounds: body.bounds,
                ground: body.ground.as_ref().map(qa_core::identity::SavedActorId::from),
            })
    }

    fn create_body(
        &mut self,
        saved: qa_core::identity::SavedActorId,
        state: qa_world::session::SavedBodyState,
    ) -> Result<(), qa_world::WorldError> {
        let Some(owned) = self.resolve(saved) else {
            return Err(Self::world_failure("Missing restored actor"));
        };
        let ground = state
            .ground
            .map(|ground| reference_saved_actor(&self.actors.borrow(), ground))
            .transpose()
            .map_err(Self::world_failure)?;
        let actors = self.actors.borrow();
        let mut bodies = self.bodies.borrow_mut();
        bodies.create(
            actors.inner(),
            &owned,
            qa_world::body::BodyState {
                origin: state.origin,
                angles: state.angles,
                velocity: state.velocity,
                bounds: state.bounds,
                ground,
            },
        )
    }

    fn attach(
        &mut self,
        saved: qa_core::identity::SavedActorId,
        attachment: &qa_world::save::records::SavedBodyAttachment,
    ) -> Result<(), qa_world::WorldError> {
        let Some(owned) = self.resolve(saved) else {
            return Err(Self::world_failure("Missing restored actor"));
        };
        let anchor = reference_saved_actor(&self.actors.borrow(), attachment.anchor).map_err(Self::world_failure)?;
        let actors = self.actors.borrow();
        let mut bodies = self.bodies.borrow_mut();
        bodies.attach(
            actors.inner(),
            &owned,
            qa_world::body::BodyAttachment {
                anchor,
                follow: attachment.follow,
            },
        )
    }

    fn restore_link(
        &mut self,
        saved: qa_core::identity::SavedActorId,
        link_count: u64,
        linked: Option<(qa_world::session::SavedBodyState, Bounds)>,
    ) -> Result<(), qa_world::WorldError> {
        let Some(owned) = self.resolve(saved) else {
            return Err(Self::world_failure("Missing restored actor"));
        };
        let linked = linked
            .map(|(body, bounds)| {
                let ground = body
                    .ground
                    .map(|ground| reference_saved_actor(&self.actors.borrow(), ground))
                    .transpose()
                    .map_err(Self::world_failure)?;
                Ok::<_, qa_world::WorldError>((
                    qa_world::body::BodyState {
                        origin: body.origin,
                        angles: body.angles,
                        velocity: body.velocity,
                        bounds: body.bounds,
                        ground,
                    },
                    bounds,
                ))
            })
            .transpose()?;
        let actors = self.actors.borrow();
        let mut bodies = self.bodies.borrow_mut();
        bodies.restore_link_state(actors.inner(), &owned, link_count, linked)
    }

    fn combat(&self, saved: qa_core::identity::SavedActorId) -> Option<qa_world::combat::CombatState> {
        let owned = self.resolve(saved)?;
        self.state.borrow().combat.read(owned.id())
    }

    fn create_combat(&mut self, saved: qa_core::identity::SavedActorId, state: qa_world::combat::CombatState) {
        let Some(owned) = self.resolve(saved) else {
            self.combat_error = Some(RuntimeError::Failure("Missing restored actor".to_string()));
            return;
        };
        match self.state.borrow_mut().combat.create(&owned, state) {
            Ok(()) => {
                self.copied_combat.insert((saved.slot, saved.generation));
            }
            Err(error) => {
                self.combat_error = Some(error);
            }
        }
    }

    fn set_powered(&mut self, saved: qa_core::identity::SavedActorId, powered: qa_world::combat::PoweredProtection) {
        let Some(owned) = self.resolve(saved) else {
            return;
        };
        if let Some(mut combat) = self.state.borrow().combat.read(owned.id()) {
            combat.armor.powered = powered;
            self.state.borrow_mut().combat.write(owned.id(), combat);
        }
    }

    fn normalize_legacy_armor(
        &self,
        saved: qa_core::identity::SavedActorId,
        armor: &qa_world::combat::ArmorState,
    ) -> qa_world::combat::ArmorState {
        let state = self.state.borrow();
        let bindings = match state.source {
            SourceRuntime::Q3Qvm {
                combat: Some(ref combat),
                ..
            } => combat,
            _ => return armor.clone(),
        };
        let _ = &state;
        let owned = self.resolve(saved);
        let source_owned = owned.as_ref().is_some_and(|owned| {
            self.actors
                .borrow()
                .source_of(owned.id())
                .is_some_and(|(provider, _)| provider == self.map_provider)
        });
        if !source_owned {
            return armor.clone();
        }
        let Some(owned) = owned else {
            return armor.clone();
        };
        bindings
            .normalize_legacy_armor(owned.id(), armor)
            .unwrap_or_else(|_| armor.clone())
    }

    fn copied_primary_armor(&self, saved: qa_core::identity::SavedActorId) -> Option<qa_world::combat::ArmorState> {
        if !self.copied_combat.contains(&(saved.slot, saved.generation)) {
            return None;
        }
        self.combat(saved).map(|state| state.armor)
    }

    fn protection_owned(
        &self,
        _actor: qa_core::identity::SavedActorId,
        _channel: qa_world::save::world_state::ProtectionChannel,
    ) -> bool {
        false
    }

    fn protection_items(
        &self,
        _actor: qa_core::identity::SavedActorId,
        _channel: qa_world::save::world_state::ProtectionChannel,
    ) -> Vec<String> {
        Vec::new()
    }

    fn inventory_has(&self, saved: qa_core::identity::SavedActorId) -> bool {
        let Some(owned) = self.resolve(saved) else {
            return false;
        };
        let actors = self.actors.borrow();
        self.state.borrow().inventory.has(actors.inner(), owned.id())
    }

    fn inventory_entries(&self, saved: qa_core::identity::SavedActorId) -> Vec<qa_world::inventory::InventoryEntry> {
        let Some(owned) = self.resolve(saved) else {
            return Vec::new();
        };
        let actors = self.actors.borrow();
        self.state
            .borrow()
            .inventory
            .inner()
            .entries(actors.inner(), owned.id())
    }

    fn create_inventory(
        &mut self,
        saved: qa_core::identity::SavedActorId,
        entries: Vec<qa_world::inventory::InventoryEntry>,
    ) {
        let Some(owned) = self.resolve(saved) else {
            return;
        };
        let actors = self.actors.borrow();
        let _ = self
            .state
            .borrow_mut()
            .inventory
            .inner_mut()
            .create(actors.inner(), &owned, &entries);
    }
}

impl SharedSimulation {
    /// Donor `restoreInventoryCoverage` closure (C10).
    #[allow(dead_code)]
    fn restore_inventory_coverage(
        &self,
        inventories: &mut Vec<super::save::SimSavedInventory>,
        actors: &[OwnedActor],
        legacy: bool,
        save_actors: &[qa_world::registry::ActorSlotCheckpoint],
    ) -> Result<(), RuntimeError> {
        for actor in actors {
            let index = inventories
                .iter()
                .position(|entry| self.actors.borrow().resolve_saved(entry.actor) == Some(actor.clone()));
            let entries = self
                .state
                .borrow()
                .inventory
                .inner()
                .entries(self.actors.borrow().inner(), actor.id());
            if !legacy {
                let matches = match index {
                    Some(index) => inventories[index].entries == entries,
                    None => false,
                };
                if !matches {
                    return fail("Saved native inventory disagrees with restored source storage");
                }
                continue;
            }
            let mismatch = match index {
                Some(index) => inventories[index]
                    .entries
                    .iter()
                    .any(|entry| entries.iter().find(|current| current.item == entry.item) != Some(entry)),
                None => false,
            };
            if mismatch {
                return fail("Legacy source inventory disagrees with restored source storage");
            }
            let saved_actor = index.map(|index| inventories[index].actor).or_else(|| {
                save_actors
                    .iter()
                    .find(|entry| {
                        self.actors.borrow().resolve_saved(qa_core::identity::SavedActorId {
                            slot: entry.slot,
                            generation: entry.generation,
                        }) == Some(actor.clone())
                    })
                    .map(|entry| qa_core::identity::SavedActorId {
                        slot: entry.slot,
                        generation: entry.generation,
                    })
            });
            let Some(saved_actor) = saved_actor else {
                return fail("Restored source inventory has no saved actor identity");
            };
            let migrated = super::save::SimSavedInventory {
                actor: saved_actor,
                entries,
            };
            match index {
                Some(index) => inventories[index] = migrated,
                None => inventories.push(migrated),
            }
        }
        Ok(())
    }
}

