/// Snapshot of source ordering for actor turns (donor `sourcePosition`
/// recipe inputs, precomputed so the turn closure borrows no state).
#[allow(dead_code)]
struct StepOrderSnapshot {
    /// Mixed-order provider keys, when the recipe mixes providers.
    mixed: Option<Vec<String>>,
    /// Map provider key.
    map_provider: String,
}

/// Actor-turn position from the registry plus a precomputed snapshot
/// (donor `sourcePosition`, closure-friendly shape).
#[allow(dead_code)]
fn step_order_position(
    registry: &qa_world::registry::ActorRegistry,
    snapshot: &StepOrderSnapshot,
    actor: &ActorId,
) -> (i64, i64) {
    let source = registry.source_of(actor);
    let provider = source
        .as_ref()
        .map(|(provider, _)| qa_world::registry::provider_key(provider))
        .or_else(|| {
            registry
                .observe(actor)
                .map(|observed| qa_world::registry::provider_key(&observed.owner))
        })
        .unwrap_or_else(|| "world:unknown".to_string());
    let slot = source
        .map(|(_, slot)| i64::from(slot))
        .unwrap_or_else(|| i64::from(actor.slot()));
    match &snapshot.mixed {
        Some(providers) => {
            let index = providers
                .iter()
                .position(|candidate| candidate == &provider)
                .map(|index| index as i64)
                .unwrap_or(-1);
            (index, slot)
        }
        None => {
            if provider != snapshot.map_provider {
                (1, i64::from(actor.slot()))
            } else {
                (0, slot)
            }
        }
    }
}

