/// Resolve the execution frame for a non-player entry (donor 4673-4675
/// frame chain).
///
/// Entry-to-game identity is owner/proxy-based until the actor lane (C4)
/// lands execution-identity matching: the monster leg reads the owner's
/// monster clock, the selected-Q1 leg fires on kind mismatch, and the
/// grapple/equipment legs match the owner's provider against the
/// selection providers.
#[allow(dead_code)]
fn step_execution_frame(
    state: &SharedSimulationState,
    entry: &RuntimeExecutionEntry,
    actor: &OwnedActor,
) -> Result<FrameContext, RuntimeError> {
    if let Some(monster) = state.monster_sources.get(actor.owner()) {
        return Ok(monster.clock().frame);
    }
    if matches!(state.selected_arsenal, Some(SelectedArsenal::Q1(_)))
        && matches!(entry, RuntimeExecutionEntry::Q1 { .. })
        && state.source.kind() != "q1"
    {
        return selected_q1_frame(state);
    }
    if let Some(grapple) = state.grapple.as_ref() {
        if let qa_content::contract::GrappleSelection::Enabled { source, .. } = grapple.selection() {
            if source.provider == *actor.owner() {
                return Ok(state.grapple_frame);
            }
        }
    }
    if let Some(hand) = state.hand_grenades.as_ref() {
        if let qa_content::contract::HandGrenadeSelection::Enabled { source, .. } = hand.selection() {
            if source.provider == *actor.owner() {
                return Ok(state.equipment_frame);
            }
        }
    }
    Ok(state.source_frame)
}

/// Run one actor think (donor `scheduler.run`, donor runtime.ts 4689).
///
/// Merges due times ([`qa_world::scheduler::Scheduler::run`] at the
/// donor's `during-physics` boundary) with think bindings
/// ([`ActorCallbackTable::fire_think`]): the resolver answers the donor's
/// `"world:think"` callback (donor runtime.ts 679) with the pending
/// actor's bound think closure, and unknown callbacks propagate exactly
/// as the donor's `Unknown think callback` throw. Holds the state guard
/// across the run so the scheduler borrow stays live; think closures
/// re-enter through the callback and registry handles, matching the
/// `C11Scheduler` equipment runner.
fn run_actor_think_seam(sim: &SharedSimulation, actor: &OwnedActor, frame: &FrameContext) -> Result<(), RuntimeError> {
    let callbacks = sim.peek().callbacks.clone();
    let actors = Rc::clone(&sim.actors);
    let callback: qa_world::scheduler::ThinkCallback = Rc::new(move |owned, invoked, _| {
        let table = callbacks.borrow();
        let registry = actors.borrow();
        let _ = table.fire_think(&registry, owned, invoked);
    });
    let resolver = |_execution: &ProviderId, name: &str| {
        if name == "world:think" {
            Some(callback.clone())
        } else {
            None
        }
    };
    let registry = sim.actors.borrow();
    let state = sim.peek();
    state
        .scheduler
        .inner()
        .run(
            registry.inner(),
            &resolver,
            actor.id(),
            *frame,
            qa_world::scheduler::ThinkBoundary::DuringPhysics,
        )
        .map(|_| ())
        .map_err(RuntimeError::from)
}

impl SharedSimulation {
    /// Actor-turn loop (donor 4592-4689).
    #[allow(dead_code)]
    fn step_tail_actors(&self, ctx: &StepTailContext, prepares_q1_clients: bool) -> Result<(), RuntimeError> {
        if ctx.paused {
            return Ok(());
        }
        // Donor 4595-4596.
        if ctx.run && self.peek().source.kind() == "q2" {
            q2_source_monsters_begin_frame_seam();
        }
        if ctx.run && self.peek().source.kind() == "q3" {
            let frame = self.peek().source_frame;
            q3_source_begin_frame_seam(&frame);
        }
        // Donor 4597-4598: revision-sensitive actor turns.
        let snapshot = {
            let state = self.peek();
            let mixed = match &state.recipe.ordering {
                qa_content::contract::FrameOrdering::Mixed { providers } => {
                    Some(providers.iter().map(qa_world::registry::provider_key).collect())
                }
                _ => None,
            };
            let map_provider = provider_text(&state.recipe.map.entities.provider);
            StepOrderSnapshot { mixed, map_provider }
        };
        let mut visited: HashSet<OwnedActor> = HashSet::new();
        let actors_ref = self.actors.borrow();
        let registry = actors_ref.inner();
        for actor in ordered_actor_turns(
            &actors_ref,
            &|owned| step_order_position(registry, &snapshot, owned.id()),
            &mut visited,
        ) {
            // Donor 4599: Q3-QVM grapple providers skip their own turn.
            let grapple_skip = {
                let state = self.peek();
                match state.grapple.as_ref() {
                    Some(grapple) => match grapple.selection() {
                        qa_content::contract::GrappleSelection::Enabled {
                            source,
                            mechanic: qa_content::contract::GrappleMechanicDetail::Q3Qvm { .. },
                            ..
                        } => source.provider == *actor.owner(),
                        _ => false,
                    },
                    None => false,
                }
            };
            if grapple_skip {
                continue;
            }
            // Donor 4600: mod-owned actors run with their mods.
            if self
                .peek()
                .mod_owner
                .as_ref()
                .is_some_and(|owner| owner.owns(actor.owner()))
            {
                continue;
            }
            self.step_tail_actor(ctx, prepares_q1_clients, &actor)?;
        }
        Ok(())
    }
}

impl SharedSimulation {
    /// NetQuake client turn (donor 4602-4616).
    #[allow(dead_code)]
    fn step_tail_netquake_actor(
        &self,
        ctx: &StepTailContext,
        actor: &OwnedActor,
        player: &MovementPlayer,
    ) -> Result<(), RuntimeError> {
        use qa_core::time::FramePhase;
        // Donor 4603-4604.
        if self.peek().source.kind() == "quakec" {
            let state = self.peek();
            if let SourceRuntime::QuakeC { game } = &state.source {
                game.before_actor(actor)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            }
        } else if self.peek().source.kind() == "q1" {
            let retouch = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q1 { services, .. } => services.borrow().force_retouch,
                    _ => 0,
                }
            };
            if retouch > 0 {
                self.step_tail_link_and_touch(actor)?;
            }
        }
        // Donor 4605-4613.
        let live_run = self.actors.borrow().is_live(actor.id()) && player.cutscene.is_none() && !player.intermission;
        if live_run {
            let scale = {
                let state = self.peek();
                state
                    .grapple
                    .as_ref()
                    .map(|grapple| grapple.gravity_scale(actor.id()))
                    .unwrap_or(1)
            };
            let mut pstate = player.clone();
            pstate.gravity_multiplier *= f64::from(scale);
            let frame = {
                let state = self.peek();
                FrameContext {
                    phase: FramePhase::EntityPhysics,
                    ..state.source_frame
                }
            };
            physics_net_quake_seam(&pstate, &frame)?;
            pstate.gravity_multiplier = player.gravity_multiplier;
            if !self.actors.borrow().is_live(actor.id()) {
                // Donor `continue`: nothing after this runs, including the
                // commit, and no persistent player change exists yet.
                return Ok(());
            }
            if step_state_kind(&pstate.state) == "q1-netquake" {
                let punch = {
                    let mut state = self.lock();
                    state
                        .q1_punch
                        .read(actor.id())
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?
                };
                if let MovementState::Q1Netquake(inner) = &mut pstate.state {
                    inner.punch_angles = punch;
                }
            }
            sync_quake_c_client_view_seam(&pstate);
            self.step_writeback_player(actor, &pstate);
        } else {
            finish_net_quake_input_seam(player);
        }
        // Donor 4614.
        if ctx.boundary.q2 {
            frame_selected_q2_weapon_seam(actor);
        }
        // Donor 4615-4619.
        if self.actors.borrow().is_live(actor.id()) {
            if self.peek().q2_characters.contains_key(actor) {
                q2_character_begin_frame_seam(actor);
            }
            let health = self
                .peek()
                .combat
                .read(actor.id())
                .map(|state| state.health)
                .unwrap_or(0.0);
            let alive = health > 0.0;
            self.step_hand_grenade(actor.id(), Some(if alive { "alive" } else { "dead" }))?;
            let (intermission, cutscene) = {
                let state = self.peek();
                match state.player_states.get(actor) {
                    Some(player) => (player.intermission, player.cutscene.is_some()),
                    None => (true, true),
                }
            };
            {
                let state = self.peek();
                if let Some(grapple) = state.grapple.as_ref() {
                    grapple
                        .step(actor.id(), alive && !intermission && !cutscene)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
            if let Some(player) = self.peek().player_states.get(actor).cloned() {
                player_weapon_seam(&player);
            }
        }
        // Donor 4616 (commit; the donor `continue` is the return).
        self.lock().physics.commit_attachments();
        Ok(())
    }

    /// Relink an actor and touch its triggers (donor `bodies.link` +
    /// `physics.touchTriggers` under `forceRetouch`).
    fn step_tail_link_and_touch(&self, actor: &OwnedActor) -> Result<(), RuntimeError> {
        {
            let actors = self.actors.borrow();
            self.bodies_table
                .borrow_mut()
                .link(actors.inner(), actor, None)
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        }
        self.lock().physics.touch_triggers(actor);
        Ok(())
    }
}

impl SharedSimulation {
    /// One actor turn (donor 4601-4687).
    #[allow(dead_code)]
    fn step_tail_actor(
        &self,
        ctx: &StepTailContext,
        prepares_q1_clients: bool,
        actor: &OwnedActor,
    ) -> Result<(), RuntimeError> {
        use qa_core::time::FramePhase;
        // Donor 4601.
        let (execution, client_player) = {
            let state = self.peek();
            (
                state.actor_executions.get(actor.id()).cloned(),
                state.player_states.get(actor).cloned(),
            )
        };
        let execution_kind = execution.as_ref().map(|entry| match entry {
            RuntimeExecutionEntry::QuakeC { .. } => "quakec",
            RuntimeExecutionEntry::Q1 { .. } => "q1",
            RuntimeExecutionEntry::Q2 { .. } => "q2",
            RuntimeExecutionEntry::Q3 { .. } => "q3",
            RuntimeExecutionEntry::Q3Source { .. } => "q3-source",
        });
        // Donor 4602-4616.
        if ctx.run && prepares_q1_clients {
            if let Some(player) = client_player.as_ref() {
                if step_profile_kind(&player.profile) == "q1-netquake" {
                    self.step_tail_netquake_actor(ctx, actor, player)?;
                    return Ok(());
                }
            }
        }
        // Donor 4617-4623: QuakeC execution.
        if execution_kind == Some("quakec") {
            if !ctx.run {
                return Ok(());
            }
            {
                let state = self.peek();
                // Entries carry no source handle; the source QuakeC game
                // runs the turn, and entry-owned sources wait for C4.
                if let SourceRuntime::QuakeC { game } = &state.source {
                    game.before_actor(actor)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
            if self.actors.borrow().is_live(actor.id()) {
                if let Some(entry) = execution.as_ref() {
                    let (frame, time_seconds) = {
                        let state = self.peek();
                        (state.source_frame, self.time_seconds())
                    };
                    execute_runtime_entry_seam(entry, &frame, time_seconds, ctx.elapsed)?;
                }
            }
            run_quake_world_new_missile_seam();
            self.lock().physics.commit_attachments();
            return Ok(());
        }
        // Donor 4624-4627: Q3-source stepping.
        if execution_kind == Some("q3-source") {
            if ctx.boundary.q3 {
                if let Some(entry) = execution.as_ref() {
                    let next = self.peek().selected_q3_time;
                    step_q3_source_actor_seam(entry, ctx.previous_q3_time, next);
                }
            }
            self.lock().physics.commit_attachments();
            return Ok(());
        }
        // Donor 4628-4632: Q3 stepping.
        if execution_kind == Some("q3") {
            if !ctx.command_turn {
                return Ok(());
            }
            if let Some(entry) = execution.as_ref() {
                let next = self.peek().selected_milliseconds;
                step_q3_actor_seam(entry, ctx.previous_selected_milliseconds, next);
            }
            self.lock().physics.commit_attachments();
            return Ok(());
        }
        // Donor 4633-4642: selected-Q2 actor.
        let selected_q2 = {
            let state = self.peek();
            match &state.selected_weapon_source {
                Some(SelectedWeaponSource::Q2 {
                    frame,
                    interval_milliseconds,
                    ..
                }) => Some((*frame, *interval_milliseconds)),
                _ => None,
            }
        };
        let selected_actor = selected_q2.is_some()
            && execution_kind == Some("q2")
            && *actor.owner() == self.peek().weapon_provider.provider;
        if selected_actor {
            if ctx.boundary.q2 {
                if let (Some(entry), Some((frame, interval))) = (execution.as_ref(), selected_q2) {
                    execute_runtime_entry_seam(entry, &frame, seconds(frame.time), interval / 1000.0)?;
                    self.lock().physics.commit_attachments();
                }
            }
            return Ok(());
        }
        // Donor 4643.
        if ctx.boundary.q2 {
            frame_selected_q2_weapon_seam(actor);
        }
        // Donor 4644-4658: Q2 monster source.
        let monster_is_q2 = execution_kind == Some("q2")
            && matches!(
                self.peek().monster_sources.get(actor.owner()),
                Some(monster) if matches!(monster, super::monster_runtime::SelectedMonsterSource::Q2 { .. })
            );
        if execution_kind == Some("q2") && monster_is_q2 {
            let active = if ctx.run {
                selected_monsters_before_turn_seam(actor.id())
            } else {
                selected_monsters_active_seam(actor.id())
            };
            if ctx.run && active && self.peek().source.kind() == "q1" {
                let retouch = {
                    let state = self.peek();
                    match &state.source {
                        SourceRuntime::Q1 { services, .. } => services.borrow().force_retouch,
                        _ => 0,
                    }
                };
                if retouch > 0 {
                    self.step_tail_link_and_touch(actor)?;
                }
            }
            let clock = self.peek().monster_sources.get(actor.owner()).and_then(|monster| {
                if matches!(monster, super::monster_runtime::SelectedMonsterSource::Q2 { .. }) {
                    Some(monster.clock().clone())
                } else {
                    None
                }
            });
            if let Some(clock) = clock {
                if ctx.map_run && active && clock.advanced && self.actors.borrow().is_live(actor.id()) {
                    if let Some(entry) = execution.as_ref() {
                        execute_runtime_entry_seam(
                            entry,
                            &clock.frame,
                            seconds(clock.frame.time),
                            seconds(clock.frame.elapsed),
                        )?;
                        self.lock().physics.commit_attachments();
                    }
                }
            }
            return Ok(());
        }
        // Donor 4659: run/monster gate.
        if !ctx.run || !selected_monsters_before_turn_seam(actor.id()) {
            return Ok(());
        }
        // Donor 4660-4666: equipment + grapple for players.
        let equipment_player = self.peek().player_states.get(actor).cloned();
        if let Some(player) = equipment_player.as_ref() {
            self.step_hand_grenade(actor.id(), None)?;
            let health = self
                .peek()
                .combat
                .read(actor.id())
                .map(|state| state.health)
                .unwrap_or(0.0);
            let spectator_q3 =
                matches!(&player.state, MovementState::Q3(inner) if inner.movement_type == Q3_PM_SPECTATOR);
            let spectator_q2 = self.peek().source.kind() == "q2" && q2_player_spectator_seam(actor.id());
            {
                let state = self.peek();
                if let Some(grapple) = state.grapple.as_ref() {
                    grapple
                        .step(
                            actor.id(),
                            health > 0.0
                                && !player.intermission
                                && player.cutscene.is_none()
                                && !spectator_q3
                                && !spectator_q2,
                        )
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
        }
        // Donor 4667.
        if !self.actors.borrow().is_live(actor.id()) {
            return Ok(());
        }
        // Donor 4668-4671: Q1 retouch.
        if self.peek().source.kind() == "q1" {
            let retouch = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q1 { services, .. } => services.borrow().force_retouch,
                    _ => 0,
                }
            };
            if retouch > 0 {
                self.step_tail_link_and_touch(actor)?;
                if !self.actors.borrow().is_live(actor.id()) {
                    return Ok(());
                }
            }
        }
        // Donor 4672-4680: non-player execution.
        if execution.is_some() && !self.peek().player_states.contains_key(actor) {
            if let Some(entry) = execution.as_ref() {
                let frame = {
                    let state = self.peek();
                    step_execution_frame(&state, entry, actor)?
                };
                execute_runtime_entry_seam(entry, &frame, seconds(frame.time), ctx.elapsed)?;
                self.lock().physics.commit_attachments();
            }
            return Ok(());
        }
        // Donor 4681: Q3 source run + sync.
        if self.peek().source.kind() == "q3" {
            q3_run_actor_seam(actor);
            self.lock().physics.commit_attachments();
            if let Some(player) = self.peek().player_states.get(actor).cloned() {
                sync_q3_player_seam(&player);
            }
            return Ok(());
        }
        // Donor 4682-4684: player weapon.
        if self.peek().player_states.contains_key(actor) {
            if self.peek().q2_characters.contains_key(actor) {
                q2_character_begin_frame_seam(actor);
            }
            let player = match self.peek().player_states.get(actor).cloned() {
                Some(player) => player,
                None => self.require_player(actor.id())?,
            };
            player_weapon_seam(&player);
            self.lock().physics.commit_attachments();
            return Ok(());
        }
        // Donor 4685-4687: think + physics.
        {
            let frame = {
                let state = self.peek();
                FrameContext {
                    phase: FramePhase::EntityThink,
                    ..state.source_frame
                }
            };
            run_actor_think_seam(self, actor, &frame)?;
        }
        if self.actors.borrow().is_live(actor.id()) {
            self.lock()
                .physics
                .step(actor, ctx.elapsed)
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        }
        self.lock().physics.commit_attachments();
        Ok(())
    }
}
// --- C11 part 1b: equipment-player ports ------------------------------------
// Donor `runtime.ts` pre-2168 unowned ports. These have no owning lane;
// they exist because the C11 range calls them.

impl SharedSimulation {
    /// Port `requireEquipmentPlayer` (donor 2098-2112).
    fn require_equipment_player(&self, actor: &qa_core::identity::ActorId) {
        let equipment = matches!(
            self.peek().source,
            SourceRuntime::Q2Native(_) | SourceRuntime::Q3Qvm { .. }
        );
        if !equipment {
            self.require_player(actor).expect("Actor is not an admitted player");
            return;
        }
        let client = self
            .player_client(actor)
            .expect("Equipment owner is not an admitted source player");
        let armed = self.peek().grapple.is_some() || self.peek().hand_grenades.is_some();
        if !armed || self.peek().native_equipment_players.contains(actor) {
            return;
        }
        let owner = self
            .actors_handle()
            .borrow()
            .resolve_owned(actor)
            .expect("Equipment owner was released");
        let bound = {
            let actors = self.actors_handle();
            let actors_ref = actors.borrow();
            let state = self.peek();
            state.inventory.has(actors_ref.inner(), actor)
        };
        if !bound {
            self.bind_equipment_inventory(&owner, &[]);
        }
        let carry = self
            .peek()
            .options_native_q2_travel
            .as_ref()
            .and_then(|travel| travel.clients().iter().find(|entry| entry.client == client))
            .map(|entry| (entry.hand_grenades.clone(), entry.weapon_slot.clone()));
        if self.peek().hand_grenades.is_some() {
            let grenades = carry.as_ref().and_then(|entry| entry.0.clone()).map(|carry| {
                super::equipment_runtime::HandGrenadeTravel {
                    state: carry.state.clone(),
                    ammo: carry.ammo.clone(),
                    seconds: carry.seconds,
                }
            });
            self.with_hand_grenades(|runtime, game| {
                runtime
                    .admit(actor, game, grenades.as_ref())
                    .expect("hand-grenade owner admission failed");
            })
            .expect("hand-grenade arena is missing");
        }
        self.admit_grapple(actor).expect("grapple owner admission failed");
        let available = self.equipment_player_available(actor);
        let mut state = self.lock();
        state.native_equipment_players.insert(actor.clone());
        state.native_equipment_alive.insert(actor.clone(), available);
        drop(state);
        if let Some((_, Some(slot))) = carry.as_ref() {
            if self.peek().weapon_slots.contains_key(actor) {
                self.primary_handoff(actor)
                    .expect("travel primary handoff failed")
                    .holster();
                self.bind_weapon_slot(
                    actor,
                    Some(super::weapon_slot::WeaponSlotRestoreState::HolsteringPrimary { next: slot.clone() }),
                )
                .expect("travel weapon slot bind failed");
                self.with_weapon_slot(actor, |slot| {
                    slot.reconcile().expect("travel weapon slot reconcile failed");
                });
            }
        }
    }

    /// Port `equipmentPlayerAvailable` (donor 2140-2149).
    fn equipment_player_available(&self, actor: &qa_core::identity::ActorId) -> bool {
        let actors = self.actors.borrow();
        equipment_player_available_in(&self.peek(), &actors, actor)
    }

    fn bind_equipment_inventory(
        &self,
        actor: &qa_core::identity::OwnedActor,
        initial: &[qa_content::contract::InventoryEntry],
    ) {
        // Missing siblings: the guest lane owns the host handle that the
        // donor's `sourceInventory` binding needs, so the source always reads
        // empty and every owner takes the donor's create path.
        let actors = self.actors_handle();
        let actors_ref = actors.borrow();
        let mut state = self.lock();
        let world: Vec<qa_world::inventory::InventoryEntry> = initial.iter().map(contract_entry_to_world).collect();
        state
            .inventory
            .inner_mut()
            .create(actors_ref.inner(), actor, world.as_slice())
            .expect("equipment inventory binding failed");
    }

    /// Port `requireNativeWeapons` (donor 1393-1403): presence assertion. The
    /// handle itself stays in state because every native call needs the
    /// native-weapon lane's synthetic host.
    #[allow(dead_code)]
    fn require_native_weapons(&self) {
        assert!(
            self.peek().native_primary_weapons.is_some(),
            "Original native selected weapons have no qualified owner"
        );
    }

    /// Port `requireQvmWeapons` (donor 1371-1392): presence assertion. Callers
    /// below borrow the state field directly because the handle is not `Clone`.
    #[allow(dead_code)]
    fn require_qvm_weapons(&self) {
        let state = self.peek();
        assert!(
            matches!(&state.source, SourceRuntime::Q3Qvm { weapons: Some(_), .. }),
            "Original QVM weapon services have no qualified owner"
        );
    }

    /// Port `selectedWeaponDelay` (donor 1833-1846).
    #[allow(dead_code)]
    fn selected_weapon_delay(&self, actor: &qa_core::identity::ActorId, seconds: f64) -> f64 {
        if matches!(self.peek().source, SourceRuntime::Q2Native(_)) {
            if self.peek().native_primary_commands.is_none() {
                panic!("Selected firing delay has no original weapon policy");
            }
            panic!("Missing siblings: native-primary lane owns withWeapon (donor `selectedWeaponDelay` q2-native arm)");
        }
        if matches!(self.peek().source, SourceRuntime::Q3Qvm { .. }) {
            self.require_qvm_weapons();
            let mut state = self.lock();
            let SourceRuntime::Q3Qvm {
                weapons: Some(services),
                ..
            } = &mut state.source
            else {
                panic!("Original QVM weapon services have no qualified owner");
            };
            let delayed = services
                .weapon_delay(actor, (seconds * 1000.0).trunc() as i32)
                .expect("qvm weapon delay failed");
            return f64::from(delayed) / 1000.0;
        }
        // Missing siblings: the q3 lane owns the source records behind
        // `nativeByActor`, so the q3 arm reads empty and every source takes
        // the donor's identity fallback.
        seconds
    }

    /// Borrowed `teamGame` (donor 5707-5720; canonical lane replaces).
    #[allow(dead_code)]
    fn c11_team_game(&self) -> bool {
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q1 { composition, cvars, .. } => {
                composition.program() == qa_content::q1::composition::types::Q1SourceProgram::Ctf
                    || cvars.borrow().variable_value("teamplay") != 0.0
            }
            // Missing siblings: the quakec lane owns the game cvar registry.
            SourceRuntime::QuakeC { .. } => false,
            // Missing siblings: the q3 lane owns the source game type.
            SourceRuntime::Q3 { .. } => false,
            SourceRuntime::Q3Qvm { game, .. } => game.state.cvars.borrow().variable_value("g_gametype") >= 3.0,
            SourceRuntime::Q2Native(_) => state
                .q2_server_registry
                .as_ref()
                .map(|registry| {
                    registry.borrow().variable_value("ctf") != 0.0
                        || (registry.borrow().variable_value("dmflags") as i32 & (64 | 128)) != 0
                })
                .unwrap_or(false),
            SourceRuntime::Q2 { game, .. } => {
                // Missing siblings: the q2 lane owns the product match record,
                // so only the donor's deathmatch-flags arm is live.
                let services = game.borrow();
                services.options.mode == qa_content::q2::foundation::host::Q2Mode::Deathmatch
                    && (services.options.deathmatch_flags & (64 | 128)) != 0
            }
            SourceRuntime::Loading => panic!("Team match policy requires an initialized source"),
        }
    }

    /// Borrowed `sourcePlayerUserinfo` (donor 5219-5235; canonical lane replaces).
    #[allow(dead_code)]
    fn c11_source_player_userinfo(&self, actor: &qa_core::identity::ActorId) -> Option<String> {
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q1 { composition, .. } => composition.client(actor).map(|client| {
                client
                    .userinfo
                    .iter()
                    .map(|(name, value)| format!("\\{name}\\{value}"))
                    .collect::<String>()
            }),
            SourceRuntime::Q2 { game, .. } => game
                .borrow()
                .players
                .states
                .get(actor)
                .map(|entry| entry.userinfo.clone()),
            // Missing siblings: the q3 lane owns the source host engine.
            SourceRuntime::Q3 { .. } => None,
            SourceRuntime::Q3Qvm { .. } => {
                let client = self.player_client(actor)?;
                drop(state);
                let state = self.peek();
                let SourceRuntime::Q3Qvm { game, .. } = &state.source else {
                    return None;
                };
                game.state.get_userinfo(client.slot() as i32)
            }
            SourceRuntime::Q2Native(native) => {
                let slot = self
                    .native_q2_client(actor)
                    .unwrap_or_else(|error| panic!("{error}"))
                    .slot()
                    + 1;
                let clients = match native {
                    Q2NativeSource::Classic { game, .. } => game.clients().ok().unwrap_or_default(),
                    Q2NativeSource::Rerelease { game, .. } => game.clients().ok().unwrap_or_default(),
                };
                clients
                    .into_iter()
                    .find(|entry| entry.slot == slot)
                    .map(|entry| entry.userinfo)
            }
            SourceRuntime::QuakeC { game } => {
                let client = self.player_client(actor)?;
                let mut pairs: Vec<(String, String)> = game.client_info(&client).into_iter().collect();
                // Donor map order is insertion order; the Rust map is
                // unordered, so sort for a deterministic string.
                pairs.sort();
                Some(
                    pairs
                        .iter()
                        .map(|(name, value)| format!("\\{name}\\{value}"))
                        .collect::<String>(),
                )
            }
            SourceRuntime::Loading => None,
        }
    }
}
