/// Windows file over a callback-owned classic file (donor
/// `files.openFile`).
struct C3WindowsFile {
    inner: crate::persistence::q2::classic_guest::ClassicOpenedFile,
}

impl qa_guest::runtime::windows::contracts::WindowsFile for C3WindowsFile {
    fn read(&mut self, offset: usize, length: usize) -> Vec<u8> {
        use crate::persistence::q2::classic_guest::ClassicGuestFile;
        self.inner.read(offset, length).unwrap_or_default()
    }

    fn write(&mut self, offset: usize, bytes: &[u8]) -> usize {
        use crate::persistence::q2::classic_guest::ClassicGuestFile;
        self.inner.write(offset, bytes).unwrap_or(0)
    }

    fn size(&mut self) -> usize {
        use crate::persistence::q2::classic_guest::ClassicGuestFile;
        self.inner.size().unwrap_or(0)
    }

    fn truncate(&mut self, length: usize) {
        use crate::persistence::q2::classic_guest::ClassicGuestFile;
        let _ = self.inner.truncate(length);
    }

    fn flush(&mut self) {
        use crate::persistence::q2::classic_guest::ClassicGuestFile;
        let _ = self.inner.flush();
    }

    fn close(&mut self) {
        use crate::persistence::q2::classic_guest::ClassicGuestFile;
        self.inner.close();
    }
}

/// Build the overlay file opener (donor `{ ...native.capabilities,
/// openFile: files.openFile }`).
///
/// The overlay stages travel-level bytes; misses fall through to the
/// capabilities opener, which the donor threads through the files
/// object and the port composes outside (the fallback opener type is
/// persistence-private).
fn native_files_opener(
    files: &crate::persistence::q2::classic_guest::ClassicOriginalSaveFiles,
    capabilities: &qa_guest::runtime::windows::contracts::WindowsCapabilities,
) -> qa_guest::runtime::windows::contracts::WindowsFileOpener {
    use crate::persistence::q2::classic_guest::ClassicOpenMode;
    let overlay = files.clone();
    let fallback = capabilities.open_file.clone();
    Rc::new(move |path: &str, options| {
        let mode = ClassicOpenMode {
            read: options.read,
            write: options.write,
            creation: options.creation,
        };
        if let Some(opened) = overlay.open_file(path, mode).ok().flatten() {
            return Some(Box::new(C3WindowsFile { inner: opened })
                as Box<dyn qa_guest::runtime::windows::contracts::WindowsFile>);
        }
        fallback.as_ref().and_then(|fallback| fallback(path, options))
    })
}

/// Entity admission (donor `admit`).
fn native_guest_admit(tables: &C11Tables, provider: &ProviderId) -> super::classic_guest_services::GuestAdmitFn {
    let tables = tables.clone();
    let provider = provider.clone();
    Box::new(move |record, actor| {
        let sim = tables.sim();
        sim.actors()
            .assert_owned(actor)
            .unwrap_or_else(|error| panic!("{error}"));
        let current = sim.actors().at_source(&provider, record.slot);
        if current.as_ref().map(|owned| owned.id()) != Some(actor.id()) {
            panic!("Native actor projection lost shared identity");
        }
    })
}

/// Collision record install (donor `collision`).
fn native_guest_collision(tables: &C11Tables) -> super::classic_guest_services::GuestCollisionFn {
    let tables = tables.clone();
    Box::new(move |actor, collision| {
        tables.sim().lock().physics.set_collision(actor, collision.clone());
    })
}

/// Damage provenance (donor `damageProvenance`).
fn native_damage_provenance(
    tables: &C11Tables,
    providers: (ProviderId, ProviderId, ProviderId, ProviderId),
) -> super::classic_guest_services::ClassicDamageProvenance {
    let tables = tables.clone();
    let (weapon_provider, combat_provider, inventory_provider, movement_provider) = providers;
    Rc::new(move |_, _, _| {
        let sim = tables.sim();
        super::classic_guest_services::AttackProvenanceTail {
            sequence: sim.next_attack_sequence(),
            time: qa_core::time::SourceTime::Seconds(sim.time_seconds() as f32),
            originating_projectile: None,
            weapon: None,
            weapon_provider: weapon_provider.clone(),
            damage_powerup_owner: None,
            combat_provider: combat_provider.clone(),
            inventory_provider: inventory_provider.clone(),
            movement_provider: movement_provider.clone(),
        }
    })
}

/// Presentation tag for world text (donor `content`).
///
/// The port stores a `u32` tag where the donor carries the entities
/// content id; hash the id text so distinct contents stay distinct.
fn content_tag(content: &ContentId) -> u32 {
    let mut hash: u32 = 0x811c_9dc5;
    for byte in content.as_str().bytes() {
        hash = (hash ^ u32::from(byte)).wrapping_mul(0x0100_0193);
    }
    hash
}

/// Classic revisit record (donor `revisit`).
fn classic_revisit(
    tables: &C11Tables,
    level_path: String,
    configstrings: Vec<(i64, String)>,
    portals: Vec<(i64, bool)>,
) -> super::classic_guest_world::ClassicGuestRevisit {
    let tables = tables.clone();
    super::classic_guest_world::ClassicGuestRevisit {
        level_path,
        restore_server_state: Box::new(move |world| {
            let strings: HashMap<i32, String> = configstrings
                .iter()
                .map(|(index, value)| (*index as i32, value.clone()))
                .collect();
            world
                .restore_configstrings(&strings)
                .unwrap_or_else(|error| panic!("{error}"));
            let sim = tables.sim();
            let scene = sim.scene();
            let mut state = sim.lock();
            for (portal, open) in &portals {
                state.area_portals.insert(*portal as u32, *open);
                scene.set_area_portal_state(*portal as u32, *open);
            }
        }),
    }
}

