/// Rerelease navigation over bot services (donor
/// `rereleaseNavigationServices`).
pub struct C3RereleaseNavigation {
    tables: C11Tables,
    provider: ProviderId,
}

impl qa_compat::q2::rerelease::navigation::NavigationServices for C3RereleaseNavigation {
    fn runtime(&self) -> Option<&qa_compat::q2::rerelease::navigation::NavRuntime> {
        // Missing siblings: navigation-lane runtime (the state holds the
        // unit value); the donor reads install-time navigation.
        None
    }

    fn move_to_point(
        &mut self,
        actor: u32,
        point: Vec3,
        tolerance: f32,
    ) -> qa_compat::q2::rerelease::navigation::GoalStatus {
        let sim = self.tables.sim();
        let actors = sim.actors();
        match actors.at_source(&self.provider, actor) {
            Some(owned) => sim
                .peek()
                .bot_services
                .move_to_point(owned.id(), point, f64::from(tolerance)) as u8,
            None => 0,
        }
    }

    fn follow_actor(&mut self, actor: u32, target: u32) -> qa_compat::q2::rerelease::navigation::GoalStatus {
        let sim = self.tables.sim();
        let actors = sim.actors();
        match (
            actors.at_source(&self.provider, actor),
            actors.at_source(&self.provider, target),
        ) {
            (Some(owned), Some(target)) => sim.peek().bot_services.follow_actor(owned.id(), target.id()) as u8,
            _ => 0,
        }
    }
}

/// Convert a rerelease source save to the host save shape.
///
/// The donor passes the save through; the port split rich persistence
/// saves from the host shape, so attack/request context is dropped.
///
/// Missing siblings: compat-lane rich deferred saves.
fn rr_source_save_to_host(
    save: &super::native_q2_rerelease_save::RereleaseSourceSave,
) -> qa_compat::q2::rerelease::host::SourceSave {
    use super::native_q2_rerelease_save::RereleaseSavedActor;
    use qa_compat::q2::rerelease::host::{DeferredSave, ProjectionSave, SourceSave};
    SourceSave {
        native: save.native.clone(),
        deferred: save
            .deferred_damage
            .iter()
            .map(|damage| DeferredSave {
                target_slot: match &damage.target {
                    RereleaseSavedActor::Native { slot, .. } => *slot,
                    RereleaseSavedActor::Shared { actor } => actor.slot,
                },
                blood: damage.blood as i32,
            })
            .collect(),
        projections: save
            .projections
            .iter()
            .map(|projection| ProjectionSave {
                slot: projection.slot,
                actor: projection.actor.slot,
            })
            .collect(),
    }
}

// ---------------------------------------------------------------------------
/// Host travel save to checkpoint save (inverse of [`rr_source_save_to_host`]).
///
/// Missing siblings: the compat host summarizes deferred damage as
/// `{target_slot, blood}` and projections as slot-only pairs, so full
/// `RereleaseDeferredDamageSave` checkpoints and actor generations need
/// the compat lane's rich travel write. Native bytes travel verbatim;
/// non-empty deferred summaries fail instead of corrupting the level.
/// Slot-only projections store generation 0; the revisit path drops it
/// (see [`rr_source_save_to_host`]).
fn rr_host_save_to_source(
    save: &qa_compat::q2::rerelease::host::SourceSave,
) -> Result<super::native_q2_rerelease_save::RereleaseSourceSave, RuntimeError> {
    use super::native_q2_rerelease_save::{RereleaseProjection, RereleaseSourceSave};
    use qa_core::identity::SavedActorId;
    if !save.deferred.is_empty() {
        return fail("Native travel cannot checkpoint pending deferred damage");
    }
    Ok(RereleaseSourceSave {
        native: save.native.clone(),
        deferred_damage: Vec::new(),
        projections: save
            .projections
            .iter()
            .map(|projection| RereleaseProjection {
                slot: projection.slot,
                actor: SavedActorId {
                    slot: projection.actor,
                    generation: 0,
                },
            })
            .collect(),
    })
}

