impl SharedSimulation {
    /// Post-frame reconciliation (donor 4694-4730).
    #[allow(dead_code)]
    fn step_tail_post_frames(&self, ctx: &StepTailContext) -> Result<(), RuntimeError> {
        // Donor 4694: monster-source end frames.
        if ctx.map_run {
            let mut state = self.lock();
            for source in state.monster_sources.values_mut() {
                if let Some((clock, game)) = source.q2_frame_parts() {
                    if clock.advanced {
                        q2_monster_end_frame(game);
                    }
                }
            }
        }
        // Donor 4695: weapon slot reconciliation.
        if ctx.run {
            let mut state = self.lock();
            for slot in state.weapon_slots.values_mut() {
                slot.reconcile()
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            }
        }
        if !(ctx.run || ctx.paused) {
            return Ok(());
        }
        // Donor 4697-4704: Q2 player end frames.
        if self.peek().source.kind() == "q2" {
            let players: Vec<OwnedActor> = {
                let state = self.peek();
                state.player_states.keys().cloned().collect()
            };
            for owned in players {
                let has_entity = {
                    let state = self.peek();
                    match &state.source {
                        SourceRuntime::Q2 { game, .. } => game.borrow().entity(owned.id()).is_some(),
                        _ => false,
                    }
                };
                if !has_entity {
                    continue;
                }
                let (intermission, character) = {
                    let state = self.peek();
                    match state.player_states.get(&owned) {
                        Some(player) => (player.intermission, player.character),
                        None => continue,
                    }
                };
                let health = self
                    .peek()
                    .combat
                    .read(owned.id())
                    .map(|state| state.health)
                    .unwrap_or(0.0);
                if !intermission && character == GameFamily::Q2 && health <= 0.0 {
                    let height = if q2_player_gibbed_seam(owned.id()) { 8 } else { -2 };
                    {
                        let state = self.peek();
                        if let SourceRuntime::Q2 { game, .. } = &state.source {
                            if let Some(entity) = game.borrow_mut().entity_mut(owned.id()) {
                                entity.view_height = height;
                            }
                        }
                    }
                    {
                        let mut state = self.lock();
                        if let Some(player) = state.player_states.get_mut(&owned) {
                            player.view_height = f64::from(height);
                        }
                    }
                }
                q2_players_end_frame_seam();
                if character == GameFamily::Q2 {
                    if let Some(anim) = q2_player_anim_state_seam(owned.id()) {
                        let frame = {
                            let state = self.peek();
                            match &state.source {
                                SourceRuntime::Q2 { game, .. } => game
                                    .borrow()
                                    .entity(owned.id())
                                    .map(|entity| entity.frame())
                                    .unwrap_or(0),
                                _ => 0,
                            }
                        };
                        let provider = self.peek().recipe.character.definition.provider.clone();
                        {
                            let mut state = self.lock();
                            if let Some(player) = state.player_states.get_mut(&owned) {
                                player.animation = ActorAnimationState {
                                    provider,
                                    state: qa_world::movement::types::AnimationState::Q2 {
                                        frame,
                                        end_frame: anim.end_frame,
                                        priority: anim.priority,
                                        duck: anim.duck,
                                        run: anim.run,
                                    },
                                };
                            }
                        }
                    }
                }
            }
        }
        // Donor 4705-4712: Q2 match maintenance.
        if ctx.run && self.peek().source.kind() == "q2" {
            if q2_lmctf_countdown_elapsed_seam() {
                if let Some(registry) = self.peek().q2_server_registry.clone() {
                    registry
                        .borrow_mut()
                        .apply_latched(Some("timelimit"))
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
            q2_after_player_frames_seam();
            q2_source_monsters_end_frame_seam();
            {
                let mut state = self.lock();
                state.checking_q2_rules = true;
            }
            q2_check_rules_seam();
            {
                let mut state = self.lock();
                state.checking_q2_rules = false;
            }
        }
        // Donor 4713-4719: Q3 player end frames.
        if self.peek().source.kind() == "q3" {
            let players: Vec<OwnedActor> = {
                let state = self.peek();
                state.player_states.keys().cloned().collect()
            };
            for owned in players {
                let dead_q3 = {
                    let state = self.peek();
                    match state.player_states.get(&owned) {
                        Some(player) => {
                            !player.intermission
                                && player.character == GameFamily::Q3
                                && state.combat.read(owned.id()).map(|combat| combat.health).unwrap_or(0.0) <= 0.0
                        }
                        None => false,
                    }
                };
                if dead_q3 {
                    q3_dead_viewheight_seam(owned.id());
                }
            }
            q3_source_end_frame_seam();
        }
        // Donor 4720: Q3 character animation sync.
        {
            let updates: Vec<(OwnedActor, ActorAnimationState)> = {
                let state = self.peek();
                state
                    .characters
                    .iter()
                    .filter(|(actor, _)| state.player_states.contains_key(*actor))
                    .filter_map(|(actor, character)| character.animation().map(|animation| (actor.clone(), animation)))
                    .collect()
            };
            let mut state = self.lock();
            for (owned, animation) in updates {
                if let Some(player) = state.player_states.get_mut(&owned) {
                    player.animation = animation;
                }
            }
        }
        // Donor 4721-4725: Q2 character animation sync.
        {
            let time_seconds = self.time_seconds();
            let due: Vec<OwnedActor> = {
                let state = self.peek();
                state
                    .q2_characters
                    .keys()
                    .filter(|actor| {
                        ctx.paused || time_seconds + 0.001 >= state.character_ticks.get(*actor).copied().unwrap_or(0.0)
                    })
                    .cloned()
                    .collect()
            };
            for owned in due {
                {
                    let mut state = self.lock();
                    state.character_ticks.insert(owned.clone(), time_seconds + 0.1);
                }
                q2_character_end_frame_seam(owned.id());
                let update = {
                    let state = self.peek();
                    state.q2_characters.get(&owned).map(|character| {
                        (
                            character.entity.frame(),
                            character.state.animation_end,
                            character.state.animation_priority,
                            character.state.animation_duck,
                            character.state.animation_run,
                        )
                    })
                };
                if let Some((frame, end_frame, priority, duck, run)) = update {
                    let provider = self.peek().recipe.character.definition.provider.clone();
                    let mut state = self.lock();
                    if let Some(player) = state.player_states.get_mut(&owned) {
                        player.animation = ActorAnimationState {
                            provider,
                            state: qa_world::movement::types::AnimationState::Q2 {
                                frame,
                                end_frame,
                                priority,
                                duck,
                                run,
                            },
                        };
                    }
                }
            }
        }
        // Donor 4726-4730: Q1 character animation sync.
        self.step_tail_q1_characters()
    }
}

impl SharedSimulation {
    /// Q1 character animation sync (donor 4726-4730).
    #[allow(dead_code)]
    fn step_tail_q1_characters(&self) -> Result<(), RuntimeError> {
        use qa_content::q1::base::player::{Q1CharacterInput, Q1CharacterWater};
        use qa_content::q1::foundation::types::Q1Powerup;
        let time_seconds = self.time_seconds();
        let actors: Vec<OwnedActor> = {
            let state = self.peek();
            state.q1_characters.keys().cloned().collect()
        };
        for owned in actors {
            let player = match self.peek().player_states.get(&owned).cloned() {
                Some(player) => player,
                None => continue,
            };
            // The character's game is the Q1 source game when the source is
            // Q1, else the selected Q1 arsenal game; with neither, the
            // lane's game registry owns the call and it is skipped.
            let source_game = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::Q1 { services, .. } => Some(services.clone()),
                    _ => None,
                }
            };
            let selected_game = {
                let state = self.peek();
                match &state.selected_arsenal {
                    Some(SelectedArsenal::Q1(q1)) => Some(q1.game()),
                    _ => None,
                }
            };
            let game = match (source_game, selected_game) {
                (Some(services), _) => services,
                (None, Some(game)) => game,
                (None, None) => continue,
            };
            let powers = if self.peek().source.kind() == "q1" {
                game.borrow()
                    .player_ref(owned.id())
                    .and_then(|player| player.powerups.get(&Q1Powerup::Invisibility).copied())
                    .unwrap_or(0.0)
            } else {
                0.0
            };
            let water_level = if player.water_level >= 3.0 {
                3
            } else if player.water_level == 2.0 {
                2
            } else if player.water_level == 1.0 {
                1
            } else {
                0
            };
            let water_type = if player.water_type == -3.0 {
                Q1CharacterWater::Water
            } else if player.water_type == -4.0 {
                Q1CharacterWater::Slime
            } else if player.water_type == -5.0 {
                Q1CharacterWater::Lava
            } else {
                Q1CharacterWater::Empty
            };
            let invulnerable = self
                .peek()
                .combat
                .read(owned.id())
                .map(|state| state.invulnerable)
                .unwrap_or(false);
            let presentation = {
                let mut locked = self.lock();
                let Some(character) = locked.q1_characters.get_mut(&owned) else {
                    continue;
                };
                character
                    .frame(
                        &mut game.borrow_mut(),
                        time_seconds,
                        &Q1CharacterInput {
                            axe_pose: q1_character_axe_pose_seam(owned.id()),
                            attack: step_button_bits(player.buttons) & 1 != 0,
                            jump: step_button_bits(player.buttons) & 2 != 0,
                            use_input: step_button_bits(player.buttons) & 4 != 0,
                            water_level,
                            water_type,
                            invisible: powers > time_seconds,
                            invulnerable,
                        },
                    )
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?
            };
            if self.peek().source.kind() == "q1" {
                let state = self.peek();
                if let SourceRuntime::Q1 {
                    services, composition, ..
                } = &state.source
                {
                    composition
                        .character_frame(&mut services.borrow_mut(), owned.id(), &presentation)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
            let provider = self.peek().recipe.character.definition.provider.clone();
            {
                let mut state = self.lock();
                if let Some(player) = state.player_states.get_mut(&owned) {
                    player.animation = ActorAnimationState {
                        provider,
                        state: qa_world::movement::types::AnimationState::Q1 {
                            frame: presentation.frame as i32,
                            next_frame_seconds: time_seconds + 0.1,
                        },
                    };
                }
            }
        }
        Ok(())
    }
}

impl SharedSimulation {
    /// QuakeC finish (donor 4732-4754).
    #[allow(dead_code)]
    fn step_tail_quakec_finish(&self) -> Result<(), RuntimeError> {
        {
            let state = self.peek();
            if let SourceRuntime::QuakeC { game } = &state.source {
                game.end_frame()
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            } else {
                return Ok(());
            }
        }
        {
            let players: Vec<OwnedActor> = {
                let state = self.peek();
                state.player_states.keys().cloned().collect()
            };
            for owned in players {
                let intermission = {
                    let state = self.peek();
                    match &state.source {
                        SourceRuntime::QuakeC { game } => game.local_client_intermission(owned.id()),
                        _ => None,
                    }
                };
                if let Some(intermission) = intermission {
                    let mut state = self.lock();
                    if let Some(player) = state.player_states.get_mut(&owned) {
                        player.intermission = intermission;
                    }
                }
            }
        }
        {
            let is_quakeworld = {
                let state = self.peek();
                match &state.source {
                    SourceRuntime::QuakeC { game } => game.kind() == super::types::QuakeCSourceKind::Quakeworld,
                    _ => false,
                }
            };
            if is_quakeworld {
                run_quake_world_commands_seam();
                quake_c_messages_flush_seam();
            }
        }
        let players: Vec<MovementPlayer> = {
            let state = self.peek();
            state.player_states.values().cloned().collect()
        };
        for player in players {
            if player.character == GameFamily::Q1 || player.intermission || player.cutscene.is_some() {
                continue;
            }
            let body = {
                let actors = self.actors.borrow();
                self.bodies_table.borrow().read(actors.inner(), player.actor.id())
            };
            let Some(body) = body else {
                continue;
            };
            let moving = f64::from(body.velocity.x).hypot(f64::from(body.velocity.y)) != 0.0;
            let locomotion = if player.water_level >= 2.0 {
                "swim"
            } else if matches!(player.ground, TraceHit::None) {
                "jump"
            } else if player.bounds.max.z < player.standing_bounds.max.z {
                "crouch"
            } else if moving {
                "run"
            } else {
                "idle"
            };
            let yaw = f64::from(player.view_angles.y) * std::f64::consts::PI / 180.0;
            let backwards = f64::from(body.velocity.x) * yaw.cos() + f64::from(body.velocity.y) * yaw.sin() < 0.0;
            let frame = self.peek().source_frame;
            let animation =
                quake_c_character_step_seam(&player.actor, &frame, &player.animation, locomotion, backwards, false);
            {
                let mut state = self.lock();
                if let Some(entry) = state.player_states.get_mut(&player.actor) {
                    entry.animation = animation;
                }
            }
        }
        Ok(())
    }

    /// Frame-exit finish (donor 4755-4765).
    fn step_tail_finish(&self, ctx: &StepTailContext) -> Result<StepTailFlow, RuntimeError> {
        use qa_core::time::FramePhase;
        if ctx.run {
            self.step_tail_quakec_finish()?;
            // Donor 4756: Q1 retouch decay.
            if self.peek().source.kind() == "q1" {
                let state = self.peek();
                if let SourceRuntime::Q1 { services, .. } = &state.source {
                    let mut borrowed = services.borrow_mut();
                    if borrowed.force_retouch > 0 {
                        borrowed.force_retouch -= 1;
                    }
                }
            }
            // Donor 4757-4762: frame-exit settlement.
            {
                let mut state = self.lock();
                if ctx.settlement_active {
                    state.source_frame = state
                        .clock
                        .advance(SourceTime::Milliseconds(100), FramePhase::FrameExit)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                    if let SourceRoundSettlement::Active { completed } = &mut state.source_round_settlement {
                        *completed += 1;
                    }
                } else if ctx.fixed.is_none() {
                    state.source_frame = state
                        .clock
                        .advance(SourceTime::Seconds(ctx.elapsed as f32), FramePhase::FrameExit)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                } else {
                    state.source_frame = state.clock.enter(FramePhase::FrameExit);
                }
                let frame = state.source_frame;
                if let Some(owner) = state.mod_owner.as_mut() {
                    owner.advance(&frame)?;
                }
            }
        }
        // Donor 4763-4765: Q2 transitions break the boundary loop.
        if self.peek().source.kind() == "q2" && !self.peek().transitions.is_empty() {
            return Ok(StepTailFlow::BreakLoop);
        }
        Ok(StepTailFlow::Fallthrough)
    }

    /// Emit Q2 shadow lights once per step (donor 4768).
    ///
    /// C5 calls this after their boundary loop; the emit runs once per
    /// step, not once per boundary.
    #[allow(dead_code)]
    pub(super) fn step_tail_emit_shadows(&self) {
        if self.peek().source.kind() == "q2" {
            emit_q2_shadow_lights_seam();
        }
    }
}

/// Settle a failed round (donor catch, 4771-4773).
///
/// C5 calls this from their catch; the Rust settlement carries no source
/// handle, so only the failed kind survives.
#[allow(dead_code)]
pub(super) fn step_tail_fail_settlement(state: &mut SharedSimulationState) {
    state.source_round_settlement = SourceRoundSettlement::Failed;
}

/// Reset per-step guards (donor finally, 4774).
///
/// C5 calls this from their finally.
#[allow(dead_code)]
pub(super) fn step_tail_finalize(state: &mut SharedSimulationState) {
    state.primary_command_blocks.clear();
    state.stepping = false;
}

/// Donor `close` (C10: donor `runtime.ts` 6783-6805).
impl SharedSimulation {
    pub fn close(&mut self) -> Result<(), RuntimeError> {
        if self.peek().checkpoint_in_progress {
            return fail("Await checkpoint completion before closing the simulation");
        }
        if self.peek().closed {
            return Ok(());
        }
        if self.with_q3_guest(|guest| guest.is_retired()) == Some(false) {
            return fail("Q3 guest shutdown must be awaited before closing its shared world");
        }
        let mut errors: Vec<RuntimeError> = Vec::new();
        if let Some(owner) = self.lock().mod_owner.as_mut() {
            owner.close();
        }
        self.lock().source_match.close();
        if let Some(grapple) = self.peek().grapple.as_ref() {
            grapple.close_qvm_game();
        }
        self.lock().qvm_grapple_source = None;
        if let Err(error) = self.lock().weapon_behavior.close() {
            errors.push(RuntimeError::Failure(format!("{error:?}")));
        }
        {
            let mut state = self.lock();
            if let Some(drop) = state.native_primary_drop.as_mut() {
                drop.close();
            }
            if let Some(inventory) = state.native_primary_inventory.as_mut() {
                inventory.close();
            }
            // Donor calls `disposeNativePickupSupply?.()` without clearing it;
            // Rust `FnOnce` must be taken to fire. Double close is guarded by
            // `closed` above, so take-then-fire matches the donor sequence.
            if let Some(dispose) = state.dispose_native_pickup_supply.take() {
                dispose();
            }
            if let Some(commands) = state.native_primary_commands.as_mut() {
                commands.close();
            }
            if let Some(weapons) = state.native_primary_weapons.as_mut() {
                weapons.close();
            }
        }
        {
            let mut state = self.lock();
            if let SourceRuntime::Q2Native(native) = &mut state.source {
                if let Err(error) = native.close() {
                    errors.push(error);
                }
            }
        }
        {
            let mut state = self.lock();
            state.closed = true;
            state.mod_client_applications.close();
            state.mod_client_outputs.close();
            state.mod_client_listeners.clear();
            state.mod_client_admissions.clear();
            state.mod_client_commands.clear();
            state.mod_client_drops.clear();
            state.debug_line_store.clear();
            state.debug_line_snapshot.clear();
            state.world_text_store.clear();
            state.world_text_snapshot.clear();
        }
        {
            let mut state = self.lock();
            if let Some(timers) = state.selected_ammo_timers.as_mut() {
                timers.close();
            }
            if let Some(selected) = state.selected_q3_source.as_mut() {
                if let Err(error) = selected.close() {
                    errors.push(RuntimeError::Failure(format!("{error:?}")));
                }
            }
        }
        self.actors.borrow_mut().close();
        {
            let mut state = self.lock();
            if let SourceRuntime::Q3 { game } = &mut state.source {
                if let Err(error) = game.close() {
                    errors.push(error);
                }
            }
            if let Some(dispose) = state.dispose_source_combat.take() {
                dispose();
            }
            state.scheduler.close();
        }
        match errors.len() {
            0 => Ok(()),
            1 => Err(errors.into_iter().next().unwrap()),
            _ => Err(RuntimeError::Aggregate(
                "Simulation source and shared owner shutdown failed".to_string(),
                errors.iter().map(|error| error.to_string()).collect(),
            )),
        }
    }
}

impl SessionMods {
    /// Donor `modOwner.close` (donor `src/world/session/mods.ts` 303-310).
    ///
    /// Idempotent: a closed session returns at once, otherwise it marks
    /// itself closed and drops the enabled set (donor `active = []` plus
    /// `pending.clear()`; the seam carries no runtime scopes to close).
    pub fn close(&mut self) {
        if self.closed {
            return;
        }
        self.closed = true;
        self.enabled.clear();
    }
}

impl FrameScheduler {
    /// Donor `scheduler.close`: drop every pending think and refuse further
    /// scheduling, via [`qa_world::scheduler::Scheduler::close`].
    pub fn close(&mut self) {
        self.inner.close();
    }
}

impl Q2NativeSource {
    /// Donor `q2Native().close` (donor runtime.ts 6794).
    ///
    /// Shuts the guest world down; failures join the simulation close
    /// aggregate like the donor's `errors.push`.
    pub fn close(&mut self) -> Result<(), RuntimeError> {
        match self {
            Q2NativeSource::Classic { game, .. } => game
                .close()
                .map_err(|error| RuntimeError::Failure(format!("{error:?}"))),
            Q2NativeSource::Rerelease { game, .. } => game
                .close()
                .map_err(|error| RuntimeError::Failure(format!("{error:?}"))),
        }
    }
}

