/// Shared native-source build parts (donor `createSource` preamble).
pub struct NativeSourceParts {
    /// Shared table handles for service closures.
    tables: C11Tables,
    /// Map entities provider reference.
    source: ProviderReference,
    /// Damage provenance providers: entities, combat, inventory, movement.
    providers: (ProviderId, ProviderId, ProviderId, ProviderId),
    /// Timing numeric profile.
    numeric: qa_core::numeric::NumericProfile,
    /// Server console variables.
    cvars: qa_core::cvar::CvarRegistry,
    /// Destination map.
    map: super::classic_guest_world::ClassicGuestMap,
    /// Requested map path (visited-level key).
    requested_path: String,
    /// Maximum clients.
    max_clients: u32,
    /// Session seat identity lookup.
    player_identity: Option<super::types::PlayerIdentityLookup>,
}

/// Closures shared by the native service options and map bindings.
struct NativeServiceParts {
    /// Engine authorities.
    engine: Box<dyn qa_content::q2::foundation::host::Q2FoundationHost>,
    /// Shared scene queries.
    scene: Rc<dyn super::source_hosts::ActorHostScene>,
    /// Entity admission callback.
    admit: super::classic_guest_services::GuestAdmitFn,
    /// Body collision callback.
    collision: super::classic_guest_services::GuestCollisionFn,
    /// Guest print sink.
    print: super::classic_guest_services::GuestPrintFn,
    /// Current command line reader.
    command: super::classic_guest_services::GuestCommandFn,
    /// Console command sink.
    add_command: super::classic_guest_services::GuestAddCommandFn,
    /// Debug graph sink.
    debug_graph: super::classic_guest_services::GuestDebugGraphFn,
}

/// Retained classic travel: payload files plus the live world.
///
/// The travel payload carries a unit world mirror; the live world is taken
/// from the running source across the retirement boundary.
pub struct RetainedClassicTravel {
    /// Original save-file overlay.
    files: crate::persistence::q2::classic_guest::ClassicOriginalSaveFiles,
    /// Visited hub levels by map path.
    visited: HashMap<String, crate::persistence::q2::classic_guest::Q2ClassicVisitedLevel>,
    /// Live world taken from the running source.
    world: super::classic_guest_world::ClassicGuestWorld,
}

/// Retained rerelease travel: payload plus the live world.
pub struct RetainedRereleaseTravel {
    /// Visited hub levels by map path.
    visited: HashMap<String, super::native_q2_rerelease_save::Q2RereleaseVisitedLevel>,
    /// Live world taken from the running source.
    world: super::rerelease_guest_world::RereleaseGuestWorld,
}

/// Fallback opener bridging native capabilities into the save overlay.
///
/// The donor threads `native.capabilities.openFile` through
/// `ClassicOriginalSaveFiles`; the port reads fallback files eagerly into
/// memory because the overlay consumes `MemoryFile` values.
#[allow(clippy::type_complexity)]
fn native_save_fallback(
    capabilities: &qa_guest::runtime::windows::contracts::WindowsCapabilities,
) -> Option<
    Box<
        dyn Fn(
            &str,
            &crate::persistence::q2::classic_guest::ClassicOpenMode,
        ) -> Option<crate::persistence::q2::classic_guest::MemoryFile>,
    >,
> {
    use crate::persistence::q2::classic_guest::MemoryFile;
    use qa_guest::runtime::windows::contracts::WindowsOpenOptions;
    capabilities.open_file.clone().map(|opener| {
        Box::new(
            move |path: &str, mode: &crate::persistence::q2::classic_guest::ClassicOpenMode| {
                let options = WindowsOpenOptions {
                    read: mode.read,
                    write: mode.write,
                    creation: mode.creation,
                };
                opener(path, options).map(|mut file| {
                    let size = file.size();
                    MemoryFile::new(file.read(0, size), mode.read, mode.write)
                })
            },
        ) as Box<dyn Fn(&str, &crate::persistence::q2::classic_guest::ClassicOpenMode) -> Option<MemoryFile>>
    })
}

impl SharedSimulation {
    /// Native Q2 source (donor `createSource` q2Guest branch).
    ///
    /// Validates retained travel, provisions the server console, and
    /// dispatches to the edition halves. `native_loading` mirrors the
    /// donor `loading === nativeLoading` comparison: travel commits
    /// through a [`NativeTravelLoader`] and the synchronous result is
    /// [`SourceRuntime::Loading`].
    pub fn create_native_source(
        &self,
        inputs: CreateSourceInputs<'_>,
        native_loading: bool,
    ) -> Result<SourceRuntime, RuntimeError> {
        use super::native_q2_travel::NativeQ2Travel;
        use super::q2_native_world::{native_module_identity, PreparedQ2NativeGuest};
        use qa_content::q2::foundation::host::Q2Edition;

        let CreateSourceInputs {
            world,
            q2_guest,
            native_q2_travel: traveling,
            restore,
            source_registry,
            source_archive,
            q2_next_server,
            player_identity,
            profile,
            ..
        } = inputs;
        let native =
            q2_guest.ok_or_else(|| source_failure("Native Q2 source construction requires q2 guest options"))?;
        let edition = native.edition();
        let (mode, skill, max_clients) = {
            let state = self.peek();
            (state.options_mode, state.options_skill, state.options_max_clients)
        };
        let edition_mismatch = traveling.as_ref().is_some_and(|travel| travel.edition() != edition);
        if edition_mismatch || traveling.is_some() && restore.is_some() {
            return Err(source_failure(
                "Native travel requires the same source module and client capacity",
            ));
        }
        let mut retained_classic: Option<super::classic_guest_world::ClassicGuestWorld> = None;
        let mut retained_rerelease: Option<super::rerelease_guest_world::RereleaseGuestWorld> = None;
        let mut retained_cvars: Option<qa_core::cvar::CvarRegistry> = None;
        if traveling.is_some() {
            let unified = match edition {
                Q2Edition::Classic => native
                    .prepared_classic()
                    .map(|prepared| PreparedQ2NativeGuest::Classic(prepared.clone()))
                    .ok_or_else(|| source_failure("Native Q2 guest edition mismatch"))?,
                Q2Edition::Rerelease => native
                    .prepared_rerelease()
                    .map(|prepared| PreparedQ2NativeGuest::Rerelease(prepared.clone()))
                    .ok_or_else(|| source_failure("Native Q2 guest edition mismatch"))?,
            };
            let expected = native_module_identity(&unified);
            let previous = std::mem::replace(&mut self.lock().source, SourceRuntime::Loading);
            match previous {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => {
                    let same_module = game.module().map(|module| module == expected).unwrap_or(false);
                    let same_capacity =
                        game.services().map(|services| services.options().max_clients) == Some(max_clients as u32);
                    if edition != Q2Edition::Classic || !same_module || !same_capacity {
                        return Err(source_failure(
                            "Native travel requires the same source module and client capacity",
                        ));
                    }
                    retained_cvars = game.services().map(|services| services.options().cvars.clone());
                    retained_classic = Some(game);
                }
                SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => {
                    let same_module = game.module().map(|module| module == expected).unwrap_or(false);
                    let same_capacity =
                        game.services().map(|services| services.options().base.max_clients) == Some(max_clients as u32);
                    if edition != Q2Edition::Rerelease || !same_module || !same_capacity {
                        return Err(source_failure(
                            "Native travel requires the same source module and client capacity",
                        ));
                    }
                    retained_cvars = game.services().map(|services| services.options().base.cvars.clone());
                    retained_rerelease = Some(game);
                }
                _ => {
                    return Err(source_failure(
                        "Native travel requires the same source module and client capacity",
                    ));
                }
            }
        }
        let registry_injected = source_registry.is_some();
        let mut cvars = retained_cvars
            .or_else(|| if restore.is_none() { source_registry } else { None })
            .unwrap_or_else(|| {
                qa_core::cvar::CvarRegistry::new(if edition == Q2Edition::Classic {
                    qa_core::cmd::Dialect::Q2Classic
                } else {
                    qa_core::cmd::Dialect::Q2Rerelease
                })
            });
        if traveling.is_none() && !registry_injected {
            cvars
                .apply_archive(source_archive.unwrap_or(&[]))
                .map_err(source_failure)?;
        }
        if traveling.is_none() {
            let deathmatch = mode == super::types::SimulationMode::Deathmatch;
            let coop = mode == super::types::SimulationMode::Coop;
            for (name, value) in [
                ("maxclients", max_clients.to_string()),
                ("skill", skill.to_string()),
                ("deathmatch", if deathmatch { "1".to_string() } else { "0".to_string() }),
                ("coop", if coop { "1".to_string() } else { "0".to_string() }),
                ("sv_gravity", "800".to_string()),
                ("sv_airaccelerate", "0".to_string()),
            ] {
                provision_source_cvar(&mut cvars, name, &value)?;
            }
        }
        if restore.is_none() {
            cvars
                .set("nextserver", q2_next_server.unwrap_or(""), true)
                .map_err(source_failure)?;
        }
        self.lock().q2_server_registry = Some(Rc::new(RefCell::new(cvars.clone())));
        self.initialize_server_settings(&mut cvars, profile, restore.is_some())?;
        if let Some(image) = restore.as_ref() {
            if let Some(saved) = super::save::saved_source_cvars(image).map_err(source_failure)? {
                crate::settings::server::restore_q2_server_cvars(&mut cvars, &saved).map_err(source_failure)?;
            }
        }
        let (entities, combat, inventory, movement, requested_path) = {
            let state = self.peek();
            let recipe = &state.recipe;
            (
                recipe.map.entities.clone(),
                recipe.combat.clone(),
                recipe.inventory.clone(),
                recipe.movement.clone(),
                recipe.map.geometry.requested_path.clone(),
            )
        };
        let numeric = {
            let state = self.peek();
            provider_timing(&state.recipe, &provider_text(&entities.provider))?.numeric
        };
        let map = super::classic_guest_world::ClassicGuestMap {
            map: source_map_name(&requested_path),
            entities: super::native_q2_map::prepare_native_q2_map(world, edition, mode).map_err(source_failure)?,
            spawn_point: self.peek().initial_spawn_point.clone(),
        };
        let providers = (
            entities.provider.clone(),
            combat.provider.clone(),
            inventory.provider.clone(),
            movement.provider.clone(),
        );
        let parts = NativeSourceParts {
            tables: C11Tables {
                actors: self.actors_handle(),
                bodies: self.bodies_handle(),
                weak: self.weak(),
            },
            source: ProviderReference {
                provider: entities.provider.clone(),
                content: entities.content.clone(),
            },
            providers,
            numeric,
            cvars,
            map,
            requested_path,
            max_clients: max_clients as u32,
            player_identity,
        };
        match (edition, traveling) {
            (Q2Edition::Classic, Some(NativeQ2Travel::Classic(classic))) => {
                let world = retained_classic.ok_or_else(|| {
                    source_failure("Native travel requires the same source module and client capacity")
                })?;
                self.create_classic_native_source(
                    native,
                    parts,
                    Some(RetainedClassicTravel {
                        files: classic.files,
                        visited: classic.visited,
                        world,
                    }),
                    native_loading,
                )
            }
            (Q2Edition::Classic, None) => self.create_classic_native_source(native, parts, None, native_loading),
            (Q2Edition::Rerelease, Some(NativeQ2Travel::Rerelease(rerelease))) => {
                let world = retained_rerelease.ok_or_else(|| {
                    source_failure("Native travel requires the same source module and client capacity")
                })?;
                self.create_rerelease_source(
                    native,
                    parts,
                    Some(RetainedRereleaseTravel {
                        visited: rerelease.visited,
                        world,
                    }),
                    native_loading,
                )
            }
            (Q2Edition::Rerelease, None) => self.create_rerelease_source(native, parts, None, native_loading),
            _ => Err(source_failure("Native travel edition changed")),
        }
    }

    /// Shared native service closures (donor `services` literal).
    fn native_service_parts(
        &self,
        parts: &NativeSourceParts,
        callbacks: &super::types::NativeQ2GuestCallbacks,
        frame_seconds: f64,
    ) -> NativeServiceParts {
        let print = callbacks.print.clone();
        let add_command = callbacks.add_command.clone();
        let debug_graph = callbacks.debug_graph.clone();
        NativeServiceParts {
            engine: self.q2_actor_host(
                &parts.source,
                parts.numeric,
                frame_seconds,
                super::source_transition::SourceLevelAuthority::PrimaryWorld,
                parts.player_identity.clone(),
            ),
            scene: Rc::new(SharedSceneAdapter {
                scene: self.scene(),
                bodies: self.bodies_handle(),
                actors: self.actors_handle(),
                simulation: self.weak(),
            }),
            admit: native_guest_admit(&parts.tables, &parts.source.provider),
            collision: native_guest_collision(&parts.tables),
            print: Box::new(move |text: &str| print(text)),
            command: Rc::new(|| super::classic_guest_services::GuestCommandLine {
                arguments: Vec::new(),
                args: String::new(),
            }),
            add_command: Box::new(move |text: &str| add_command(text)),
            debug_graph: Box::new(move |value: f64, color: i32| debug_graph(value, color)),
        }
    }

    /// Classic native Q2 source (donor classic half).
    pub fn create_classic_native_source(
        &self,
        native: &super::types::NativeQ2GuestOptions,
        parts: NativeSourceParts,
        retained: Option<RetainedClassicTravel>,
        native_loading: bool,
    ) -> Result<SourceRuntime, RuntimeError> {
        use super::classic_guest_services::ClassicGuestServicesOptions;
        use super::classic_guest_world::{ClassicGuestWorld, ClassicGuestWorldOptions};
        use crate::persistence::q2::classic_guest::ClassicOriginalSaveFiles;

        let callbacks = native.callbacks();
        let prepared = native
            .prepared_classic()
            .ok_or_else(|| source_failure("Classic native source requires a prepared classic guest"))?;
        let NativeSourceParts {
            tables,
            providers,
            numeric,
            cvars,
            map,
            requested_path,
            max_clients,
            ..
        } = parts;
        let source = parts.source;
        let service = self.native_service_parts(
            &NativeSourceParts {
                tables: tables.clone(),
                source: source.clone(),
                providers: providers.clone(),
                numeric,
                cvars: cvars.clone(),
                map: super::classic_guest_world::ClassicGuestMap {
                    map: map.map.clone(),
                    entities: map.entities.clone(),
                    spawn_point: map.spawn_point.clone(),
                },
                requested_path: requested_path.clone(),
                max_clients,
                player_identity: parts.player_identity.clone(),
            },
            callbacks,
            0.1,
        );
        let (world, files, visited) = match retained {
            Some(travel) => (Some(travel.world), travel.files, travel.visited),
            None => (
                None,
                ClassicOriginalSaveFiles::new(native_save_fallback(&callbacks.capabilities)),
                HashMap::new(),
            ),
        };
        let revisit = if cvar_is_zero(&cvars, "deathmatch") {
            visited.get(&requested_path).cloned()
        } else {
            None
        };
        match world {
            None => {
                let services = ClassicGuestServicesOptions {
                    primary_world: None,
                    pickup_profile: None,
                    pickups: Some(super::classic_guest_services::GuestPickupAdmission::new(
                        RuntimePickupAdmission::new(self.weak()),
                    )),
                    damage_provenance: Some(native_damage_provenance(&tables, providers)),
                    engine: service.engine,
                    scene: service.scene,
                    cvars,
                    numeric: qa_core::numeric::NumericOps::select(numeric).map_err(source_failure)?,
                    map_path: requested_path,
                    max_clients,
                    accepts_client: None,
                    admit: service.admit,
                    collision: service.collision,
                    print: service.print,
                    command: service.command,
                    add_command: service.add_command,
                    debug_graph: service.debug_graph,
                };
                let capabilities = qa_guest::runtime::windows::contracts::WindowsCapabilities {
                    open_file: Some(native_files_opener(&files, &callbacks.capabilities)),
                    ..callbacks.capabilities.clone()
                };
                let game = ClassicGuestWorld::create(ClassicGuestWorldOptions {
                    prepared: prepared.clone(),
                    services,
                    capabilities,
                    instruction_budget: None,
                })
                .map_err(source_failure)?;
                Ok(SourceRuntime::Q2Native(Q2NativeSource::Classic {
                    game,
                    files,
                    visited,
                    clients: HashMap::new(),
                }))
            }
            Some(mut world) => {
                let binding = super::classic_guest_services::ClassicGuestMapServices {
                    engine: service.engine,
                    scene: service.scene,
                    map_path: requested_path,
                    admit: service.admit,
                    collision: service.collision,
                    print: service.print,
                    command: service.command,
                    add_command: service.add_command,
                    debug_graph: service.debug_graph,
                    damage_provenance: Some(native_damage_provenance(&tables, providers)),
                    pickups: Some(super::classic_guest_services::GuestPickupAdmission::new(
                        RuntimePickupAdmission::new(self.weak()),
                    )),
                };
                if native_loading {
                    let loader = NativeTravelLoader::new(move |next_frame| {
                        let game = match revisit {
                            None => world
                                .travel_loading(map, binding, next_frame, None)
                                .map_err(|error| crate::persistence::PersistenceError::BadSave(error.to_string())),
                            Some(level) => files.with_travel_level(&level.level, |level_path| {
                                world
                                    .travel_loading(
                                        map,
                                        binding,
                                        next_frame,
                                        Some(classic_revisit(
                                            &tables,
                                            level_path.to_string(),
                                            level.state.configstrings.clone(),
                                            level.state.portals.clone(),
                                        )),
                                    )
                                    .map_err(|error| crate::persistence::PersistenceError::BadSave(error.to_string()))
                            }),
                        }
                        .map_err(source_failure)?;
                        Ok(SourceRuntime::Q2Native(Q2NativeSource::Classic {
                            game,
                            files,
                            visited,
                            clients: HashMap::new(),
                        }))
                    });
                    self.lock().pending_native_travel = Some(loader);
                    return Ok(SourceRuntime::Loading);
                }
                let game = match revisit {
                    None => world.travel(map, binding, None).map_err(source_failure)?,
                    Some(level) => files
                        .with_travel_level(&level.level, |level_path| {
                            world
                                .travel(
                                    map,
                                    binding,
                                    Some(classic_revisit(
                                        &tables,
                                        level_path.to_string(),
                                        level.state.configstrings.clone(),
                                        level.state.portals.clone(),
                                    )),
                                )
                                .map_err(|error| crate::persistence::PersistenceError::BadSave(error.to_string()))
                        })
                        .map_err(source_failure)?,
                };
                Ok(SourceRuntime::Q2Native(Q2NativeSource::Classic {
                    game,
                    files,
                    visited,
                    clients: HashMap::new(),
                }))
            }
        }
    }

    /// Rerelease native Q2 source (donor rerelease half).
    pub fn create_rerelease_source(
        &self,
        native: &super::types::NativeQ2GuestOptions,
        parts: NativeSourceParts,
        retained: Option<RetainedRereleaseTravel>,
        native_loading: bool,
    ) -> Result<SourceRuntime, RuntimeError> {
        use super::classic_guest_services::ClassicGuestServicesOptions;
        use super::q2_native_world::{prepared_native_primary, PreparedQ2NativeGuest};
        use super::rerelease_guest_services_contract::{
            RereleaseDebugShapesFn, RereleaseGuestClipboard, RereleaseGuestServicesOptions, RereleaseWorldTextFn,
        };
        use super::rerelease_guest_world::{RereleaseGuestRevisit, RereleaseGuestWorld, RereleaseGuestWorldOptions};

        let callbacks = native.callbacks();
        let prepared = native
            .prepared_rerelease()
            .ok_or_else(|| source_failure("Rerelease native source requires a prepared rerelease guest"))?;
        let local = native
            .local()
            .ok_or_else(|| source_failure("Rerelease native source requires local services"))?;
        let NativeSourceParts {
            tables,
            providers,
            numeric,
            cvars,
            map,
            requested_path,
            max_clients,
            ..
        } = parts;
        let source = parts.source;
        let rebuild = NativeSourceParts {
            tables: tables.clone(),
            source: source.clone(),
            providers: providers.clone(),
            numeric,
            cvars: cvars.clone(),
            map: super::classic_guest_world::ClassicGuestMap {
                map: map.map.clone(),
                entities: map.entities.clone(),
                spawn_point: map.spawn_point.clone(),
            },
            requested_path: requested_path.clone(),
            max_clients,
            player_identity: parts.player_identity.clone(),
        };
        let service = self.native_service_parts(&rebuild, callbacks, 0.025);
        let content = content_tag(&source.content);
        let shapes_tables = tables.clone();
        let debug_shapes: RereleaseDebugShapesFn = Box::new(move |event| {
            let lines: Vec<crate::debug::DebugLine> = event
                .lines
                .iter()
                .map(|line| crate::debug::DebugLine {
                    start: line.start,
                    end: line.end,
                    color: line.color,
                    depth_test: line.depth_test,
                })
                .collect();
            let _ = shapes_tables
                .sim()
                .submit_debug_shapes(&lines, event.lifetime_milliseconds);
        });
        let text_tables = tables.clone();
        let world_text: RereleaseWorldTextFn = Box::new(move |event| {
            use qa_client::text::ui_world::{WorldText, WorldTextFont, WorldTextInput, WorldTextOrientation};
            use qa_compat::q2::rerelease::world_text::{
                WorldTextFont as CompatFont, WorldTextOrientation as CompatOrientation,
            };
            let orientation = match event.text.orientation {
                CompatOrientation::Billboard => WorldTextOrientation::Billboard,
                CompatOrientation::Fixed { angles } => WorldTextOrientation::Fixed { angles },
            };
            let font = match event.text.font {
                CompatFont::Classic => WorldTextFont::Classic,
                CompatFont::Selected => WorldTextFont::Selected,
            };
            let input = WorldTextInput {
                text: event.text.text.clone(),
                origin: event.text.origin,
                color: event.text.color,
                cell_size: event.text.cell_size,
                distance_cull_factor: Some(event.text.distance_cull_factor),
                orientation,
                depth_test: event.text.depth_test,
                font,
            };
            let sim = text_tables.sim();
            let now = sim.time_seconds();
            let _ = sim
                .lock()
                .world_text_store
                .submit(WorldText { input, content }, now, f64::from(event.lifetime));
        });
        let clipboard = match local.clipboard {
            super::types::RereleaseClipboard::Internal => RereleaseGuestClipboard::Dedicated,
            super::types::RereleaseClipboard::System => RereleaseGuestClipboard::Client(Box::new(|text| {
                let _ = qa_platform::sdl::write_sdl_clipboard(text);
            })),
        };
        let foreign_damage = if prepared_native_primary(&PreparedQ2NativeGuest::Rerelease(prepared.clone())).is_some()
            && local.semantic_bindings.is_none()
        {
            Some(native_damage_provenance(&tables, providers.clone()))
        } else {
            None
        };
        let (world, visited) = match retained {
            Some(travel) => (Some(travel.world), travel.visited),
            None => (None, HashMap::new()),
        };
        let revisit = if cvar_is_zero(&cvars, "deathmatch") {
            visited.get(&requested_path).cloned()
        } else {
            None
        };
        let revisit_tables = tables.clone();
        let revisit_scene = self.scene();
        let make_revisit = move |level: &super::native_q2_rerelease_save::Q2RereleaseVisitedLevel| {
            let strings: HashMap<i32, String> = level
                .state
                .configstrings
                .iter()
                .map(|entry| (entry.index as i32, entry.value.clone()))
                .collect();
            let portals = level.state.portals.clone();
            let tables = revisit_tables.clone();
            let scene = revisit_scene.clone();
            RereleaseGuestRevisit {
                level: rr_source_save_to_host(&level.level),
                restore_server_state: Box::new(move |world: &mut RereleaseGuestWorld| {
                    world
                        .restore_configstrings(&strings)
                        .expect("Rerelease configstring restoration failed");
                    for entry in &portals {
                        tables.sim().lock().area_portals.insert(entry.portal, entry.open);
                        scene.set_area_portal_state(entry.portal, entry.open);
                    }
                }),
            }
        };
        match world {
            None => {
                let base = ClassicGuestServicesOptions {
                    primary_world: None,
                    pickup_profile: None,
                    pickups: Some(super::classic_guest_services::GuestPickupAdmission::new(
                        RuntimePickupAdmission::new(self.weak()),
                    )),
                    damage_provenance: Some(native_damage_provenance(&tables, providers)),
                    engine: service.engine,
                    scene: service.scene,
                    cvars,
                    numeric: qa_core::numeric::NumericOps::select(numeric).map_err(source_failure)?,
                    map_path: requested_path,
                    max_clients,
                    accepts_client: None,
                    admit: service.admit,
                    collision: service.collision,
                    print: service.print,
                    command: service.command,
                    add_command: service.add_command,
                    debug_graph: service.debug_graph,
                };
                let services = RereleaseGuestServicesOptions {
                    base,
                    frame_milliseconds: 25,
                    localize: local.localize.clone(),
                    clipboard,
                    debug_shapes,
                    world_text,
                    navigation: Box::new(C3RereleaseNavigation {
                        tables: tables.clone(),
                        provider: source.provider.clone(),
                    }),
                    semantic_bindings: local.semantic_bindings.clone(),
                    foreign_damage,
                };
                let game = RereleaseGuestWorld::create(RereleaseGuestWorldOptions {
                    prepared: prepared.clone(),
                    services,
                    capabilities: callbacks.capabilities.clone(),
                    instruction_budget: None,
                })
                .map_err(source_failure)?;
                Ok(SourceRuntime::Q2Native(Q2NativeSource::Rerelease {
                    game,
                    visited,
                    clients: HashMap::new(),
                }))
            }
            Some(mut world) => {
                let navigation_tables = tables.clone();
                let binding = super::rerelease_guest_services_contract::RereleaseGuestMapServices {
                    base: super::classic_guest_services::ClassicGuestMapServices {
                        engine: service.engine,
                        scene: service.scene,
                        map_path: requested_path,
                        admit: service.admit,
                        collision: service.collision,
                        print: service.print,
                        command: service.command,
                        add_command: service.add_command,
                        debug_graph: service.debug_graph,
                        damage_provenance: Some(native_damage_provenance(&tables, providers)),
                        pickups: Some(super::classic_guest_services::GuestPickupAdmission::new(
                            RuntimePickupAdmission::new(self.weak()),
                        )),
                    },
                    frame_milliseconds: 25,
                    localize: local.localize.clone(),
                    debug_shapes,
                    world_text,
                    navigation: Box::new(C3RereleaseNavigation {
                        tables: navigation_tables,
                        provider: source.provider.clone(),
                    }),
                    foreign_damage,
                };
                if native_loading {
                    let loader = NativeTravelLoader::new(move |next_frame| {
                        let game = match revisit {
                            None => world.travel_loading(map, binding, next_frame, None),
                            Some(level) => world.travel_loading(map, binding, next_frame, Some(make_revisit(&level))),
                        }
                        .map_err(source_failure)?;
                        Ok(SourceRuntime::Q2Native(Q2NativeSource::Rerelease {
                            game,
                            visited,
                            clients: HashMap::new(),
                        }))
                    });
                    self.lock().pending_native_travel = Some(loader);
                    return Ok(SourceRuntime::Loading);
                }
                let game = match revisit {
                    None => world.travel(map, binding, None).map_err(source_failure)?,
                    Some(level) => world
                        .travel(map, binding, Some(make_revisit(&level)))
                        .map_err(source_failure)?,
                };
                Ok(SourceRuntime::Q2Native(Q2NativeSource::Rerelease {
                    game,
                    visited,
                    clients: HashMap::new(),
                }))
            }
        }
    }
}

/// Donor `restoreQ2Attack` (C10).
///
/// Resolves the saved actor references against the restored registry and
/// converts the persistence checkpoint into the simulation-native
/// [`super::events::AttackProvenance`]. Provider spellings parse via
/// `parse_provider`; out-of-range integers and unknown cause spellings fail
/// the restore.
#[allow(dead_code)]
fn restore_q2_attack(
    checkpoint: &crate::persistence::q2::foundation::Q2AttackCheckpoint,
    actors: &SessionActorRegistry,
) -> Result<super::events::AttackProvenance, RuntimeError> {
    use super::events::{AttackArmorEffect, AttackCause, EnvironmentHazard, Q2NativeGame};
    use crate::persistence::q2::foundation::{Q2AttackCause, Q2NativeCause};
    let resolve = |saved: Option<qa_core::identity::SavedActorId>| -> Result<Option<ActorId>, RuntimeError> {
        saved.map(|saved| reference_saved_actor(actors, saved)).transpose()
    };
    let cause = match &checkpoint.cause {
        Q2AttackCause::Q1 {
            death_type,
            armor_effect,
        } => AttackCause::Q1 {
            death_type: death_type.clone(),
            armor_effect: armor_effect
                .as_deref()
                .map(|effect| match effect {
                    "bypass" => Ok(AttackArmorEffect::Bypass),
                    "half-effectiveness" => Ok(AttackArmorEffect::HalfEffectiveness),
                    _ => range(format!("Unknown attack armor effect: {effect}")),
                })
                .transpose()?,
        },
        Q2AttackCause::Q2 {
            means_of_death,
            damage_flags,
            native,
        } => AttackCause::Q2 {
            means_of_death: i32::try_from(*means_of_death)
                .map_err(|_| RuntimeError::Range("Attack means of death is out of range".to_string()))?,
            damage_flags: i32::try_from(*damage_flags)
                .map_err(|_| RuntimeError::Range("Attack damage flags are out of range".to_string()))?,
            native: native
                .as_ref()
                .map(|native| match native {
                    Q2NativeCause::Classic { game, value } => {
                        let game = match game.as_str() {
                            "base" => Q2NativeGame::Base,
                            "xatrix" => Q2NativeGame::Xatrix,
                            "rogue" => Q2NativeGame::Rogue,
                            "ctf" => Q2NativeGame::Ctf,
                            _ => return range(format!("Unknown native attack game: {game}")),
                        };
                        Ok(super::events::Q2NativeCause::Classic {
                            game,
                            value: i32::try_from(*value)
                                .map_err(|_| RuntimeError::Range("Native attack value is out of range".to_string()))?,
                        })
                    }
                    Q2NativeCause::Rerelease {
                        id,
                        friendly_fire,
                        no_point_loss,
                    } => Ok(super::events::Q2NativeCause::Rerelease {
                        id: i32::try_from(*id)
                            .map_err(|_| RuntimeError::Range("Native attack cause id is out of range".to_string()))?,
                        friendly_fire: *friendly_fire,
                        no_point_loss: *no_point_loss,
                    }),
                })
                .transpose()?,
        },
        Q2AttackCause::Q3 {
            means_of_death,
            damage_flags,
        } => AttackCause::Q3 {
            means_of_death: i32::try_from(*means_of_death)
                .map_err(|_| RuntimeError::Range("Attack means of death is out of range".to_string()))?,
            damage_flags: i32::try_from(*damage_flags)
                .map_err(|_| RuntimeError::Range("Attack damage flags are out of range".to_string()))?,
        },
        Q2AttackCause::Environment { hazard } => AttackCause::Environment {
            hazard: match hazard.as_str() {
                "fall" => EnvironmentHazard::Fall,
                "drown" => EnvironmentHazard::Drown,
                "lava" => EnvironmentHazard::Lava,
                "slime" => EnvironmentHazard::Slime,
                "crush" => EnvironmentHazard::Crush,
                "trigger" => EnvironmentHazard::Trigger,
                _ => return range(format!("Unknown attack hazard: {hazard}")),
            },
        },
    };
    Ok(super::events::AttackProvenance {
        sequence: checkpoint.sequence,
        time: checkpoint.time,
        attacker: resolve(checkpoint.attacker)?,
        inflictor: resolve(checkpoint.inflictor)?,
        originating_projectile: resolve(checkpoint.originating_projectile)?,
        weapon: checkpoint.weapon.clone(),
        weapon_provider: parse_provider(&checkpoint.weapon_provider)?,
        damage_powerup_owner: checkpoint
            .damage_powerup_owner
            .as_deref()
            .map(parse_provider)
            .transpose()?,
        combat_provider: parse_provider(&checkpoint.combat_provider)?,
        inventory_provider: parse_provider(&checkpoint.inventory_provider)?,
        movement_provider: parse_provider(&checkpoint.movement_provider)?,
        cause,
    })
}
// ---------------------------------------------------------------------------
// C11 part 2a: Q1 actor host (donor `q1ActorHost`, runtime.ts 2018-2059) plus
// the pre-2168 helpers the C11 range calls.
// ---------------------------------------------------------------------------

/// Q1 punch-angle store over the shared simulation (C11).
struct C11Q1Punch {
    tables: C11Tables,
}

impl qa_content::q1::foundation::host::Q1PunchAngles for C11Q1Punch {
    fn read(&mut self, actor: &ActorId) -> Vec3 {
        self.tables
            .sim()
            .lock()
            .q1_punch
            .read(actor)
            .unwrap_or(qa_core::math::vec3(0.0, 0.0, 0.0))
    }

    fn write(&mut self, actor: &ActorId, angles: Vec3) {
        let _ = self.tables.sim().lock().q1_punch.write(actor, angles);
    }
}

/// Q1 weapon-behavior port over the shared simulation (C11).
struct C11Q1WeaponBehavior {
    tables: C11Tables,
}

impl qa_content::q1::foundation::host::Q1WeaponBehaviorPort for C11Q1WeaponBehavior {
    fn controls_trajectory(&mut self, projectile: &ActorId) -> bool {
        self.tables.sim().peek().weapon_behavior.controls_trajectory(projectile)
    }

    fn launch(
        &mut self,
        input: &qa_content::q1::foundation::host::Q1WeaponBehaviorLaunch,
    ) -> Option<qa_content::q1::foundation::host::Q1TrajectoryUpdate> {
        let launch = super::weapon_behavior_runtime::WeaponBehaviorLaunch {
            projectile: input.projectile.clone(),
            shooter: input.shooter.clone(),
            weapon: input.weapon.clone(),
            role: input.role,
            time_seconds: input.time_seconds,
            body: q1_body_to_world(&input.body),
        };
        let update = self.tables.sim().lock().weapon_behavior.launch(&launch).ok()??;
        Some(qa_content::q1::foundation::host::Q1TrajectoryUpdate {
            origin: update.origin,
            velocity: update.velocity,
            angles: update.angles,
        })
    }

    fn step(
        &mut self,
        projectile: &OwnedActor,
        body: &Q1Body,
        time_seconds: f64,
    ) -> Option<qa_content::q1::foundation::host::Q1TrajectoryUpdate> {
        let world_body = q1_body_to_world(body);
        let update = self
            .tables
            .sim()
            .lock()
            .weapon_behavior
            .step(projectile, &world_body, time_seconds)
            .ok()??;
        Some(qa_content::q1::foundation::host::Q1TrajectoryUpdate {
            origin: update.origin,
            velocity: update.velocity,
            angles: update.angles,
        })
    }
}

/// Q1 entity registration over the shared simulation (C11).
struct C11Q1Register {
    tables: C11Tables,
    content: ContentId,
}

impl qa_content::q1::foundation::host::Q1RegisterEntity for C11Q1Register {
    fn register(&mut self, _game: &mut qa_content::q1::foundation::entity_services::Q1EntityServices, id: &ActorId) {
        let sim = self.tables.sim();
        let Some(actor) = sim.actors.borrow().resolve_owned(id) else {
            return;
        };
        let _ = sim.register_actor_execution(RuntimeExecutionEntry::Q1 {
            actor,
            content: self.content.clone(),
        });
    }
}

impl SharedSimulation {
    /// Build a Q1 actor host over the shared session (donor `q1ActorHost`,
    /// runtime.ts 2018-2059).
    ///
    /// The donor passes a runtime bundle (`numeric`, shared `random`,
    /// `now`/`frameSeconds`/`schedule` closures); the Rust bundle is
    /// [`ActorHostRuntime`](super::source_hosts::ActorHostRuntime). The
    /// tables are the C11 adapters; the hook closures rejoin the session
    /// through the weak handle with narrow borrow scopes. Hook bodies that
    /// belong to other lanes are seams: `check_client` (C4
    /// `q1VisibilityEye`, donor 3261). `control_player` rejoins
    /// [`SharedSimulation::control_player`]. `step_pusher` reports no
    /// displacement: driving the
    /// native pusher needs physics-lane ports (`candidates`, `numeric`,
    /// `test_position`, `push_entity`, `unlink` on `SharedPhysics`) that do
    /// not exist yet, the equipment arenas that call this factory carry no
    /// map pushers, and the foundation currently discards the step result.
    /// `original_pickups` is `None`: the shared admission twin is a
    /// predicate without grant execution, and the equipment arenas touch no
    /// map pickups.
    pub fn q1_actor_host(
        &self,
        source: &ProviderReference,
        runtime: super::source_hosts::ActorHostRuntime,
        authority: super::source_transition::SourceLevelAuthority,
    ) -> qa_content::q1::foundation::host::Q1FoundationHost {
        use super::source_hosts::{create_q1_actor_host, Q1ActorHostBindings};
        let tables = C11Tables {
            actors: self.actors_handle(),
            bodies: self.bodies_handle(),
            weak: self.weak(),
        };
        let content = source.content.clone();
        let map_provider = self.peek().recipe.map.entities.provider.clone();
        let super::source_hosts::ActorHostRuntime {
            numeric,
            random,
            now,
            frame_seconds: _,
            schedule,
        } = runtime;
        // Donor 2020 + 2029: the host runtime's stream is one object shared
        // between the fresh movement and the random hook.
        let random = Rc::new(RefCell::new(random));
        let numeric_ops = qa_core::numeric::NumericOps::select(numeric).expect("provider numeric profile selects");
        let fresh_movement: Option<
            Rc<RefCell<qa_world::movement::q1::monsters::Q1MonsterMovement<RuntimeMonsterServices>>>,
        > = if source.provider == map_provider {
            None
        } else {
            Some(Rc::new(RefCell::new(
                qa_world::movement::q1::monsters::Q1MonsterMovement::new(RuntimeMonsterServices::new(
                    self.weak(),
                    self.actors_handle(),
                    self.bodies_handle(),
                    numeric_ops,
                    Some(Rc::clone(&random)),
                )),
            )))
        };
        let now: Rc<dyn Fn() -> f64> = now.into();
        let schedule: Rc<RefCell<super::source_hosts::ActorHostSchedule>> = Rc::new(RefCell::new(schedule));

        let walk_tables = tables.clone();
        let walk_movement = fresh_movement.clone();
        let walk_move = Box::new(move |actor: &OwnedActor, yaw: f64, distance: f64| -> bool {
            if let Some(movement) = walk_movement.as_ref() {
                return movement.borrow_mut().walk_move(actor, yaw, distance).unwrap_or(false);
            }
            walk_tables
                .sim()
                .lock()
                .q1_movement
                .borrow_mut()
                .walk_move(actor, yaw, distance)
                .unwrap_or(false)
        });
        let yaw_tables = tables.clone();
        let yaw_movement = fresh_movement.clone();
        let change_yaw = Box::new(move |actor: &OwnedActor| {
            if let Some(movement) = yaw_movement.as_ref() {
                movement.borrow_mut().change_yaw(actor);
                return;
            }
            yaw_tables.sim().lock().q1_movement.borrow_mut().change_yaw(actor);
        });
        let goal_tables = tables.clone();
        let goal_movement = fresh_movement.clone();
        let move_to_goal = Box::new(
            move |actor: &OwnedActor,
                  goal: &ActorId,
                  distance: f64,
                  mode: Option<qa_content::q1::foundation::host::Q1GoalMode>| {
                let contact = matches!(mode, Some(qa_content::q1::foundation::host::Q1GoalMode::Contact));
                if let Some(movement) = goal_movement.as_ref() {
                    let _ = movement.borrow_mut().move_to_goal(actor, goal, distance, contact);
                    return;
                }
                let _ = goal_tables
                    .sim()
                    .lock()
                    .q1_movement
                    .borrow_mut()
                    .move_to_goal(actor, goal, distance, contact);
            },
        );
        let bottom_tables = tables.clone();
        let bottom_movement = fresh_movement.clone();
        let check_bottom = Box::new(move |actor: &ActorId| -> bool {
            if let Some(movement) = bottom_movement.as_ref() {
                return movement.borrow_mut().check_bottom(actor);
            }
            bottom_tables.sim().lock().q1_movement.borrow_mut().check_bottom(actor)
        });

        let hook_random = Rc::clone(&random);
        let random_hook = Box::new(move || f64::from(hook_random.borrow_mut().next_unit()));

        let think_schedule = schedule.clone();
        let schedule_think = Box::new(move |actor: &OwnedActor, due: f64| {
            think_schedule.borrow_mut()(actor, Some(due));
        });
        let cancel_think = Box::new(move |actor: &OwnedActor| {
            schedule.borrow_mut()(actor, None);
        });

        let emit_tables = tables.clone();
        let emit_content = content.clone();
        let emit_now = now.clone();
        let emit = Box::new(move |event: qa_content::q1::foundation::types::Q1Event| {
            use qa_content::q1::foundation::types::Q1Event;
            let sim = emit_tables.sim();
            match &event {
                Q1Event::Weapon {
                    player,
                    view_model,
                    frame,
                    attack,
                    ..
                } => {
                    sim.lock().view_models.insert(
                        player.clone(),
                        ViewModelEntry {
                            path: view_model.clone(),
                            frame: *frame,
                            q2: None,
                        },
                    );
                    if let Some(attack) = attack {
                        let attack = *attack;
                        let owner = sim
                            .peek()
                            .player_states
                            .iter()
                            .find(|(_, entry)| entry.actor.id() == player)
                            .map(|(owned, _)| owned.clone());
                        if let Some(owner) = owner {
                            let mut state = sim.lock();
                            let services = match &state.source {
                                SourceRuntime::Q1 { services, .. } => Some(services.clone()),
                                _ => None,
                            };
                            if let Some(services) = services {
                                if let Ok(game) = services.try_borrow() {
                                    if let Some(character) = state.q1_characters.get_mut(&owner) {
                                        character.attack(&game, attack).expect("q1 character attack failed");
                                    }
                                }
                            }
                        }
                    }
                }
                Q1Event::Intermission { origin, angles, .. } => {
                    let players: Vec<OwnedActor> = sim.peek().player_states.keys().cloned().collect();
                    for owned in &players {
                        let id = owned.id().clone();
                        let _ = sim.update_player(&id, |entry| {
                            entry.view_height = 0.0;
                        });
                        sim.set_player_movement(
                            &id,
                            qa_content::q2::base::player::types::Q2PlayerMovementChange::Freeze {
                                origin: *origin,
                                angles: *angles,
                            },
                            false,
                        );
                    }
                }
                Q1Event::TeleportPlayer {
                    player,
                    angles,
                    lock_until,
                } => {
                    if sim.peek().grapple.is_some() {
                        let _ = sim
                            .peek()
                            .grapple
                            .as_ref()
                            .expect("grapple checked above")
                            .release(player);
                    }
                    let _ = sim.update_player(player, |entry| {
                        entry.view_angles = *angles;
                        if let super::player_input_application::MovementState::Q1Netquake(state) = &mut entry.state {
                            state.view_angles = *angles;
                            state.teleport_time_seconds = *lock_until;
                        }
                    });
                }
                _ => {}
            }
            sim.lock().events.emit_owned(
                None,
                &emit_content,
                super::types::SourcePresentationEvent::Q1(event),
                qa_core::time::SourceTime::Seconds(emit_now() as f32),
                None,
            );
        });

        let transition_tables = tables.clone();
        let transition = Box::new(move |intent: qa_content::q1::foundation::gameplay::TransitionIntent| {
            let cause = match &intent {
                qa_content::q1::foundation::gameplay::TransitionIntent::CampaignLevel { cause, .. } => cause.clone(),
                _ => None,
            };
            let sim = transition_tables.sim();
            let (campaign, match_provider) = {
                let state = sim.peek();
                (state.recipe.campaign.clone(), state.recipe.r#match.provider.clone())
            };
            let out = super::source_transition::source_level_transition(
                q1_intent_to_session(&intent),
                &campaign,
                &match_provider,
                authority,
            );
            sim.lock().transitions.push(session_intent_to_q1(out, cause));
        });

        let players_tables = tables.clone();
        let players = Box::new(move || players_tables.sim().players());
        let classname_tables = tables.clone();
        let classname = Box::new(move |actor: &ActorId| classname_tables.sim().classname(actor));
        let powerup_tables = tables.clone();
        let powerup = Box::new(
            move |actor: &OwnedActor, powerup: qa_content::q1::foundation::types::Q1Powerup, expires: f64| {
                powerup_tables
                    .sim()
                    .powerup(actor, powerup, expires)
                    .expect("q1 powerup failed");
            },
        );
        // Missing siblings: C4 ports `q1VisibilityEye` (donor 3261) plus the
        // visibility check; the seam reports no visible client until then.
        let check_client = Box::new(|_: &OwnedActor| -> Option<ActorId> { None });
        let monster_tables = tables.clone();
        let monster_target = Box::new(
            move |actor: &ActorId| -> Option<qa_content::monsters::MonsterTargetObservation> {
                monster_tables
                    .sim()
                    .monster_target(actor)
                    .expect("q1 monster target failed")
            },
        );
        let control_tables = tables.clone();
        let control_player = Box::new(
            move |actor: &ActorId, control: &qa_content::q1::foundation::host::Q1CutsceneControl| {
                control_tables
                    .sim()
                    .control_player(actor, control)
                    .expect("q1 control player failed");
            },
        );

        let gravity_tables = tables.clone();
        let set_gravity = Box::new(move |actor: &ActorId, scale: f64| {
            let sim = gravity_tables.sim();
            let scaled = (sim.peek().physics.gravity() * scale).trunc();
            let _ = sim.update_player(actor, |player| {
                player.gravity_multiplier = scale;
                match &mut player.state {
                    super::player_input_application::MovementState::Q2Classic(state) => {
                        state.gravity = scaled;
                    }
                    super::player_input_application::MovementState::Q2Rerelease(state) => {
                        state.gravity = scaled;
                    }
                    super::player_input_application::MovementState::Q3(state) => {
                        state.gravity = scaled;
                    }
                    _ => {}
                }
            });
        });

        let target_tables = tables.clone();
        let source_target = Box::new(
            move |actor: &ActorId| -> qa_content::q1::foundation::host::Q1SourceTarget {
                c11_q1_source_target(&target_tables, actor)
            },
        );

        let pusher_tables = tables.clone();
        let step_pusher = Box::new(
            move |actor: &ActorId, _elapsed: f64| -> qa_content::q1::foundation::host::Q1PusherStep {
                use qa_content::q1::foundation::host::{Q1PusherStatus, Q1PusherStep};
                let _ = pusher_tables.sim();
                Q1PusherStep {
                    actor: actor.clone(),
                    status: Q1PusherStatus::Moved,
                    moved: Vec::new(),
                }
            },
        );

        let bindings = Q1ActorHostBindings {
            actors: Box::new(C11Q1Actors { tables: tables.clone() }),
            bodies: Box::new(C11Q1Bodies { tables: tables.clone() }),
            callbacks: Box::new(C11Q1Callbacks {
                bound: std::collections::HashSet::new(),
            }),
            combat: Box::new(C11Q1Combat {
                tables: tables.clone(),
                adjustments: std::collections::HashMap::new(),
            }),
            inventory: Box::new(C11Q1Inventory { tables: tables.clone() }),
            original_pickups: None,
            punch_angles: Some(Box::new(C11Q1Punch { tables: tables.clone() })),
            weapon_behavior: Some(Box::new(C11Q1WeaponBehavior { tables: tables.clone() })),
            register_entity: Some(Box::new(C11Q1Register {
                tables: tables.clone(),
                content: content.clone(),
            })),
            source_damage_modifier: None,
            source_damage_powerup_owner: None,
            random: random_hook,
            walk_move,
            change_yaw,
            move_to_goal,
            check_bottom,
            schedule_think,
            cancel_think,
            emit,
            transition,
            players,
            check_client,
            classname,
            powerup,
            step_pusher,
            weapon_impact: None,
            weapon_volume: None,
            monster_target: Some(monster_target),
            set_gravity: Some(set_gravity),
            control_player: Some(control_player),
            source_target: Some(source_target),
            powerup_expires: None,
            source_damage_multiplier: None,
        };
        let world = c11_actor_host_world(self, numeric);
        let _ = tables;
        create_q1_actor_host(bindings, world)
    }
}
// ---------------------------------------------------------------------------
// C3 §3e: Q2 product source construction (donor `createSource` Q2
// fallthrough, runtime.ts 2998-3112).
//
// Missing siblings: the q2 lane owns `createQ2ProductRuntime`
// (`Q2ProductRuntime` is still the opaque seam). The donor hooks close over
// the simulation, but the port hook types are `fn` pointers without
// captures, so the composition common, match selection, spawn modules,
// rerelease hooks, and server-cvar binding ride with the q2 lane's
// host-trait routing design. This section ports the live effects:
// program validation, the server console sequence, and game-services
// construction.
// ---------------------------------------------------------------------------

/// Q2 product server console plus retained save state.
struct Q2ProductCvars {
    /// Server console variables.
    cvars: qa_core::cvar::CvarRegistry,
    /// Retained source save cvars for the post-bind restore.
    saved: Option<qa_world::save::value::SaveJson>,
}

impl SharedSimulation {
    /// Q2 product server console (donor `serverCvars` sequence).
    #[allow(clippy::too_many_arguments)]
    fn q2_product_server_cvars(
        &self,
        edition: qa_content::q2::foundation::host::Q2Edition,
        source_registry: Option<qa_core::cvar::CvarRegistry>,
        source_archive: Option<&[qa_core::cvar::CvarArchiveEntry]>,
        restore: Option<&super::save::SimulationSaveImage>,
        q2_cvars: Option<&[super::types::CvarNameValue]>,
        q2_next_server: Option<&str>,
        profile: Option<&crate::settings::server::ServerProfile>,
    ) -> Result<Q2ProductCvars, RuntimeError> {
        use qa_content::q2::foundation::host::Q2Edition;
        let registry_injected = source_registry.is_some();
        let mut cvars = source_registry.unwrap_or_else(|| {
            qa_core::cvar::CvarRegistry::new(if edition == Q2Edition::Classic {
                qa_core::cmd::Dialect::Q2Classic
            } else {
                qa_core::cmd::Dialect::Q2Rerelease
            })
        });
        self.lock().q2_server_registry = Some(Rc::new(RefCell::new(cvars.clone())));
        let match_provider = provider_text(&self.peek().recipe.r#match.provider);
        crate::settings::server::register_q2_server_cvars(&mut cvars, &match_provider).map_err(source_failure)?;
        if restore.is_none() && !registry_injected {
            cvars
                .apply_archive(source_archive.unwrap_or(&[]))
                .map_err(source_failure)?;
        }
        for variable in q2_cvars.unwrap_or(&[]) {
            cvars
                .set(&variable.name, &variable.value, true)
                .map_err(source_failure)?;
        }
        let (mode, skill) = {
            let state = self.peek();
            (state.options_mode, state.options_skill)
        };
        cvars.set("skill", &skill.to_string(), true).map_err(source_failure)?;
        cvars
            .set(
                "deathmatch",
                if mode == super::types::SimulationMode::Deathmatch {
                    "1"
                } else {
                    "0"
                },
                true,
            )
            .map_err(source_failure)?;
        cvars
            .set(
                "coop",
                if mode == super::types::SimulationMode::Coop {
                    "1"
                } else {
                    "0"
                },
                true,
            )
            .map_err(source_failure)?;
        self.initialize_server_settings(&mut cvars, profile, restore.is_some())?;
        if restore.is_none() {
            cvars
                .set("nextserver", q2_next_server.unwrap_or(""), true)
                .map_err(source_failure)?;
        }
        let saved = match restore {
            Some(image) => super::save::saved_source_cvars(image).map_err(source_failure)?,
            None => None,
        };
        if let Some(saved) = saved.as_ref() {
            crate::settings::server::restore_q2_server_cvars(&mut cvars, saved).map_err(source_failure)?;
        }
        Ok(Q2ProductCvars { cvars, saved })
    }

    /// Q2 product actor-host frame seconds (donor `actorRuntime`).
    fn q2_product_frame_seconds(&self, entities: &ProviderReference) -> Result<f64, RuntimeError> {
        let state = self.peek();
        let timing = provider_timing(&state.recipe, &provider_text(&entities.provider))?;
        match &timing.clock {
            qa_core::time::ClockProfile::Q2Classic => Ok(0.1),
            qa_core::time::ClockProfile::Q2Rerelease { frame_milliseconds } => Ok(frame_milliseconds / 1000.0),
            _ => Ok(state.source_frame.elapsed.as_seconds_f64()),
        }
    }

    /// Classic Q2 product source (donor classic half of the fallthrough).
    pub fn create_classic_q2_source(&self, inputs: CreateSourceInputs<'_>) -> Result<SourceRuntime, RuntimeError> {
        use qa_content::q2::foundation::host::Q2Edition;
        let CreateSourceInputs {
            source_registry,
            source_archive,
            restore,
            q2_cvars,
            q2_next_server,
            player_identity,
            profile,
            ..
        } = inputs;
        let program = self.q2_product_program()?;
        if program.as_deref() != Some("baseq2")
            && program.as_deref() != Some("xatrix")
            && program.as_deref() != Some("rogue")
        {
            return Err(source_failure(format!(
                "Unsupported Q2 classic program {}",
                program.as_deref().unwrap_or("undefined")
            )));
        }
        self.create_q2_product_source(
            Q2Edition::Classic,
            source_registry,
            source_archive,
            restore,
            q2_cvars,
            q2_next_server,
            player_identity,
            profile,
        )
    }

    /// Rerelease Q2 product source (donor rerelease half of the fallthrough).
    pub fn create_rerelease_q2_source(&self, inputs: CreateSourceInputs<'_>) -> Result<SourceRuntime, RuntimeError> {
        use qa_content::q2::foundation::host::Q2Edition;
        let CreateSourceInputs {
            source_registry,
            source_archive,
            restore,
            q2_cvars,
            q2_next_server,
            player_identity,
            profile,
            ..
        } = inputs;
        let program = self.q2_product_program()?;
        if program.as_deref() != Some("baseq2")
            && program.as_deref() != Some("xatrix")
            && program.as_deref() != Some("rogue")
            && program.as_deref() != Some("mg2")
            && program.as_deref() != Some("n64")
        {
            return Err(source_failure(format!(
                "Unsupported Q2 rerelease program {}",
                program.as_deref().unwrap_or("undefined")
            )));
        }
        self.create_q2_product_source(
            Q2Edition::Rerelease,
            source_registry,
            source_archive,
            restore,
            q2_cvars,
            q2_next_server,
            player_identity,
            profile,
        )
    }

    /// Selected Q2 source program with CTF normalization (donor `program`).
    fn q2_product_program(&self) -> Result<Option<String>, RuntimeError> {
        let state = self.peek();
        let program = qa_content::catalog::selected_source_program(&state.recipe.execution, &state.recipe.map.entities)
            .map_err(source_failure)?;
        Ok(program.map(|program| {
            if program == "ctf" || program == "lmctf" {
                "baseq2".to_string()
            } else {
                program
            }
        }))
    }

    /// Shared Q2 product construction (donor `common` + `create` tail).
    #[allow(clippy::too_many_arguments)]
    fn create_q2_product_source(
        &self,
        edition: qa_content::q2::foundation::host::Q2Edition,
        source_registry: Option<qa_core::cvar::CvarRegistry>,
        source_archive: Option<&[qa_core::cvar::CvarArchiveEntry]>,
        restore: Option<&super::save::SimulationSaveImage>,
        q2_cvars: Option<&[super::types::CvarNameValue]>,
        q2_next_server: Option<&str>,
        player_identity: Option<super::types::PlayerIdentityLookup>,
        profile: Option<&crate::settings::server::ServerProfile>,
    ) -> Result<SourceRuntime, RuntimeError> {
        use qa_content::q2::foundation::host::{Q2GameOptions, Q2GameServices, Q2Mode};
        let Q2ProductCvars { mut cvars, saved } = self.q2_product_server_cvars(
            edition,
            source_registry,
            source_archive,
            restore,
            q2_cvars,
            q2_next_server,
            profile,
        )?;
        let (entities, combat, inventory, movement, requested_path, campaign, mode, skill, max_clients) = {
            let state = self.peek();
            let recipe = &state.recipe;
            (
                recipe.map.entities.clone(),
                recipe.combat.clone(),
                recipe.inventory.clone(),
                recipe.movement.clone(),
                recipe.map.geometry.requested_path.clone(),
                recipe
                    .campaign
                    .mission()
                    .map(|mission| mission.provider.clone())
                    .unwrap_or_else(|| recipe.map.entities.provider.clone()),
                state.options_mode,
                state.options_skill,
                state.options_max_clients,
            )
        };
        let timing = {
            let state = self.peek();
            provider_timing(&state.recipe, &provider_text(&entities.provider))?.numeric
        };
        let frame_seconds = self.q2_product_frame_seconds(&entities)?;
        let host = self.q2_actor_host(
            &entities,
            timing,
            frame_seconds,
            super::source_transition::SourceLevelAuthority::PrimaryWorld,
            player_identity,
        );
        let game = Q2GameServices::new(
            host,
            Q2GameOptions {
                edition,
                map_name: source_map_name(&requested_path),
                skill,
                mode: match mode {
                    super::types::SimulationMode::Singleplayer => Q2Mode::Singleplayer,
                    super::types::SimulationMode::Coop => Q2Mode::Coop,
                    super::types::SimulationMode::Deathmatch => Q2Mode::Deathmatch,
                },
                deathmatch_flags: crate::settings::server::q2_source_deathmatch_flags(&cvars),
                max_clients: max_clients as u32,
                provider: entities.provider.clone(),
                damage_powerup_owner: None,
                source_damage_modifier: None,
                campaign,
                combat_provider: combat.provider.clone(),
                inventory_provider: inventory.provider.clone(),
                movement_provider: movement.provider.clone(),
            },
            Vec::new(),
        );
        let product = Q2ProductRuntime::new();
        cvars.set_server_active(true);
        if let Some(saved) = saved.as_ref() {
            crate::settings::server::restore_q2_server_cvars(&mut cvars, saved).map_err(source_failure)?;
        }
        Ok(SourceRuntime::Q2 {
            product,
            game: Rc::new(RefCell::new(game)),
        })
    }
}

