// C11 part 2a-fix: transition converters, monster-move services, anchor.
// ---------------------------------------------------------------------------

/// Convert a Q1 foundation transition intent to the session intent (C11).
fn q1_intent_to_session(
    intent: &qa_content::q1::foundation::gameplay::TransitionIntent,
) -> qa_world::session::TransitionIntent {
    use qa_content::q1::foundation::gameplay::TransitionIntent as Q1;
    use qa_world::session::{MissionGate as SessionGate, TransitionIntent as Session};
    let convert_gates = |gates: &[qa_content::q1::foundation::gameplay::MissionGate]| -> Vec<SessionGate> {
        gates
            .iter()
            .map(|gate| SessionGate {
                objective: gate.objective.clone(),
                satisfied: gate.satisfied,
            })
            .collect()
    };
    match intent {
        Q1::CampaignLevel {
            campaign,
            map,
            spawn_point,
            gates,
            ..
        } => Session::CampaignLevel {
            campaign: campaign.clone(),
            map: map.clone(),
            spawn: spawn_point.clone(),
            gates: convert_gates(gates),
        },
        Q1::CampaignComplete { campaign, gates } => Session::CampaignComplete {
            campaign: campaign.clone(),
            gates: convert_gates(gates),
        },
        Q1::RoundComplete { match_provider, winner } => Session::RoundComplete {
            match_id: match_provider.clone(),
            winner: winner.clone(),
        },
        Q1::MatchRotation { match_provider, map } => Session::MatchRotation {
            match_id: match_provider.clone(),
            map: map.clone(),
        },
    }
}

/// Convert a session transition intent back to the Q1 foundation intent
/// (C11). The trigger cause has no session twin; the caller carries it
/// across the rewrite.
fn session_intent_to_q1(
    intent: qa_world::session::TransitionIntent,
    cause: Option<ActorId>,
) -> qa_content::q1::foundation::gameplay::TransitionIntent {
    use qa_content::q1::foundation::gameplay::{MissionGate as Q1Gate, TransitionIntent as Q1};
    use qa_world::session::TransitionIntent as Session;
    let convert_gates = |gates: Vec<qa_world::session::MissionGate>| -> Vec<Q1Gate> {
        gates
            .into_iter()
            .map(|gate| Q1Gate {
                objective: gate.objective,
                satisfied: gate.satisfied,
            })
            .collect()
    };
    match intent {
        Session::CampaignLevel {
            campaign,
            map,
            spawn,
            gates,
        } => Q1::CampaignLevel {
            campaign,
            map,
            spawn_point: spawn,
            gates: convert_gates(gates),
            cause,
        },
        Session::CampaignComplete { campaign, gates } => Q1::CampaignComplete {
            campaign,
            gates: convert_gates(gates),
        },
        Session::RoundComplete { match_id, winner } => Q1::RoundComplete {
            match_provider: match_id,
            winner,
        },
        Session::MatchRotation { match_id, map } => Q1::MatchRotation {
            match_provider: match_id,
            map,
        },
    }
}

/// Map a scene trace result to the Q1 movement trace (C11).
fn c11_trace_to_q1(trace: &super::physics::TraceResult) -> qa_world::movement::q1::types::Q1Trace {
    use qa_world::movement::q1::types::Q1Trace;
    if let super::physics::TraceResult::Q1(q1) = trace {
        return q1.clone();
    }
    Q1Trace {
        fraction: trace.fraction(),
        end: trace.end(),
        start_solid: trace.start_solid(),
        all_solid: trace.all_solid(),
        contact: *trace.contact(),
        hit: trace.hit().clone(),
        in_open: false,
        in_water: false,
        source_plane: trace.source_plane(),
        surface_flags: None,
    }
}

impl qa_world::movement::q1::monsters::Q1MonsterMoveServices for RuntimeMonsterServices {
    fn numeric(&self) -> qa_core::numeric::NumericOps {
        self.numeric
    }

    fn trace(
        &mut self,
        actor: &ActorId,
        start: Vec3,
        end: Vec3,
        bounds: Option<Bounds>,
    ) -> qa_world::movement::q1::types::Q1Trace {
        let sim = self
            .simulation()
            .expect("equipment arena used after the simulation dropped");
        let result = sim.peek().physics.trace(
            &qa_content::q2::foundation::host::Q2TraceRequest {
                start,
                end,
                bounds,
                ignore: Some(actor.clone()),
                mask: 0,
                exclude: Vec::new(),
            },
            super::physics::PhysicsFamily::Q1,
        );
        c11_trace_to_q1(&result)
    }

    fn point_contents(&mut self, _actor: &ActorId, point: Vec3) -> i32 {
        let sim = self
            .simulation()
            .expect("equipment arena used after the simulation dropped");
        sim.contents(point, ContentsFamily::Q1).expect("q1 contents failed")
    }

    fn next_random(&mut self) -> i32 {
        if let Some(random) = self.random.as_ref() {
            let drawn = random.borrow_mut().next_integer() as i32;
            return drawn;
        }
        let sim = self
            .simulation()
            .expect("equipment arena used after the simulation dropped");
        let drawn = sim.lock().random.next_integer() as i32;
        drawn
    }

    fn read(&mut self, actor: &ActorId) -> Option<qa_world::movement::q1::monsters::Q1MonsterMoveState> {
        use qa_world::movement::q1::monsters::Q1MonsterMoveState;
        let actors = self.actors.borrow();
        let body = self.bodies.borrow().read(actors.inner(), actor)?;
        let sim = self
            .simulation()
            .expect("equipment arena used after the simulation dropped");
        let state = sim.peek();
        let qa_app_state = &state.source;
        let services = match qa_app_state {
            SourceRuntime::Q1 { services, .. } => services,
            _ => return None,
        };
        let game = services.try_borrow().ok()?;
        let entity = game.entity_ref(actor)?;
        Some(Q1MonsterMoveState {
            origin: body.origin,
            angles: body.angles,
            bounds: body.bounds,
            absolute_bounds: qa_world::body::translated_body_bounds(&body),
            flags: entity.movement_flags,
            ground: body
                .ground
                .map(|ground| qa_world::movement::types::TraceHit::Actor { actor: ground })
                .unwrap_or(qa_world::movement::types::TraceHit::None),
            ideal_yaw: entity.ideal_yaw,
            yaw_speed: entity.yaw_speed,
            enemy: entity.monster.as_ref().and_then(|monster| monster.enemy.clone()),
        })
    }

    fn read_target(&mut self, actor: &ActorId) -> Option<qa_world::movement::q1::monsters::Q1MonsterTarget> {
        let actors = self.actors.borrow();
        let body = self.bodies.borrow().read(actors.inner(), actor)?;
        Some(qa_world::movement::q1::monsters::Q1MonsterTarget {
            origin: body.origin,
            absolute_bounds: qa_world::body::translated_body_bounds(&body),
        })
    }

    fn write(&mut self, actor: &OwnedActor, state: qa_world::movement::q1::monsters::Q1MonsterMoveState) {
        {
            let actors = self.actors.borrow();
            let mut bodies = self.bodies.borrow_mut();
            if let Some(mut body) = bodies.read(actors.inner(), actor.id()) {
                body.origin = state.origin;
                body.angles = state.angles;
                let _ = bodies.write(actors.inner(), actor, body);
            }
        }
        let sim = self
            .simulation()
            .expect("equipment arena used after the simulation dropped");
        let peeked = sim.peek();
        if let SourceRuntime::Q1 { services, .. } = &peeked.source {
            if let Ok(mut game) = services.try_borrow_mut() {
                let _ = game.update_entity(actor.id(), |entity| {
                    entity.ideal_yaw = state.ideal_yaw;
                    entity.yaw_speed = state.yaw_speed;
                    entity.movement_flags = state.flags;
                    if let Some(monster) = entity.monster.as_mut() {
                        monster.enemy = state.enemy.clone();
                    }
                });
            }
        }
    }

    fn link(&mut self, actor: &OwnedActor, touch_triggers: bool) {
        {
            let actors = self.actors.borrow();
            let _ = self.bodies.borrow_mut().link(actors.inner(), actor, None);
        }
        if touch_triggers {
            let sim = self
                .simulation()
                .expect("equipment arena used after the simulation dropped");
            sim.lock().physics.touch_triggers(actor);
        }
    }
}

impl SharedSimulation {
    /// Anchor classification for grapple attachment (donor `grappleAnchor`,
    /// runtime.ts 2274-2283).
    ///
    /// The donor also consults the scene's linked-actor collision; the Rust
    /// scene twin exposes no actor collision, so actors without a physics
    /// entry read as unattachable.
    fn grapple_anchor(&self, actor: &ActorId) -> qa_content::q2::equipment::grapple_services::GrappleAnchor {
        use super::physics::SolidKind;
        use qa_content::q2::equipment::grapple_services::GrappleAnchor;
        if self.world_actor().as_ref() == Some(actor) {
            return GrappleAnchor::World;
        }
        if self.actors.borrow().resolve_owned(actor).is_none() {
            return GrappleAnchor::None;
        }
        let solid = self.peek().physics.solid_of(actor).map(|entry| entry.solid);
        if solid.is_none() || matches!(solid, Some(SolidKind::None)) {
            return GrappleAnchor::None;
        }
        if self.player_client(actor).is_some() {
            return if self.equipment_player_available(actor) {
                GrappleAnchor::Player
            } else {
                GrappleAnchor::Corpse
            };
        }
        if self.classname(actor) == "bodyque" {
            return GrappleAnchor::Corpse;
        }
        match solid {
            Some(SolidKind::Brush) => GrappleAnchor::Brush,
            Some(SolidKind::Box) => GrappleAnchor::Box,
            _ => GrappleAnchor::None,
        }
    }
}
// ---------------------------------------------------------------------------
// C3 §3d: Q1 source construction (donor `createSource` q1-bsp branch,
// runtime.ts 2924-2968).
//
// Missing siblings: the actor host needs C11's Q1 table adapters (C11 is
// building them in the C11 2a region; only test mocks implement the
// `Q1SessionActorRegistry` family today), and the composition needs a
// `Send` `Q1CompositionServices` routing to the simulation (the q1 lane
// owns that design; its only reference is the `pub(crate)` recording
// fake). This section ports the live prefix verbatim — program
// validation, the console sequence, foundation options, and source
// selection — and reports the composition block as an error.
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Q1 source console (donor q1-bsp `cvars` sequence).
    fn q1_source_cvars(
        &self,
        source_registry: Option<qa_core::cvar::CvarRegistry>,
        source_archive: Option<&[qa_core::cvar::CvarArchiveEntry]>,
        restore: Option<&super::save::SimulationSaveImage>,
        profile: Option<&crate::settings::server::ServerProfile>,
    ) -> Result<qa_core::cvar::CvarRegistry, RuntimeError> {
        let registry_injected = source_registry.is_some();
        let mut cvars =
            source_registry.unwrap_or_else(|| qa_core::cvar::CvarRegistry::new(qa_core::cmd::Dialect::Q1Netquake));
        if restore.is_none() && !registry_injected {
            cvars
                .apply_archive(source_archive.unwrap_or(&[]))
                .map_err(source_failure)?;
        }
        let (mode, skill) = {
            let state = self.peek();
            (state.options_mode, state.q1_campaign.skill)
        };
        if !registry_injected {
            for (name, value) in [
                ("skill", skill.to_string()),
                (
                    "deathmatch",
                    if mode == super::types::SimulationMode::Deathmatch {
                        "1".to_string()
                    } else {
                        "0".to_string()
                    },
                ),
                (
                    "coop",
                    if mode == super::types::SimulationMode::Coop {
                        "1".to_string()
                    } else {
                        "0".to_string()
                    },
                ),
                ("teamplay", "0".to_string()),
                ("sv_gravity", "800".to_string()),
                ("sv_maxspeed", "320".to_string()),
                ("samelevel", "0".to_string()),
                ("timelimit", "0".to_string()),
                ("fraglimit", "0".to_string()),
                ("gamecfg", "0".to_string()),
                ("sv_cheats", "0".to_string()),
                ("footsteps", "1".to_string()),
            ] {
                cvars.register(name, &value, 0).map_err(source_failure)?;
            }
        }
        cvars.set("skill", &skill.to_string(), true).map_err(source_failure)?;
        cvars
            .set(
                "deathmatch",
                if mode == super::types::SimulationMode::Deathmatch {
                    "1"
                } else {
                    "0"
                },
                true,
            )
            .map_err(source_failure)?;
        cvars
            .set(
                "coop",
                if mode == super::types::SimulationMode::Coop {
                    "1"
                } else {
                    "0"
                },
                true,
            )
            .map_err(source_failure)?;
        self.initialize_server_settings(&mut cvars, profile, restore.is_some())?;
        if let Some(image) = restore {
            if let Some(saved) = super::save::saved_source_cvars(image).map_err(source_failure)? {
                crate::settings::server::restore_cvar_save_state(&mut cvars, &saved).map_err(source_failure)?;
            }
        }
        let horde = provider_text(&self.peek().recipe.r#match.provider) == "q1:horde";
        if horde && restore.is_none() {
            if cvars.get("horde").is_none() {
                cvars.register("horde", "0", 0).map_err(source_failure)?;
            }
            cvars.set("horde", "1", true).map_err(source_failure)?;
        }
        Ok(cvars)
    }

    /// Q1 source program selection (donor `program` validation).
    fn q1_source_program(&self) -> Result<qa_content::q1::composition::types::Q1SourceProgram, RuntimeError> {
        use qa_content::q1::composition::types::Q1SourceProgram;
        let state = self.peek();
        let program = qa_content::catalog::selected_source_program(&state.recipe.execution, &state.recipe.map.entities)
            .map_err(source_failure)?;
        match program.as_deref() {
            Some("id1") => Ok(Q1SourceProgram::Id1),
            Some("hipnotic") => Ok(Q1SourceProgram::Hipnotic),
            Some("rogue") => Ok(Q1SourceProgram::Rogue),
            Some("dopa") => Ok(Q1SourceProgram::Dopa),
            Some("mg1") => Ok(Q1SourceProgram::Mg1),
            Some("mg3") => Ok(Q1SourceProgram::Mg3),
            Some("ctf") => Ok(Q1SourceProgram::Ctf),
            _ => Err(source_failure(format!(
                "Unsupported Q1 source program {}",
                program.as_deref().unwrap_or("undefined")
            ))),
        }
    }

    /// Q1 source (donor q1-bsp branch).
    pub fn create_q1_source(&self, inputs: CreateSourceInputs<'_>) -> Result<SourceRuntime, RuntimeError> {
        use qa_content::q1::composition::types::{Q1SourceProgram, Q1SourceSelection};
        use qa_content::q1::foundation::types::{Q1Edition, Q1FoundationOptions};
        let CreateSourceInputs {
            source_registry,
            source_archive,
            restore,
            profile,
            ..
        } = inputs;
        let program = self.q1_source_program()?;
        let cvars = self.q1_source_cvars(source_registry, source_archive, restore, profile)?;
        let (entities, combat, movement, inventory, campaign, mode, max_clients, q1_campaign) = {
            let state = self.peek();
            let recipe = &state.recipe;
            (
                recipe.map.entities.clone(),
                recipe.combat.clone(),
                recipe.movement.clone(),
                recipe.inventory.clone(),
                recipe
                    .campaign
                    .mission()
                    .map(|mission| mission.provider.clone())
                    .unwrap_or_else(|| recipe.map.entities.provider.clone()),
                state.options_mode,
                state.options_max_clients,
                state.q1_campaign.clone(),
            )
        };
        let edition = if entities.content.as_str().contains(":rerelease:") {
            Q1Edition::Rerelease
        } else {
            Q1Edition::Classic
        };
        let _options = Q1FoundationOptions {
            provider: Some(entities.provider.clone()),
            precache_program: None,
            edition,
            physics_edition: Some(self.q1_physics_edition()),
            skill: q1_campaign.skill,
            deathmatch: if mode == super::types::SimulationMode::Deathmatch {
                1
            } else {
                0
            },
            coop: mode == super::types::SimulationMode::Coop,
            campaign,
            combat_provider: combat.provider.clone(),
            movement_provider: movement.provider.clone(),
            inventory_provider: inventory.provider.clone(),
            gravity: 800.0,
            max_clients: Some(max_clients as i32),
            no_exit: None,
            teamplay: None,
            aim_threshold: None,
        };
        let _selection = Q1SourceSelection {
            program,
            campaign: Box::new(q1_campaign),
            registered: true,
            official_campaign: program == Q1SourceProgram::Id1,
        };
        let _cvars = cvars;
        let _entities = entities;
        Err(source_failure(
            "Q1 source composition requires the q1 actor-host table adapters and Send services routing",
        ))
    }
}
