/// Source player identity patch (donor `setSourcePlayerIdentity` identity).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct SourcePlayerIdentity {
    /// Player name.
    pub name: Option<String>,
    /// Player skin.
    pub skin: Option<String>,
    /// Shirt color.
    pub shirt: Option<i32>,
    /// Pants color.
    pub pants: Option<i32>,
}

/// Field-of-view update mode (donor `setPlayerFieldOfView` mode).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PlayerFovMode {
    /// Ordinary change.
    Change,
    /// Restore path (cameras keep the effective FOV).
    Restore,
}

/// Parse a userinfo string into pairs (Vec view over C4 `q2_userinfo`).
fn q2_userinfo_vec(source: &str) -> Vec<(String, String)> {
    q2_userinfo(source).into_iter().collect()
}

/// Read one userinfo value.
fn userinfo_get<'a>(values: &'a [(String, String)], key: &str) -> Option<&'a str> {
    values
        .iter()
        .find(|(name, _)| name == key)
        .map(|(_, value)| value.as_str())
}

/// Set one userinfo value, preserving first-insertion order.
fn userinfo_set(values: &mut Vec<(String, String)>, key: &str, value: &str) {
    if let Some(entry) = values.iter_mut().find(|(name, _)| name == key) {
        entry.1 = value.to_string();
    } else {
        values.push((key.to_string(), value.to_string()));
    }
}

/// Serialize userinfo pairs (donor `` `\\${key}\\${value}` `` join).
fn userinfo_serialize(values: &[(String, String)]) -> String {
    let mut out = String::new();
    for (key, value) in values {
        out.push('\\');
        out.push_str(key);
        out.push('\\');
        out.push_str(value);
    }
    out
}

/// Parse a leading decimal integer like JS `parseInt(value, 10)`.
fn parse_int_prefix(value: &str) -> Option<i32> {
    let text = value.trim_start();
    let (sign, digits) = match text.strip_prefix('-') {
        Some(rest) => (-1i64, rest),
        None => (1i64, text.strip_prefix('+').unwrap_or(text)),
    };
    let mut acc: i64 = 0;
    let mut count = 0;
    for byte in digits.bytes() {
        if !byte.is_ascii_digit() {
            break;
        }
        acc = acc.saturating_mul(10).saturating_add(i64::from(byte - b'0'));
        count += 1;
    }
    if count == 0 {
        return None;
    }
    Some((sign.saturating_mul(acc)).clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32)
}

/// Validate an int32 match score (donor `sourceScore`).
fn source_score(value: f64) -> Result<i32, RuntimeError> {
    if value.fract() != 0.0 || !(f64::from(i32::MIN)..=f64::from(i32::MAX)).contains(&value) {
        return Err(RuntimeError::Failure(
            "Original score requires an int32 value".to_string(),
        ));
    }
    Ok(value as i32)
}

/// Resolve a declared team-change command (donor `sourceTeamCommand`).
fn source_team_command(
    teams: &[(Option<String>, Vec<String>)],
    team: Option<&str>,
) -> Result<Vec<String>, RuntimeError> {
    let command = teams.iter().find(|(entry, _)| entry.as_deref() == team);
    match command {
        Some((_, arguments)) => Ok(arguments.clone()),
        None => Err(RuntimeError::Failure(format!(
            "The original source has no declared command for team {}",
            team.unwrap_or("unassigned")
        ))),
    }
}

/// Map a Q1 weapon to its base weapon, if any (donor `isQ1BaseWeapon` guard).
fn q1_base_weapon(
    weapon: qa_content::q1::foundation::types::Q1Weapon,
) -> Option<qa_content::q1::foundation::types::Q1BaseWeapon> {
    use qa_content::q1::foundation::types::{Q1BaseWeapon, Q1Weapon};
    match weapon {
        Q1Weapon::Axe => Some(Q1BaseWeapon::Axe),
        Q1Weapon::Shotgun => Some(Q1BaseWeapon::Shotgun),
        Q1Weapon::Supershotgun => Some(Q1BaseWeapon::Supershotgun),
        Q1Weapon::Nailgun => Some(Q1BaseWeapon::Nailgun),
        Q1Weapon::Supernailgun => Some(Q1BaseWeapon::Supernailgun),
        Q1Weapon::Grenadelauncher => Some(Q1BaseWeapon::Grenadelauncher),
        Q1Weapon::Rocketlauncher => Some(Q1BaseWeapon::Rocketlauncher),
        Q1Weapon::Lightning => Some(Q1BaseWeapon::Lightning),
        _ => None,
    }
}

impl SharedSimulation {
    /// Read an arsenal snapshot for a movement player (donor `arsenal`).
    fn read_player_arsenal(&self, player: &MovementPlayer) -> Result<ArsenalState, RuntimeError> {
        use super::arsenal::selected::SelectedArsenal as SelectedArsenalBehavior;
        let state = self.peek();
        if let Some(selected) = state.selected_arsenal.as_ref() {
            let arsenal = match selected {
                SelectedArsenal::Q1(arsenal) => arsenal.read(player.actor.id()),
                SelectedArsenal::Q2(arsenal) => arsenal.read(player.actor.id()),
                SelectedArsenal::Q3(arsenal) => arsenal.read(player.actor.id()),
            };
            return Ok(arsenal);
        }
        match &state.source {
            SourceRuntime::Q3 { .. } => {
                let mut arsenal = player.arsenal.clone();
                let registry = self.actors.borrow();
                arsenal.ammo = state
                    .inventory
                    .entries(registry.inner(), player.actor.id())
                    .iter()
                    .map(|entry| qa_world::movement::types::InventoryEntry {
                        item: entry.item.clone(),
                        count: entry.count,
                    })
                    .collect();
                Ok(arsenal)
            }
            SourceRuntime::QuakeC { game, .. } => game
                .client_arsenal(player.actor.id())
                .map_err(|error| RuntimeError::Failure(error.to_string())),
            SourceRuntime::Q1 { services, .. } => {
                let game = services.borrow();
                let player_state = game
                    .player_ref(player.actor.id())
                    .ok_or_else(|| RuntimeError::Failure("Q1 player has no arsenal".to_string()))?;
                let registry = self.actors.borrow();
                Ok(ArsenalState {
                    provider: state.weapon_provider.provider.clone(),
                    active_weapon: Some(game.weapon_item(player_state.weapon)),
                    state: WeaponState::Q1 {
                        frame: player_state.weapon_frame,
                        attack_finished_seconds: player_state.attack_finished,
                        source_weapon: q1_base_weapon(player_state.weapon)
                            .map(qa_content::q1::foundation::types::q1_weapon_bit)
                            .unwrap_or(0),
                    },
                    ammo: state
                        .inventory
                        .entries(registry.inner(), player.actor.id())
                        .iter()
                        .map(|entry| qa_world::movement::types::InventoryEntry {
                            item: entry.item.clone(),
                            count: entry.count,
                        })
                        .collect(),
                })
            }
            SourceRuntime::Q2 { game, .. } => {
                let provider = state.weapon_provider.provider.clone();
                let game = Rc::clone(game);
                drop(state);
                let mut services = game.borrow_mut();
                super::arsenal::q2::project_q2_arsenal(player.actor.id(), &provider, &mut services)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))
            }
            _ => Err(RuntimeError::Failure(
                "Arsenal accessed before source admission".to_string(),
            )),
        }
    }

    /// Weapon slot projection (donor `weaponSlot`).
    pub fn weapon_slot(
        &self,
        actor: &ActorId,
    ) -> Result<super::weapon_slot_projection::WeaponSlotProjection, RuntimeError> {
        let model = self
            .primary_presentations()
            .into_iter()
            .find(|presentation| presentation.view_weapon && presentation.actor == *actor);
        self.slot_projection(actor, model)
    }

    /// Primary presentation models (donor `primaryPresentations`, donor 5812).
    fn primary_presentations(&self) -> Vec<super::types::SimulationPresentation> {
        let mut result = Vec::new();
        self.push_native_presentations(&mut result);
        if matches!(self.peek().source, SourceRuntime::Q3 { .. }) {
            // `create_q3_source` always fails, so no live Q3 game exists to
            // present; the arm contributes nothing until the q3 lane lands
            // the source host.
        }
        if let Some(presentations) = self
            .peek()
            .selected_q3_source
            .as_ref()
            .map(|selected| selected.presentations())
        {
            result.extend(presentations);
        }
        self.push_execution_presentations(&mut result);
        self.push_player_presentations(&mut result);
        self.push_detached_presentations(&mut result);
        self.push_view_model_presentations(&mut result);
        result
    }

    /// Q1 alpha/scale presentation fields (donor `q1VisualFields`).
    fn q1_visual_fields(alpha: f64, scale: f64) -> (f64, f64) {
        (
            if alpha == 0.0 {
                1.0
            } else {
                (alpha as f32).clamp(0.0, 1.0) as f64
            },
            if scale == 0.0 { 1.0 } else { scale as f32 as f64 },
        )
    }

    /// Blank presentation row filled by each arm below.
    fn blank_presentation(
        actor: ActorId,
        content: ContentId,
        family: GameFamily,
        path: String,
    ) -> super::types::SimulationPresentation {
        super::types::SimulationPresentation {
            actor,
            content,
            held_weapon: None,
            family,
            path,
            frame: 0,
            old_frame: 0,
            origin: zero(),
            angles: zero(),
            scale: 1.0,
            visible: true,
            view_weapon: false,
            native_held_weapon: false,
            weapon_item: None,
            replaces_body: false,
            render_source_client: false,
            flare: None,
            back_lerp: None,
            skin: 0,
            skin_path: None,
            indexed_skin: None,
            player_colors: None,
            effects: 0,
            render_flags: 0,
            previous_origin: None,
            model_beam: None,
            shader_beam: None,
            model_attachments: None,
            model_anchor: None,
            q3_grapple_cable: None,
            alpha: None,
            q3_weapon: None,
        }
    }

    /// Whether a selected arsenal covers an actor (donor
    /// `selectedArsenal?.has(...) === true`).
    fn selected_arsenal_has(&self, actor: &ActorId) -> bool {
        use super::arsenal::selected::SelectedArsenal as FamilyArsenal;
        let state = self.peek();
        let Some(selected) = state.selected_arsenal.as_ref() else {
            return false;
        };
        match selected {
            SelectedArsenal::Q1(arsenal) => arsenal.has(actor),
            SelectedArsenal::Q2(arsenal) => arsenal.has(actor),
            SelectedArsenal::Q3(arsenal) => arsenal.has(actor),
        }
    }

    /// Native Q2 entity and gun presentations (donor `primaryPresentations`
    /// q2-native arm).
    fn push_native_presentations(&self, result: &mut Vec<super::types::SimulationPresentation>) {
        let content = self.peek().recipe.map.entities.content.clone();
        let clients: Vec<(ClientId, OwnedActor)> = {
            let state = self.peek();
            let SourceRuntime::Q2Native(native) = &state.source else {
                return;
            };
            match native {
                Q2NativeSource::Classic { clients, .. } | Q2NativeSource::Rerelease { clients, .. } => clients
                    .iter()
                    .map(|(client, actor)| (client.clone(), actor.clone()))
                    .collect(),
            }
        };
        let classic = matches!(
            self.peek().source,
            SourceRuntime::Q2Native(Q2NativeSource::Classic { .. })
        );
        if classic {
            let rows = {
                let mut state = self.lock();
                let SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) = &mut state.source else {
                    panic!("Native presentations lost their source owner");
                };
                let states = game.entity_states().expect("native entity states failed");
                let mut rows = Vec::with_capacity(states.len());
                for state in states {
                    let info = game
                        .entity_info(u32::from(state.number))
                        .expect("native entity info failed");
                    let appearance = game
                        .model_appearance(u32::from(state.number))
                        .expect("native model appearance failed");
                    rows.push((state, info, appearance));
                }
                rows
            };
            for (state, info, appearance) in rows {
                let Some(actor) = info.actor.clone() else { continue };
                if state.number == 0 || !info.active || info.server_flags & 1 != 0 {
                    continue;
                }
                let mut model =
                    Self::blank_presentation(actor.clone(), content.clone(), GameFamily::Q2, appearance.path.clone());
                model.frame = state.frame;
                model.old_frame = state.frame;
                model.skin = appearance.skin;
                model.skin_path = appearance.skin_path.clone();
                model.effects = state.effects as i32;
                model.render_flags = state.render_effects as i32;
                model.origin = q2_vec3(&state.origin);
                model.previous_origin = Some(q2_vec3(&state.old_origin));
                model.angles = q2_vec3(&state.angles);
                model.alpha = Some(1.0);
                if !appearance.path.is_empty() {
                    result.push(model.clone());
                }
                for (index, path) in appearance.attached_models.iter().enumerate() {
                    if path.is_empty() {
                        continue;
                    }
                    let mut attached = model.clone();
                    attached.path = path.clone();
                    attached.skin = 0;
                    attached.skin_path = None;
                    attached.native_held_weapon = index == 0 && self.selected_arsenal_has(&actor);
                    result.push(attached);
                }
            }
        } else {
            let rows = {
                let mut state = self.lock();
                let SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) = &mut state.source else {
                    panic!("Native presentations lost their source owner");
                };
                let states = game.entity_states().expect("native entity states failed");
                let mut rows = Vec::with_capacity(states.len());
                for state in states {
                    let info = game
                        .entity_info(u32::from(state.base.number))
                        .expect("native entity info failed");
                    let appearance = game
                        .model_appearance(u32::from(state.base.number))
                        .expect("native model appearance failed");
                    rows.push((state, info, appearance));
                }
                rows
            };
            for (state, info, appearance) in rows {
                let Some(actor) = info.actor.clone() else { continue };
                if state.base.number == 0 || !info.active || info.server_flags & 1 != 0 {
                    continue;
                }
                let mut model =
                    Self::blank_presentation(actor.clone(), content.clone(), GameFamily::Q2, appearance.path.clone());
                model.frame = state.base.frame;
                model.old_frame = i32::from(state.old_frame);
                model.skin = appearance.skin;
                model.skin_path = appearance.skin_path.clone();
                model.effects = i32::try_from(state.effects).expect("native effects exceed shared presentation");
                model.render_flags = state.base.render_effects as i32;
                model.origin = q2_vec3(&state.base.origin);
                model.previous_origin = Some(q2_vec3(&state.base.old_origin));
                model.angles = q2_vec3(&state.base.angles);
                model.scale = if state.scale != 0.0 { state.scale } else { 1.0 };
                model.alpha = Some(if state.alpha != 0.0 {
                    state.alpha
                } else if state.base.render_effects & 32 != 0 {
                    0.3
                } else {
                    1.0
                });
                if !appearance.path.is_empty() {
                    result.push(model.clone());
                }
                for (index, path) in appearance.attached_models.iter().enumerate() {
                    if path.is_empty() {
                        continue;
                    }
                    let mut attached = model.clone();
                    attached.path = path.clone();
                    attached.skin = 0;
                    attached.skin_path = None;
                    attached.native_held_weapon = index == 0 && self.selected_arsenal_has(&actor);
                    result.push(attached);
                }
            }
        }
        for (client, actor) in &clients {
            if self.selected_arsenal_has(actor.id()) {
                continue;
            }
            let (gun_index, gun_frame, gun_skin, gun_offset, gun_angles, path) = {
                let mut state = self.lock();
                match &mut state.source {
                    SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => {
                        let player = game
                            .player_state(client.slot() + 1)
                            .expect("native player state failed");
                        let strings = game.configstrings().expect("native configstrings failed");
                        let path = strings.get(&(32 + player.view.gun_index)).cloned().unwrap_or_default();
                        (
                            player.view.gun_index,
                            player.view.gun_frame,
                            0,
                            q2_vec3(&player.view.gun_offset),
                            q2_vec3(&player.view.gun_angles),
                            path,
                        )
                    }
                    SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => {
                        let player = game
                            .player_state(client.slot() + 1)
                            .expect("native player state failed");
                        let strings = game.configstrings().expect("native configstrings failed");
                        let path = strings.get(&(62 + player.view.gun_index)).cloned().unwrap_or_default();
                        (
                            player.view.gun_index,
                            player.view.gun_frame,
                            player.gun_skin,
                            q2_vec3(&player.view.gun_offset),
                            q2_vec3(&player.view.gun_angles),
                            path,
                        )
                    }
                    _ => panic!("Native presentations lost their source owner"),
                }
            };
            if gun_index == 0 || path.is_empty() {
                continue;
            }
            let view = self.player_view(actor.id()).expect("native gun view failed");
            let mut model = Self::blank_presentation(actor.id().clone(), content.clone(), GameFamily::Q2, path);
            model.frame = gun_frame;
            model.old_frame = gun_frame;
            model.skin = gun_skin;
            model.origin = add(
                add(
                    view.origin,
                    Vec3 {
                        x: 0.0,
                        y: 0.0,
                        z: view.view_height as f32,
                    },
                ),
                gun_offset,
            );
            model.angles = add(view.angles, gun_angles);
            model.view_weapon = true;
            result.push(model);
        }
    }

    /// Actor-execution entity presentations (donor `primaryPresentations`
    /// execution arm).
    fn push_execution_presentations(&self, result: &mut Vec<super::types::SimulationPresentation>) {
        let entries: Vec<(ActorId, RuntimeExecutionEntry)> = self
            .peek()
            .actor_executions
            .iter()
            .map(|(actor, entry)| (actor.clone(), entry.clone()))
            .collect();
        let geometry = self.peek().recipe.map.geometry.requested_path.clone();
        for (actor, entry) in &entries {
            match entry {
                RuntimeExecutionEntry::QuakeC { .. }
                | RuntimeExecutionEntry::Q3 { .. }
                | RuntimeExecutionEntry::Q3Source { .. } => continue,
                RuntimeExecutionEntry::Q1 { .. } | RuntimeExecutionEntry::Q2 { .. } => {}
            }
            let Some(body) = self.bodies().read(actor) else {
                continue;
            };
            if self
                .peek()
                .selected_monsters
                .as_ref()
                .is_some_and(|monsters| !monsters.active(actor))
            {
                continue;
            }
            if self.player(actor).is_some() {
                continue;
            }
            if matches!(entry, RuntimeExecutionEntry::Q1 { .. }) {
                let Some((entity, _)) = self.q1_motion_entity(actor) else {
                    continue;
                };
                if entity.model.is_empty() || entity.model == geometry {
                    continue;
                }
                let (alpha, scale) = Self::q1_visual_fields(entity.number("alpha"), entity.number("scale"));
                let mut model = Self::blank_presentation(
                    actor.clone(),
                    entry.content().clone(),
                    GameFamily::Q1,
                    entity.model.clone(),
                );
                model.frame = entity.frame;
                model.old_frame = entity.frame;
                model.skin = entity.skin;
                model.effects = entity.effects;
                model.origin = body.origin;
                model.angles = body.angles;
                model.scale = scale;
                model.alpha = Some(alpha);
                result.push(model);
            } else {
                let resolved = self.q2_presentation_entity(actor);
                let Some((entity, edition)) = resolved else { continue };
                if entity.classname == "worldspawn" {
                    continue;
                }
                let flare = entity.flare();
                if entity.model.is_empty() && flare.is_none() {
                    continue;
                }
                let over = self.peek().source_models.get(actor).cloned();
                let frame = over.as_ref().map(|over| over.frame).unwrap_or(entity.frame);
                let old_frame = over.as_ref().map(|over| over.old_frame).unwrap_or(entity.old_frame);
                let beam =
                    edition == qa_content::q2::foundation::host::Q2Edition::Rerelease && entity.render_flags & 128 != 0;
                let mut model = Self::blank_presentation(
                    actor.clone(),
                    entry.content().clone(),
                    GameFamily::Q2,
                    entity.model.clone(),
                );
                model.flare = flare;
                model.frame = frame;
                model.old_frame = if old_frame == -1 { frame } else { old_frame };
                model.skin = over.as_ref().map(|over| over.skin).unwrap_or(entity.skin);
                model.effects = over.as_ref().map(|over| over.effects).unwrap_or(entity.effects) as i32;
                model.render_flags = over
                    .as_ref()
                    .map(|over| over.render_flags)
                    .unwrap_or(entity.render_flags);
                model.alpha = Some(over.as_ref().map(|over| over.alpha).unwrap_or(entity.alpha));
                model.origin = body.origin;
                model.angles = body.angles;
                model.previous_origin = Some(if beam { entity.pos2 } else { body.origin });
                if beam {
                    model.model_beam = Some(super::types::ModelBeam {
                        segment_length: f64::from(entity.frame),
                    });
                }
                model.scale = over.as_ref().map(|over| over.scale).unwrap_or(1.0);
                model.visible = entity.server_flags & 1 == 0;
                result.push(model);
            }
        }
    }

    /// Resolve a live Q2 entity plus edition for presentations.
    fn q2_presentation_entity(
        &self,
        actor: &ActorId,
    ) -> Option<(
        qa_content::q2::foundation::host::Q2Entity,
        qa_content::q2::foundation::host::Q2Edition,
    )> {
        if let Some(game) = self.q2_game_services() {
            let game = game.borrow();
            if let Some(entity) = game.entity(actor) {
                return Some((entity.clone(), game.options.edition));
            }
        }
        let state = self.peek();
        for source in state.monster_sources.values() {
            if let SelectedMonsterSource::Q2 { game, .. } = source {
                if let Some(entity) = game.entity(actor) {
                    return Some((entity.clone(), game.options.edition));
                }
            }
        }
        None
    }

    /// Player body presentations (donor `primaryPresentations` player arm).
    fn push_player_presentations(&self, result: &mut Vec<super::types::SimulationPresentation>) {
        let players: Vec<MovementPlayer> = self.peek().player_states.values().cloned().collect();
        let appearance = self.peek().recipe.character.appearance.clone();
        let model_name = provider_text(&appearance.provider)
            .rsplit('/')
            .next()
            .unwrap_or("male")
            .to_string();
        let q1_services = self.q1_services();
        let q2_game = self.q2_game_services();
        for player in &players {
            if player.character == GameFamily::Q3 || player.intermission || player.cutscene.is_some() {
                continue;
            }
            let actor = player.actor.id();
            let Some(body) = self.bodies().read(actor) else {
                continue;
            };
            let owned = player.actor.clone();
            let q2_entity = self
                .peek()
                .q2_characters
                .get(&owned)
                .map(|character| character.entity.clone())
                .or_else(|| {
                    if player.character == GameFamily::Q2 {
                        q2_game.as_ref().and_then(|game| game.borrow().entity(actor).cloned())
                    } else {
                        None
                    }
                });
            let gibbed = self.player_gibbed(actor);
            let q1_player = q1_services
                .as_ref()
                .and_then(|services| services.borrow().player_ref(actor).cloned());
            let colors = if player.character == GameFamily::Q1 {
                match &self.peek().source {
                    SourceRuntime::Q1 { composition, .. } => {
                        composition.client(actor).map(|client| (client.shirt(), client.pants()))
                    }
                    _ => None,
                }
            } else {
                None
            };
            let (alpha, scale) = q1_player
                .map(|player| Self::q1_visual_fields(player.alpha, player.scale))
                .unwrap_or((1.0, 1.0));
            let q1_model = self
                .peek()
                .q1_characters
                .get(&owned)
                .map(|character| character.presentation().model);
            let path = q2_entity
                .as_ref()
                .map(|entity| entity.model.clone())
                .filter(|model| !model.is_empty())
                .or_else(|| q1_model.filter(|model| !model.is_empty()))
                .unwrap_or_else(|| {
                    if player.character == GameFamily::Q1 {
                        "progs/player.mdl".to_string()
                    } else {
                        format!("players/{model_name}/tris.md2")
                    }
                });
            let mut model = Self::blank_presentation(actor.clone(), appearance.content.clone(), player.character, path);
            if player.character == GameFamily::Q2 && !gibbed {
                model.skin_path = Some(format!("players/{model_name}/grunt.pcx"));
            }
            model.frame =
                q2_entity
                    .as_ref()
                    .map(|entity| entity.frame)
                    .unwrap_or_else(|| match player.animation.state {
                        qa_world::movement::types::AnimationState::Q1 { frame, .. }
                        | qa_world::movement::types::AnimationState::Q2 { frame, .. } => frame,
                        _ => 0,
                    });
            model.old_frame = q2_entity.as_ref().map(|entity| entity.old_frame).unwrap_or(0);
            model.skin = q2_entity.as_ref().map(|entity| entity.skin).unwrap_or(0);
            model.effects = q2_entity.as_ref().map(|entity| entity.effects as i32).unwrap_or(0);
            model.render_flags = q2_entity.as_ref().map(|entity| entity.render_flags).unwrap_or(0);
            model.origin = body.origin;
            model.angles = body.angles;
            model.scale = scale;
            model.alpha = Some(alpha);
            if let Some((top, bottom)) = colors {
                model.player_colors = Some(super::types::PlayerColors { top, bottom });
            }
            result.push(model);
        }
    }

    /// Detached-model presentations (donor `primaryPresentations` detached arm).
    fn push_detached_presentations(&self, result: &mut Vec<super::types::SimulationPresentation>) {
        let detached: Vec<(OwnedActor, DetachedModel)> = self
            .peek()
            .detached_models
            .iter()
            .map(|(actor, model)| (actor.clone(), model.clone()))
            .collect();
        for (actor, model) in &detached {
            let Some(body) = self.bodies().read(actor.id()) else {
                continue;
            };
            let mut row = Self::blank_presentation(
                actor.id().clone(),
                model.content.clone(),
                GameFamily::Q2,
                model.path.clone(),
            );
            row.effects = 2;
            row.origin = body.origin;
            row.angles = body.angles;
            result.push(row);
        }
    }

    /// View-weapon presentations (donor `primaryPresentations` weapon arm).
    fn push_view_model_presentations(&self, result: &mut Vec<super::types::SimulationPresentation>) {
        use super::arsenal::selected::SelectedArsenal as FamilyArsenal;
        let weapon_provider = self.peek().weapon_provider.clone();
        let family = provider_family(&provider_text(&weapon_provider.provider)).expect("weapon provider family");
        let weapon_models: Vec<(ActorId, String, i32)> = if self.peek().selected_arsenal.is_none() {
            self.peek()
                .view_models
                .iter()
                .map(|(actor, model)| (actor.clone(), model.path.clone(), model.frame))
                .collect()
        } else {
            self.players()
                .into_iter()
                .filter_map(|actor| {
                    let state = self.peek();
                    let selected = state.selected_arsenal.as_ref().expect("selected arsenal checked");
                    let model = match selected {
                        SelectedArsenal::Q1(arsenal) => arsenal.view(&actor),
                        SelectedArsenal::Q2(arsenal) => arsenal.view(&actor),
                        SelectedArsenal::Q3(arsenal) => arsenal.view(&actor),
                    };
                    model.map(|model| (actor, model.path, model.frame as i32))
                })
                .collect()
        };
        for (actor, path, frame) in &weapon_models {
            let player = self.player(actor);
            let skip = match player.as_ref() {
                None => {
                    !matches!(
                        self.peek().source,
                        SourceRuntime::Q3Qvm { .. } | SourceRuntime::Q2Native(_)
                    ) || self.player_client(actor).is_none()
                }
                Some(player) => player.intermission || player.cutscene.is_some(),
            };
            if skip {
                continue;
            }
            let q2 = if family == GameFamily::Q2 {
                self.peek().view_models.get(actor).and_then(|model| model.q2)
            } else {
                None
            };
            let native_view = match (&self.peek().source, player.as_ref()) {
                (SourceRuntime::Q2 { .. }, Some(player)) if player.character == GameFamily::Q2 => {
                    self.peek().q2_views.get(actor).cloned()
                }
                _ => None,
            };
            let body = self.bodies().read(actor);
            let (origin, angles, view_height) = if native_view.is_none() {
                if let Some(player) = player.as_ref() {
                    let body = body.clone().expect("view-model player has no body");
                    (body.origin, player.view_angles, player.view_height)
                } else {
                    let view = self.player_view(actor).expect("view-model view failed");
                    (view.origin, view.angles, view.view_height)
                }
            } else {
                let view = self.player_view(actor).expect("view-model view failed");
                (view.origin, view.angles, view.view_height)
            };
            let source_view = if q2.is_some() { native_view.as_ref() } else { None };
            let arsenal = {
                let state = self.peek();
                state.selected_arsenal.as_ref().map(|selected| match selected {
                    SelectedArsenal::Q1(arsenal) => arsenal.read(actor),
                    SelectedArsenal::Q2(arsenal) => arsenal.read(actor),
                    SelectedArsenal::Q3(arsenal) => arsenal.read(actor),
                })
            };
            let health = self
                .peek()
                .combat
                .read(actor)
                .map(|combat| combat.health)
                .unwrap_or(0.0);
            let q3_weapon = match (&self.peek().selected_arsenal, arsenal.as_ref(), body.as_ref()) {
                (Some(SelectedArsenal::Q3(selected)), Some(arsenal), Some(body)) => match arsenal.state {
                    qa_world::movement::types::WeaponState::Q3 { source_weapon, .. } => {
                        let buttons = player
                            .as_ref()
                            .map(|player| step_button_bits(player.buttons))
                            .unwrap_or_else(|| {
                                self.peek()
                                    .mod_client_commands
                                    .get(actor)
                                    .map(|command| step_button_bits(command.input.command.buttons()))
                                    .unwrap_or(0)
                            });
                        let view_state = selected.view_state(actor).expect("selected q3 view state failed");
                        let bob_cycle = match player.as_ref().map(|player| &player.state) {
                            Some(MovementState::Q3(state)) => f64::from(state.bob_cycle),
                            _ => match &self.peek().source {
                                SourceRuntime::Q3Qvm { game, .. } => {
                                    f64::from(game.records.player(game.records.require_slot(actor)).bob_cycle)
                                }
                                _ => 0.0,
                            },
                        };
                        Some(super::types::Q3WeaponPresentation {
                            time_milliseconds: self.peek().selected_milliseconds as i32,
                            torso_animation: view_state.torso_animation,
                            last_fire_milliseconds: view_state
                                .last_fire_milliseconds
                                .map(|milliseconds| milliseconds as i32),
                            firing: buttons & 1 != 0 && health > 0.0,
                            horizontal_speed: f64::hypot(f64::from(body.velocity.x), f64::from(body.velocity.y)),
                            bob_cycle,
                            weapon: source_weapon,
                        })
                    }
                    _ => None,
                },
                _ => None,
            };
            let visible = match &self.peek().source {
                SourceRuntime::Q3Qvm { .. } => true,
                SourceRuntime::Q2Native(_) => {
                    let client = self.native_q2_client(actor).expect("native view-model client failed");
                    let gun_index = {
                        let mut state = self.lock();
                        match &mut state.source {
                            SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => {
                                game.player_state(client.slot() + 1)
                                    .expect("native player state failed")
                                    .view
                                    .gun_index
                            }
                            SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => {
                                game.player_state(client.slot() + 1)
                                    .expect("native player state failed")
                                    .view
                                    .gun_index
                            }
                            _ => panic!("Native presentations lost their source owner"),
                        }
                    };
                    // The `NativePrimaryWeapons::available` synthetic host
                    // belongs to the native-weapon lane (see the
                    // `equipment_player_available_in` native arm), so the
                    // native arm reads the health fallback here as well.
                    gun_index != 0 && health > 0.0
                }
                _ => health > 0.0,
            };
            let mut model =
                Self::blank_presentation(actor.clone(), weapon_provider.content.clone(), family, path.clone());
            model.q3_weapon = q3_weapon;
            model.weapon_item = arsenal.and_then(|arsenal| arsenal.active_weapon.clone());
            model.frame = *frame;
            model.old_frame = *frame;
            model.skin = q2.map(|q2| q2.skin).unwrap_or(0);
            model.render_flags = if family == GameFamily::Q2 { 1 | 4 | 16 } else { 0 };
            model.origin = add(
                add(
                    origin,
                    Vec3 {
                        x: 0.0,
                        y: 0.0,
                        z: view_height as f32,
                    },
                ),
                source_view
                    .map(|view| view.gun_offset)
                    .or_else(|| q2.map(|q2| q2.kick_origin))
                    .unwrap_or_else(zero),
            );
            model.angles = add(
                angles,
                source_view
                    .map(|view| view.gun_angles)
                    .or_else(|| q2.map(|q2| q2.kick_angles))
                    .unwrap_or_else(zero),
            );
            model.visible = visible;
            model.view_weapon = true;
            result.push(model);
        }
    }

    /// Primary HUD snapshot (donor `primaryUi`).
    fn primary_ui(&self, actor: &ActorId) -> Result<PlayerUi, RuntimeError> {
        use super::arsenal::selected::SelectedArsenal as SelectedArsenalBehavior;
        use super::types::{PlayerUiItem, PlayerUiItemKind};
        let mut actor = actor.clone();
        if matches!(self.peek().source, SourceRuntime::Q2 { .. }) {
            let game = self.q2_game_services();
            if let Some(game) = game {
                let services = game.borrow();
                let observer = services.players.states.get(&actor);
                let chase = match observer {
                    Some(state) if state.spectator => state.chase_target.clone(),
                    _ => None,
                };
                if let Some(target) = chase {
                    if let Some(watched) = services.players.states.get(&target) {
                        if watched.connected && !watched.spectator {
                            actor = target;
                        }
                    }
                }
            }
        }
        let player = self.require_player(&actor)?;
        let combat = self
            .peek()
            .combat
            .read(&actor)
            .ok_or_else(|| RuntimeError::Failure("Player has no combat state".to_string()))?;
        let state = self.peek();
        let quake_c_ui = match &state.source {
            SourceRuntime::QuakeC { game, .. } => Some(
                game.client_ui(&actor)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?,
            ),
            _ => None,
        };
        let powerups = match &state.source {
            SourceRuntime::Q2 { game, .. } => {
                let services = game.borrow();
                let product = qa_content::q2::composition::product_runtime(&services);
                let mission = product
                    .armory
                    .as_ref()
                    .map(|armory| armory.items.powerups(&actor, &services));
                super::powerup_timers::q2_powerup_timers(
                    &product.items.player_powerups(&services, &actor),
                    mission.as_ref(),
                    services.now(),
                )
            }
            SourceRuntime::Q1 { services, .. } => {
                let game = services.borrow();
                super::powerup_timers::q1_powerup_timers(
                    game.player_ref(&actor)
                        .map(|state| &state.powerups)
                        .unwrap_or(&empty_q1_powerups()),
                    game.time,
                )
            }
            SourceRuntime::Q3 { .. } => {
                panic!("Missing siblings: q3 lane owns the source records/level/pool behind q3PowerupTimers")
            }
            _ => quake_c_ui.as_ref().map(|ui| ui.powerups.clone()).unwrap_or_default(),
        };
        if let Some(selected) = state.selected_arsenal.as_ref() {
            let ui = match selected {
                SelectedArsenal::Q1(arsenal) => arsenal.ui(&actor, &state.weapon_provider),
                SelectedArsenal::Q2(arsenal) => arsenal.ui(&actor, &state.weapon_provider),
                SelectedArsenal::Q3(arsenal) => arsenal.ui(&actor, &state.weapon_provider),
            };
            let registry = self.actors.borrow();
            return Ok(PlayerUi {
                selected_arsenal: false,
                native_inventory: None,
                powerups,
                health: combat.health,
                armor: world_armor_to_contract(&combat.armor),
                inventory: state.inventory.entries(registry.inner(), &actor),
                active_weapon: ui.active_weapon,
                ammo: ui.ammo,
                items: ui.items,
                weapon_status: ui.weapon_status,
                arsenal_warning: ui.arsenal_warning,
            });
        }
        if let Some(ui) = quake_c_ui {
            let registry = self.actors.borrow();
            return Ok(PlayerUi {
                selected_arsenal: false,
                native_inventory: None,
                health: combat.health,
                armor: world_armor_to_contract(&combat.armor),
                inventory: state.inventory.entries(registry.inner(), &actor),
                powerups: ui.powerups,
                active_weapon: ui.weapon.active_weapon,
                ammo: ui.weapon.ammo,
                items: ui.weapon.items,
                weapon_status: ui.weapon.weapon_status,
                arsenal_warning: ui.weapon.arsenal_warning,
            });
        }
        let source_kind = self.source_kind().to_string();
        drop(state);
        let arsenal = self.read_player_arsenal(&player)?;
        let state = self.peek();
        let registry = self.actors.borrow();
        let inventory = state.inventory.entries(registry.inner(), &actor);
        let mut items: Vec<PlayerUiItem> = Vec::new();
        let mut ammo: Option<super::types::UiAmmo> = None;
        let mut weapon_status: Option<super::arsenal::selected::WeaponHudStatus> = None;
        let mut arsenal_warning = super::arsenal::selected::ArsenalAmmoWarning::None;
        if source_kind == "q1" {
            let SourceRuntime::Q1 { services, .. } = &state.source else {
                unreachable!("q1 source changed under primary_ui");
            };
            let mut game = services.borrow_mut();
            let weapons: Vec<qa_content::q1::foundation::types::Q1Weapon> = qa_content::q1::foundation::types::WEAPONS
                .iter()
                .map(|base| qa_content::q1::foundation::types::Q1Weapon::from(*base))
                .chain(game.registered_weapons.keys().copied())
                .collect();
            for (source_ordinal, weapon) in weapons.into_iter().enumerate() {
                let item = game.weapon_ammo(weapon);
                let count = item
                    .as_ref()
                    .map(|item| state.inventory.count(registry.inner(), &actor, item.as_str()));
                let expected = game
                    .registered_weapons
                    .get(&weapon)
                    .and_then(|definition| definition.ammo_per_shot)
                    .unwrap_or(
                        if weapon == qa_content::q1::foundation::types::Q1Weapon::Supernailgun
                            || weapon == qa_content::q1::foundation::types::Q1Weapon::Supershotgun
                        {
                            2.0
                        } else {
                            1.0
                        },
                    );
                let id = game.weapon_item(weapon);
                items.push(PlayerUiItem {
                    id: id.clone(),
                    label: weapon.as_str().to_string(),
                    kind: PlayerUiItemKind::Weapon,
                    source_ordinal: source_ordinal as f64,
                    owned: state.inventory.count(registry.inner(), &actor, id.as_str()) > 0.0,
                    has_ammo: count.is_none() || count.is_some_and(|count| count >= expected),
                    count,
                    warning_count: 0.0,
                });
            }
            let player_state = game.player_ref(&actor).cloned();
            if let Some(player_state) = player_state {
                weapon_status = Some(super::arsenal::weapon_status::q1_weapon_status(
                    &mut *game,
                    &actor,
                    player_state.weapon,
                    state.weapon_provider.clone(),
                ));
                if let Some(item) = game.weapon_ammo(player_state.weapon) {
                    ammo = Some(super::types::UiAmmo {
                        item: item.clone(),
                        count: state.inventory.count(registry.inner(), &actor, item.as_str()),
                    });
                }
            }
        } else if source_kind == "q2" {
            let SourceRuntime::Q2 { game, .. } = &state.source else {
                unreachable!("q2 source changed under primary_ui");
            };
            let services = game.borrow();
            let product = qa_content::q2::composition::product_runtime(&services);
            for (source_ordinal, definition) in product.items.list(&services).into_iter().enumerate() {
                if !definition.usable {
                    continue;
                }
                let weapon = services
                    .weapons
                    .definitions
                    .values()
                    .find(|weapon| weapon.item == definition.id);
                let quantity = state.inventory.count(registry.inner(), &actor, definition.id.as_str());
                let count = match weapon {
                    None => Some(quantity),
                    Some(weapon) => weapon
                        .ammo
                        .as_ref()
                        .map(|ammo| state.inventory.count(registry.inner(), &actor, ammo.as_str())),
                };
                items.push(PlayerUiItem {
                    id: definition.id.clone(),
                    label: definition.name.clone(),
                    kind: if weapon.is_none() {
                        PlayerUiItemKind::Powerup
                    } else {
                        PlayerUiItemKind::Weapon
                    },
                    source_ordinal: source_ordinal as f64,
                    owned: quantity > 0.0,
                    has_ammo: count.is_none()
                        || count
                            .is_some_and(|count| count >= f64::from(weapon.map(|weapon| weapon.quantity).unwrap_or(1))),
                    count,
                    warning_count: f64::from(weapon.map(|weapon| weapon.warning).unwrap_or(0)),
                });
            }
            let weapon = services
                .weapons
                .definitions
                .values()
                .find(|weapon| Some(&weapon.item) == arsenal.active_weapon.as_ref());
            weapon_status = super::arsenal::weapon_status::q2_weapon_status(
                weapon,
                |item| state.inventory.count(registry.inner(), &actor, item.as_str()) as i32,
                state.weapon_provider.clone(),
            );
            if let Some(weapon) = weapon {
                if let Some(ammo_item) = weapon.ammo.as_ref() {
                    ammo = Some(super::types::UiAmmo {
                        item: ammo_item.clone(),
                        count: state.inventory.count(registry.inner(), &actor, ammo_item.as_str()),
                    });
                }
            }
        } else if source_kind == "q3" {
            for definition in qa_content::q3::foundation::arsenal::Q3_WEAPON_ITEMS.iter() {
                let count = definition
                    .ammo
                    .as_ref()
                    .map(|ammo| state.inventory.count(registry.inner(), &actor, ammo.as_str()));
                items.push(PlayerUiItem {
                    id: definition.item.clone(),
                    label: definition
                        .item
                        .strip_prefix("q3:weapon/")
                        .unwrap_or(definition.item.as_str())
                        .to_string(),
                    kind: PlayerUiItemKind::Weapon,
                    source_ordinal: f64::from(definition.weapon as i32),
                    owned: state
                        .inventory
                        .count(registry.inner(), &actor, definition.item.as_str())
                        > 0.0,
                    has_ammo: count.is_none() || count.is_some_and(|count| count > 0.0),
                    count,
                    warning_count: 0.0,
                });
            }
            let SourceRuntime::Q3 { game, .. } = &state.source else {
                unreachable!("q3 source changed under primary_ui");
            };
            let product = game.product().expect("Q3 source product is not bound");
            if let WeaponState::Q3 { source_weapon, .. } = &arsenal.state {
                if let Some(definition) = qa_content::q3::foundation::arsenal::q3_weapon_item(*source_weapon) {
                    if let Some(ammo_item) = definition.ammo.as_ref() {
                        ammo = Some(super::types::UiAmmo {
                            item: ammo_item.clone(),
                            count: state.inventory.count(registry.inner(), &actor, ammo_item.as_str()),
                        });
                    }
                }
            }
            weapon_status = super::arsenal::weapon_status::q3_weapon_status(
                arsenal.active_weapon.as_ref(),
                product,
                |item| state.inventory.count(registry.inner(), &actor, item.as_str()) as i32,
                state.weapon_provider.clone(),
            );
            arsenal_warning = super::arsenal::weapon_status::q3_arsenal_warning(product, |item| {
                state.inventory.count(registry.inner(), &actor, item.as_str()) as i32
            });
        }
        Ok(PlayerUi {
            selected_arsenal: false,
            native_inventory: None,
            powerups,
            health: combat.health,
            armor: world_armor_to_contract(&combat.armor),
            active_weapon: arsenal.active_weapon,
            ammo,
            inventory,
            items,
            weapon_status,
            arsenal_warning,
        })
    }
}

/// Empty Q1 powerup map for players without Q1 state.
fn empty_q1_powerups() -> std::collections::HashMap<qa_content::q1::foundation::types::Q1Powerup, f64> {
    std::collections::HashMap::new()
}

impl SharedSimulation {
    /// Update a source player identity (donor `setSourcePlayerIdentity`).
    pub fn set_source_player_identity(
        &self,
        actor: &ActorId,
        identity: &SourcePlayerIdentity,
    ) -> Result<(), RuntimeError> {
        self.require_player(actor)?;
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q1 {
                services, composition, ..
            } => {
                let client = composition
                    .client(actor)
                    .ok_or_else(|| RuntimeError::Failure("Q1 source client is not admitted".to_string()))?;
                let mut info = client.userinfo.clone();
                if let Some(name) = identity.name.as_ref() {
                    userinfo_set(&mut info, "name", name);
                }
                let game = Rc::clone(services);
                let mut services = game.borrow_mut();
                composition
                    .userinfo(&mut services, actor, &info)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                if identity.shirt.is_some() || identity.pants.is_some() {
                    composition
                        .colors(
                            &mut services,
                            actor,
                            identity.shirt.unwrap_or_else(|| client.shirt()),
                            identity.pants.unwrap_or_else(|| client.pants()),
                        )
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
                Ok(())
            }
            SourceRuntime::Q2 { game, .. } => {
                let game = Rc::clone(game);
                drop(state);
                let services = game.borrow();
                let admitted = services.entity(actor).is_some() && services.players.states.contains_key(actor);
                if !admitted {
                    return Err(RuntimeError::Failure(
                        "Q2 source identity requires an admitted player".to_string(),
                    ));
                }
                let userinfo = services
                    .players
                    .states
                    .get(actor)
                    .map(|state| state.userinfo.clone())
                    .unwrap_or_default();
                let players = qa_content::q2::composition::product_runtime(&services).players;
                drop(services);
                let mut info = q2_userinfo_vec(&userinfo);
                if let Some(name) = identity.name.as_ref() {
                    userinfo_set(&mut info, "name", name);
                }
                if let Some(skin) = identity.skin.as_ref() {
                    userinfo_set(&mut info, "skin", skin);
                }
                players.userinfo_changed(actor.clone(), &mut game.borrow_mut(), &userinfo_serialize(&info));
                Ok(())
            }
            _ => Err(RuntimeError::Failure(
                "Source identity updates require a native Q1 or Q2 player".to_string(),
            )),
        }
    }

    /// Update a player field of view (donor `setPlayerFieldOfView`).
    pub fn set_player_field_of_view(
        &self,
        actor: &ActorId,
        field_of_view: f64,
        mode: PlayerFovMode,
    ) -> Result<(), RuntimeError> {
        if matches!(self.peek().source, SourceRuntime::Q2Native(_)) {
            let client = self.native_q2_client(actor)?;
            let slot = client.slot() + 1;
            let mut state = self.lock();
            let record = match &mut state.source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game
                    .clients()
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?
                    .into_iter()
                    .find(|record| record.slot == slot)
                    .map(|record| record.userinfo),
                SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game
                    .clients()
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?
                    .into_iter()
                    .find(|record| record.slot == slot)
                    .map(|record| record.userinfo),
                _ => None,
            };
            let Some(userinfo) = record else {
                return Err(RuntimeError::Failure(
                    "Native player has no source userinfo".to_string(),
                ));
            };
            if mode == PlayerFovMode::Restore {
                return Ok(());
            }
            let mut info = q2_userinfo_vec(&userinfo);
            userinfo_set(&mut info, "fov", &format!("{field_of_view}"));
            let serialized = userinfo_serialize(&info);
            match &mut state.source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game
                    .userinfo(slot, &serialized)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?,
                SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game
                    .userinfo(slot, &serialized)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?,
                _ => {}
            }
            return Ok(());
        }
        let player = self.require_player(actor)?;
        if !matches!(self.peek().source, SourceRuntime::Q2 { .. }) {
            let mut state = self.lock();
            let previous = state
                .q2_characters
                .get(&player.actor)
                .map(|character| character.state.fov);
            if let Some(previous) = previous {
                Self::update_effective_fov(
                    &mut state,
                    actor,
                    player.intermission,
                    false,
                    previous,
                    field_of_view as i32,
                );
                if let Some(character) = state.q2_characters.get_mut(&player.actor) {
                    character.state.fov = field_of_view as i32;
                }
            }
            return Ok(());
        }
        let game = self
            .q2_game_services()
            .ok_or_else(|| RuntimeError::Failure("Q2 source identity requires an admitted player".to_string()))?;
        let (admitted, previous_userinfo, previous_fov, chase, flags) = {
            let services = game.borrow();
            let state = services.players.states.get(actor);
            let entity = services.entity(actor);
            match (state, entity) {
                (Some(player_state), Some(entity)) => (
                    true,
                    player_state.userinfo.clone(),
                    player_state.fov,
                    player_state.chase_target.is_some(),
                    entity.flags,
                ),
                _ => (false, String::new(), 0, false, 0),
            }
        };
        if !admitted {
            return Ok(());
        }
        let info = q2_userinfo_vec(&previous_userinfo);
        let requested = userinfo_get(&info, "fov").and_then(parse_int_prefix).unwrap_or(0);
        let (rerelease, deathmatch, deathmatch_flags) = {
            let services = game.borrow();
            (
                services.options.edition == qa_content::q2::foundation::host::Q2Edition::Rerelease,
                services.options.mode == qa_content::q2::foundation::host::Q2Mode::Deathmatch,
                services.deathmatch_flags(),
            )
        };
        let fixed = !rerelease && deathmatch && (deathmatch_flags & 32768) != 0;
        let ordinary = if fixed {
            90
        } else if rerelease {
            requested.clamp(1, 160)
        } else if requested < 1 {
            90
        } else {
            requested.min(160)
        };
        let preserve = !fixed
            && (player.cutscene.is_some()
                || chase
                || (flags & 0x4000i64) != 0
                || (mode == PlayerFovMode::Restore && previous_fov != ordinary));
        let mut info = info;
        userinfo_set(&mut info, "fov", &format!("{field_of_view}"));
        let serialized = userinfo_serialize(&info);
        let players = qa_content::q2::composition::product_runtime(&game.borrow()).players;
        let mut services = game.borrow_mut();
        players.userinfo_changed(actor.clone(), &mut services, &serialized);
        if preserve {
            if let Some(player_state) = services.players.states.get_mut(actor) {
                player_state.fov = previous_fov;
            }
        }
        let current = services
            .players
            .states
            .get(actor)
            .map(|state| state.fov)
            .unwrap_or(previous_fov);
        let intermission = !matches!(
            services.players.intermission,
            qa_content::q2::base::player::index::Q2Intermission::Playing
        );
        drop(services);
        let mut state = self.lock();
        Self::update_effective_fov(
            &mut state,
            actor,
            player.intermission,
            intermission,
            previous_fov,
            current,
        );
        Ok(())
    }

    /// Sync the effective FOV cache when it tracks the previous value (donor `updateView`).
    fn update_effective_fov(
        state: &mut SharedSimulationState,
        actor: &ActorId,
        intermission: bool,
        q2_intermission: bool,
        previous: i32,
        current: i32,
    ) {
        if intermission || q2_intermission {
            return;
        }
        if let Some(view) = state.q2_views.get_mut(actor) {
            if view.fov == previous {
                view.fov = current;
            }
        }
    }

    /// Drain pending mod-client drops (donor `takeModClientDrops`).
    pub fn take_mod_client_drops(&self) -> Vec<ModClientDrop> {
        std::mem::take(&mut self.lock().mod_client_drops)
    }

    /// Resolve a mod-client actor (donor `modClients.actor`).
    pub fn mod_client_actor(&self, client: &ClientId) -> Option<ActorId> {
        if !self.actors.borrow().inner().owner().owns_client(client) {
            return None;
        }
        self.players().into_iter().find(|actor| {
            self.actors.borrow().inner().is_live(actor) && self.player_client(actor).as_ref() == Some(client)
        })
    }

    /// Require an admitted mod-client actor (donor `requireModClient`).
    pub fn require_mod_client(&self, client: &ClientId) -> Result<ActorId, RuntimeError> {
        self.assert_open()?;
        self.mod_client_actor(client)
            .ok_or_else(|| RuntimeError::Failure("Component client is no longer admitted".to_string()))
    }

    /// Fan out a mod-client lifecycle event (donor `notifyClientEvent`).
    pub fn notify_client_event(&self, kind: ModClientEventKind, actor: &ActorId) -> Result<(), RuntimeError> {
        let live = self.actors.borrow().inner().is_live(actor);
        let client = if live { self.player_client(actor) } else { None };
        let Some(client) = client else {
            return Ok(());
        };
        if kind == ModClientEventKind::Admitted {
            if self.peek().mod_client_admissions.contains(actor) {
                return Ok(());
            }
            self.lock().mod_client_admissions.insert(actor.clone());
        }
        let event = ModClientEvent {
            kind,
            identity: ModClientIdentity {
                client,
                actor: actor.clone(),
            },
        };
        let listeners = self.peek().mod_client_listeners.clone();
        for (_, listener) in &listeners {
            listener(&event);
        }
        if kind == ModClientEventKind::Admitted && self.actors.borrow().inner().is_live(actor) {
            self.restore_native_inventory_cursors(Some(actor))?;
        }
        if kind == ModClientEventKind::Disconnecting {
            let mut state = self.lock();
            state.mod_client_admissions.remove(actor);
            state.mod_client_commands.remove(actor);
        }
        Ok(())
    }

    /// Observe a component input command (donor `observeClientCommand`).
    pub fn observe_client_command(&self, input: &ActorCommand) -> Result<(), RuntimeError> {
        use qa_net::common::commands::{CommandSource, UserCommand};
        let admission_failed =
            || RuntimeError::Failure("Component input does not belong to an admitted client".to_string());
        let client = self.player_client(&input.actor).ok_or_else(admission_failed)?;
        if !self.actors.borrow().inner().is_live(&input.actor) {
            return Err(admission_failed());
        }
        match &input.source {
            CommandSource::Bot { .. } => {}
            CommandSource::Remote { client: source } => {
                let owned = self.actors.borrow().inner().owner().owns_client(source);
                if !owned || client != *source {
                    return Err(admission_failed());
                }
            }
            CommandSource::LocalSeat { seat } => {
                if !self.actors.borrow().inner().owner().owns_seat(seat) {
                    return Err(admission_failed());
                }
            }
        }
        if let Some(previous) = self.peek().mod_client_commands.get(&input.actor) {
            if input.sequence < previous.input.sequence {
                return Ok(());
            }
        }
        let command = input.command.clone();
        let local_seat = matches!(input.source, CommandSource::LocalSeat { .. });
        match &command {
            UserCommand::Q1Netquake { .. } | UserCommand::Q1Quakeworld { .. } => {
                self.remember_mod_client_command(input.clone());
                return Ok(());
            }
            _ if local_seat && !matches!(command, UserCommand::Q3 { .. }) => {
                self.remember_mod_client_command(input.clone());
                return Ok(());
            }
            _ => {}
        }
        let stored = self.stored_movement_state(&input.actor);
        if matches!(self.peek().source, SourceRuntime::Q2Native(_)) {
            let slot = client.slot() + 1;
            let mut state = self.lock();
            let movement = match &mut state.source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game
                    .player_state(slot)
                    .map(|player| NativeGuestMovement::Classic(player.movement))
                    .map_err(|error| RuntimeError::Failure(error.to_string())),
                SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game
                    .player_state(slot)
                    .map(|player| NativeGuestMovement::Rerelease(player.movement))
                    .map_err(|error| RuntimeError::Failure(error.to_string())),
                _ => {
                    return Err(RuntimeError::Failure(
                        "Component input has no matching source movement state".to_string(),
                    ))
                }
            }?;
            drop(state);
            match (command, movement) {
                (UserCommand::Q2Classic { .. }, NativeGuestMovement::Classic(movement)) => {
                    let mut rewritten = input.command.clone();
                    if let UserCommand::Q2Classic { angle_shorts, .. } = &mut rewritten {
                        for (index, delta) in movement.delta_angle_shorts.iter().enumerate() {
                            angle_shorts[index] = (angle_shorts[index] + f64::from(*delta)).rem_euclid(65536.0);
                        }
                    }
                    self.remember_mod_client_command(ActorCommand {
                        command: rewritten,
                        ..input.clone()
                    });
                    Ok(())
                }
                (UserCommand::Q2Rerelease { .. }, NativeGuestMovement::Rerelease(movement)) => {
                    let mut rewritten = input.command.clone();
                    if let UserCommand::Q2Rerelease { angles, .. } = &mut rewritten {
                        angles[0] += movement.delta_angles.x;
                        angles[1] += movement.delta_angles.y;
                        angles[2] += movement.delta_angles.z;
                    }
                    self.remember_mod_client_command(ActorCommand {
                        command: rewritten,
                        ..input.clone()
                    });
                    Ok(())
                }
                (UserCommand::Q3 { .. }, _) => self.remember_q3_command(input, &client, stored.as_ref()),
                _ => Err(RuntimeError::Failure(
                    "Component input has no matching source movement state".to_string(),
                )),
            }
        } else {
            match (command, stored) {
                (UserCommand::Q2Classic { .. }, Some(MovementState::Q2Classic(state))) => {
                    let mut rewritten = input.command.clone();
                    if let UserCommand::Q2Classic { angle_shorts, .. } = &mut rewritten {
                        for (index, delta) in state.delta_angle_shorts.iter().enumerate() {
                            angle_shorts[index] = (angle_shorts[index] + f64::from(*delta)).rem_euclid(65536.0);
                        }
                    }
                    self.remember_mod_client_command(ActorCommand {
                        command: rewritten,
                        ..input.clone()
                    });
                    Ok(())
                }
                (UserCommand::Q2Rerelease { .. }, Some(MovementState::Q2Rerelease(state))) => {
                    let mut rewritten = input.command.clone();
                    if let UserCommand::Q2Rerelease { angles, .. } = &mut rewritten {
                        angles[0] += f64::from(state.delta_angles.x);
                        angles[1] += f64::from(state.delta_angles.y);
                        angles[2] += f64::from(state.delta_angles.z);
                    }
                    self.remember_mod_client_command(ActorCommand {
                        command: rewritten,
                        ..input.clone()
                    });
                    Ok(())
                }
                (UserCommand::Q3 { .. }, state) => self.remember_q3_command(input, &client, state.as_ref()),
                _ => Err(RuntimeError::Failure(
                    "Component input has no matching source movement state".to_string(),
                )),
            }
        }
    }

    /// Remember a Q3 command with authoritative angle words (donor `observeClientCommand` q3 arm).
    fn remember_q3_command(
        &self,
        input: &ActorCommand,
        client: &ClientId,
        state: Option<&MovementState>,
    ) -> Result<(), RuntimeError> {
        use qa_net::common::commands::UserCommand;
        let peeked = self.peek();
        let qvm_delta = if matches!(peeked.source, SourceRuntime::Q3Qvm { .. }) {
            self.q3_command_delta(client)
        } else {
            None
        };
        let stored_delta = match state {
            Some(MovementState::Q3(state)) => Some(state.delta_angle_words),
            _ => None,
        };
        // The q3 lane has not landed native records yet, so the Q3 arm takes
        // the stored-state fallback exactly like the default arm.
        let delta = qvm_delta.or(stored_delta);
        drop(peeked);
        let Some(delta) = delta else {
            return Err(RuntimeError::Failure(
                "Q3 component input has no authoritative angle delta".to_string(),
            ));
        };
        let mut rewritten = input.command.clone();
        if let UserCommand::Q3 { angle_words, .. } = &mut rewritten {
            for (index, word) in delta.iter().enumerate() {
                angle_words[index] = (angle_words[index] + f64::from(*word)).rem_euclid(65536.0);
            }
        }
        self.remember_mod_client_command(ActorCommand {
            command: rewritten,
            ..input.clone()
        });
        Ok(())
    }

    /// Read the stored movement state for an actor (donor `player.readState` deltas).
    fn stored_movement_state(&self, actor: &ActorId) -> Option<MovementState> {
        self.player(actor).map(|player| player.state)
    }

    /// Canonical team name for a match player (donor `canonicalTeam`).
    pub fn canonical_team(&self, actor: &ActorId, original: Option<&str>) -> Option<String> {
        if self.player_client(actor).is_none() {
            return original.map(str::to_string);
        }
        if self.peek().options_mode == super::types::SimulationMode::Coop {
            return Some("team:coop".to_string());
        }
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q2Native(_) => {
                drop(state);
                let profile = self.native_primary_match_profile();
                let mapping = profile
                    .as_ref()
                    .and_then(|profile| profile.teams.iter().find(|team| Some(team.source.as_str()) == original));
                match mapping {
                    Some(team) => Some(team.team.clone()),
                    None => original.map(str::to_string),
                }
            }
            SourceRuntime::Q3Qvm { weapons, .. } => {
                let mapping = weapons
                    .as_ref()
                    .and_then(|weapons| weapons.match_profile())
                    .and_then(|profile| {
                        profile
                            .teams
                            .into_iter()
                            .find(|team| Some(team.source.as_str()) == original)
                    });
                match mapping {
                    Some(team) => Some(team.team),
                    None => original.map(str::to_string),
                }
            }
            SourceRuntime::QuakeC { game, .. } => {
                let mapping = game
                    .prepared()
                    .teams
                    .as_ref()
                    .and_then(|teams| teams.iter().find(|team| team.source.as_deref() == original));
                match mapping {
                    Some(team) => team.team.clone(),
                    None => original.map(str::to_string),
                }
            }
            SourceRuntime::Q1 { composition, .. } => {
                if composition.program() == qa_content::q1::composition::types::Q1SourceProgram::Ctf {
                    match original {
                        Some("red") => Some("team:red".to_string()),
                        Some("blue") => Some("team:blue".to_string()),
                        _ => original.map(str::to_string),
                    }
                } else {
                    original.map(str::to_string)
                }
            }
            SourceRuntime::Q2 { game, .. } => {
                let services = game.borrow();
                let product = qa_content::q2::composition::product_runtime(&services);
                let ctf = matches!(
                    product.selection,
                    qa_content::q2::composition::types::Q2MatchSelection::Ctf
                        | qa_content::q2::composition::types::Q2MatchSelection::Lmctf { .. }
                );
                if ctf {
                    match original {
                        Some("RED") => Some("team:red".to_string()),
                        Some("BLUE") => Some("team:blue".to_string()),
                        _ => original.map(str::to_string),
                    }
                } else {
                    original.map(str::to_string)
                }
            }
            SourceRuntime::Q3 { .. } => match original {
                Some("q3-team:1") => Some("team:red".to_string()),
                Some("q3-team:2") => Some("team:blue".to_string()),
                _ => original.map(str::to_string),
            },
            SourceRuntime::Loading => original.map(str::to_string),
        }
    }

    /// Native primary match profile, if declared (donor `nativePrimary()?.player.match`).
    fn native_primary_match_profile(&self) -> Option<qa_compat::q2::native_primary_player::SourcePrimaryMatch> {
        let state = self.peek();
        let prepared = match state.options_q2_guest.as_ref()? {
            super::types::NativeQ2GuestOptions::Classic { prepared, .. } => {
                super::q2_native_world::PreparedQ2NativeGuest::Classic(prepared.clone())
            }
            super::types::NativeQ2GuestOptions::Rerelease { prepared, .. } => {
                super::q2_native_world::PreparedQ2NativeGuest::Rerelease(prepared.clone())
            }
        };
        match super::q2_native_world::prepared_native_primary(&prepared)? {
            qa_compat::q2::native_primary::NativePrimaryProfile::Classic { player, .. } => player.match_profile.clone(),
            qa_compat::q2::native_primary::NativePrimaryProfile::Rerelease { player, .. } => {
                player.match_profile.clone()
            }
        }
    }

    /// Match-player snapshot for an actor (donor `primaryMatchPlayer`).
    pub fn primary_match_player(&self, actor: &ActorId) -> Option<SourceMatchPlayer> {
        let owned = self.actors.borrow().inner().resolve_owned(actor)?;
        let _ = owned;
        let client = self.player_client(actor)?;
        let state = self.peek();
        match &state.source {
            SourceRuntime::Loading => None,
            SourceRuntime::Q2Native(_) => {
                drop(state);
                self.native_primary_match_profile()?;
                panic!("Missing siblings: native-primary lane owns the selectedNativePlayer score host binding")
            }
            SourceRuntime::Q3Qvm { game, weapons, .. } => {
                let matched = weapons.as_ref().and_then(|weapons| weapons.match_profile()).is_some();
                if !matched {
                    return None;
                }
                let score = weapons
                    .as_ref()
                    .map(|weapons| weapons.score(actor).unwrap_or_else(|error| panic!("{error}")))
                    .unwrap_or(0);
                let _ = game;
                Some(SourceMatchPlayer {
                    actor: actor.clone(),
                    client,
                    team: state.combat.read(actor).and_then(|combat| combat.team),
                    score,
                })
            }
            SourceRuntime::Q1 { composition, .. } => {
                let frags = composition
                    .client(actor)
                    .unwrap_or_else(|| panic!("Q1 source client is not admitted"))
                    .frags;
                Some(SourceMatchPlayer {
                    actor: actor.clone(),
                    client,
                    team: state.combat.read(actor).and_then(|combat| combat.team),
                    score: frags as i32,
                })
            }
            SourceRuntime::QuakeC { game, .. } => {
                let score = game.match_score(actor).unwrap_or_else(|error| panic!("{error}")) as i32;
                Some(SourceMatchPlayer {
                    actor: actor.clone(),
                    client,
                    team: state.combat.read(actor).and_then(|combat| combat.team),
                    score,
                })
            }
            SourceRuntime::Q2 { game, .. } => {
                let services = game.borrow();
                let product = qa_content::q2::composition::product_runtime(&services);
                let player_state = services
                    .players
                    .states
                    .get(actor)
                    .unwrap_or_else(|| panic!("Original Q2 score has no player"));
                let score = if matches!(
                    product.selection,
                    qa_content::q2::composition::types::Q2MatchSelection::Lmctf { .. }
                ) {
                    services
                        .lmctf
                        .states
                        .get(actor)
                        .and_then(|state| state.statistics.get("score"))
                        .copied()
                        .unwrap_or(0.0) as i32
                } else {
                    player_state.score
                };
                Some(SourceMatchPlayer {
                    actor: actor.clone(),
                    client,
                    team: state.combat.read(actor).and_then(|combat| combat.team),
                    score,
                })
            }
            SourceRuntime::Q3 { .. } => {
                panic!("Missing siblings: q3 lane owns the source records behind the Q3 score read")
            }
        }
    }

    /// Set a match-player score (donor `primaryMatchPlayer` `setScore`).
    pub fn set_primary_match_score(&self, actor: &ActorId, value: f64) -> Result<(), RuntimeError> {
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q1 {
                services, composition, ..
            } => {
                if !value.is_finite() {
                    return Err(RuntimeError::Failure("Quake score must be finite".to_string()));
                }
                let game = Rc::clone(services);
                let mut services = game.borrow_mut();
                composition
                    .set_frags(&mut services, actor, f64::from(value as f32))
                    .map_err(|error| RuntimeError::Failure(error.to_string()))
            }
            SourceRuntime::QuakeC { game, .. } => game
                .set_match_score(actor, value)
                .map_err(|error| RuntimeError::Failure(error.to_string())),
            SourceRuntime::Q2Native(_) => {
                let _ = source_score(value)?;
                drop(state);
                Err(RuntimeError::Failure(
                    "Missing siblings: native-primary lane owns the selectedNativePlayer score host binding"
                        .to_string(),
                ))
            }
            SourceRuntime::Q3Qvm { weapons, .. } => {
                let Some(weapons) = weapons.as_ref() else {
                    return Err(RuntimeError::Failure(
                        "QVM weapons require a Q3 guest source".to_string(),
                    ));
                };
                let score = source_score(value)?;
                weapons
                    .set_score(actor, score)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))
            }
            SourceRuntime::Q2 { game, .. } => {
                let game = Rc::clone(game);
                let lmctf = {
                    let services = game.borrow();
                    matches!(
                        qa_content::q2::composition::product_runtime(&services).selection,
                        qa_content::q2::composition::types::Q2MatchSelection::Lmctf { .. }
                    )
                };
                drop(state);
                let mut services = game.borrow_mut();
                let Some(player_state) = services.players.states.get_mut(actor) else {
                    return Err(RuntimeError::Failure("Original Q2 score has no player".to_string()));
                };
                player_state.score = source_score(value)?;
                let score = player_state.score;
                if lmctf {
                    if let Some(entry) = services.lmctf.states.get_mut(actor) {
                        entry.statistics.insert("score".to_string(), f64::from(score));
                    }
                }
                Ok(())
            }
            SourceRuntime::Q3 { .. } => Err(RuntimeError::Failure(
                "Missing siblings: q3 lane owns the source records behind the Q3 score write".to_string(),
            )),
            SourceRuntime::Loading => Err(RuntimeError::Failure("Original match player was retired".to_string())),
        }
    }

    /// Set a match-player team (donor `primaryMatchPlayer` `setTeam`).
    pub fn set_primary_match_team(&self, actor: &ActorId, team: Option<&str>) -> Result<(), RuntimeError> {
        let current = self.peek().combat.read(actor).and_then(|combat| combat.team);
        if current.as_deref() == team {
            return Ok(());
        }
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q2Native(_) => {
                drop(state);
                let profile = self.native_primary_match_profile().ok_or_else(|| {
                    RuntimeError::Failure("Original native team commands have no declaration".to_string())
                })?;
                let teams: Vec<(Option<String>, Vec<String>)> = profile
                    .teams
                    .iter()
                    .map(|team| (Some(team.team.clone()), team.arguments.clone()))
                    .collect();
                let args = source_team_command(&teams, team)?;
                if args.is_empty() {
                    return Err(RuntimeError::Failure("Original team command is empty".to_string()));
                }
                let tail = args.iter().skip(1).cloned().collect::<Vec<_>>().join(" ");
                let client = self.native_q2_client(actor)?;
                let slot = client.slot() + 1;
                let mut state = self.lock();
                match &mut state.source {
                    SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => {
                        game.command(slot, &args, &tail)
                            .map_err(|error| RuntimeError::Failure(format!("Q2 game callback failed: {error}")))?
                    }
                    SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game
                        .command(slot, &args, &tail)
                        .map_err(|error| RuntimeError::Failure(format!("Q2 game callback failed: {error}")))?,
                    _ => {}
                }
                Ok(())
            }
            SourceRuntime::Q3Qvm { game, weapons, .. } => {
                let profile = weapons.as_ref().and_then(|weapons| weapons.match_profile());
                let player = game.players().into_iter().find(|player| player.actor == *actor);
                let (Some(profile), Some(player)) = (profile, player) else {
                    return Err(RuntimeError::Failure(
                        "Original QVM team commands have no declaration".to_string(),
                    ));
                };
                let teams: Vec<(Option<String>, Vec<String>)> = profile
                    .teams
                    .iter()
                    .map(|team| (Some(team.team.clone()), team.arguments.clone()))
                    .collect();
                let args = source_team_command(&teams, team)?;
                game.command_immediate(&player, &args)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))
            }
            SourceRuntime::QuakeC { game, .. } => {
                let mapping = game
                    .prepared()
                    .teams
                    .as_ref()
                    .and_then(|teams| teams.iter().find(|candidate| candidate.team.as_deref() == team));
                let resolved = match mapping {
                    Some(team) => team.source.clone(),
                    None => team.map(str::to_string),
                };
                game.set_match_team(actor, resolved.as_deref())
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                drop(state);
                self.notify_client_event(ModClientEventKind::Userinfo, actor)
            }
            SourceRuntime::Q3 { game } => {
                let values = [("team:red", "red"), ("team:blue", "blue")];
                let argument = if team.is_none() {
                    Some("free")
                } else {
                    values
                        .iter()
                        .find(|(name, _)| Some(*name) == team)
                        .map(|(_, argument)| *argument)
                };
                let Some(argument) = argument else {
                    return Err(RuntimeError::Failure("Team has no original Q3 command".to_string()));
                };
                game.player_command(actor, "team", &[argument.to_string()])
            }
            SourceRuntime::Q1 {
                services, composition, ..
            } => {
                let entry = composition
                    .client(actor)
                    .ok_or_else(|| RuntimeError::Failure("Q1 source client is not admitted".to_string()))?;
                let ctf = composition.program() == qa_content::q1::composition::types::Q1SourceProgram::Ctf;
                let value = if ctf {
                    match team {
                        Some("team:red") => 5.0,
                        Some("team:blue") => 14.0,
                        _ => f64::NAN,
                    }
                } else {
                    team.and_then(|team| team.parse::<f64>().ok()).unwrap_or(f64::NAN)
                };
                if value.fract() != 0.0 || !(1.0..=14.0).contains(&value) {
                    return Err(RuntimeError::Failure(
                        "Team has no original Quake color command".to_string(),
                    ));
                }
                let game = Rc::clone(services);
                let shirt = entry.shirt();
                let mut services = game.borrow_mut();
                composition
                    .colors(&mut services, actor, shirt, value as i32 - 1)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))
            }
            SourceRuntime::Q2 { game, .. } => {
                let game = Rc::clone(game);
                let (ctf, product_match) = {
                    let services = game.borrow();
                    let product = qa_content::q2::composition::product_runtime(&services);
                    (
                        matches!(
                            product.selection,
                            qa_content::q2::composition::types::Q2MatchSelection::Ctf
                                | qa_content::q2::composition::types::Q2MatchSelection::Lmctf { .. }
                        ),
                        product.product_match.clone(),
                    )
                };
                if !ctf {
                    return Err(RuntimeError::Failure(
                        "This original source has no declared team-change command".to_string(),
                    ));
                }
                let admitted = game.borrow().entity(actor).is_some();
                let argument = match team {
                    Some("team:red") => Some("red".to_string()),
                    Some("team:blue") => Some("blue".to_string()),
                    _ => None,
                };
                if !admitted || argument.is_none() {
                    return Err(RuntimeError::Failure(
                        "Team has no original Q2 team command".to_string(),
                    ));
                }
                let _ = product_match.command(
                    actor.clone(),
                    &mut game.borrow_mut(),
                    "team",
                    &[argument.unwrap_or_default()],
                );
                Ok(())
            }
            SourceRuntime::Loading => Err(RuntimeError::Failure(
                "This original source has no declared team-change command".to_string(),
            )),
        }
    }

    /// Store raw userinfo for an actor (donor `storePlayerUserinfo`).
    pub fn store_player_userinfo(&self, actor: &ActorId, userinfo: &str) -> Result<(), RuntimeError> {
        let client = self
            .player_client(actor)
            .ok_or_else(|| RuntimeError::Failure("Component userinfo has no admitted client".to_string()))?;
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q2Native(_) => {
                let slot = client.slot() + 1;
                drop(state);
                let mut state = self.lock();
                match &mut state.source {
                    SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game
                        .set_userinfo_storage(slot, userinfo)
                        .map_err(|error| RuntimeError::Failure(error.to_string())),
                    SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game
                        .set_userinfo_storage(slot, userinfo)
                        .map_err(|error| RuntimeError::Failure(error.to_string())),
                    _ => Ok(()),
                }
            }
            SourceRuntime::Q3Qvm { game, .. } => {
                game.state.set_userinfo(client.slot() as i32, userinfo);
                Ok(())
            }
            SourceRuntime::Q3 { .. } => Err(RuntimeError::Failure(
                "Missing siblings: q3 lane owns the host engine behind setUserinfo".to_string(),
            )),
            SourceRuntime::QuakeC { game, .. } => {
                let values: std::collections::HashMap<String, String> = q2_userinfo_vec(userinfo).into_iter().collect();
                game.set_client_info_storage(&client, &values)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))
            }
            SourceRuntime::Q1 { composition, .. } => composition
                .replace_userinfo(actor, &q2_userinfo_vec(userinfo))
                .map_err(|error| RuntimeError::Failure(error.to_string())),
            SourceRuntime::Q2 { game, .. } => {
                let game = Rc::clone(game);
                drop(state);
                let mut services = game.borrow_mut();
                let Some(player_state) = services.players.states.get_mut(actor) else {
                    return Err(RuntimeError::Failure("Component userinfo has no Q2 player".to_string()));
                };
                player_state.userinfo = userinfo.to_string();
                Ok(())
            }
            SourceRuntime::Loading => Err(RuntimeError::Failure(
                "Component userinfo requires an initialized source".to_string(),
            )),
        }
    }

    /// Player display name (donor `sourcePlayerName`).
    pub fn source_player_name(&self, actor: &ActorId) -> String {
        let userinfo = self
            .source_player_userinfo(actor)
            .unwrap_or_else(|error| panic!("{error}"))
            .unwrap_or_default();
        userinfo_get(&q2_userinfo_vec(&userinfo), "name")
            .unwrap_or("unconnected")
            .to_string()
    }

    /// Whether the Quake source server is paused (donor `q1Paused`).
    pub fn q1_paused(&self) -> bool {
        self.peek().q1_pause_state
    }

    /// Toggle the Quake source pause (donor `toggleQ1Pause`).
    pub fn toggle_q1_pause(&self, actor: Option<&ActorId>) -> Result<String, RuntimeError> {
        let state = self.peek();
        let cvars = match &state.source {
            SourceRuntime::Q1 { cvars, .. } => Rc::clone(cvars),
            SourceRuntime::QuakeC { game, .. } => game.cvars(),
            _ => {
                return Err(RuntimeError::Failure(
                    "Pause requires a Quake source server".to_string(),
                ))
            }
        };
        if actor.is_some()
            && cvars
                .borrow()
                .get("pausable")
                .is_some_and(|cvar| cvar.numeric_value == 0.0f32)
        {
            return Ok("Pause not allowed.\n".to_string());
        }
        if let (Some(actor), SourceRuntime::QuakeC { game, .. }) = (actor, &state.source) {
            if game.kind() == super::types::QuakeCSourceKind::Quakeworld && game.is_spectator_client(actor) {
                return Ok("Spectators can not pause.\n".to_string());
            }
        }
        drop(state);
        let mut state = self.lock();
        state.q1_pause_state = !state.q1_pause_state;
        let paused = state.q1_pause_state;
        drop(state);
        let name = match actor {
            None => "Server".to_string(),
            Some(actor) => {
                let userinfo = self.source_player_userinfo(actor)?.unwrap_or_default();
                userinfo_get(&q2_userinfo_vec(&userinfo), "name")
                    .unwrap_or("unconnected")
                    .to_string()
            }
        };
        Ok(format!(
            "{name} {} the game\n",
            if paused { "paused" } else { "unpaused" }
        ))
    }

    /// Raw userinfo for an actor (donor `sourcePlayerUserinfo`).
    pub fn source_player_userinfo(&self, actor: &ActorId) -> Result<Option<String>, RuntimeError> {
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q1 { composition, .. } => {
                let client = composition
                    .client(actor)
                    .ok_or_else(|| RuntimeError::Failure("Q1 source client is not admitted".to_string()))?;
                Ok(Some(userinfo_serialize(&client.userinfo)))
            }
            SourceRuntime::Q2 { game, .. } => Ok(game
                .borrow()
                .players
                .states
                .get(actor)
                .map(|state| state.userinfo.clone())),
            SourceRuntime::Q3 { .. } => {
                if self.player_client(actor).is_none() {
                    return Ok(None);
                }
                Err(RuntimeError::Failure(
                    "Missing siblings: q3 lane owns the host engine behind getUserinfo".to_string(),
                ))
            }
            SourceRuntime::Q3Qvm { game, .. } => {
                let client = self.player_client(actor);
                match client {
                    None => Ok(None),
                    Some(client) => Ok(game.state.get_userinfo(client.slot() as i32)),
                }
            }
            SourceRuntime::Q2Native(native) => {
                let client = self.native_q2_client(actor)?;
                let slot = client.slot() + 1;
                match native {
                    Q2NativeSource::Classic { game, .. } => Ok(game
                        .clients()
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?
                        .into_iter()
                        .find(|record| record.slot == slot)
                        .map(|record| record.userinfo)),
                    Q2NativeSource::Rerelease { game, .. } => Ok(game
                        .clients()
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?
                        .into_iter()
                        .find(|record| record.slot == slot)
                        .map(|record| record.userinfo)),
                }
            }
            SourceRuntime::QuakeC { game, .. } => {
                let client = self.player_client(actor);
                match client {
                    None => Ok(None),
                    Some(client) => {
                        let info: Vec<(String, String)> = game.client_info(&client).into_iter().collect();
                        Ok(Some(userinfo_serialize(&info)))
                    }
                }
            }
            SourceRuntime::Loading => Ok(None),
        }
    }

    /// Apply a userinfo update (donor `updatePlayerUserinfo`).
    pub fn update_player_userinfo(&self, actor: &ActorId, userinfo: &str) -> Result<(), RuntimeError> {
        let previous_userinfo = self.source_player_userinfo(actor)?;
        if previous_userinfo.as_deref() == Some(userinfo) {
            return Ok(());
        }
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q3Qvm { game, .. } => {
                let player = game.players().into_iter().find(|player| player.actor == *actor);
                let Some(player) = player else {
                    return Err(RuntimeError::Failure(
                        "Q3 guest userinfo has no admitted client".to_string(),
                    ));
                };
                return game
                    .userinfo(&player, userinfo)
                    .map_err(|error| RuntimeError::Failure(error.to_string()));
            }
            SourceRuntime::Q2Native(native) => {
                let client = self.native_q2_client(actor)?;
                let slot = client.slot() + 1;
                let current = match native {
                    Q2NativeSource::Classic { game, .. } => game
                        .clients()
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?
                        .into_iter()
                        .find(|record| record.slot == slot)
                        .map(|record| record.userinfo),
                    Q2NativeSource::Rerelease { game, .. } => game
                        .clients()
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?
                        .into_iter()
                        .find(|record| record.slot == slot)
                        .map(|record| record.userinfo),
                };
                if current.as_deref() != Some(userinfo) {
                    drop(state);
                    let mut state = self.lock();
                    match &mut state.source {
                        SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game
                            .userinfo(slot, userinfo)
                            .map_err(|error| RuntimeError::Failure(error.to_string()))?,
                        SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game
                            .userinfo(slot, userinfo)
                            .map_err(|error| RuntimeError::Failure(error.to_string()))?,
                        _ => {}
                    }
                }
            }
            SourceRuntime::Q3 { .. } => {
                if self.player_client(actor).is_none() {
                    return Err(RuntimeError::Failure("Q3 userinfo has no admitted client".to_string()));
                }
                return Err(RuntimeError::Failure(
                    "Missing siblings: q3 lane owns the host engine/admission behind userinfoChanged".to_string(),
                ));
            }
            SourceRuntime::Q1 {
                services, composition, ..
            } => {
                let previous = composition
                    .client(actor)
                    .ok_or_else(|| RuntimeError::Failure("Q1 source client is not admitted".to_string()))?
                    .userinfo
                    .clone();
                let values = q2_userinfo_vec(userinfo);
                let same = previous.len() == values.len()
                    && values
                        .iter()
                        .all(|(name, value)| userinfo_get(&previous, name) == Some(value.as_str()));
                if !same {
                    let game = Rc::clone(services);
                    composition
                        .userinfo(&mut game.borrow_mut(), actor, &values)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
            SourceRuntime::QuakeC { game, .. } => {
                let Some(client) = self.player_client(actor) else {
                    return Ok(());
                };
                let previous = game.client_info(&client);
                let values = q2_userinfo_vec(userinfo);
                let same = previous.len() == values.len()
                    && values
                        .iter()
                        .all(|(name, value)| previous.get(name).is_some_and(|current| current == value));
                if !same {
                    let values: std::collections::HashMap<String, String> = values.into_iter().collect();
                    game.set_client_info(&client, &values)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
            SourceRuntime::Q2 { game, .. } => {
                let game = Rc::clone(game);
                drop(state);
                let snapshot = {
                    let services = game.borrow();
                    match (services.players.states.get(actor), services.entity(actor)) {
                        (Some(player_state), Some(entity)) if player_state.userinfo != userinfo => Some((
                            player_state.fov,
                            userinfo_get(&q2_userinfo_vec(&player_state.userinfo), "fov").map(str::to_string),
                            player_state.chase_target.is_some(),
                            entity.flags,
                        )),
                        _ => None,
                    }
                };
                let Some((previous_fov, previous_request, chased, flags)) = snapshot else {
                    return Ok(());
                };
                let player = self.require_player(actor)?;
                let players = qa_content::q2::composition::product_runtime(&game.borrow()).players;
                let mut services = game.borrow_mut();
                players.userinfo_changed(actor.clone(), &mut services, userinfo);
                if player.cutscene.is_some()
                    || chased
                    || (flags & 0x4000i64) != 0
                    || previous_request.as_deref() == userinfo_get(&q2_userinfo_vec(userinfo), "fov")
                {
                    if let Some(player_state) = services.players.states.get_mut(actor) {
                        player_state.fov = previous_fov;
                    }
                }
                let current_fov = services
                    .players
                    .states
                    .get(actor)
                    .map(|state| state.fov)
                    .unwrap_or(previous_fov);
                drop(services);
                let mut state = self.lock();
                if let Some(view) = state.q2_views.get_mut(actor) {
                    if view.fov == previous_fov {
                        view.fov = current_fov;
                    }
                }
            }
            SourceRuntime::Loading => {}
        }
        if self.source_player_userinfo(actor)? != previous_userinfo {
            self.notify_client_event(ModClientEventKind::Userinfo, actor)?;
        }
        Ok(())
    }
}

/// Guest movement state by edition for input observation.
enum NativeGuestMovement {
    Classic(qa_net::q2_adapters::Q2MovementState),
    Rerelease(qa_net::q2_adapters::Q2RereleaseMovementState),
}

impl Q3SourceRuntime {
    /// Run a player console command (donor `Q3SourceRuntime.playerCommand`).
    ///
    /// Missing siblings: the q3 lane owns the client records/command table.
    pub fn player_command(&self, actor: &ActorId, name: &str, args: &[String]) -> Result<(), RuntimeError> {
        let _ = (actor, name, args);
        Err(RuntimeError::Failure(
            "Missing siblings: q3 lane owns the client records/command table behind playerCommand".to_string(),
        ))
    }
}
// ---------------------------------------------------------------------------
// C3 §3c: QuakeC source construction (donor `createSource` preparedQuakeC
// branch, runtime.ts 2791-2857).
//
// Missing siblings: `QuakeCSource::new` needs eight production table
// adapters and only test fakes implement those traits. Two adapters are
// unimplementable today: bodies need external-storage bindings in
// `BodyTable` (world lane; donor `bodies.bind`), and pushers need a
// projection-based `Q1PusherServices` builder in physics (physics lane).
// The restore checkpoint also needs a conversion between the save
// schema and the executor schema (persistence/CQ lane), and the branch
// closures need CQ's parallel game surface plus C4's execution
// registration. This section ports the live prefix — checkpoint,
// weapon-stage probe, client-spawn detection, and save-candidate flag —
// and reports the adapter block as an error.
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// QuakeC source (donor preparedQuakeC branch).
    pub fn create_quakec_source(&self, inputs: CreateSourceInputs<'_>) -> Result<SourceRuntime, RuntimeError> {
        let CreateSourceInputs {
            prepared_quakec,
            restore,
            restored_clients,
            source_registry,
            original_save_candidate,
            ..
        } = inputs;
        let prepared =
            prepared_quakec.ok_or_else(|| source_failure("QuakeC source construction requires prepared QuakeC"))?;
        let checkpoint = match restore {
            Some(image) => super::save::simulation_quakec_checkpoint(image).map_err(source_failure)?,
            None => None,
        };
        let _weapon_stage = super::quakec_source::prepared_quake_c_weapon_stage(prepared).map_err(source_failure)?;
        let client_spawned = {
            let state = self.peek();
            state
                .recipe
                .weapons
                .iter()
                .any(|weapon| weapon != &state.recipe.map.entities)
        };
        let _ = (
            checkpoint,
            client_spawned,
            original_save_candidate,
            restored_clients,
            source_registry,
        );
        Err(source_failure(
            "QuakeC source construction requires the production table adapters",
        ))
    }
}
// ---------------------------------------------------------------------------
// C3 §3f: Q3 source construction (donor `createSource` q3-provider
// branch, runtime.ts 2858-2923).
//
// Missing siblings: `create_q3_source_host` needs `Rc<dyn
// Q3HostOperations>` and only test fakes implement that trait (plus the
// six session-table traits it returns). The q3 lane owns the production
// operations routing (selected-arsenal grants, spawn/move-client,
// mover actors, source commands). This section ports the live prefix —
// product selection, host settings, server state, game cvar
// registration, and objective adaptation — and reports the operations
// block as an error.
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Q3 source (donor q3-provider branch).
    pub fn create_q3_source(&self, inputs: CreateSourceInputs<'_>) -> Result<SourceRuntime, RuntimeError> {
        use super::q3::host::Q3HostSettings;
        use qa_content::q3::base::settings::q3_game_cvar_definitions;
        use qa_content::q3::base::shared::definitions::Product;
        use qa_content::q3::team_arena::foreign_objectives::{
            adapt_foreign_q3_objectives, ForeignObjectiveAdaptation, ForeignWorld, WorldKind,
        };
        let CreateSourceInputs {
            world,
            source_registry,
            source_archive,
            restore,
            q3_cvars,
            q3_session,
            profile,
            ..
        } = inputs;
        let single_player = {
            let state = self.peek();
            state.options_mode == super::types::SimulationMode::Singleplayer
        };
        let (max_clients, requested_path) = {
            let state = self.peek();
            (
                state.options_max_clients,
                state.recipe.map.geometry.requested_path.clone(),
            )
        };
        let program = {
            let state = self.peek();
            qa_content::catalog::selected_source_program(&state.recipe.execution, &state.recipe.map.entities)
                .map_err(source_failure)?
        };
        let product = if program.as_deref() == Some("missionpack") {
            Product::Missionpack
        } else {
            Product::Baseq3
        };
        let game_type = if single_player { 2 } else { 0 };
        let _settings = Q3HostSettings {
            game_type,
            single_player,
            max_clients,
            map_name: source_map_name(&requested_path),
            source_registry: if restore.is_none() {
                source_registry.map(|registry| Rc::new(RefCell::new(registry)))
            } else {
                None
            },
            source_archive: if restore.is_none() {
                source_archive.unwrap_or(&[]).to_vec()
            } else {
                Vec::new()
            },
            cvars: q3_cvars.unwrap_or(&[]).to_vec(),
        };
        let tables = C11Tables {
            actors: self.actors_handle(),
            bodies: self.bodies_handle(),
            weak: self.weak(),
        };
        let fresh = restore.is_none();
        let profile = profile.cloned();
        let closure_profile = profile.clone();
        let _register: super::q3::server_state::Q3ServerCvarRegistration = Rc::new(
            move |cvars: &mut qa_core::cvar::CvarRegistry, _max_clients: usize, _map: &str| {
                if fresh {
                    for definition in q3_game_cvar_definitions(product) {
                        let _ = cvars.register(&definition.name, &definition.value, definition.flags);
                    }
                    let _ = tables
                        .sim()
                        .initialize_server_settings(cvars, closure_profile.as_ref(), false);
                }
            },
        );
        let registry_injected = _settings.source_registry.is_some();
        let mut console = qa_core::cvar::CvarRegistry::new(qa_core::cmd::Dialect::Q3);
        if fresh {
            for definition in q3_game_cvar_definitions(product) {
                console
                    .register(&definition.name, &definition.value, definition.flags)
                    .map_err(source_failure)?;
            }
            self.initialize_server_settings(&mut console, profile.as_ref(), false)?;
        }
        if !registry_injected {
            console
                .set("g_gametype", &game_type.to_string(), true)
                .map_err(source_failure)?;
        }
        for variable in q3_cvars.unwrap_or(&[]) {
            console
                .set(&variable.name, &variable.value, true)
                .map_err(source_failure)?;
        }
        let foreign = ForeignWorld {
            kind: match world {
                super::types::ApplicationWorld::Q1(_) => WorldKind::Q1Bsp,
                super::types::ApplicationWorld::Q2(_) => WorldKind::Q2Bsp,
                super::types::ApplicationWorld::Q3(_) => WorldKind::Q3Bsp,
            },
            entities: world.entities().to_string(),
        };
        let game_type_value = console.variable_value("g_gametype") as i32;
        let _entities = match adapt_foreign_q3_objectives(&foreign, product, game_type_value, &[]) {
            ForeignObjectiveAdaptation::Ready { entities, .. } => entities,
            ForeignObjectiveAdaptation::MissingObjectives { classnames } => {
                return Err(source_failure(format!(
                    "Selected Q3 objectives are unavailable: {classnames:?}"
                )));
            }
            ForeignObjectiveAdaptation::UnsupportedMode { product, game_type } => {
                return Err(source_failure(format!(
                    "Selected Q3 objectives do not support {product:?} game type {game_type}"
                )));
            }
        };
        let _ = q3_session;
        Err(source_failure(
            "Q3 source construction requires the production host operations",
        ))
    }
}

// ---------------------------------------------------------------------------
// C7: saved native inventory cursors (donor runtime.ts 5472-5480, called by
// in-range `notifyClientEvent`; the 8-line overrun is reported).
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Restore saved native inventory cursors (donor
    /// `restoreNativeInventoryCursors`).
    fn restore_native_inventory_cursors(&self, actor: Option<&ActorId>) -> Result<(), RuntimeError> {
        let owners: Vec<(ActorId, Option<ItemId>)> = self
            .peek()
            .restored_native_inventory_selections
            .iter()
            .filter(|(owner, _)| actor.is_none_or(|actor| *owner == actor))
            .map(|(owner, item)| (owner.clone(), item.clone()))
            .collect();
        if let Some((owner, _item)) = owners.first() {
            if self.peek().native_primary_inventory.is_none() {
                return Err(RuntimeError::Failure(
                    "Saved native inventory cursor has no qualified owner".to_string(),
                ));
            }
            let _ = owner;
            return Err(RuntimeError::Failure(
                "Missing siblings: native-primary lane owns the NativePrimaryInventory restore host binding"
                    .to_string(),
            ));
        }
        Ok(())
    }
}
// ---------------------------------------------------------------------------
// C3 §3g: QVM guest source construction (donor `createSource` q3Guest
// branch, runtime.ts 2649-2790).
//
// Missing siblings: the records host needs `bindSourceInventory` (no
// home), the admit closure needs the guest record slot API plus the
// bound item catalog, and the bindings need the QVM lane's combat,
// inventory-projection, weapon, and pickup wiring with the
// selected-arsenal, grapple, and grenade lanes. This section ports the
// live prefix — host settings, server state, `fs_game`, and server
// settings — and reports the records block as an error.
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// QVM guest source (donor q3Guest branch).
    pub fn create_qvm_source(&self, inputs: CreateSourceInputs<'_>) -> Result<SourceRuntime, RuntimeError> {
        use super::q3::host::Q3HostSettings;
        use super::q3::server_state::{Q3ServerState, Q3ServerStateOptions};
        let CreateSourceInputs {
            q3_guest,
            mounts,
            source_registry,
            source_archive,
            restore,
            q3_cvars,
            profile,
            dedicated,
            ..
        } = inputs;
        let guest = q3_guest.ok_or_else(|| source_failure("QVM source construction requires q3 guest options"))?;
        let (max_clients, seed, requested_path) = {
            let state = self.peek();
            (
                state.options_max_clients,
                state.options_seed,
                state.recipe.map.geometry.requested_path.clone(),
            )
        };
        let settings = Q3HostSettings {
            game_type: 0,
            single_player: false,
            max_clients,
            map_name: source_map_name(&requested_path),
            source_registry: if restore.is_none() {
                source_registry.map(|registry| Rc::new(RefCell::new(registry)))
            } else {
                None
            },
            source_archive: if restore.is_none() {
                source_archive.unwrap_or(&[]).to_vec()
            } else {
                Vec::new()
            },
            cvars: q3_cvars.unwrap_or(&[]).to_vec(),
        };
        let now_tables = C11Tables {
            actors: self.actors_handle(),
            bodies: self.bodies_handle(),
            weak: self.weak(),
        };
        let session = self.peek().session.clone();
        let state = Q3ServerState::new(Q3ServerStateOptions {
            session,
            settings,
            now: Rc::new(move || (now_tables.sim().time_seconds() * 1000.0) as i32),
            print: guest.print.clone(),
            register_server_cvars: Rc::new(|_, _, _| {}),
        });
        state
            .cvars
            .borrow_mut()
            .set("fs_game", &guest.game_directory, true)
            .map_err(source_failure)?;
        self.initialize_server_settings(&mut state.cvars.borrow_mut(), profile, restore.is_some())?;
        let _ = (seed, mounts, dedicated, &guest.prepared.artifact);
        Err(source_failure(
            "QVM source construction requires the guest records host",
        ))
    }
}
// ---------------------------------------------------------------------------
// C3 §3h: source dispatcher (donor `createSource`, runtime.ts 2575-2578).
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Source runtime dispatcher (donor `createSource`).
    ///
    /// Routes to the per-source constructors in donor order: native Q2
    /// guest, QVM guest, prepared QuakeC, `q3:` provider, `q1-bsp`
    /// world, then the Q2 product fallthrough split by `:rerelease:`
    /// content. `native_loading` mirrors the donor `loading ===
    /// nativeLoading` comparison for the travel path.
    pub fn create_source(
        &self,
        inputs: CreateSourceInputs<'_>,
        native_loading: bool,
    ) -> Result<SourceRuntime, RuntimeError> {
        if inputs.q2_guest.is_some() {
            return self.create_native_source(inputs, native_loading);
        }
        if inputs.q3_guest.is_some() {
            return self.create_qvm_source(inputs);
        }
        if inputs.prepared_quakec.is_some() {
            return self.create_quakec_source(inputs);
        }
        let (provider, content) = {
            let state = self.peek();
            (
                provider_text(&state.recipe.map.entities.provider),
                state.recipe.map.entities.content.as_str().to_string(),
            )
        };
        if provider.starts_with("q3:") {
            return self.create_q3_source(inputs);
        }
        if inputs.world.kind() == "q1-bsp" {
            return self.create_q1_source(inputs);
        }
        if content.contains(":rerelease:") {
            self.create_rerelease_q2_source(inputs)
        } else {
            self.create_classic_q2_source(inputs)
        }
    }
}
