/// Refused source-input request (C11; immediate handoffs never defer).
struct C11RefusedRequest;

impl super::weapon_slot::SourceWeaponRequest for C11RefusedRequest {
    fn id(&self) -> u64 {
        u64::MAX
    }

    fn status(&mut self) -> super::weapon_slot::RequestStatus {
        super::weapon_slot::RequestStatus::Refused
    }

    fn cancel(&mut self) {}
}

/// Immediate primary handoff for QVM/native sources (C11; donor
/// `primaryHandoff` q3-qvm/q2-native arm, runtime.ts 2205-2223).
///
/// Guest UI reads degrade to refusal: `nativePlayerUi` is a C7 seam that
/// always fails until C7 lands it (donor 4926+), and the boolean handoff
/// methods have no error channel. Guest command refusals also read as
/// refused switches instead of crashing the session.
struct C11ImmediateHandoff {
    tables: C11Tables,
    actor: ActorId,
    provider: ProviderId,
    holstered: std::cell::Cell<bool>,
}

impl super::weapon_slot::SourceWeaponHandoff for C11ImmediateHandoff {
    fn provider(&self) -> ProviderId {
        self.provider.clone()
    }

    fn accepts(&self, item: &ItemId) -> bool {
        let sim = self.tables.sim();
        let accepted = sim
            .native_player_ui(&self.actor)
            .map(|ui| {
                ui.active_weapon.as_ref() == Some(item)
                    || ui.items.iter().any(|entry| {
                        &entry.id == item && entry.kind == super::types::PlayerUiItemKind::Weapon && entry.owned
                    })
            })
            .unwrap_or(false);
        accepted
    }

    fn select(&mut self, item: &ItemId) -> bool {
        if !self.accepts(item) {
            return false;
        }
        let sim = self.tables.sim();
        let ui = match sim.native_player_ui(&self.actor) {
            Ok(ui) => ui,
            Err(_) => return false,
        };
        if ui.active_weapon.as_ref() == Some(item) {
            return true;
        }
        let is_qvm = matches!(sim.peek().source, SourceRuntime::Q3Qvm { .. });
        if is_qvm {
            let ordinal = match ui
                .items
                .iter()
                .find(|entry| &entry.id == item && entry.kind == super::types::PlayerUiItemKind::Weapon)
            {
                Some(weapon) => weapon.source_ordinal as i32,
                None => return false,
            };
            sim.lock().native_weapon_requests.insert(self.actor.clone(), ordinal);
            return true;
        }
        let label = match ui.items.iter().find(|entry| &entry.id == item) {
            Some(weapon) => weapon.label.clone(),
            None => return false,
        };
        let slot = match sim.native_q2_client(&self.actor) {
            Ok(client) => client.slot() + 1,
            Err(_) => return false,
        };
        let mut state = sim.lock();
        match &mut state.source {
            SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => {
                game.command(slot, &["use".to_string(), label.clone()], &label).is_ok()
            }
            SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => {
                game.command(slot, &["use".to_string(), label.clone()], &label).is_ok()
            }
            _ => false,
        }
    }

    fn holster(&mut self) {
        self.holstered.set(true);
    }

    fn is_holstered(&self) -> bool {
        self.holstered.get()
    }

    fn resume(&mut self, item: Option<&ItemId>) -> super::weapon_slot::ResumeOutcome {
        self.holstered.set(false);
        super::weapon_slot::ResumeOutcome::Immediate(item.is_none_or(|entry| self.select(entry)))
    }

    fn restore_request(
        &mut self,
        _id: u64,
        _item: Option<&ItemId>,
    ) -> Box<dyn super::weapon_slot::SourceWeaponRequest> {
        Box::new(C11RefusedRequest)
    }

    fn is_deferred(&self) -> bool {
        false
    }
}

/// Immediate primary handoff for QuakeC sources (C11; donor
/// `primaryHandoff` quakec arm, runtime.ts 2225-2229).
struct C11QuakeCHandoff {
    tables: C11Tables,
    actor: ActorId,
    provider: ProviderId,
    game: Rc<super::quakec_source::QuakeCSource<RuntimePickupAdmission>>,
}

impl super::weapon_slot::SourceWeaponHandoff for C11QuakeCHandoff {
    fn provider(&self) -> ProviderId {
        self.provider.clone()
    }

    fn accepts(&self, item: &ItemId) -> bool {
        let sim = self.tables.sim();
        let accepted = sim
            .primary_ui(&self.actor)
            .map(|ui| {
                ui.items.iter().any(|entry| {
                    &entry.id == item && entry.kind == super::types::PlayerUiItemKind::Weapon && entry.owned
                })
            })
            .unwrap_or(false);
        accepted
    }

    fn select(&mut self, item: &ItemId) -> bool {
        let selected = self.game.request_client_weapon(&self.actor, item).unwrap_or(false);
        assert!(
            self.tables.sim().actors.borrow().is_live(&self.actor),
            "QC weapon owner retired"
        );
        selected
    }

    fn holster(&mut self) {
        // Missing siblings: the QuakeC source settles client weapons
        // without an explicit holster request; nothing to send until a
        // holster call lands on the source.
    }

    fn is_holstered(&self) -> bool {
        self.game.client_weapon_settled(&self.actor).unwrap_or(true)
    }

    fn resume(&mut self, item: Option<&ItemId>) -> super::weapon_slot::ResumeOutcome {
        super::weapon_slot::ResumeOutcome::Immediate(item.is_none_or(|entry| self.select(entry)))
    }

    fn restore_request(
        &mut self,
        _id: u64,
        _item: Option<&ItemId>,
    ) -> Box<dyn super::weapon_slot::SourceWeaponRequest> {
        Box::new(C11RefusedRequest)
    }

    fn is_deferred(&self) -> bool {
        false
    }
}

impl SharedSimulation {
    /// Native Q2 weapon input for a player (donor `q2WeaponInput`,
    /// runtime.ts 3963-3976).
    ///
    /// The Q3 player-state terms read empty: the Q3 source host carries no
    /// Rust records, and Q3 callers fail at the q3-records arms once this
    /// returns.
    fn q2_weapon_input(
        &self,
        player: &MovementPlayer,
    ) -> Result<qa_content::q2::foundation::weapons::types::Q2WeaponInput, RuntimeError> {
        use qa_content::q2::base::player::types::Q2PlayerHand;
        use qa_content::q2::foundation::weapons::types::{Q2WeaponInput, WeaponHand};
        let actor = player.actor.id();
        let selected = self
            .peek()
            .selected_arsenal
            .as_ref()
            .is_some_and(|arsenal| arsenal.family() == "q2");
        let pressed = (player.buttons as i32 & 1) != 0
            && (!selected
                || self
                    .peek()
                    .weapon_slots
                    .get(actor)
                    .is_none_or(|slot| slot.primary_selected()));
        let (q2_spectator, hand) = match &self.peek().source {
            SourceRuntime::Q2 { game, .. } => {
                let services = game.borrow();
                let record = services.players.states.get(actor);
                (
                    record.is_some_and(|record| record.spectator),
                    match record.map(|record| &record.hand) {
                        Some(Q2PlayerHand::Left) => WeaponHand::Left,
                        Some(Q2PlayerHand::Center) => WeaponHand::Center,
                        _ => WeaponHand::Right,
                    },
                )
            }
            _ => (false, WeaponHand::Right),
        };
        let spectator = q2_spectator || (selected && (player.intermission || player.cutscene.is_some()));
        let notarget = selected
            && self
                .monster_target(actor)
                .ok()
                .flatten()
                .is_some_and(|target| target.notarget);
        let quad_until = match &self.peek().source {
            SourceRuntime::Q2 { game, .. } => {
                let services = game.borrow();
                let product = qa_content::q2::composition::product_runtime(&services);
                product.items.player_powerups(&services, actor).quad_until
            }
            SourceRuntime::Q1 { services, .. } => services
                .borrow()
                .player_ref(actor)
                .and_then(|state| {
                    state
                        .powerups
                        .get(&qa_content::q1::foundation::types::Q1Powerup::Quad)
                        .copied()
                })
                .unwrap_or(0.0),
            SourceRuntime::QuakeC { game, .. } => game
                .client_powerup_expires(actor, super::quakec_source::QuakeCPowerup::Quad)
                .map_err(|error| RuntimeError::Failure(error.to_string()))?,
            _ => 0.0,
        };
        let rerelease_flag = |name: &str| {
            self.peek().q2_server_registry.as_ref().is_some_and(|registry| {
                let registry = registry.borrow();
                registry.dialect() == qa_core::cmd::Dialect::Q2Rerelease && registry.variable_value(name) != 0.0
            })
        };
        Ok(Q2WeaponInput {
            attack: pressed,
            latched_attack: pressed && (player.previous_buttons as i32 & 1) == 0,
            holster: false,
            angles: player.view_angles,
            ducked: player.bounds.max.z < player.standing_bounds.max.z,
            spectator,
            notarget,
            hand,
            animate_player: player.character == GameFamily::Q2,
            quad_until,
            double_until: 0.0,
            quad_fire_until: 0.0,
            haste: false,
            no_stack_double: rerelease_flag("g_dm_no_stack_double"),
            instant_switch: rerelease_flag("g_instant_weapon_switch"),
            quick_switch: false,
            infinite_ammo: false,
            players_collide: true,
            gravity: self.peek().physics.gravity(),
            weapon_thunk: false,
            view_height: player.view_height,
        })
    }
}

/// Neutral Q2 weapon input for handoffs without an error channel.
///
/// Carries the player's view pose with neutral buttons; used when the full
/// input read fails where the donor throw cannot surface.
fn q2_weapon_input_neutral(player: &MovementPlayer) -> qa_content::q2::foundation::weapons::types::Q2WeaponInput {
    use qa_content::q2::foundation::weapons::types::{Q2WeaponInput, WeaponHand};
    Q2WeaponInput {
        attack: false,
        latched_attack: false,
        holster: false,
        angles: player.view_angles,
        ducked: false,
        spectator: false,
        notarget: false,
        hand: WeaponHand::Right,
        animate_player: false,
        quad_until: 0.0,
        double_until: 0.0,
        quad_fire_until: 0.0,
        haste: false,
        no_stack_double: false,
        instant_switch: false,
        quick_switch: false,
        infinite_ammo: false,
        players_collide: false,
        gravity: 800.0,
        weapon_thunk: false,
        view_height: player.view_height,
    }
}

/// Immediate primary handoff for Quake II sources (C11; donor
/// `primaryHandoff` q2 arm, runtime.ts 2231-2237).
struct C11Q2Handoff {
    tables: C11Tables,
    player: MovementPlayer,
    provider: ProviderId,
    game: Rc<RefCell<qa_content::q2::foundation::host::Q2GameServices>>,
}

impl C11Q2Handoff {
    fn definition(&self, item: &ItemId) -> Option<qa_content::q2::foundation::weapons::types::Q2WeaponDefinition> {
        let found = qa_content::q2::foundation::weapons::player::registered_weapon_definitions(&self.game.borrow())
            .into_iter()
            .find(|definition| &definition.item == item);
        found
    }

    fn inventory_count(&self, item: &ItemId) -> f64 {
        let sim = self.tables.sim();
        let actors = sim.actors.borrow();
        let count = sim
            .peek()
            .inventory
            .count(actors.inner(), self.player.actor.id(), item.as_str());
        count
    }
}

impl super::weapon_slot::SourceWeaponHandoff for C11Q2Handoff {
    fn provider(&self) -> ProviderId {
        self.provider.clone()
    }

    fn accepts(&self, item: &ItemId) -> bool {
        self.definition(item).is_some() && self.inventory_count(item) > 0.0
    }

    fn select(&mut self, item: &ItemId) -> bool {
        let definition = match self.definition(item) {
            Some(definition) => definition,
            None => return false,
        };
        let result = qa_content::q2::foundation::weapons::player::request_weapon(
            &mut self.game.borrow_mut(),
            &self.player.actor,
            definition.name.as_str(),
            false,
        );
        matches!(
            result,
            qa_content::q2::foundation::weapons::player::Q2WeaponSelection::Selected
                | qa_content::q2::foundation::weapons::player::Q2WeaponSelection::Current
        )
    }

    fn holster(&mut self) {
        qa_content::q2::foundation::weapons::player::request_holster(&mut self.game.borrow_mut(), &self.player.actor);
    }

    fn is_holstered(&self) -> bool {
        let holstered =
            qa_content::q2::foundation::weapons::player::is_holstered(&self.game.borrow(), self.player.actor.id());
        holstered
    }

    fn resume(&mut self, item: Option<&ItemId>) -> super::weapon_slot::ResumeOutcome {
        let name = item
            .and_then(|entry| self.definition(entry))
            .map(|definition| definition.name);
        let native = self
            .tables
            .sim()
            .q2_weapon_input(&self.player)
            .unwrap_or_else(|_| q2_weapon_input_neutral(&self.player));
        qa_content::q2::foundation::weapons::player::resume_primary(
            &mut self.game.borrow_mut(),
            &self.player.actor,
            &native,
            name.as_deref(),
        );
        let active = arsenal_seam(&self.player).active_weapon;
        super::weapon_slot::ResumeOutcome::Immediate(item.is_none_or(|entry| active.as_ref() == Some(entry)))
    }

    fn restore_request(
        &mut self,
        _id: u64,
        _item: Option<&ItemId>,
    ) -> Box<dyn super::weapon_slot::SourceWeaponRequest> {
        Box::new(C11RefusedRequest)
    }

    fn is_deferred(&self) -> bool {
        false
    }
}

/// Immediate primary handoff for Quake III sources (C11; donor
/// `primaryHandoff` q3 arm, runtime.ts 2239-2247).
///
/// A missing Q3 primary continuation reads as refusal: the donor throws,
/// but the boolean handoff methods have no error channel.
struct C11Q3Handoff {
    tables: C11Tables,
    player: MovementPlayer,
    provider: ProviderId,
}

impl C11Q3Handoff {
    fn runtime_state(&self) -> Option<qa_content::q3::foundation::arsenal::Q3ArsenalRuntimeState> {
        let sim = self.tables.sim();
        let entry = sim.peek().q3_arsenals.get(&self.player.actor).cloned();
        entry
    }

    fn inventory_count(&self, item: &ItemId) -> f64 {
        let sim = self.tables.sim();
        let actors = sim.actors.borrow();
        let count = sim
            .peek()
            .inventory
            .count(actors.inner(), self.player.actor.id(), item.as_str());
        count
    }
}

impl super::weapon_slot::SourceWeaponHandoff for C11Q3Handoff {
    fn provider(&self) -> ProviderId {
        self.provider.clone()
    }

    fn accepts(&self, item: &ItemId) -> bool {
        let state = match self.runtime_state() {
            Some(state) => state,
            None => return false,
        };
        let missionpack = state.product == qa_content::q3::base::shared::definitions::Product::Missionpack;
        qa_content::q3::foundation::arsenal::Q3_WEAPON_ITEMS
            .iter()
            .any(|weapon| &weapon.item == item && (missionpack || weapon.weapon as i32 <= 10))
            && self.inventory_count(item) > 0.0
    }

    fn select(&mut self, item: &ItemId) -> bool {
        let weapon = match qa_content::q3::foundation::arsenal::Q3_WEAPON_ITEMS
            .iter()
            .find(|entry| &entry.item == item)
        {
            Some(entry) => entry.weapon,
            None => return false,
        };
        if self.inventory_count(item) <= 0.0 {
            return false;
        }
        let state = match self.runtime_state() {
            Some(state) => state,
            None => return false,
        };
        if state.product == qa_content::q3::base::shared::definitions::Product::Baseq3 && weapon as i32 > 10 {
            return false;
        }
        let next = match qa_content::q3::foundation::arsenal::q3_request_weapon(&state, weapon as i32) {
            Ok(next) => next,
            Err(_) => return false,
        };
        let sim = self.tables.sim();
        sim.lock().q3_arsenals.insert(self.player.actor.clone(), next);
        true
    }

    fn holster(&mut self) {
        if let Some(state) = self.runtime_state() {
            let next = qa_content::q3::foundation::arsenal::q3_request_weapon_holster(&state);
            let sim = self.tables.sim();
            sim.lock().q3_arsenals.insert(self.player.actor.clone(), next);
        }
    }

    fn is_holstered(&self) -> bool {
        self.runtime_state()
            .is_some_and(|state| state.external_slot == qa_world::movement::q3::weapon::Q3ExternalWeaponSlot::Holstered)
    }

    fn resume(&mut self, item: Option<&ItemId>) -> super::weapon_slot::ResumeOutcome {
        let next = match self.runtime_state() {
            Some(state) => match qa_content::q3::foundation::arsenal::q3_request_weapon_resume(&state) {
                Ok(next) => next,
                Err(_) => return super::weapon_slot::ResumeOutcome::Immediate(false),
            },
            None => return super::weapon_slot::ResumeOutcome::Immediate(false),
        };
        let sim = self.tables.sim();
        sim.lock().q3_arsenals.insert(self.player.actor.clone(), next);
        super::weapon_slot::ResumeOutcome::Immediate(item.is_none_or(|entry| self.select(entry)))
    }

    fn restore_request(
        &mut self,
        _id: u64,
        _item: Option<&ItemId>,
    ) -> Box<dyn super::weapon_slot::SourceWeaponRequest> {
        Box::new(C11RefusedRequest)
    }

    fn is_deferred(&self) -> bool {
        false
    }
}

impl SharedSimulation {
    /// Read grapple state (donor `grappleState`, runtime.ts 2189).
    pub fn grapple_state(&self, actor: &ActorId) -> Option<GrappleStateSnapshot> {
        let state = self.peek();
        let grapple = state.grapple.as_ref()?;
        let qa_content::contract::GrappleSelection::Enabled { mechanic, .. } = grapple.selection() else {
            return None;
        };
        let snapshot = GrappleStateSnapshot {
            mechanic: mechanic.clone(),
            hook: grapple.hook(actor),
            pulling: grapple.pulling(actor),
            gravity_scale: grapple.gravity_scale(actor),
            prediction_suppressed: grapple.prediction(actor),
        };
        Some(snapshot)
    }

    /// Shared grapple control (donor `sharedGrapple`, runtime.ts 2195).
    #[allow(dead_code)]
    fn shared_grapple(&self) -> SessionGrappleControl {
        SessionGrappleControl {
            selection: self.peek().recipe.equipment.grapple.clone(),
            weak: self.weak(),
            actors: self.actors_handle(),
            bodies: self.bodies_handle(),
        }
    }

    /// Primary weapon handoff (donor `primaryHandoff`, runtime.ts 2202-2247).
    ///
    /// The selected-arsenal arm delegates to the selected arsenals' own
    /// handoffs; the Q1 arm wraps the entity services' contract handoff.
    /// The Q2 resume path reads a neutral weapon input: `q2WeaponInput` is
    /// a C5 seam (donor 3963) until C5 lands it.
    fn primary_handoff(
        &self,
        actor: &ActorId,
    ) -> Result<Box<dyn super::weapon_slot::SourceWeaponHandoff>, RuntimeError> {
        use super::arsenal::selected::SelectedArsenal as SelectedArsenalBehavior;
        if self.peek().selected_arsenal.is_some() {
            let mut state = self.lock();
            let arsenal = state.selected_arsenal.as_mut().expect("selected arsenal checked above");
            let handoff: Box<dyn super::weapon_slot::PrimaryWeaponHandoff> = match arsenal {
                SelectedArsenal::Q1(arsenal) => arsenal.handoff(actor),
                SelectedArsenal::Q2(arsenal) => arsenal.handoff(actor),
                SelectedArsenal::Q3(arsenal) => arsenal.handoff(actor),
            };
            let handoff: Box<dyn super::weapon_slot::SourceWeaponHandoff> = handoff;
            return Ok(handoff);
        }
        let tables = C11Tables {
            actors: self.actors_handle(),
            bodies: self.bodies_handle(),
            weak: self.weak(),
        };
        let provider = self.peek().weapon_provider.provider.clone();
        let immediate = matches!(
            self.peek().source,
            SourceRuntime::Q3Qvm { .. } | SourceRuntime::Q2Native(_)
        );
        if immediate {
            let handoff = C11ImmediateHandoff {
                tables,
                actor: actor.clone(),
                provider,
                holstered: std::cell::Cell::new(false),
            };
            return Ok(Box::new(handoff));
        }
        let player = self.require_player(actor)?;
        let state = self.peek();
        match &state.source {
            SourceRuntime::QuakeC { game } => {
                let handoff = C11QuakeCHandoff {
                    tables,
                    actor: actor.clone(),
                    provider,
                    game: game.clone(),
                };
                Ok(Box::new(handoff))
            }
            SourceRuntime::Q1 { services, .. } => {
                let services = services.clone();
                let inner = services
                    .borrow_mut()
                    .primary_weapon_handoff(&player.actor)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                Ok(super::arsenal::q1::q1_handoff(inner))
            }
            SourceRuntime::Q2 { game, .. } => {
                if game.borrow().entity(actor).is_none() {
                    return fail("Q2 primary has no source player");
                }
                let handoff = C11Q2Handoff {
                    tables,
                    player,
                    provider,
                    game: game.clone(),
                };
                Ok(Box::new(handoff))
            }
            SourceRuntime::Q3 { .. } => {
                let handoff = C11Q3Handoff {
                    tables,
                    player,
                    provider,
                };
                Ok(Box::new(handoff))
            }
            _ => fail("Primary source is not ready"),
        }
    }

    /// Admit an actor to the grapple runtime (donor `admitGrapple`,
    /// runtime.ts 2249).
    fn admit_grapple(&self, actor: &ActorId) -> Result<(), RuntimeError> {
        let state = self.peek();
        let Some(grapple) = state.grapple.as_ref() else {
            return Ok(());
        };
        grapple
            .admit(actor)
            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        let slot_bound = matches!(
            grapple.selection(),
            qa_content::contract::GrappleSelection::Enabled {
                binding: qa_content::contract::GrappleBinding::Slot,
                ..
            }
        );
        let weapon_item = if slot_bound {
            Some(grapple.weapon().item.clone())
        } else {
            None
        };
        drop(state);
        let Some(weapon_item) = weapon_item else {
            return Ok(());
        };
        let owner = self
            .actors
            .borrow()
            .resolve_owned(actor)
            .ok_or_else(|| RuntimeError::Failure("Grapple owner was released".to_string()))?;
        let bound = {
            let actors = self.actors.borrow();
            let bound = self.peek().inventory.has(actors.inner(), actor);
            bound
        };
        if !bound {
            self.bind_equipment_inventory(&owner, &[]);
        }
        {
            let actors = self.actors.borrow();
            let mut state = self.lock();
            state
                .inventory
                .configure(
                    actors.inner(),
                    &owner,
                    qa_content::contract::InventoryEntry {
                        item: weapon_item,
                        count: 1.0,
                        capacity: 1.0,
                        count_policy: None,
                    },
                )
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        }
        if !self.peek().weapon_slots.contains_key(actor) {
            self.bind_weapon_slot(actor, None)?;
        }
        Ok(())
    }

    /// Whether the actor has a bound weapon slot (donor `hasWeaponSlot`,
    /// runtime.ts 2263).
    pub fn has_weapon_slot(&self, actor: &ActorId) -> bool {
        self.peek().weapon_slots.contains_key(actor)
    }

    /// Request a weapon switch (donor `requestWeapon`, runtime.ts 2265).
    ///
    /// The slot is removed, driven, then reinserted so the handoff methods
    /// can borrow the session while the slot is out; a failed request
    /// still restores the slot.
    pub fn request_weapon(
        &self,
        actor: &ActorId,
        weapon: &super::weapon_slot::WeaponReference,
    ) -> Result<bool, RuntimeError> {
        self.assert_open()?;
        self.require_equipment_player(actor);
        let mut slot = match self.lock().weapon_slots.remove(actor) {
            Some(slot) => slot,
            None => {
                let primary = self.primary_handoff(actor)?;
                let mut primary = primary;
                return Ok(weapon.provider == primary.provider() && primary.select(&weapon.item));
            }
        };
        let accepted = slot
            .request(weapon)
            .map_err(|error| RuntimeError::Failure(error.to_string()))
            .and_then(|accepted| {
                slot.reconcile()
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                Ok(accepted)
            });
        self.lock().weapon_slots.insert(actor.clone(), slot);
        accepted
    }
}

