/// Admitted native player handle (donor `q2NativePlayers` rows).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Q2NativePlayer {
    /// Session client.
    pub client: ClientId,
    /// Owned actor.
    pub actor: ActorId,
}

/// Quake weapon-source view (donor `q1WeaponSource`).
pub enum Q1WeaponSourceRef<'a> {
    /// Live source entity services handle.
    Live {
        /// Entity services handle.
        services: &'a Rc<RefCell<qa_content::q1::foundation::entity_services::Q1EntityServices>>,
    },
    /// Selected-arsenal entity services.
    Selected {
        /// Entity services.
        game: &'a qa_content::q1::foundation::entity_services::Q1EntityServices,
    },
}

/// Quake II weapon-source view (donor `q2WeaponSource`).
pub enum Q2WeaponSourceRef<'a> {
    /// Live source game services handle.
    Live {
        /// Game services handle.
        game: Rc<RefCell<qa_content::q2::foundation::host::Q2GameServices>>,
    },
    /// Selected-arsenal services bundle.
    Selected {
        /// Entity services.
        game: &'a Q2EntityServices,
        /// Weapon services.
        weapons: &'a Q2Weapons,
    },
}

impl SharedSimulation {
    /// Quake II server registry (donor `q2ServerCvars`).
    pub fn q2_server_cvars(&self) -> Option<Rc<RefCell<qa_core::cvar::CvarRegistry>>> {
        self.peek().q2_server_registry.clone()
    }

    /// Quake II movement tuning (donor `q2MovementConfig`).
    pub fn q2_movement_config(&self) -> Option<Q2MovementConfig> {
        let state = self.peek();
        if !matches!(state.source, SourceRuntime::Q2 { .. }) {
            return None;
        }
        let registry = state.q2_server_registry.clone()?;
        let game = self.q2_game_services()?;
        drop(state);
        let services = game.borrow();
        let rerelease = services.options.edition == qa_content::q2::foundation::host::Q2Edition::Rerelease;
        let deathmatch = services.options.mode == qa_content::q2::foundation::host::Q2Mode::Deathmatch;
        let air_accelerate = if rerelease {
            f64::from(
                registry
                    .borrow()
                    .get("sv_airaccelerate")
                    .map(|snapshot| snapshot.integer_value)
                    .unwrap_or(0),
            )
        } else if deathmatch {
            f64::from(registry.borrow().variable_value("sv_airaccelerate"))
        } else {
            0.0
        };
        Some(Q2MovementConfig {
            air_accelerate,
            n64_physics: rerelease && !deathmatch && services.options.map_name.starts_with("q64/"),
        })
    }

    /// Bound server settings for the active registry (donor `serverSettings`).
    ///
    /// Missing siblings: the q3 lane owns the host cvars/settings snapshot
    /// behind the Q3 arm; that source reports no bindings until it lands.
    pub fn server_settings(&self) -> Vec<crate::settings::server::ServerBinding> {
        use crate::settings::server::{server_definitions_for_selection, ProviderRef, ServerBinding};
        let state = self.peek();
        let registry = state.q2_server_registry.clone().or_else(|| match &state.source {
            SourceRuntime::Q3 { .. } => None,
            SourceRuntime::Q3Qvm { game, .. } => Some(Rc::clone(&game.state.cvars)),
            SourceRuntime::Q1 { cvars, .. } => Some(Rc::clone(cvars)),
            SourceRuntime::QuakeC { game, .. } => Some(Rc::clone(&game.cvars())),
            _ => None,
        });
        if registry.is_none() {
            return Vec::new();
        }
        let recipe = state.recipe.clone();
        drop(state);
        let reference = |value: &ProviderReference| ProviderRef {
            provider: provider_text(&value.provider),
            content: value.content.as_str().to_string(),
        };
        let Ok(definitions) = server_definitions_for_selection(
            &reference(&recipe.map.entities),
            &reference(&recipe.r#match),
            &reference(&recipe.combat),
        ) else {
            return Vec::new();
        };
        definitions
            .into_iter()
            .map(|definition| ServerBinding {
                definition,
                initializing: false,
            })
            .collect()
    }

    /// Captured server profile (donor `serverProfile`).
    pub fn server_profile(&self) -> Result<crate::settings::server::ServerProfile, RuntimeError> {
        let state = self.peek();
        let registry = state.q2_server_registry.clone().or_else(|| match &state.source {
            SourceRuntime::Q3 { .. } => None,
            SourceRuntime::Q3Qvm { game, .. } => Some(Rc::clone(&game.state.cvars)),
            SourceRuntime::Q1 { cvars, .. } => Some(Rc::clone(cvars)),
            SourceRuntime::QuakeC { game, .. } => Some(Rc::clone(&game.cvars())),
            _ => None,
        });
        drop(state);
        let Some(registry) = registry else {
            return Err(RuntimeError::Failure(
                "Server profile has no source registry".to_string(),
            ));
        };
        let bindings = self.server_settings();
        let borrowed = registry.borrow();
        let profile = crate::settings::server::capture_server_profile(&bindings, &borrowed).map_err(source_failure);
        drop(borrowed);
        profile
    }

    /// Admitted native players (donor `q2NativePlayers`).
    pub fn q2_native_players(&self) -> Vec<Q2NativePlayer> {
        let state = self.peek();
        let SourceRuntime::Q2Native(native) = &state.source else {
            return Vec::new();
        };
        let clients = match native {
            Q2NativeSource::Classic { clients, .. } | Q2NativeSource::Rerelease { clients, .. } => clients,
        };
        clients
            .iter()
            .map(|(client, actor)| Q2NativePlayer {
                client: client.clone(),
                actor: actor.id().clone(),
            })
            .collect()
    }

    /// Run a reader over the Quake weapon source (donor `q1WeaponSource`).
    pub fn with_q1_weapon_source<R>(&self, f: impl FnOnce(Q1WeaponSourceRef<'_>) -> R) -> Option<R> {
        let state = self.peek();
        if state.selected_arsenal.is_some() {
            let selected = state
                .selected_arsenal
                .as_ref()
                .is_some_and(|arsenal| arsenal.family() == "q1")
                && matches!(state.selected_weapon_source, Some(SelectedWeaponSource::Q1 { .. }));
            if !selected {
                return None;
            }
            let SelectedWeaponSource::Q1 { game, .. } = state.selected_weapon_source.as_ref()? else {
                return None;
            };
            return Some(f(Q1WeaponSourceRef::Selected { game }));
        }
        let SourceRuntime::Q1 { services, .. } = &state.source else {
            return None;
        };
        Some(f(Q1WeaponSourceRef::Live { services }))
    }

    /// Run a reader over the Quake II weapon source (donor `q2WeaponSource`).
    pub fn with_q2_weapon_source<R>(&self, f: impl FnOnce(Q2WeaponSourceRef<'_>) -> R) -> Option<R> {
        let state = self.peek();
        if state.selected_arsenal.is_some() {
            let selected = state
                .selected_arsenal
                .as_ref()
                .is_some_and(|arsenal| arsenal.family() == "q2")
                && matches!(state.selected_weapon_source, Some(SelectedWeaponSource::Q2 { .. }));
            if !selected {
                return None;
            }
            let SelectedWeaponSource::Q2 { game, weapons, .. } = state.selected_weapon_source.as_ref()? else {
                return None;
            };
            return Some(f(Q2WeaponSourceRef::Selected { game, weapons }));
        }
        if !matches!(state.source, SourceRuntime::Q2 { .. }) {
            return None;
        }
        drop(state);
        let game = self.q2_game_services()?;
        Some(f(Q2WeaponSourceRef::Live { game }))
    }

    /// Run a reader over the item-capable Quake II weapon source (donor
    /// `q2ItemWeaponSource`).
    pub fn with_q2_item_weapon_source<R>(&self, f: impl FnOnce(Q2WeaponSourceRef<'_>) -> R) -> Option<R> {
        // The live fallback duplicates `with_q2_weapon_source`'s live arm so
        // the reader closure (which is not `Clone`) runs exactly once.
        let state = self.peek();
        if state.selected_arsenal.is_some() {
            return self.with_q2_weapon_source(f);
        }
        if !matches!(state.source, SourceRuntime::Q2 { .. }) {
            return None;
        }
        drop(state);
        let game = self.q2_game_services()?;
        Some(f(Q2WeaponSourceRef::Live { game }))
    }

    /// Run a reader over the selected Q3 arsenal (donor
    /// `selectedQ3WeaponSource`).
    pub fn with_selected_q3_weapon_source<R>(
        &self,
        f: impl FnOnce(&super::arsenal::q3::Q3SelectedArsenal) -> R,
    ) -> Option<R> {
        let state = self.peek();
        let SelectedArsenal::Q3(arsenal) = state.selected_arsenal.as_ref()? else {
            return None;
        };
        Some(f(arsenal))
    }

    /// Raw world entity text (donor `sourceEntityText`).
    pub fn source_entity_text(&self) -> String {
        self.peek().world_entities.clone()
    }
}

