// C7: player views (donor runtime.ts 5270-5326).
// ---------------------------------------------------------------------------

/// Base view with neutral presentation (donor `PlayerView` literal).
fn base_player_view(origin: Vec3, angles: Vec3, view_height: f64) -> PlayerView {
    PlayerView {
        client_view_offset_delta: None,
        blend: None,
        damage_blend: None,
        origin,
        angles,
        view_height,
        kick_angles: None,
        field_of_view: None,
        foreign_character_death: false,
        pitch_drift: None,
    }
}

impl SharedSimulation {
    /// Movement-player base view (donor `MovementPlayer.view`, players.ts).
    fn movement_player_view(&self, player: &MovementPlayer) -> PlayerView {
        let actors = self.actors.borrow();
        let origin = self
            .bodies_table
            .borrow()
            .read(actors.inner(), player.actor.id())
            .map(|body| body.origin)
            .unwrap_or_else(zero);
        base_player_view(origin, player.view_angles, player.view_height)
    }

    /// Whether the source client view is crouched (donor `sourceClientView`
    /// crouched arm, donor runtime.ts 440; the canonical method belongs to
    /// the movement lane, this helper ports only what `playerView` needs).
    fn source_client_crouched(&self, actor: &ActorId) -> Result<bool, RuntimeError> {
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q2Native(_) => {
                let client = self.native_q2_client(actor)?;
                let slot = client.slot() + 1;
                drop(state);
                let mut locked = self.lock();
                let view = match &mut locked.source {
                    SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game
                        .player_view(slot, actor)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?,
                    SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game
                        .player_view(slot, actor)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?,
                    _ => return Err(RuntimeError::Failure("No native Quake II source".to_string())),
                };
                Ok(view.crouched)
            }
            SourceRuntime::Q3Qvm { game, .. } => {
                let slot = game
                    .records
                    .slot(actor)
                    .ok_or_else(|| RuntimeError::Failure("QVM view requires a live source client".to_string()))?;
                Ok(game.records.player(slot).movement_flags & 1 != 0)
            }
            _ => {
                drop(state);
                let player = self.require_player(actor)?;
                let view = self.source_player_view(actor)?;
                let actors = self.actors.borrow();
                let body = self.bodies_table.borrow().read(actors.inner(), actor);
                let Some(body) = body else {
                    return Err(RuntimeError::Failure(
                        "Client view requires a live movement owner".to_string(),
                    ));
                };
                let _ = view;
                match &player.state {
                    MovementState::Q3(state) => Ok(state.movement_flags & 1 != 0),
                    MovementState::Q2Classic(state) => Ok(state.flags & 1 != 0),
                    MovementState::Q2Rerelease(state) => Ok(state.flags & 1 != 0),
                    _ => Ok(matches!(player.state, MovementState::Q1Quakeworld(_))
                        && body.bounds.max.z < player.standing_bounds.max.z),
                }
            }
        }
    }

    /// Player view with client-output and punch overlays (donor `playerView`).
    pub fn player_view(&self, actor: &ActorId) -> Result<PlayerView, RuntimeError> {
        let mut view = self.source_player_view(actor)?;
        let output = self.active_client_outputs(actor);
        let body = match output.as_ref().and_then(|output| output.view_offset) {
            None => None,
            Some(_) => {
                let actors = self.actors.borrow();
                self.bodies_table.borrow().read(actors.inner(), actor)
            }
        };
        if let (Some(output), Some(body)) = (output.as_ref(), body.as_ref()) {
            if let Some(offset) = output.view_offset {
                if output.stance != Some(false) || !self.source_client_crouched(actor)? {
                    let origin = add(
                        body.origin,
                        Vec3 {
                            x: offset.x,
                            y: offset.y,
                            z: 0.0,
                        },
                    );
                    let delta = Vec3 {
                        x: origin.x - view.origin.x,
                        y: origin.y - view.origin.y,
                        z: (f64::from(origin.z) + f64::from(offset.z) - f64::from(view.origin.z) - view.view_height)
                            as f32,
                    };
                    view.origin = origin;
                    view.view_height = f64::from(offset.z);
                    view.client_view_offset_delta = Some(delta);
                }
            }
        }
        let punch = self
            .lock()
            .q1_punch
            .read(actor)
            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        view.kick_angles = Some(add(view.kick_angles.unwrap_or_else(zero), punch));
        Ok(view)
    }

    /// Source player view (donor `sourcePlayerView`).
    pub fn source_player_view(&self, actor: &ActorId) -> Result<PlayerView, RuntimeError> {
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q2Native(_) => {
                let client = self.native_q2_client(actor)?;
                let slot = client.slot() + 1;
                drop(state);
                let mut locked = self.lock();
                match &mut locked.source {
                    SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => {
                        let player_state = game
                            .player_state(slot)
                            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                        Ok(super::classic_guest_player::classic_guest_player_view(&player_state))
                    }
                    SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => {
                        let player_state = game
                            .player_state(slot)
                            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                        Ok(super::rerelease_guest_player::rerelease_guest_player_view(
                            &player_state,
                        ))
                    }
                    _ => Err(RuntimeError::Failure("No native Quake II source".to_string())),
                }
            }
            SourceRuntime::Q3Qvm { game, .. } => {
                let player = game
                    .players()
                    .into_iter()
                    .find(|player| player.actor == *actor)
                    .ok_or_else(|| RuntimeError::Failure("Actor has no Q3 guest client view".to_string()))?;
                let record = game.records.player(player.source_entity);
                Ok(base_player_view(
                    record.origin,
                    record.view_angles,
                    f64::from(record.view_height),
                ))
            }
            _ => {
                drop(state);
                self.general_source_player_view(actor)
            }
        }
    }
}

// ---------------------------------------------------------------------------
// C7: general source view arms (donor runtime.ts 5286-5326).
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Non-native source view arms (donor `sourcePlayerView` general path).
    fn general_source_player_view(&self, actor: &ActorId) -> Result<PlayerView, RuntimeError> {
        let player = self.require_player(actor)?;
        let state = self.peek();
        let source = state.q2_views.get(actor).cloned();
        let is_q2 = matches!(state.source, SourceRuntime::Q2 { .. });
        let is_q3 = matches!(state.source, SourceRuntime::Q3 { .. });
        let is_quakec = matches!(state.source, SourceRuntime::QuakeC { .. });
        let health = state.combat.read(actor).map(|combat| combat.health).unwrap_or(0.0);
        drop(state);
        let mut view = self.movement_player_view(&player);
        match &player.state {
            MovementState::Q1Netquake(state) => {
                view.pitch_drift = Some(super::types::PitchDrift {
                    grounded: !matches!(state.ground, qa_world::movement::types::TraceHit::None),
                    ideal_pitch: state.ideal_pitch,
                    disabled: player.intermission || player.cutscene.is_some() || health <= 0.0 || state.move_type != 3,
                });
            }
            MovementState::Q1Quakeworld(state) => {
                view.pitch_drift = Some(super::types::PitchDrift {
                    grounded: !matches!(state.ground, qa_world::movement::types::TraceHit::None),
                    ideal_pitch: 0.0,
                    disabled: player.intermission || player.cutscene.is_some() || health <= 0.0 || state.spectator != 0,
                });
            }
            _ => {}
        }
        if is_q2 {
            let game = self.q2_game_services();
            if let Some(game) = game {
                let services = game.borrow();
                if let Some(observer) = services.players.states.get(actor) {
                    if observer.spectator && observer.chase_target.is_some() {
                        return Ok(PlayerView {
                            origin: view.origin,
                            angles: view.angles,
                            view_height: 0.0,
                            field_of_view: Some(source.map(|source| f64::from(source.fov)).unwrap_or(90.0)),
                            ..view
                        });
                    }
                }
            }
        }
        if let Some(cutscene) = player.cutscene.as_ref() {
            return Ok(PlayerView {
                origin: add(
                    cutscene.origin,
                    Vec3 {
                        x: cutscene.view_offset.x,
                        y: cutscene.view_offset.y,
                        z: 0.0,
                    },
                ),
                angles: cutscene.angles,
                view_height: f64::from(cutscene.view_offset.z),
                field_of_view: Some(if is_q2 {
                    source.map(|source| f64::from(source.fov)).unwrap_or(90.0)
                } else {
                    90.0
                }),
                ..view
            });
        }
        if is_quakec {
            let state = self.peek();
            let SourceRuntime::QuakeC { game, .. } = &state.source else {
                return Err(RuntimeError::Failure("QuakeC view lost its source".to_string()));
            };
            if let Some(camera) = game.local_client_view(actor) {
                return Ok(camera);
            }
        }
        if is_quakec && !player.intermission {
            let state = self.peek();
            let SourceRuntime::QuakeC { game, .. } = &state.source else {
                return Err(RuntimeError::Failure("QuakeC view lost its source".to_string()));
            };
            let offset = game
                .client_view_offset(actor)
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            return Ok(PlayerView {
                origin: add(
                    view.origin,
                    Vec3 {
                        x: offset.x,
                        y: offset.y,
                        z: 0.0,
                    },
                ),
                view_height: f64::from(offset.z),
                angles: if health <= 0.0 {
                    Vec3 { z: 80.0, ..view.angles }
                } else {
                    view.angles
                },
                ..view
            });
        }
        if !player.intermission && health <= 0.0 {
            let state = self.peek();
            if let Some(lifecycle) = state
                .q1_characters
                .get(&player.actor)
                .map(|character| character.lifecycle())
            {
                if lifecycle.life != qa_content::q1::base::player::Q1PlayerLife::Alive {
                    let mut view = PlayerView {
                        origin: add(
                            view.origin,
                            Vec3 {
                                x: lifecycle.view_offset.x,
                                y: lifecycle.view_offset.y,
                                z: 0.0,
                            },
                        ),
                        view_height: f64::from(lifecycle.view_offset.z),
                        angles: Vec3 { z: 80.0, ..view.angles },
                        field_of_view: Some(source.map(|source| f64::from(source.fov)).unwrap_or(90.0)),
                        ..view
                    };
                    if is_q3 {
                        view.foreign_character_death = true;
                    }
                    return Ok(view);
                }
            }
            if player.character == qa_content::contract::GameFamily::Q3 && state.characters.contains_key(&player.actor)
            {
                let attack = state.last_attack.get(&player.actor).cloned();
                drop(state);
                let actors = self.actors.borrow();
                let killer = attack
                    .as_ref()
                    .and_then(|attack| attack.attacker.as_ref())
                    .and_then(|attacker| self.bodies_table.borrow().read(actors.inner(), attacker));
                let yaw = match (killer, attack.as_ref().and_then(|attack| attack.attacker.as_ref())) {
                    (Some(killer), Some(attacker)) if attacker != actor => {
                        ((f64::from(killer.origin.y) - f64::from(view.origin.y))
                            .atan2(f64::from(killer.origin.x) - f64::from(view.origin.x))
                            * 180.0
                            / std::f64::consts::PI) as f32
                    }
                    _ => view.angles.y,
                };
                return Ok(PlayerView {
                    view_height: -16.0,
                    angles: Vec3 {
                        x: -15.0,
                        y: yaw,
                        z: 40.0,
                    },
                    field_of_view: Some(source.map(|source| f64::from(source.fov)).unwrap_or(90.0)),
                    ..view
                });
            }
        }
        if player.character != qa_content::contract::GameFamily::Q2 {
            if let Some(source) = source {
                view.field_of_view = Some(f64::from(source.fov));
            }
            return Ok(view);
        }
        let Some(source) = source else {
            return Ok(view);
        };
        let state = self.peek();
        let rerelease = is_q2
            && self.q2_game_services().is_some_and(|game| {
                game.borrow().options.edition == qa_content::q2::foundation::host::Q2Edition::Rerelease
            });
        let mut foreign_character_death = false;
        if is_q3 && !player.intermission {
            foreign_character_death = state
                .q2_characters
                .get(&player.actor)
                .is_some_and(|character| character.state.dead);
        }
        drop(state);
        Ok(PlayerView {
            origin: add(
                view.origin,
                Vec3 {
                    x: source.offset.x,
                    y: source.offset.y,
                    z: 0.0,
                },
            ),
            angles: add(
                if !player.intermission && health > 0.0 {
                    view.angles
                } else {
                    source.angles
                },
                source.kick_angles,
            ),
            foreign_character_death,
            field_of_view: Some(f64::from(source.fov)),
            view_height: f64::from(source.offset.z)
                + if is_q2 && rerelease && !player.intermission {
                    view.view_height
                } else {
                    0.0
                },
            ..view
        })
    }
}

// --- C11 part 2e: grapple poses, equipment weapon input, character animation, slot host (donor 2285-2346) ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[allow(dead_code)]
enum C11AnimPriority {
    Attack,
    Reverse,
}

fn player_client_in(state: &SharedSimulationState, actors: &SessionActorRegistry, actor: &ActorId) -> Option<ClientId> {
    if let SourceRuntime::Q2Native(native) = &state.source {
        let clients = match native {
            Q2NativeSource::Classic { clients, .. } => clients,
            Q2NativeSource::Rerelease { clients, .. } => clients,
        };
        return clients
            .iter()
            .find(|(_, owner)| owner.id() == actor)
            .map(|(client, _)| client.clone());
    }
    if let SourceRuntime::Q3Qvm { game, .. } = &state.source {
        return game
            .players()
            .into_iter()
            .find(|player| player.actor == *actor)
            .map(|player| player.client);
    }
    let owned = actors.resolve_owned(actor)?;
    state.player_states.get(&owned).map(|player| player.client.clone())
}

fn equipment_player_available_in(
    state: &SharedSimulationState,
    actors: &SessionActorRegistry,
    actor: &ActorId,
) -> bool {
    match &state.source {
        SourceRuntime::Q3Qvm { game, weapons, .. } => {
            let Some(player) = game.players().iter().find(|entry| entry.actor == *actor).cloned() else {
                return false;
            };
            if let Some(services) = weapons {
                return services
                    .available(actor, false)
                    .expect("qvm weapon availability failed");
            }
            let record = game.records.player(player.source_entity);
            record.stats[0] > 0
                && record.movement_type != qa_content::q3::base::shared::definitions::MoveType::PmSpectator as i32
                && record.movement_type != qa_content::q3::base::shared::definitions::MoveType::PmIntermission as i32
                && record.movement_type != qa_content::q3::base::shared::definitions::MoveType::PmSpintermission as i32
        }
        SourceRuntime::Q2Native(_) => {
            if player_client_in(state, actors, actor).is_none() {
                return false;
            }
            // Missing siblings: `NativePrimaryWeapons::available` needs the
            // native-weapon lane's synthetic host, so the donor's native
            // arm reads empty and every owner takes the health fallback.
            state.combat.read(actor).map(|entry| entry.health).unwrap_or(100.0) > 0.0
        }
        _ => {
            let Some(owned) = actors.resolve_owned(actor) else {
                return false;
            };
            let Some(player) = state.player_states.get(&owned) else {
                return false;
            };
            !player.intermission
                && player.cutscene.is_none()
                && state.combat.read(actor).map(|entry| entry.health).unwrap_or(0.0) > 0.0
        }
    }
}

#[allow(dead_code)]
fn c11_weapon_character_animation_in(
    state: &mut SharedSimulationState,
    actors: &SessionActorRegistry,
    actor: &ActorId,
    priority: C11AnimPriority,
    melee: bool,
    content: &ContentId,
    reset_time: bool,
) -> Result<(), RuntimeError> {
    if matches!(state.source, SourceRuntime::Q2Native(_)) {
        if priority == C11AnimPriority::Attack {
            assert!(
                state.native_primary_weapons.is_some(),
                "Original native selected weapons have no qualified owner"
            );
            return Err(RuntimeError::Failure(
                "Missing siblings: native attack animation needs the native-weapon lane's synthetic host".to_string(),
            ));
        }
        return Ok(());
    }
    if let SourceRuntime::Q3Qvm { weapons, .. } = &state.source {
        assert!(
            weapons.is_some(),
            "Original QVM weapon services have no qualified owner"
        );
        if priority == C11AnimPriority::Attack {
            weapons
                .as_ref()
                .expect("qvm weapons checked above")
                .attack_animation(actor, melee)
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        }
        return Ok(());
    }
    let Some(owned) = actors.resolve_owned(actor) else {
        return Ok(());
    };
    let Some(player) = state.player_states.get(&owned).cloned() else {
        return Ok(());
    };
    if matches!(
        player.animation.state,
        qa_world::movement::types::AnimationState::Q3 { .. }
    ) {
        let dead = state.combat.read(actor).map(|entry| entry.health).unwrap_or(0.0) <= 0.0;
        let missionpack = state
            .recipe
            .character
            .definition
            .content
            .to_string()
            .contains("missionpack");
        let context = qa_world::movement::q3::animation::Q3AnimationContext {
            animation: player.animation.clone(),
            dead,
            elapsed_milliseconds: 0,
            buttons: player.buttons as i32,
            product: if missionpack {
                qa_world::movement::q3::types::Q3Product::MissionPack
            } else {
                qa_world::movement::q3::types::Q3Product::BaseQ3
            },
            event_sequence: 0,
        };
        let operation = match (priority, melee) {
            (C11AnimPriority::Reverse, _) => qa_world::movement::q3::constants::player_animation::TORSO_DROP,
            (C11AnimPriority::Attack, true) => qa_world::movement::q3::constants::player_animation::TORSO_ATTACK2,
            (C11AnimPriority::Attack, false) => qa_world::movement::q3::constants::player_animation::TORSO_ATTACK,
        };
        let result = qa_world::movement::q3::animation::run_q3_torso_operation(operation, &context, false)
            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        if let Some(entry) = state.player_states.get_mut(&owned) {
            entry.animation = result.animation.clone();
        }
        if let Some(character) = state.characters.get_mut(&owned) {
            character.animation = Some(result.animation.clone());
        }
        if matches!(state.source, SourceRuntime::Q3 { .. }) {
            panic!("Missing siblings: q3 lane owns the source records behind writeQ3CharacterAnimation");
        }
        return Ok(());
    }
    if player.character != GameFamily::Q2 {
        return Ok(());
    }
    let ducked = player.bounds.max.z < player.standing_bounds.max.z;
    let (first, last) = match priority {
        C11AnimPriority::Attack => qa_content::q2::foundation::weapons::presentation::q2_attack_frames(ducked, 1),
        C11AnimPriority::Reverse => qa_content::q2::foundation::weapons::presentation::q2_reverse_frames(ducked),
    };
    let frame_priority = match priority {
        C11AnimPriority::Attack => qa_content::q2::base::player::character::Q2CharacterAnimation::Attack,
        C11AnimPriority::Reverse => qa_content::q2::base::player::character::Q2CharacterAnimation::Reverse,
    };
    if let Some(character) = state.q2_characters.get_mut(&player.actor) {
        character.set_animation(frame_priority, first, last);
    }
    let event_priority = match priority {
        C11AnimPriority::Attack => qa_content::q2::foundation::weapons::types::PlayerAnimationPriority::Attack,
        C11AnimPriority::Reverse => qa_content::q2::foundation::weapons::types::PlayerAnimationPriority::Reverse,
    };
    let event = qa_content::q2::foundation::weapons::types::Q2WeaponEvent::PlayerAnimation {
        actor: actor.clone(),
        priority: event_priority,
        first,
        last,
        reset_time,
    };
    if let Some(character) = state.q2_characters.get_mut(&player.actor) {
        character.set_animation(frame_priority, first, last);
    }
    let time = match &state.selected_weapon_source {
        Some(SelectedWeaponSource::Q2 { frame, .. }) if content == &state.weapon_provider.content => frame.time,
        _ => state.source_frame.time,
    };
    state.events.emit_owned(
        None,
        content,
        super::types::SourcePresentationEvent::Q2Weapon(event),
        time,
        None,
    );
    Ok(())
}

#[allow(dead_code)]
fn c11_grapple_character_animation_in(
    state: &mut SharedSimulationState,
    actors: &SessionActorRegistry,
    actor: &ActorId,
    priority: C11AnimPriority,
    melee: bool,
) -> Result<(), RuntimeError> {
    let (content, reset_time) = match &state.recipe.equipment.grapple {
        qa_content::contract::GrappleSelection::Disabled => {
            return fail("Grapple animation has no selected source");
        }
        qa_content::contract::GrappleSelection::Enabled { source, mechanic, .. } => {
            let reset = matches!(
                mechanic,
                qa_content::contract::GrappleMechanicDetail::Q1Threewave {
                    edition: qa_content::contract::SourceEdition::Rerelease
                } | qa_content::contract::GrappleMechanicDetail::Q2Ctf {
                    edition: qa_content::contract::SourceEdition::Rerelease
                }
            );
            (source.content.clone(), reset)
        }
    };
    c11_weapon_character_animation_in(state, actors, actor, priority, melee, &content, reset_time)
}

#[allow(dead_code)]
fn c11_slot_attack_animation() {}

#[allow(dead_code)]
fn c11_slot_reverse_animation() {}

#[allow(dead_code)]
fn c11_slot_powerup_sound() {}

#[allow(dead_code)]
fn c11_slot_animation_time(state: &qa_content::q2::foundation::weapons::generic_frame::Q2GenericFrameState) -> f64 {
    // Bare `fn` hooks cannot reach the firing actor, so the session-derived
    // rate inputs default per the grapple runtime's documented hook design.
    let rate = qa_content::q2::foundation::weapons::presentation::q2_weapon_animation_rate(
        &qa_content::q2::foundation::weapons::presentation::Q2AnimationRateInput {
            quick_switch: false,
            frame_seconds: 0.0,
            phase: state.phase,
            frame: state.frame,
            quad_fire_until: 0.0,
            haste: false,
            now: 0.0,
        },
    );
    f64::from(1000 / rate) / 1000.0
}

#[allow(dead_code)]
struct C11GrappleSlotHost {
    state: Weak<RefCell<SharedSimulationState>>,
    actors: Rc<RefCell<SessionActorRegistry>>,
}

impl super::grapple_runtime::GrappleSlotHost for C11GrappleSlotHost {
    fn selected(&self, actor: &ActorId) -> bool {
        self.state.upgrade().is_some_and(|state| {
            state
                .borrow()
                .weapon_slots
                .get(actor)
                .is_some_and(|slot| slot.equipment_selected())
        })
    }

    fn available(&self, actor: &ActorId) -> bool {
        let Some(state) = self.state.upgrade() else {
            return false;
        };
        let actors = self.actors.borrow();
        let borrowed = state.borrow();
        equipment_player_available_in(&borrowed, &actors, actor)
    }

    fn frame(&self, actor: &ActorId, frame: i32) {
        if frame != 2 {
            return;
        }
        let Some(state) = self.state.upgrade() else {
            return;
        };
        let actors = self.actors.borrow();
        c11_grapple_character_animation_in(&mut state.borrow_mut(), &actors, actor, C11AnimPriority::Attack, true)
            .expect("Grapple animation has no selected source");
    }

    fn presentation(&self, _actor: &ActorId) -> super::grapple_runtime::GrappleSlotPresentation {
        super::grapple_runtime::GrappleSlotPresentation {
            attack_animation: c11_slot_attack_animation,
            reverse_animation: c11_slot_reverse_animation,
            powerup_sound: c11_slot_powerup_sound,
            animation_time: c11_slot_animation_time,
        }
    }
}

impl SharedSimulation {
    #[allow(dead_code)]
    fn q1_character_pose(
        &self,
        actor: &ActorId,
    ) -> Result<qa_content::q1::base::player::Q1CharacterSourcePose, RuntimeError> {
        if self
            .peek()
            .weapon_slots
            .get(actor)
            .is_some_and(|slot| slot.equipment_selected())
        {
            let pose = self
                .with_grapple(|grapple| {
                    grapple.with_source(|source| match source {
                        super::grapple_runtime::GrappleSource::Q1Threewave { game } => {
                            match qa_content::q1::equipment::weapon::threewave_character_pose(game, actor) {
                                Ok(pose) => Some(Ok(pose)),
                                Err(error) => Some(Err(RuntimeError::Failure(error.to_string()))),
                            }
                        }
                        _ => None,
                    })
                })
                .flatten();
            if let Some(result) = pose {
                let pose = result?;
                return Ok(qa_content::q1::base::player::Q1CharacterSourcePose {
                    axe_pose: Some(pose.axe_pose),
                    definition: None,
                    frame: pose.frame.map(f64::from),
                });
            }
        }
        if let SourceRuntime::Q1 {
            services, composition, ..
        } = &self.peek().source
        {
            let mut game = services.borrow_mut();
            return composition
                .character_pose(&mut game, actor)
                .map_err(|error| RuntimeError::Failure(error.to_string()));
        }
        let ui = self.player_ui(actor)?;
        Ok(qa_content::q1::base::player::Q1CharacterSourcePose {
            axe_pose: Some(ui.active_weapon.as_ref().is_some_and(|id| id == "q1:weapon/axe")),
            definition: None,
            frame: None,
        })
    }

    #[allow(dead_code)]
    fn equipment_weapon_input(
        &self,
        actor: &ActorId,
    ) -> Result<qa_content::q2::foundation::weapons::types::Q2WeaponInput, RuntimeError> {
        use qa_content::q2::foundation::weapons::types::{Q2WeaponInput, WeaponHand};
        let native_equipment = matches!(
            self.peek().source,
            SourceRuntime::Q2Native(_) | SourceRuntime::Q3Qvm { .. }
        );
        if native_equipment {
            let player = self.require_player(actor)?;
            let view = self.movement_player_view(&player);
            let attack = self.with_grapple(|grapple| grapple.held(actor)).unwrap_or(false);
            let actors = self.actors.borrow();
            let max_z = self
                .bodies_table
                .borrow()
                .read(actors.inner(), actor)
                .map(|body| body.bounds.max.z)
                .unwrap_or(32.0);
            let spectator = !self.equipment_player_available(actor);
            let gravity = self.peek().physics.gravity();
            let (quad_until, haste) = match &self.peek().source {
                SourceRuntime::Q3Qvm { game, .. } => {
                    let record = game.records.player(game.records.require_slot(actor));
                    let quad =
                        f64::from(record.powerups[qa_content::q3::base::shared::definitions::Powerup::PwQuad as usize])
                            / 1000.0;
                    let hasted = f64::from(
                        record.powerups[qa_content::q3::base::shared::definitions::Powerup::PwHaste as usize],
                    ) > self.time_seconds() * 1000.0;
                    (quad, hasted)
                }
                _ => (0.0, false),
            };
            return Ok(Q2WeaponInput {
                attack,
                latched_attack: false,
                holster: false,
                angles: view.angles,
                ducked: max_z < 32.0,
                spectator,
                notarget: false,
                hand: WeaponHand::Right,
                animate_player: false,
                quad_until,
                double_until: 0.0,
                quad_fire_until: 0.0,
                haste,
                no_stack_double: false,
                instant_switch: false,
                quick_switch: false,
                infinite_ammo: false,
                players_collide: true,
                gravity,
                weapon_thunk: false,
                view_height: view.view_height,
            });
        }
        let player = self.require_player(actor)?;
        let native = self.q2_weapon_input(&player)?;
        let input = match &self.peek().source {
            SourceRuntime::Q2 { game, .. } => {
                let product = qa_content::q2::composition::product_runtime(&game.borrow()).clone();
                product.weapon_input(actor.clone(), &mut game.borrow_mut(), native)
            }
            _ => native,
        };
        if matches!(self.peek().source, SourceRuntime::Q3 { .. }) {
            panic!("Missing siblings: q3 lane owns the source records behind equipmentWeaponInput");
        }
        let quad_until = if matches!(self.peek().source, SourceRuntime::Q1 { .. }) {
            if let SourceRuntime::Q1 { services, .. } = &self.peek().source {
                services
                    .borrow()
                    .player_ref(actor)
                    .and_then(|state| {
                        state
                            .powerups
                            .get(&qa_content::q1::foundation::types::Q1Powerup::Quad)
                            .copied()
                    })
                    .unwrap_or(0.0)
            } else {
                input.quad_until
            }
        } else {
            input.quad_until
        };
        Ok(Q2WeaponInput {
            quad_until,
            haste: input.haste,
            ..input
        })
    }

    #[allow(dead_code)]
    fn grapple_character_animation(
        &self,
        actor: &ActorId,
        priority: C11AnimPriority,
        melee: bool,
    ) -> Result<(), RuntimeError> {
        let actors = self.actors.borrow();
        c11_grapple_character_animation_in(&mut self.lock(), &actors, actor, priority, melee)
    }

    #[allow(dead_code)]
    fn weapon_character_animation(
        &self,
        actor: &ActorId,
        priority: C11AnimPriority,
        melee: bool,
        content: &ContentId,
        reset_time: bool,
    ) -> Result<(), RuntimeError> {
        let actors = self.actors.borrow();
        c11_weapon_character_animation_in(&mut self.lock(), &actors, actor, priority, melee, content, reset_time)
    }

    fn grapple_slot_host(&self) -> Rc<dyn super::grapple_runtime::GrappleSlotHost> {
        Rc::new(C11GrappleSlotHost {
            state: Rc::downgrade(&self.state),
            actors: Rc::clone(&self.actors),
        })
    }
}
// ---------------------------------------------------------------------------
// C7: native source UI tail (donor runtime.ts 4926-4947).
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Native source HUD tail (donor `nativePlayerUi` q3-qvm/q2-native arms).
    ///
    /// Missing siblings: the runtime `NativePrimaryInventory` seam has no
    /// compat-host backing for `read()`, so the donor q2-native
    /// `nativeInventory` overlay stays empty until the compat lane lands it.
    pub fn native_player_ui(&self, actor: &ActorId) -> Result<PlayerUi, RuntimeError> {
        let state = self.peek();
        match &state.source {
            SourceRuntime::Q3Qvm {
                game,
                combat,
                inventory,
                weapons,
                ..
            } => {
                let has_combat = combat.is_some();
                let has_inventory = inventory.is_some();
                let player = native_q3_guest_record(game, actor)?;
                let record = game.records.player(player.source_entity);
                let entities = state.recipe.map.entities.clone();
                let now_milliseconds = (self.time_seconds() * 1000.0) as i32;
                let program =
                    qa_content::catalog::selected_source_program(&state.recipe.execution, &state.recipe.map.entities)
                        .map_err(source_failure)?;
                let product = if program.as_deref() == Some("missionpack") {
                    qa_content::q3::base::shared::definitions::Product::Missionpack
                } else {
                    qa_content::q3::base::shared::definitions::Product::Baseq3
                };
                let entries = if has_inventory {
                    Some(state.inventory.entries(self.actors.borrow().inner(), actor))
                } else {
                    None
                };
                let active = match weapons {
                    None => super::q3::guest_player::Q3GuestActiveWeapon::FromState,
                    Some(weapons) => match weapons
                        .active(actor)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?
                    {
                        Some(item) => super::q3::guest_player::Q3GuestActiveWeapon::Item(item),
                        None => super::q3::guest_player::Q3GuestActiveWeapon::None,
                    },
                };
                let catalog = {
                    drop(state);
                    let mut locked = self.lock();
                    match &mut locked.source {
                        SourceRuntime::Q3Qvm { catalog, .. } => catalog
                            .weapons()
                            .map_err(|error| RuntimeError::Failure(error.to_string()))?,
                        _ => return Err(RuntimeError::Failure("Actor has no native source UI".to_string())),
                    }
                };
                let state = self.peek();
                let mut ui = super::q3::guest_player::q3_guest_player_ui(
                    &record,
                    entities,
                    now_milliseconds,
                    Some(catalog.as_slice()),
                    product,
                    entries.as_deref(),
                    active,
                );
                if state
                    .selected_arsenal
                    .as_ref()
                    .is_some_and(|arsenal| arsenal.has(actor))
                {
                    let arsenal = state.selected_arsenal.as_ref().expect("selected arsenal checked");
                    ui.inventory = state.inventory.entries(self.actors.borrow().inner(), actor);
                    if let Some(overlay) = arsenal.ui(actor, &state.weapon_provider) {
                        ui.active_weapon = overlay.active_weapon;
                        ui.ammo = overlay.ammo;
                        ui.items = overlay.items;
                        ui.weapon_status = overlay.weapon_status;
                        ui.arsenal_warning = overlay.arsenal_warning;
                    }
                }
                if has_combat {
                    let combat = state.combat.read(actor).ok_or_else(|| {
                        RuntimeError::Failure("Qualified Q3 guest client has no combat binding".to_string())
                    })?;
                    ui.armor = world_armor_to_contract(&combat.armor);
                }
                Ok(ui)
            }
            SourceRuntime::Q2Native(_) => {
                drop(state);
                self.native_q2_player_ui(actor)
            }
            _ => Err(RuntimeError::Failure("Actor has no native source UI".to_string())),
        }
    }

    /// Native Quake II HUD (donor `nativePlayerUi` q2-native arm).
    fn native_q2_player_ui(&self, actor: &ActorId) -> Result<PlayerUi, RuntimeError> {
        let client = self.native_q2_client(actor)?;
        let slot = client.slot() + 1;
        let state = self.peek();
        let entities = state.recipe.map.entities.clone();
        let has_arsenal = state
            .selected_arsenal
            .as_ref()
            .is_some_and(|arsenal| arsenal.has(actor));
        drop(state);
        let mut locked = self.lock();
        let mut original = match &mut locked.source {
            SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => {
                let player_state = game
                    .player_state(slot)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                let configstrings = game
                    .configstrings()
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                let configstrings: std::collections::HashMap<u32, String> = configstrings
                    .into_iter()
                    .map(|(index, value)| (index as u32, value))
                    .collect();
                let definitions: Vec<qa_content::q2::foundation::weapons::types::Q2WeaponDefinition> =
                    qa_content::q2::foundation::weapons::definitions::base_weapons()
                        .into_iter()
                        .map(|definition| definition.definition)
                        .collect();
                super::classic_guest_player::classic_guest_player_ui(
                    &player_state,
                    &configstrings,
                    entities,
                    &definitions,
                )
            }
            SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => {
                let player_state = game
                    .player_state(slot)
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                let configstrings = game
                    .configstrings()
                    .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                let configstrings: std::collections::HashMap<u32, String> = configstrings
                    .into_iter()
                    .map(|(index, value)| (index as u32, value))
                    .collect();
                let definitions: Vec<qa_content::q2::foundation::weapons::types::Q2WeaponDefinition> =
                    qa_content::q2::foundation::weapons::definitions::base_weapons()
                        .into_iter()
                        .map(|definition| definition.definition)
                        .collect();
                super::rerelease_guest_player::rerelease_guest_player_ui(
                    &player_state,
                    &configstrings,
                    entities,
                    &definitions,
                )
            }
            _ => return Err(RuntimeError::Failure("Actor has no native source UI".to_string())),
        };
        drop(locked);
        if !has_arsenal {
            return Ok(original);
        }
        let state = self.peek();
        let arsenal = state.selected_arsenal.as_ref().expect("selected arsenal checked");
        original.selected_arsenal = true;
        original.inventory = state.inventory.entries(self.actors.borrow().inner(), actor);
        if let Some(overlay) = arsenal.ui(actor, &state.weapon_provider) {
            original.active_weapon = overlay.active_weapon;
            original.ammo = overlay.ammo;
            original.items = overlay.items;
            original.weapon_status = overlay.weapon_status;
            original.arsenal_warning = overlay.arsenal_warning;
        }
        Ok(original)
    }
}
