/// Live Quake II source view (donor `q2Source` whole-source read).
///
/// The donor returns the source object; the game arena is already shared,
/// so the view clones the `Rc` (live reads) plus the `Copy` product.
#[derive(Clone)]
pub struct Q2SourceView {
    /// Product runtime.
    pub product: Q2ProductRuntime,
    /// Game services arena (shared with execution entries).
    pub game: Rc<RefCell<qa_content::q2::foundation::host::Q2GameServices>>,
}

impl SharedSimulation {
    /// Live Quake II source (donor `q2Source`).
    pub fn q2_source(&self) -> Option<Q2SourceView> {
        match &self.peek().source {
            SourceRuntime::Q2 { product, game } => Some(Q2SourceView {
                product: *product,
                game: Rc::clone(game),
            }),
            _ => None,
        }
    }

    /// Shared QuakeC game source (donor `quakecSource`).
    pub fn quakec_source(&self) -> Option<Rc<super::quakec_source::QuakeCSource<RuntimePickupAdmission>>> {
        match &self.peek().source {
            SourceRuntime::QuakeC { game, .. } => Some(Rc::clone(game)),
            _ => None,
        }
    }
}
