/// Convert a canonical grenade travel capture into the travel-mirror shape.
fn hand_grenade_travel_to_mirror(
    carry: super::equipment_runtime::HandGrenadeTravel,
) -> super::types::HandGrenadeTravel {
    super::types::HandGrenadeTravel {
        state: carry.state,
        ammo: carry.ammo,
        seconds: carry.seconds,
    }
}

// C7: native Quake II travel/admission/drop (donor runtime.ts 5388-5469).
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Capture the native travel payload (donor `captureNativeQ2Travel`).
    ///
    /// Missing siblings: the runtime `NativePrimaryInventory` seam has no
    /// compat-host backing for `read()`, so inventory selections travel as
    /// `None` until the compat lane lands it; closing the resourceless
    /// primary seams is their drop.
    pub fn capture_native_q2_travel(
        &self,
        new_unit: bool,
        spawn_point: &str,
        next_frame: &mut dyn FnMut(),
    ) -> Result<super::native_q2_travel::NativeQ2Travel, RuntimeError> {
        use super::native_q2_travel::{
            ClassicNativeQ2Travel, NativeQ2Travel, NativeQ2TravelClient, NativeQ2TravelClientPhase,
            RereleaseNativeQ2Travel,
        };
        self.assert_open()?;
        let native = matches!(self.peek().source, SourceRuntime::Q2Native(_));
        if !native || self.peek().stepping {
            return fail("Native map travel requires a completed source frame");
        }
        let map_path = self.peek().recipe.map.geometry.requested_path.clone();
        let records = {
            let state = self.peek();
            match &state.source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game
                    .clients()
                    .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game
                    .clients()
                    .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?,
                _ => return fail("Native map travel requires a completed source frame"),
            }
        };
        let clients = {
            let state = self.peek();
            match &state.source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { clients, .. })
                | SourceRuntime::Q2Native(Q2NativeSource::Rerelease { clients, .. }) => clients.clone(),
                _ => return fail("Native map travel requires a completed source frame"),
            }
        };
        let mut travel_clients = Vec::with_capacity(records.len());
        for record in &records {
            let client = clients
                .keys()
                .find(|client| client.slot() + 1 == record.slot)
                .cloned()
                .ok_or_else(|| RuntimeError::Failure("Native source client has no session identity".to_string()))?;
            let owner = clients.get(&client).map(|owner| owner.id().clone());
            let hand_grenades = match owner.as_ref() {
                None => None,
                Some(owner) => match self.with_hand_grenades(|runtime, game| runtime.travel(owner, game))? {
                    Some(outcome) => outcome
                        .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?
                        .map(hand_grenade_travel_to_mirror),
                    None => None,
                },
            };
            let weapon_slot = match owner.as_ref() {
                Some(owner) if self.peek().weapon_slots.contains_key(owner) => {
                    let projection = self.slot_projection(owner, None)?;
                    projection.pending.clone().or(projection.active.clone())
                }
                _ => None,
            };
            if let Some(owner) = owner.as_ref() {
                let state = self.peek();
                if let Some(grapple) = state.grapple.as_ref() {
                    grapple
                        .release(owner)
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                }
            }
            let selected_arsenal = match owner.as_ref() {
                Some(owner) => self.capture_selected_arsenal_travel(owner)?,
                None => None,
            };
            let phase = match record.phase {
                super::classic_guest_world::ClassicGuestClientPhase::Connected => NativeQ2TravelClientPhase::Connected,
                super::classic_guest_world::ClassicGuestClientPhase::Active => NativeQ2TravelClientPhase::Active,
            };
            travel_clients.push(NativeQ2TravelClient {
                client,
                phase,
                hand_grenades,
                weapon_slot,
                native_inventory_selection: None,
                selected_arsenal,
            });
        }
        let mut locked = self.lock();
        if let Some(dispose) = locked.dispose_native_pickup_supply.take() {
            dispose();
        }
        locked.native_primary_drop = None;
        locked.native_primary_inventory = None;
        locked.native_primary_commands = None;
        locked.native_primary_weapons = None;
        let dropped_pickups = locked
            .dropped_pickups
            .travel(&map_path, new_unit)
            .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?;
        let area_portals = locked.area_portals.clone();
        match &mut locked.source {
            SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, visited, .. }) => {
                let mut next_visited = if new_unit {
                    std::collections::HashMap::new()
                } else {
                    visited.clone()
                };
                if !new_unit {
                    let save = game
                        .write_travel_level_loading(next_frame)
                        .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?;
                    let level = rr_host_save_to_source(&save)?;
                    let configstrings = game
                        .configstrings()
                        .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?;
                    let mut entries = Vec::with_capacity(configstrings.len());
                    for (index, value) in configstrings {
                        entries.push(super::native_q2_rerelease_save::ConfigStringEntry {
                            index: u32::try_from(index).map_err(|_| {
                                RuntimeError::Failure("Native travel configstring index exceeds u32".to_string())
                            })?,
                            value,
                        });
                    }
                    let portals = area_portals
                        .iter()
                        .map(|(portal, open)| super::native_q2_rerelease_save::PortalEntry {
                            portal: *portal,
                            open: *open,
                        })
                        .collect();
                    next_visited.insert(
                        map_path.clone(),
                        super::native_q2_rerelease_save::Q2RereleaseVisitedLevel {
                            state: super::native_q2_rerelease_save::Q2RereleaseLevelState {
                                configstrings: entries,
                                portals,
                            },
                            map: map_path.clone(),
                            level,
                        },
                    );
                }
                Ok(NativeQ2Travel::Rerelease(RereleaseNativeQ2Travel {
                    dropped_pickups: Some(dropped_pickups),
                    clients: travel_clients,
                    spawn_point: spawn_point.to_string(),
                    world: super::native_q2_travel::RereleaseGuestWorld,
                    visited: next_visited,
                }))
            }
            SourceRuntime::Q2Native(Q2NativeSource::Classic {
                game, files, visited, ..
            }) => {
                let mut next_visited = if new_unit {
                    std::collections::HashMap::new()
                } else {
                    visited.clone()
                };
                if !new_unit {
                    let level = files
                        .capture_travel_level(|path| {
                            game.write_travel_level_loading(path, next_frame)
                                .map_err(|error| crate::persistence::PersistenceError::Io(format!("{error:?}")))
                        })
                        .map_err(|error| RuntimeError::Failure(error.to_string()))?;
                    let configstrings = game
                        .configstrings()
                        .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?;
                    let entries: Vec<(i64, String)> = configstrings
                        .into_iter()
                        .map(|(index, value)| (i64::from(index), value))
                        .collect();
                    let portals: Vec<(i64, bool)> = area_portals
                        .iter()
                        .map(|(portal, open)| (i64::from(*portal), *open))
                        .collect();
                    next_visited.insert(
                        map_path.clone(),
                        crate::persistence::q2::classic_guest::Q2ClassicVisitedLevel {
                            state: crate::persistence::q2::classic_guest::Q2ClassicLevelState {
                                configstrings: entries,
                                portals,
                            },
                            map: map_path.clone(),
                            level,
                        },
                    );
                }
                let files = files.clone();
                Ok(NativeQ2Travel::Classic(ClassicNativeQ2Travel {
                    dropped_pickups: Some(dropped_pickups),
                    clients: travel_clients,
                    spawn_point: spawn_point.to_string(),
                    world: super::native_q2_travel::ClassicGuestWorld,
                    files,
                    visited: next_visited,
                }))
            }
            _ => fail("Native map travel requires a completed source frame"),
        }
    }

    /// Admit a native client (donor `admitQ2NativePlayer`).
    pub fn admit_q2_native_player(
        &self,
        client: &ClientId,
        userinfo: &str,
        begin: bool,
    ) -> Result<super::types::PlayerAdmission, RuntimeError> {
        use super::native_q2_travel::NativeQ2TravelClientPhase;
        self.assert_open()?;
        let (is_native, max_clients, already) = {
            let state = self.peek();
            let has = match &state.source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { clients, .. })
                | SourceRuntime::Q2Native(Q2NativeSource::Rerelease { clients, .. }) => clients.contains_key(client),
                _ => false,
            };
            (
                matches!(state.source, SourceRuntime::Q2Native(_)),
                state.options_max_clients,
                has,
            )
        };
        let owns = self.actors.borrow().inner().owner().owns_client(client);
        if !is_native || !owns || client.slot() as usize >= max_clients || already {
            return fail("Invalid native client admission");
        }
        let retained = self
            .peek()
            .options_native_q2_travel
            .as_ref()
            .and_then(|travel| travel.clients().iter().find(|entry| entry.client == *client).cloned());
        if retained.is_some() {
            let actor = self.register_q2_native_client(client, Q2NativeClientMode::Live)?;
            if begin
                && matches!(
                    retained.map(|entry| entry.phase),
                    Some(NativeQ2TravelClientPhase::Active)
                )
            {
                self.begin_native_client(client)?;
                self.notify_client_event(ModClientEventKind::Admitted, actor.id())?;
            }
            let view = self.player_view(actor.id())?;
            return Ok(super::types::PlayerAdmission {
                actor: actor.id().clone(),
                view_height: view.view_height,
            });
        }
        let allowed = {
            let mut locked = self.lock();
            match &mut locked.source {
                SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => {
                    game.connect(client.slot() + 1, userinfo)
                        .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?
                        .allowed
                }
                SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => {
                    game.connect(client.slot() + 1, userinfo, 0, false)
                        .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?
                        .allowed
                }
                _ => return fail("Invalid native client admission"),
            }
        };
        if !allowed {
            return fail("Native Quake II rejected the local client");
        }
        let actor = self.register_q2_native_client(client, Q2NativeClientMode::Live)?;
        if begin {
            self.begin_native_client(client)?;
            self.notify_client_event(ModClientEventKind::Admitted, actor.id())?;
        }
        let view = self.player_view(actor.id())?;
        Ok(super::types::PlayerAdmission {
            actor: actor.id().clone(),
            view_height: view.view_height,
        })
    }

    /// Begin an admitted native client (donor `game.begin` admission step).
    fn begin_native_client(&self, client: &ClientId) -> Result<(), RuntimeError> {
        let mut locked = self.lock();
        match &mut locked.source {
            SourceRuntime::Q2Native(Q2NativeSource::Classic { game, .. }) => game
                .begin(client.slot() + 1)
                .map_err(|error| RuntimeError::Failure(format!("{error:?}"))),
            SourceRuntime::Q2Native(Q2NativeSource::Rerelease { game, .. }) => game
                .begin(client.slot() + 1)
                .map_err(|error| RuntimeError::Failure(format!("{error:?}"))),
            _ => fail("No native Quake II source"),
        }
    }

    /// Drop an inventory item into a pickup (donor `nativeDroppedItem`).
    #[allow(dead_code)]
    fn native_dropped_item(
        &self,
        actor: &ActorId,
        pickup: &ActorId,
        item: &ItemId,
        count: f64,
    ) -> Result<bool, RuntimeError> {
        let owner = self
            .actors
            .borrow()
            .resolve_owned(actor)
            .ok_or_else(|| RuntimeError::Failure("Dropped item has no live inventory owner".to_string()))?;
        {
            let mut locked = self.lock();
            locked
                .dropped_pickups
                .set(
                    pickup,
                    &super::dropped_pickups::DroppedPickupCargo {
                        item: item.clone(),
                        count: count as i64,
                    },
                )
                .map_err(|error| RuntimeError::Failure(format!("{error:?}")))?;
            let actors = self.actors.borrow();
            match locked
                .inventory
                .inner_mut()
                .consume(actors.inner(), &owner, item.as_str(), count)
            {
                Ok(true) => {}
                Ok(false) => {
                    locked.dropped_pickups.delete(pickup);
                    return Ok(false);
                }
                Err(error) => {
                    locked.dropped_pickups.delete(pickup);
                    return fail(format!("{error:?}"));
                }
            }
        }
        self.refresh_arsenal_cache(actor)?;
        Ok(true)
    }

    /// Resync a player's arsenal from the selected arsenal (donor `refreshArsenalCache`).
    fn refresh_arsenal_cache(&self, actor: &ActorId) -> Result<(), RuntimeError> {
        let Ok(player) = self.require_player(actor) else {
            return Ok(());
        };
        if self.peek().selected_arsenal.is_none() {
            return Ok(());
        }
        let arsenal = self.read_player_arsenal(&player)?;
        self.update_player(actor, |state| state.arsenal = arsenal)
    }
}
// ---------------------------------------------------------------------------
// C7: rerelease navigation attach (donor `installRereleaseNavigation`, 2503).
// ---------------------------------------------------------------------------

impl SharedSimulation {
    /// Attach rerelease bot navigation (donor `installRereleaseNavigation`).
    ///
    /// Missing siblings: the temporary navigation harness carries no
    /// identity, so the already-belongs inequality only lands with the
    /// real navigation home; reinstalling the harness is idempotent.
    pub fn attach_rerelease_navigation(
        &self,
        navigation: super::navigation::ApplicationBotNavigation,
    ) -> Result<(), RuntimeError> {
        self.assert_open()?;
        let mut locked = self.lock();
        if locked
            .native_navigation
            .as_ref()
            .is_some_and(|existing| *existing != navigation)
        {
            return fail("Native navigation already belongs to this world");
        }
        locked.native_navigation = Some(navigation);
        Ok(())
    }

    /// Attached rerelease bot navigation (donor `rereleaseNavigation`).
    pub fn rerelease_navigation(&self) -> Option<super::navigation::ApplicationBotNavigation> {
        self.peek().native_navigation.clone()
    }
}

// --- C11 part 2f: create_grapple with threewave host (donor 2346-2393) ---

fn c11_actor_host_world(
    sim: &SharedSimulation,
    numeric: qa_core::numeric::NumericProfile,
) -> super::source_hosts::ActorHostWorld {
    use super::source_hosts::ActorHostWorld;
    let tables = C11Tables {
        actors: sim.actors_handle(),
        bodies: sim.bodies_handle(),
        weak: sim.weak(),
    };
    let world_tables = tables.clone();
    let order_tables = tables.clone();
    ActorHostWorld {
        scene: Rc::new(SharedSceneAdapter {
            scene: sim.scene(),
            bodies: sim.bodies_handle(),
            actors: sim.actors_handle(),
            simulation: sim.weak(),
        }),
        numeric,
        world_actor: Rc::new(move || world_tables.sim().world_actor()),
        source_order: Rc::new(move |a, b| match order_tables.sim().source_order(a, b) {
            std::cmp::Ordering::Less => -1,
            std::cmp::Ordering::Equal => 0,
            std::cmp::Ordering::Greater => 1,
        }),
    }
}

fn c11_q1_source_target(tables: &C11Tables, actor: &ActorId) -> qa_content::q1::foundation::host::Q1SourceTarget {
    use qa_content::q1::foundation::host::Q1SourceTarget;
    let sim = tables.sim();
    let player = sim.player_client(actor).is_some();
    let state = sim.peek();
    let entry = state.actor_executions.get(actor);
    let is_quakec = matches!(entry, Some(RuntimeExecutionEntry::QuakeC { .. }));
    let is_q1 = matches!(entry, Some(RuntimeExecutionEntry::Q1 { .. }));
    let is_q2 = matches!(entry, Some(RuntimeExecutionEntry::Q2 { .. }));
    let aimed_damage = player
        || is_quakec
            && matches!(
                &state.source,
                SourceRuntime::QuakeC { game }
                    if game
                        .weapon_target(actor)
                        .ok()
                        .flatten()
                        .is_some_and(|target| target.aimed_damage)
            )
        || is_q1
            && matches!(
                &state.source,
                SourceRuntime::Q1 { services, .. }
                    if services.try_borrow().ok().is_some_and(|game| {
                        game.entity_ref(actor)
                            .is_some_and(|entity| entity.aimed_damage)
                    })
            )
        || is_q2
            && matches!(
                &state.source,
                SourceRuntime::Q2 { game, .. }
                    if game.try_borrow().ok().is_some_and(|game| {
                        game.entity(actor).is_some_and(|entity| {
                            (entity.server_flags & 4) != 0
                        })
                    })
            );
    let q1_traits = if is_q1 {
        match &state.source {
            SourceRuntime::Q1 { services, .. } => services
                .try_borrow()
                .ok()
                .and_then(|game| game.entity_ref(actor).map(|entity| (entity.solid, entity.movement))),
            _ => None,
        }
    } else {
        None
    };
    let slidebox =
        q1_traits.is_some_and(|(solid, _)| matches!(solid, qa_content::q1::foundation::types::Q1Solid::Slidebox));
    let q2_push = if is_q2 {
        match &state.source {
            SourceRuntime::Q2 { game, .. } => game.try_borrow().ok().and_then(|game| {
                game.entity(actor).map(|entity| {
                    entity.motion == qa_content::q2::foundation::host::Q2MotionKind::Push
                        || entity.motion == qa_content::q2::foundation::host::Q2MotionKind::Stop
                })
            }),
            _ => None,
        }
    } else {
        None
    };
    drop(state);
    let brush = matches!(
        sim.grapple_anchor(actor),
        qa_content::q2::equipment::grapple_services::GrappleAnchor::Brush
    );
    let push = match (q1_traits, q2_push) {
        (Some((_, movement)), _) => {
            matches!(movement, qa_content::q1::foundation::types::Q1MoveType::Push)
        }
        (None, Some(push)) => push,
        (None, None) => brush,
    };
    Q1SourceTarget {
        aimed_damage,
        push,
        player,
        slidebox,
    }
}

#[allow(dead_code)]
struct C11ThreewaveHost {
    tables: C11Tables,
    binding: qa_content::contract::GrappleBinding,
    aim_threshold: Option<f64>,
    teamplay: Option<i32>,
    trace: std::cell::RefCell<qa_content::q1::foundation::host::Q1TraceHook>,
}

impl C11ThreewaveHost {
    #[allow(dead_code)]
    fn aim_eligible(&self, actor: &OwnedActor, team: Option<&str>, target: &ActorId) -> bool {
        let traits = c11_q1_source_target(&self.tables, target);
        let state = self.tables.sim().combat_state(target);
        let teamplay = self.teamplay.unwrap_or(0);
        match state {
            Some(state) => {
                !qa_core::identity::same_actor(target, actor.id())
                    && (traits.aimed_damage || traits.player)
                    && state.can_take_damage
                    && !(teamplay != 0 && team.is_some() && team == state.team.as_deref())
            }
            None => false,
        }
    }

    #[allow(dead_code)]
    fn trace_q1(
        &self,
        request: &qa_content::q1::foundation::types::Q1TraceRequest,
    ) -> qa_content::q1::foundation::types::Q1Trace {
        let mut hook = self.trace.borrow_mut();
        hook(request)
    }
}

impl qa_content::q1::equipment::grapple::ThreewaveGrappleHost for C11ThreewaveHost {
    fn input(&self, actor: &ActorId) -> qa_content::q1::equipment::grapple::ThreewaveGrappleInput {
        use qa_content::q1::equipment::grapple::ThreewaveGrappleInput;
        let sim = self.tables.sim();
        let held = sim.with_grapple(|grapple| grapple.held(actor)).unwrap_or(false);
        let selected = sim
            .peek()
            .weapon_slots
            .get(actor)
            .is_some_and(|slot| slot.equipment_selected());
        let jump = sim.with_grapple(|grapple| grapple.jump(actor)).unwrap_or(false);
        let player = sim
            .require_player(actor)
            .expect("grapple input needs an admitted player");
        let view = sim.movement_player_view(&player);
        let teleport_until = match (&sim.peek().source, &player.state) {
            (SourceRuntime::Q1 { .. }, MovementState::Q1Netquake(state)) => state.teleport_time_seconds,
            _ => 0.0,
        };
        ThreewaveGrappleInput {
            held,
            release: !held && (self.binding == qa_content::contract::GrappleBinding::Offhand || selected),
            jump,
            view_angles: view.angles,
            teleport_until,
        }
    }

    fn aim(&self, actor: &ActorId, forward: Vec3) -> Vec3 {
        use qa_content::q1::foundation::types::{dot, length, vadd, vscale, vsub, Q1TraceRequest, POINT};
        use qa_core::identity::same_actor;
        let sim = self.tables.sim();
        let owned = sim
            .actors
            .borrow()
            .resolve_owned(actor)
            .expect("Hook owner was released");
        let body = {
            let actors = self.tables.actors.borrow();
            let bodies = self.tables.bodies.borrow();
            bodies.read(actors.inner(), actor)
        };
        let Some(body) = body else {
            return forward;
        };
        let team = sim.combat_state(actor).and_then(|combat| combat.team);
        let threshold = self.aim_threshold.unwrap_or(0.93);
        let origin = body.origin;
        let start = Vec3 {
            x: origin.x,
            y: origin.y,
            z: origin.z + 20.0,
        };
        let far = vadd(start, vscale(forward, 2048.0));
        let straight = self.trace_q1(&Q1TraceRequest {
            start,
            end: far,
            bounds: POINT,
            ignore: Some(actor.clone()),
            monsters: true,
            missile: false,
        });
        if let Some(hit) = straight.actor.as_ref() {
            if self.aim_eligible(&owned, team.as_deref(), hit) {
                return forward;
            }
        }
        let targets: Vec<ActorId> = self
            .tables
            .actors
            .borrow()
            .observations()
            .into_iter()
            .map(|observation| observation.id)
            .collect();
        let mut best = threshold;
        let mut selected: Option<Vec3> = None;
        for target in &targets {
            if !self.aim_eligible(&owned, team.as_deref(), target) {
                continue;
            }
            let body = {
                let actors = self.tables.actors.borrow();
                let bodies = self.tables.bodies.borrow();
                bodies.read(actors.inner(), target)
            };
            let Some(body) = body else {
                continue;
            };
            let center = Vec3 {
                x: body.origin.x + 0.5 * (body.bounds.min.x + body.bounds.max.x),
                y: body.origin.y + 0.5 * (body.bounds.min.y + body.bounds.max.y),
                z: body.origin.z + 0.5 * (body.bounds.min.z + body.bounds.max.z),
            };
            let delta = vsub(center, start);
            let size = length(delta);
            if size == 0.0 {
                continue;
            }
            let direction = Vec3 {
                x: delta.x / size,
                y: delta.y / size,
                z: delta.z / size,
            };
            let alignment = f64::from(dot(direction, forward));
            if alignment < best {
                continue;
            }
            let hit = self.trace_q1(&Q1TraceRequest {
                start,
                end: center,
                bounds: POINT,
                ignore: Some(actor.clone()),
                monsters: true,
                missile: false,
            });
            if hit.actor.as_ref().is_some_and(|hit| same_actor(hit, target)) {
                best = alignment;
                selected = Some(body.origin);
            }
        }
        let Some(selected) = selected else {
            return forward;
        };
        let delta = vsub(selected, origin);
        let along = dot(delta, forward);
        let mut corrected = Vec3 {
            x: forward.x * along,
            y: forward.y * along,
            z: delta.z,
        };
        let size = length(corrected);
        if size != 0.0 {
            corrected = Vec3 {
                x: corrected.x / size,
                y: corrected.y / size,
                z: corrected.z / size,
            };
        }
        corrected
    }

    fn anchor(&self, actor: &ActorId) -> qa_content::q1::equipment::grapple::ThreewaveAnchor {
        use qa_content::q1::equipment::grapple::ThreewaveAnchor;
        use qa_content::q2::equipment::grapple_services::GrappleAnchor;
        let sim = self.tables.sim();
        let anchor = sim.grapple_anchor(actor);
        ThreewaveAnchor {
            solid: !matches!(anchor, GrappleAnchor::None),
            centered: matches!(
                anchor,
                GrappleAnchor::Player | GrappleAnchor::Corpse | GrappleAnchor::Box
            ),
            player: sim.player_client(actor).is_some(),
        }
    }

    fn can_attach(&self, owner: &ActorId, target: &ActorId) -> bool {
        let sim = self.tables.sim();
        let team = sim.combat_state(owner).and_then(|combat| combat.team);
        team.is_none() || sim.combat_state(target).and_then(|combat| combat.team) != team
    }

    fn can_pulse(&self, owner: &ActorId, target: &ActorId) -> bool {
        self.can_attach(owner, target)
    }

    fn can_damage(&self, target: &ActorId, owner: &ActorId) -> bool {
        use qa_content::q1::foundation::types::{vadd, vscale, Q1TraceRequest, POINT};
        let (target_body, inflictor_body) = {
            let actors = self.tables.actors.borrow();
            let bodies = self.tables.bodies.borrow();
            (bodies.read(actors.inner(), target), bodies.read(actors.inner(), owner))
        };
        let (Some(target_body), Some(inflictor_body)) = (target_body, inflictor_body) else {
            return false;
        };
        let start = vadd(
            inflictor_body.origin,
            vscale(vadd(inflictor_body.bounds.min, inflictor_body.bounds.max), 0.5),
        );
        for offset in [
            Vec3 {
                x: 15.0,
                y: 15.0,
                z: 0.0,
            },
            Vec3 {
                x: -15.0,
                y: 15.0,
                z: 0.0,
            },
            Vec3 {
                x: 15.0,
                y: -15.0,
                z: 0.0,
            },
            Vec3 {
                x: -15.0,
                y: -15.0,
                z: 0.0,
            },
        ] {
            let trace = self.trace_q1(&Q1TraceRequest {
                start,
                end: vadd(
                    vadd(
                        target_body.origin,
                        vscale(vadd(target_body.bounds.min, target_body.bounds.max), 0.5),
                    ),
                    offset,
                ),
                bounds: POINT,
                ignore: Some(owner.clone()),
                monsters: false,
                missile: false,
            });
            if trace.fraction == 1.0 {
                return true;
            }
        }
        false
    }
}

impl SharedSimulation {
    #[allow(dead_code)]
    /// Selected Q1 arsenal for a foreign weapon provider (donor
    /// `createSelectedQ1Arsenal`, validation head; the arena host needs
    /// the sibling observation bridge).
    fn create_selected_q1_arsenal(&self) -> Result<super::arsenal::q1::Q1SelectedArsenal, RuntimeError> {
        let state = self.peek();
        let product = state.weapon_provider.content.as_str().split(':').nth(2);
        if !matches!(product, Some("id1" | "hipnotic" | "rogue" | "dopa" | "mg1" | "mg3")) {
            return fail("Selected Q1 arsenal has an unsupported source program");
        }
        let _timing = provider_timing(&state.recipe, &provider_text(&state.weapon_provider.provider))?;
        fail("Missing siblings: selected Q1 arsenal host (arsenalObservation/addon services)")
    }

    /// Selected Q2 arsenal for a foreign weapon provider (donor
    /// `createSelectedQ2Arsenal`, validation head; the arena host needs
    /// the sibling observation bridge).
    fn create_selected_q2_arsenal(&self) -> Result<super::arsenal::q2::Q2SelectedArsenal, RuntimeError> {
        let state = self.peek();
        let product = state.weapon_provider.content.as_str().split(':').nth(2);
        if !matches!(product, Some("baseq2" | "xatrix" | "rogue" | "mg2")) {
            return fail("Selected Q2 arsenal has an unsupported source program");
        }
        let clock = provider_timing(&state.recipe, &provider_text(&state.weapon_provider.provider))?.clock;
        if !matches!(
            clock,
            qa_core::time::ClockProfile::Q2Classic | qa_core::time::ClockProfile::Q2Rerelease { .. }
        ) {
            return fail("Selected Q2 arsenal requires its source clock");
        }
        fail("Missing siblings: selected Q2 arsenal host (arsenalObservation/weapon input)")
    }

    /// Selected Q3 arsenal for a foreign weapon provider (donor
    /// `createSelectedQ3Arsenal`, validation head; the source host needs
    /// the sibling implementation).
    fn create_selected_q3_arsenal(&self) -> Result<super::arsenal::q3::Q3SelectedArsenal, RuntimeError> {
        let state = self.peek();
        let clock = provider_timing(&state.recipe, &provider_text(&state.weapon_provider.provider))?.clock;
        if !matches!(clock, qa_core::time::ClockProfile::Q3 { .. }) {
            return fail("Selected Q3 arsenal requires its source clock");
        }
        fail("Missing siblings: selected Q3 source host (Q3SelectedSourceHost)")
    }

    /// Bind native Q2 input bridges (donor `bindNativeInput`).
    fn bind_native_input(
        &self,
        retained_drops: Option<&super::dropped_pickups::DroppedPickupLevels>,
    ) -> Result<(), RuntimeError> {
        if !matches!(self.peek().source, SourceRuntime::Q2Native(_)) {
            return Ok(());
        }
        if let Some(retained) = retained_drops {
            let requested_path = self.peek().recipe.map.geometry.requested_path.clone();
            self.lock()
                .dropped_pickups
                .revisit(retained, &requested_path)
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
        }
        let armed = self.peek().selected_arsenal.is_some() || self.peek().hand_grenades.is_some();
        let qualified = self.native_primary().is_some();
        if armed && !qualified {
            return fail("Native primary weapon source is unqualified");
        }
        if armed || qualified {
            return fail(
                "Missing siblings: native primary weapon/command/inventory/drop bridges (bindNativePrimaryWeapons)",
            );
        }
        Ok(())
    }

    /// Step the QVM client-command arsenal decision (donor `qvmWeaponStep`).
    fn qvm_weapon_step(&self, application: &ModClientApplication, reached_attack_decision: bool) {
        use qa_world::movement::types::{AnimationState, UserCommand};
        if !matches!(self.peek().source, SourceRuntime::Q3Qvm { .. }) || self.peek().selected_arsenal.is_none() {
            return;
        }
        let Some(actor) = self.actors.borrow().resolve_owned(&application.identity.actor) else {
            return;
        };
        if !self
            .peek()
            .selected_arsenal
            .as_ref()
            .is_some_and(|selected| selected.has(actor.id()))
        {
            if let Err(error) = self.qvm_client_spawned(actor.id()) {
                panic!("{error}");
            }
        }
        self.require_qvm_weapons();
        let available = {
            let state = self.peek();
            let SourceRuntime::Q3Qvm {
                weapons: Some(weapons), ..
            } = &state.source
            else {
                panic!("Original QVM weapon services have no qualified owner");
            };
            weapons
                .available(actor.id(), true)
                .expect("qvm weapon availability failed")
        };
        if !available {
            return;
        }
        let record = {
            let state = self.peek();
            let SourceRuntime::Q3Qvm { game, .. } = &state.source else {
                return;
            };
            game.records.player(game.records.require_slot(actor.id()))
        };
        let health = f64::from(record.stats[0]);
        let active = self
            .peek()
            .weapon_slots
            .get(actor.id())
            .is_none_or(|slot| slot.primary_selected())
            && reached_attack_decision;
        let mut command = application.command;
        if !active {
            command = match command {
                UserCommand::Q1Netquake(mut inner) => {
                    inner.buttons &= !1;
                    UserCommand::Q1Netquake(inner)
                }
                UserCommand::Q1Quakeworld(mut inner) => {
                    inner.buttons &= !1;
                    UserCommand::Q1Quakeworld(inner)
                }
                UserCommand::Q2Classic(mut inner) => {
                    inner.buttons &= !1;
                    UserCommand::Q2Classic(inner)
                }
                UserCommand::Q2Rerelease(mut inner) => {
                    inner.buttons &= !1;
                    UserCommand::Q2Rerelease(inner)
                }
                UserCommand::Q3(mut inner) => {
                    inner.buttons &= !1;
                    UserCommand::Q3(inner)
                }
            };
        }
        let attack = match command {
            UserCommand::Q1Netquake(inner) => inner.buttons & 1 != 0,
            UserCommand::Q1Quakeworld(inner) => inner.buttons & 1 != 0,
            UserCommand::Q2Classic(inner) => inner.buttons & 1 != 0,
            UserCommand::Q2Rerelease(inner) => inner.buttons & 1 != 0,
            UserCommand::Q3(inner) => inner.buttons & 1 != 0,
        };
        let alive = health > 0.0;
        if let Some(selected) = self.peek().selected_q3_source.as_ref() {
            selected
                .command(&actor, attack, active, alive)
                .unwrap_or_else(|error| panic!("{error}"));
        }
        let animation = ActorAnimationState {
            provider: self.peek().recipe.character.definition.provider.clone(),
            state: AnimationState::Q3 {
                legs: record.legs_animation,
                torso: record.torso_animation,
                legs_timer_milliseconds: record.legs_timer_ms,
                torso_timer_milliseconds: record.torso_timer_ms,
            },
        };
        let frame = {
            let state = self.peek();
            let selected = state.selected_arsenal.as_ref().expect("selected arsenal checked above");
            if selected.family() == "q1" {
                let mut frame = selected_q1_frame(&state).unwrap_or_else(|error| panic!("{error}"));
                frame.elapsed = application.frame.elapsed;
                frame
            } else if let Some(SelectedWeaponSource::Q2 { frame, .. }) = state.selected_weapon_source.as_ref() {
                let mut frame = *frame;
                frame.elapsed = application.frame.elapsed;
                frame
            } else {
                let mut frame = application.frame;
                frame.time = SourceTime::Milliseconds(state.selected_milliseconds as i32);
                frame
            }
        };
        let arsenal = self
            .peek()
            .selected_arsenal
            .as_ref()
            .expect("selected arsenal checked above")
            .read(actor.id());
        let gauntlet = active
            && matches!(
                arsenal.state,
                qa_world::movement::types::WeaponState::Q3 { source_weapon: 1, .. }
            )
            && attack
            && alive
            && self
                .peek()
                .selected_q3_source
                .as_ref()
                .map(|selected| selected.gauntlet_hit(&actor).unwrap_or_else(|error| panic!("{error}")))
                .unwrap_or(false);
        let intent = application.arsenal.as_ref().map(|intent| ArsenalIntent {
            provider: provider_text(&intent.provider),
            weapon: intent.weapon.clone(),
            use_holdable: intent.use_holdable,
        });
        let previous = self.lock().current_qvm_arsenal_application.replace(application.clone());
        {
            let mut state = self.lock();
            let selected = state.selected_arsenal.as_mut().expect("selected arsenal checked above");
            let input = super::arsenal::selected::WeaponStepInput {
                actor: actor.clone(),
                command,
                frame,
                arsenal,
                animation,
                environment: qa_world::movement::types::MovementEnvironment {
                    health,
                    flight: false,
                    haste: false,
                    invulnerable: false,
                    gravity_multiplier: 1.0,
                    ..Default::default()
                },
                gauntlet_hit: gauntlet,
            };
            let _ = selected.step(&input, intent.as_ref());
        }
        let reconciled = self
            .lock()
            .weapon_slots
            .get_mut(actor.id())
            .map(|slot| slot.reconcile().map_err(|error| error.to_string()));
        self.lock().current_qvm_arsenal_application = previous;
        if let Some(Err(error)) = reconciled {
            panic!("{error}");
        }
    }

    fn create_grapple(&self) -> Result<Option<GrappleRuntime>, RuntimeError> {
        use qa_content::contract::{GrappleMechanicDetail, SourceEdition};
        let selection = self.peek().recipe.equipment.grapple.clone();
        let qa_content::contract::GrappleSelection::Enabled {
            source,
            binding,
            mechanic,
        } = &selection
        else {
            return Ok(None);
        };
        if matches!(mechanic, GrappleMechanicDetail::Q3Qvm { .. }) {
            return Ok(None);
        }
        let seed = self.peek().options_seed;
        let skill = self.peek().options_skill;
        let mode = self.peek().options_mode;
        let max_clients = self.peek().options_max_clients;
        let map_provider = self.peek().recipe.map.entities.provider.clone();
        let map_path = self.peek().recipe.map.geometry.requested_path.clone();
        let campaign = match &self.peek().recipe.campaign {
            qa_content::contract::CampaignSelection::Campaign { mission, .. } => mission.provider.clone(),
            _ => map_provider.clone(),
        };
        let combat_provider = self.peek().recipe.combat.provider.clone();
        let inventory_provider = self.peek().recipe.inventory.provider.clone();
        let movement_provider = self.peek().recipe.movement.provider.clone();
        let gravity = self.peek().physics.gravity();
        let world_timing = {
            let state = self.peek();
            let timing = provider_timing(&state.recipe, &provider_text(&map_provider))?;
            (timing.clock, timing.numeric)
        };
        let timing_clock = {
            let state = self.peek();
            provider_timing(&state.recipe, &provider_text(&source.provider))?.clock
        };
        {
            let mut state = self.lock();
            let base = FrameContext {
                elapsed: SourceTime::Seconds(0.0),
                ..state.source_frame
            };
            state.grapple_frame = super::provider_frames::provider_frame(base, &world_timing.0, &timing_clock);
        }
        let edition = match mechanic {
            GrappleMechanicDetail::Q1Threewave { edition } => *edition,
            GrappleMechanicDetail::Q2Ctf { edition } => *edition,
            GrappleMechanicDetail::Q2Lmctf => SourceEdition::Classic,
            GrappleMechanicDetail::Q3Qvm { .. } => SourceEdition::Classic,
        };
        let rerelease =
            edition == SourceEdition::Rerelease && !matches!(mechanic, GrappleMechanicDetail::Q1Threewave { .. });
        let random = super::random::SourceRandom::with_profile(
            seed,
            if rerelease {
                super::random::RandomProfile::Q2Rerelease
            } else {
                super::random::RandomProfile::Classic
            },
        );
        if let GrappleMechanicDetail::Q1Threewave { .. } = mechanic {
            let tables = C11Tables {
                actors: self.actors_handle(),
                bodies: self.bodies_handle(),
                weak: self.weak(),
            };
            let now_tables = tables.clone();
            let now = Box::new(move || seconds(now_tables.sim().peek().grapple_frame.time));
            let frame_tables = tables.clone();
            let frame_seconds = Box::new(move || seconds(frame_tables.sim().peek().grapple_frame.elapsed));
            let schedule_tables = tables.clone();
            let schedule = Box::new(move |actor: &OwnedActor, due: Option<f64>| {
                let sim = schedule_tables.sim();
                match due {
                    None => {
                        let actors = sim.actors.borrow();
                        sim.lock()
                            .scheduler
                            .cancel(actors.inner(), actor)
                            .expect("grapple think cancel failed");
                    }
                    Some(due) => {
                        sim.schedule(actor, due).expect("grapple think schedule failed");
                    }
                }
            });
            let host = self.q1_actor_host(
                source,
                super::source_hosts::ActorHostRuntime {
                    numeric: world_timing.1,
                    random: random.clone(),
                    now,
                    frame_seconds,
                    schedule,
                },
                super::source_transition::SourceLevelAuthority::ActorSource,
            );
            let mut game = qa_content::q1::foundation::entity_services::Q1EntityServices::new(
                host,
                qa_content::q1::foundation::types::Q1FoundationOptions {
                    provider: Some(source.provider.clone()),
                    precache_program: None,
                    edition: match edition {
                        SourceEdition::Classic => qa_content::q1::foundation::types::Q1Edition::Classic,
                        SourceEdition::Rerelease => qa_content::q1::foundation::types::Q1Edition::Rerelease,
                    },
                    physics_edition: Some(self.q1_physics_edition()),
                    skill: i32::from(skill),
                    deathmatch: i32::from(mode == super::types::SimulationMode::Deathmatch),
                    coop: mode == super::types::SimulationMode::Coop,
                    campaign: campaign.clone(),
                    combat_provider: combat_provider.clone(),
                    movement_provider: movement_provider.clone(),
                    inventory_provider: inventory_provider.clone(),
                    gravity,
                    max_clients: Some(max_clients as i32),
                    no_exit: None,
                    teamplay: None,
                    aim_threshold: None,
                },
            )
            .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            game.begin_frame(
                seconds(self.peek().grapple_frame.time),
                seconds(self.peek().grapple_frame.elapsed),
            );
            let trace = super::source_hosts::q1_trace_hook(c11_actor_host_world(self, world_timing.1));
            let host: Box<dyn qa_content::q1::equipment::grapple::ThreewaveGrappleHost> = Box::new(C11ThreewaveHost {
                tables: tables.clone(),
                binding: *binding,
                aim_threshold: None,
                teamplay: None,
                trace: std::cell::RefCell::new(trace),
            });
            qa_content::q1::equipment::grapple::register_threewave_grapple(&mut game, host)
                .map_err(|error| RuntimeError::Failure(error.to_string()))?;
            let _ = (game, random);
            panic!("Missing siblings: grapple checkpoint bridge lane owns GrappleFoundationBridge::Q1");
        }
        let host = self.q2_actor_host(
            source,
            world_timing.1,
            0.0,
            super::source_transition::SourceLevelAuthority::ActorSource,
            None,
        );
        let game = qa_content::q2::foundation::host::Q2GameServices::new(
            host,
            qa_content::q2::foundation::host::Q2GameOptions {
                edition: match edition {
                    SourceEdition::Classic => qa_content::q2::foundation::host::Q2Edition::Classic,
                    SourceEdition::Rerelease => qa_content::q2::foundation::host::Q2Edition::Rerelease,
                },
                map_name: map_path,
                skill,
                mode: match mode {
                    super::types::SimulationMode::Singleplayer => {
                        qa_content::q2::foundation::host::Q2Mode::Singleplayer
                    }
                    super::types::SimulationMode::Coop => qa_content::q2::foundation::host::Q2Mode::Coop,
                    super::types::SimulationMode::Deathmatch => qa_content::q2::foundation::host::Q2Mode::Deathmatch,
                },
                deathmatch_flags: 0,
                max_clients: max_clients as u32,
                provider: source.provider.clone(),
                damage_powerup_owner: None,
                source_damage_modifier: None,
                campaign,
                combat_provider,
                inventory_provider,
                movement_provider,
            },
            Vec::new(),
        );
        match mechanic {
            GrappleMechanicDetail::Q2Ctf { .. } => {
                let _equipment = qa_content::q2::equipment::ctf_grapple::Q2CtfGrappleEquipment::new(
                    super::grapple_runtime::equipment_grapple_hooks(),
                );
            }
            _ => {
                let _equipment = qa_content::q2::equipment::lmctf_grapple::LmctfGrappleEquipment::new(
                    super::grapple_runtime::equipment_grapple_hooks(),
                );
            }
        }
        let _ = (game, random);
        panic!("Missing siblings: grapple checkpoint bridge lane owns GrappleFoundationBridge::Q2");
    }
}

