fn c11_qvm_combat_definition(
    profile: &qa_guest::qvm::primary_player_profile::QvmPrimaryCombatProfile,
) -> qa_guest::qvm::game_combat::QvmGameCombatDefinition {
    use qa_guest::qvm::game_combat::{
        QvmCombatCall, QvmCombatCallbacks, QvmCombatExtra, QvmCombatExtraKind, QvmCombatFields,
    };
    let damage_call = QvmCombatCall {
        roles: profile
            .damage_call
            .roles
            .iter()
            .map(|(role, index)| (role.clone(), *index))
            .collect(),
        extras: profile
            .damage_call
            .extras
            .iter()
            .map(|extra| QvmCombatExtra {
                index: extra.index,
                kind: match extra.kind {
                    qa_guest::qvm::primary_player_profile::QvmCombatExtraKind::Int32 => QvmCombatExtraKind::Int32,
                    qa_guest::qvm::primary_player_profile::QvmCombatExtraKind::Float32 => QvmCombatExtraKind::Float32,
                    qa_guest::qvm::primary_player_profile::QvmCombatExtraKind::Address => QvmCombatExtraKind::Address,
                },
                value: extra.value,
            })
            .collect(),
    };
    qa_guest::qvm::game_combat::QvmGameCombatDefinition {
        damage_call,
        module: qa_guest::qvm::game_data::ModuleIdentity {
            id: profile.module.id.clone(),
            artifact_path: profile.module.artifact_path.clone(),
            digest: profile.module.digest.clone(),
            revision: profile.module.revision.clone(),
        },
        abi_profile: match profile.abi_profile {
            qa_guest::qvm::mod_provider::QvmAbi::Modern => qa_guest::qvm::game_data::AbiProfile::Modern,
            qa_guest::qvm::mod_provider::QvmAbi::Legacy => qa_guest::qvm::game_data::AbiProfile::Legacy,
        },
        entity_stride: profile.entity_stride,
        client_stride: profile.client_stride,
        fields: QvmCombatFields {
            inuse: profile.fields.inuse,
            health: profile.fields.health,
            takedamage: profile.fields.takedamage,
            parent: profile.fields.parent,
        },
        callbacks: QvmCombatCallbacks {
            allocate: profile.callbacks.allocate,
            free: profile.callbacks.free,
            damage: profile.callbacks.damage,
        },
    }
}

