impl super::qvm_grapple_source::QvmGrappleActors for C11QvmGrappleActors {
    fn allocate(&self, provider: &ProviderId, definition: &str) -> OwnedActor {
        self.tables
            .actors
            .borrow_mut()
            .allocate(provider.clone(), definition)
            .expect("qvm grapple actor allocation failed")
    }

    fn is_live(&self, actor: &ActorId) -> bool {
        self.tables.actors.borrow().inner().is_live(actor)
    }

    fn release(&self, actor: &OwnedActor) {
        self.tables
            .actors
            .borrow_mut()
            .release(actor)
            .expect("qvm grapple actor release failed");
    }

    fn resolve_saved(&self, saved: &qa_core::identity::SavedActorId) -> Option<OwnedActor> {
        use super::physics::PhysicsActors;
        RuntimeActors::new(self.tables.actors.clone()).resolve_saved(*saved)
    }

    fn on_release(&self, callback: Box<dyn Fn(&OwnedActor)>) -> Box<dyn Fn()> {
        self.tables
            .actors
            .borrow_mut()
            .on_release(move |actor, _| callback(actor));
        // The registry keeps listeners for its own lifetime, which matches
        // the grapple source, so the guard has nothing to unregister.
        Box::new(|| {})
    }
}

