struct C11QvmGrappleScene {
    scene: SharedSceneAdapter,
}

impl super::qvm_grapple_source::QvmGrappleScene for C11QvmGrappleScene {
    fn trace_scene(
        &self,
        query: &qa_content::q3::base::world_adapter::Q3TraceQuery,
    ) -> qa_content::q3::base::world_adapter::Q3TraceResult {
        use qa_bots::scene::{QueryTarget, SceneQueries, TracePolicy, TraceQuery};
        use qa_content::q3::base::world_adapter::{Q3TraceHit, Q3TraceResult};
        let shape = match query.shape {
            qa_content::q3::base::world::TraceShape::Point => qa_bots::scene::TraceShape::Point,
            qa_content::q3::base::world::TraceShape::Box { mins, maxs } => qa_bots::scene::TraceShape::Box {
                bounds: Bounds { min: mins, max: maxs },
            },
            qa_content::q3::base::world::TraceShape::Capsule { mins, maxs } => qa_bots::scene::TraceShape::Capsule {
                bounds: Bounds { min: mins, max: maxs },
            },
        };
        let result = self.scene.trace(&TraceQuery {
            start: query.start,
            end: query.end,
            shape,
            target: QueryTarget::World,
            policy: TracePolicy::Q3 {
                contents_mask: query.mask,
                curves: query.curves,
                player_curve_clip: query.player_curve_clip,
            },
            numeric: query.numeric,
            pass_actor: query.pass_actor.clone(),
        });
        let hit = match result.hit {
            qa_bots::scene::TraceHit::None => Q3TraceHit::None,
            qa_bots::scene::TraceHit::World { .. } => Q3TraceHit::World,
            qa_bots::scene::TraceHit::Actor { actor } => Q3TraceHit::Actor { actor },
        };
        let contact = match result.contact {
            qa_bots::scene::TraceContact::None => qa_content::q3::base::world::TraceContact::None,
            qa_bots::scene::TraceContact::Plane { plane } => qa_content::q3::base::world::TraceContact::Plane { plane },
        };
        let (contents, surface_flags) = match result.detail {
            qa_bots::scene::TraceDetail::Q3 {
                contents,
                surface_flags,
                ..
            } => (contents, surface_flags),
            _ => panic!("QVM grapple trace returned another source representation"),
        };
        Q3TraceResult {
            fraction: result.fraction as f32,
            end: result.end,
            hit,
            contact,
            start_solid: result.start_solid,
            all_solid: result.all_solid,
            contents,
            surface_flags,
        }
    }

    fn point_contents_scene(&self, query: &qa_content::q3::base::world_adapter::Q3TraceQuery, point: Vec3) -> i32 {
        use qa_bots::scene::{PointContentsQuery, QueryTarget, SceneQueries, TracePolicy};
        let result = self.scene.point_contents(&PointContentsQuery {
            point,
            target: QueryTarget::World,
            policy: TracePolicy::Q3 {
                contents_mask: query.mask,
                curves: query.curves,
                player_curve_clip: query.player_curve_clip,
            },
            numeric: query.numeric,
            pass_actor: query.pass_actor.clone(),
        });
        match result {
            qa_bots::scene::PointContentsResult::Q1 { contents } => contents,
            qa_bots::scene::PointContentsResult::Q2 { merged, .. } => merged,
            qa_bots::scene::PointContentsResult::Q3 { contents } => contents,
        }
    }

    fn query_actors(&self, bounds: &Bounds) -> Vec<ActorId> {
        use super::source_hosts::ActorHostScene;
        self.scene
            .query_actors(bounds, qa_world::spatial::QueryRole::Both)
            .into_iter()
            .map(|entry| entry.body.actor)
            .collect()
    }

    fn point_leaf(&self, point: Vec3) -> i32 {
        use super::source_hosts::ActorHostScene;
        self.scene.point_leaf(point)
    }

    fn leaf_cluster(&self, leaf: i32) -> i32 {
        use super::source_hosts::ActorHostScene;
        self.scene.leaf_cluster(leaf)
    }

    fn leaf_area(&self, leaf: i32) -> i32 {
        use super::source_hosts::ActorHostScene;
        self.scene.leaf_area(leaf)
    }

    fn cluster_visible(&self, from: i32, cluster: i32) -> bool {
        use qa_bots::scene::{SceneQueries, VisibilityKind};
        self.scene.cluster_visible(from, cluster, VisibilityKind::Pvs)
    }

    fn areas_connected(&self, first: i32, second: i32) -> bool {
        use qa_bots::scene::SceneQueries;
        self.scene.areas_connected(first, second)
    }
}

