#[allow(dead_code)]
fn c11_source_checkpoint_to_runtime(
    checkpoint: super::qvm_grapple_source::QvmGrappleSourceCheckpoint,
) -> super::grapple_runtime::QvmGrappleSourceCheckpoint {
    use qa_guest::checkpoint::{GameApi, GuestCheckpoint, GuestPrivateState};
    let module = checkpoint.grapple.module;
    let api = match (module.api_kind.as_str(), module.api_version) {
        ("q3-qagame", version) => GameApi::Q3Qagame {
            version: i64::from(version),
        },
        ("q3-cgame", version) => GameApi::Q3Cgame {
            version: i64::from(version),
        },
        (_, version) => GameApi::Q3Ui {
            version: i64::from(version),
        },
    };
    let host_bytes = match module.host_state.bytes {
        qa_guest::qvm::game_data::ProfileValue::Bytes(bytes) => bytes,
        _ => panic!("qvm grapple capture needs encoded host state"),
    };
    super::grapple_runtime::QvmGrappleSourceCheckpoint {
        version: u8::try_from(checkpoint.version).expect("qvm grapple checkpoint version fits"),
        grapple: super::grapple_runtime::QvmGrappleCheckpoint {
            version: u8::try_from(checkpoint.grapple.version).expect("qvm grapple checkpoint version fits"),
            profile: checkpoint.grapple.profile,
            module: GuestCheckpoint::Qvm {
                module: c11_guest_module_identity(&module.module),
                random: Vec::new(),
                callbacks: Vec::new(),
                api,
                abi_profile: if module.abi_profile.is_modern() {
                    "q3-modern"
                } else {
                    "q3-1.16n-base"
                }
                .to_string(),
                data: module.data,
                instruction_index: i64::try_from(module.instruction_index).expect("qvm grapple instruction index fits"),
                program_stack: module.program_stack as u64,
                operand_stack: module.operand_stack.into_iter().map(i64::from).collect(),
                host_state: GuestPrivateState {
                    module: c11_guest_module_identity(&module.host_state.module),
                    format: module.host_state.format,
                    bytes: host_bytes,
                },
            },
            owners: checkpoint.grapple.owners,
        },
        bindings: checkpoint
            .bindings
            .into_iter()
            .map(|entry| super::grapple_runtime::QvmGrappleBindingCheckpoint {
                actor: entry.actor,
                pointer: i64::from(entry.pointer),
                client: entry.client,
                origin: entry.origin,
            })
            .collect(),
        tethers: checkpoint
            .tethers
            .into_iter()
            .map(|entry| super::grapple_runtime::QvmGrappleTetherCheckpoint {
                owner: entry.owner,
                actor: entry.actor,
            })
            .collect(),
    }
}

/// Read a QVM grapple component checkpoint in donor save shape, unified to
/// the grapple-runtime checkpoint the restore path consumes.
///
/// Non-QVM grapple sources never invoke this reader.
fn read_qvm_grapple_component_checkpoint(
    reader: qa_world::save::value::SaveReader,
) -> Result<super::grapple_runtime::QvmGrappleSourceCheckpoint, qa_world::WorldError> {
    let source = super::qvm_grapple_source::read_qvm_grapple_source_checkpoint(&reader)?;
    Ok(c11_source_checkpoint_to_runtime(source))
}

#[allow(dead_code)]
fn c11_runtime_checkpoint_to_source(
    checkpoint: &super::grapple_runtime::QvmGrappleSourceCheckpoint,
) -> Result<super::qvm_grapple_source::QvmGrappleSourceCheckpoint, super::grapple_runtime::GrappleError> {
    use crate::bootstrap::simulation::grapple_runtime::GrappleError;
    use qa_guest::checkpoint::GameApi;
    let module = match &checkpoint.grapple.module {
        qa_guest::checkpoint::GuestCheckpoint::Qvm {
            module,
            random,
            callbacks,
            api,
            abi_profile,
            data,
            instruction_index,
            program_stack,
            operand_stack,
            host_state,
        } => {
            if !random.is_empty() || !callbacks.is_empty() {
                return Err(GrappleError::Qvm(
                    "Saved grapple source carries runtime-owned continuations".to_string(),
                ));
            }
            let (api_kind, api_version) = match api {
                GameApi::Q3Qagame { version } => ("q3-qagame", *version),
                GameApi::Q3Cgame { version } => ("q3-cgame", *version),
                GameApi::Q3Ui { version } => ("q3-ui", *version),
                _ => {
                    return Err(GrappleError::Qvm(
                        "Saved grapple source api is not a QVM game api".to_string(),
                    ));
                }
            };
            qa_guest::qvm::game_data::QvmCheckpoint {
                module: c11_qvm_module_identity(module),
                api_kind: api_kind.to_string(),
                api_version: i32::try_from(api_version)
                    .map_err(|_| GrappleError::Qvm("Saved grapple api version overflows".to_string()))?,
                abi_profile: match abi_profile.as_str() {
                    "q3-modern" => qa_guest::qvm::game_data::AbiProfile::Modern,
                    "q3-1.16n-base" => qa_guest::qvm::game_data::AbiProfile::Legacy,
                    _ => {
                        return Err(GrappleError::Qvm("Saved grapple abi profile is unknown".to_string()));
                    }
                },
                data: data.clone(),
                instruction_index: usize::try_from(*instruction_index)
                    .map_err(|_| GrappleError::Qvm("Saved grapple address is negative".to_string()))?,
                operand_stack: operand_stack
                    .iter()
                    .map(|word| {
                        i32::try_from(*word)
                            .map_err(|_| GrappleError::Qvm("Saved grapple stack word overflows".to_string()))
                    })
                    .collect::<Result<Vec<_>, _>>()?,
                program_stack: usize::try_from(*program_stack)
                    .map_err(|_| GrappleError::Qvm("Saved grapple address is negative".to_string()))?,
                host_state: qa_guest::qvm::game_data::QvmHostState {
                    module: c11_qvm_module_identity(&host_state.module),
                    format: host_state.format.clone(),
                    bytes: qa_guest::qvm::game_data::ProfileValue::Bytes(host_state.bytes.clone()),
                },
            }
        }
        _ => {
            return Err(GrappleError::Qvm(
                "Saved grapple source module is not a QVM checkpoint".to_string(),
            ));
        }
    };
    Ok(super::qvm_grapple_source::QvmGrappleSourceCheckpoint {
        version: u32::from(checkpoint.version),
        grapple: super::qvm_grapple_source::QvmGrappleSourceGrapple {
            version: u32::from(checkpoint.grapple.version),
            profile: checkpoint.grapple.profile.clone(),
            module,
            owners: checkpoint.grapple.owners.clone(),
        },
        bindings: checkpoint
            .bindings
            .iter()
            .map(|entry| {
                Ok(super::qvm_grapple_source::QvmGrappleSourceBinding {
                    actor: entry.actor,
                    pointer: i32::try_from(entry.pointer)
                        .map_err(|_| GrappleError::Qvm("Saved grapple binding pointer overflows".to_string()))?,
                    client: entry.client,
                    origin: entry.origin,
                })
            })
            .collect::<Result<Vec<_>, GrappleError>>()?,
        tethers: checkpoint
            .tethers
            .iter()
            .map(|entry| super::qvm_grapple_source::QvmGrappleSourceTether {
                owner: entry.owner,
                actor: entry.actor,
            })
            .collect(),
    })
}

